#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("ioctl");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];

    while (running) {
        if (write(spi_fd, tx, sizeof(tx)) != sizeof(tx) ||
            read(spi_fd, rx, sizeof(rx)) != sizeof(rx)) {
            perror("SPI transfer");
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        uint16_t adc_value = ((rx[1] & 3) << 8) | rx[2];
        time_t now = time(NULL);
        printf("%sADC Value: %d\n", ctime(&now), adc_value);

        sleep(1);
    }

    close(spi_fd);
    return 0;
}

