#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096 0x0200
#define ADS1115_CONFIG_DR_128 0x0080

#define MLX91219_SCALE 0.001  // 1 mV per mA

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096 | ADS1115_CONFIG_DR_128;
    uint16_t conversion_result;
    float current;

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure ADS1115
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write to ADS1115");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Wait for conversion to complete
        usleep(10000);  // 10 ms

        // Read conversion result
        if (read(i2c_fd, &conversion_result, 2) != 2) {
            perror("Failed to read from ADS1115");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Convert to big-endian
        conversion_result = (conversion_result >> 8) | (conversion_result << 8);

        // Convert to amperes
        current = (float)conversion_result * MLX91219_SCALE;

        // Log the current value
        printf("Current: %.3f mA\n", current);

        // Wait 500 ms before the next reading
        usleep(500000);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

