#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CE0_PIN 8
#define FLAME_SENSOR_PIN 4
#define ADC_CHANNEL 0
#define CSV_FILE "flame_data.csv"

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static int spi_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

int main() {
    struct sigaction sa;
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        gpiod_chip_close(chip);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Failed to request input for flame sensor");
        gpiod_chip_close(chip);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int flame_detected = gpiod_line_get_value(flame_sensor_line);
        if (flame_detected < 0) {
            perror("Failed to read flame sensor");
            continue;
        }

        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        double temperature = (adc_value * 330.0) / 1023.0; // Approximation

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(csv_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
        fflush(csv_file);

        sleep(1);
    }

    cleanup();
    fclose(csv_file);
    return EXIT_SUCCESS;
}

