#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_1 0x0000
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CQUE_1CONV 0x0000

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define TEMP_THRESHOLD 6000 // 60°C in millivolts

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *flame_sensor_line, *buzzer_line;
    int i2c_fd;
    FILE *log_file;
    struct timespec last_flame_time = {0, 0};
    int flame_debounce = 50000; // 50 ms in microseconds

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(1);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request input for flame sensor: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request output for buzzer: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    // Open I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Configure ADS1115
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_1 | ADS1115_CONFIG_MODE_CONTINUOUS |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
                      ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW |
                      ADS1115_CONFIG_CQUE_1CONV;

    if (write(i2c_fd, &config, 2) != 2) {
        fprintf(stderr, "Failed to write ADS1115 configuration: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        exit(1);
    }

    while (running) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Read flame sensor
        int flame_detected = gpiod_line_get_value(flame_sensor_line);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
            continue;
        }

        // Debounce flame sensor
        if (flame_detected) {
            if (timespec_diff_us(&current_time, &last_flame_time) < flame_debounce) {
                flame_detected = 0;
            } else {
                last_flame_time = current_time;
            }
        }

        // Read temperature from ADS1115
        uint16_t adc_value;
        if (read(i2c_fd, &adc_value, 2) != 2) {
            fprintf(stderr, "Failed to read ADS1115: %s\n", strerror(errno));
            continue;
        }

        int16_t temp_value = (int16_t)adc_value;
        int temp_mV = (temp_value * 4096) / 32768; // Convert to millivolts

        // Check conditions
        if (flame_detected && temp_mV > TEMP_THRESHOLD) {
            // Fire condition
            gpiod_line_set_value(buzzer_line, 1);
            sleep(2);
            gpiod_line_set_value(buzzer_line, 0);

