#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8

#define GPIO_CHIP "gpiochip0"
#define FAN_GPIO_LINE 18

#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500  // Example threshold value

#define LOG_FILE "current_log.txt"

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer xfer;
    uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *fan_line;
    FILE *log_file;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Get fan GPIO line
    fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!fan_line) {
        perror("Failed to get fan GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request fan GPIO line for output
    ret = gpiod_line_request_output(fan_line, "fan_control", 0);
    if (ret < 0) {
        perror("Failed to request fan GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        // Prepare SPI transfer
        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = sizeof(tx);

        // Perform SPI transfer
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }

        // Calculate ADC value
        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        // Check for sensor-absent condition
        if (adc_value == 0 || adc_value == 0x3FF) {
            fprintf(stderr, "Sensor absent or error\n");
            break;
        }

        // Log reading with ISO-8601 timestamp
        struct timeval tv;
        gettimeofday(&tv, NULL);
        struct tm *tm = localtime(&tv.tv_sec);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
        fprintf(log_file, "%s.%06ld, ADC: %d\n", timestamp, tv.tv_usec, adc_value);
        fflush(log_file);

        // Control fan based on threshold
        if (adc_value > ADC_THRESHOLD) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

