#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_1 0x0200
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define CO_SENSOR_ADDR 0x48
#define CO_SENSOR_REG_RESISTANCE 0x00

#define LOG_FILE "co_log.txt"

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

double resistance_to_ppm(double resistance) {
    // Example calibration curve: ppm = 1000 * log(resistance / 10000)
    return 1000 * log(resistance / 10000);
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    FILE *log_file;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CO_SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        uint16_t raw_value;
        double resistance, ppm;
        struct timespec ts;

        // Read raw value from sensor
        if (read(i2c_fd, &raw_value, 2) != 2) {
            perror("Failed to read from I2C device");
            break;
        }

        // Convert raw value to resistance
        resistance = (double)raw_value * 10000 / 32767; // Example conversion

        // Convert resistance to ppm
        ppm = resistance_to_ppm(resistance);

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            break;
        }

        // Log the ppm value with timestamp
        fprintf(log_file, "%ld.%09ld, %.2f ppm\n", ts.tv_sec, ts.tv_nsec, ppm);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

