#define FLAME_SENSOR_GPIO 4
#define MCP3008_CS_GPIO 8
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *mcp3008_cs_line;
static int spi_fd;
static FILE *log_file;

static void cleanup() {
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (mcp3008_cs_line) {
        gpiod_line_release(mcp3008_cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

static int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor GPIO line");
        return -1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Failed to request input for flame sensor GPIO");
        return -1;
    }

    mcp3008_cs_line = gpiod_chip_get_line(chip, MCP3008_CS_GPIO);
    if (!mcp3008_cs_line) {
        perror("Failed to get MCP3008 CS GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(mcp3008_cs_line, "mcp3008_cs", 1) < 0) {
        perror("Failed to request output for MCP3008 CS GPIO");
        return -1;
    }

    return 0;
}

static int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    return 0;
}

static int read_mcp3008_channel(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (gpiod_line_set_value(mcp3008_cs_line, 0) < 0) {
        perror("Failed to set MCP3008 CS low");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        return -1;
    }

    if (gpiod_line_set_value(mcp3008_cs_line, 1) < 0) {
        perror("Failed to set MCP3008 CS high");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

static void log_data(int flame_present, int temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s,%d,%d\n", timestamp, flame_present, temperature) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_data.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int flame_present = gpiod_line_get_value(flame_sensor_line);
        if (flame_present < 0) {
            perror("Failed to read flame sensor");
            continue;
        }

        int temperature = read_mcp3008_channel(0);
        if (temperature < 0) {
            perror("Failed to read temperature");
            continue;
        }

        log_data(flame_present, temperature);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

