#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define REGISTER 0x00
#define CO_THRESHOLD 25.0

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void cleanup(int fd, FILE *co_log, FILE *alert_log) {
    if (fd >= 0) {
        close(fd);
    }
    if (co_log) {
        fclose(co_log);
    }
    if (alert_log) {
        fclose(alert_log);
    }
}

int main() {
    int fd = -1;
    FILE *co_log = NULL;
    FILE *alert_log = NULL;
    struct sigaction sa;
    uint8_t buffer[4];
    uint16_t ox, red;
    double co_ppm;

    // Register signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup(fd, co_log, alert_log);
        exit(EXIT_FAILURE);
    }

    // Open log files
    co_log = fopen("co_log.txt", "a");
    if (!co_log) {
        perror("Failed to open co_log.txt");
        cleanup(fd, co_log, alert_log);
        exit(EXIT_FAILURE);
    }

    alert_log = fopen("alert_log.txt", "a");
    if (!alert_log) {
        perror("Failed to open alert_log.txt");
        cleanup(fd, co_log, alert_log);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read 4 bytes from I2C
        if (read(fd, buffer, 4) != 4) {
            perror("Failed to read from I2C");
            cleanup(fd, co_log, alert_log);
            exit(EXIT_FAILURE);
        }

        // Extract OX and RED values
        ox = (buffer[0] << 8) | buffer[1];
        red = (buffer[2] << 8) | buffer[3];

        // Convert OX to CO ppm
        // Assuming a linear conversion factor for demonstration purposes
        co_ppm = (double)ox * 0.01; // Replace with actual conversion factor

        // Log CO ppm value
        if (fprintf(co_log, "%.2f ppm\n", co_ppm) < 0) {
            perror("Failed to write to co_log.txt");
            cleanup(fd, co_log, alert_log);
            exit(EXIT_FAILURE);
        }

        // Check for alert threshold
        if (co_ppm >= CO_THRESHOLD) {
            if (fprintf(alert_log, "Alert: CO concentration exceeded %d ppm\n", CO_THRESHOLD) < 0) {
                perror("Failed to write to alert_log.txt");
                cleanup(fd, co_log, alert_log);
                exit(EXIT_FAILURE);
            }
        }

        // Flush log files
        fflush(co_log);
        fflush(alert_log);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanup
    cleanup(fd, co_log, alert_log);
    return 0;
}

