    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    mic1_sda = gpiod_chip_get_line(chip, MIC1_SDA);
    mic1_scl = gpiod_chip_get_line(chip, MIC1_SCL);
    mic2_sda = gpiod_chip_get_line(chip, MIC2_SDA);
    mic2_scl = gpiod_chip_get_line(chip, MIC2_SCL);

    if (!mic1_sda || !mic1_scl || !mic2_sda || !mic2_scl) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

