        gpiod_line_request_output(mic1_scl, "mic1_scl", 0) < 0 ||
        gpiod_line_request_output(mic2_sda, "mic2_sda", 0) < 0 ||
        gpiod_line_request_output(mic2_scl, "mic2_scl", 0) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        double level1 = read_mic(mic1_sda, mic1_scl);
        double level2 = read_mic(mic2_sda, mic2_scl);
        double average_level = (level1 + level2) / 2.0;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));

        // Log the entry
        log_entry(average_level, timestamp);

        // Wait for the next sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    // Release GPIO lines
    gpiod_line_release(mic1_sda);
    gpiod_line_release(mic1_scl);
    gpiod_line_release(mic2_sda);
    gpiod_line_release(mic2_scl);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

