#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CQUE_1CONV 0x0000

#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0
#define CURRENT_SCALE 0.00125 // 6.144V / 4096 / 1000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    int16_t buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double sum = 0.0;
    double average = 0.0;

    // Register signal handler
    signal(SIGINT, sigint_handler);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (!(chip = gpiod_chip_open("/dev/gpiochip0"))) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (!(led_line = gpiod_chip_get_line(chip, 17))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_CONTINUOUS |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
                      ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW |
                      ADS1115_CONFIG_CQUE_1CONV;

    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write to ADS1115 config register");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_value;
        int16_t converted_value;
        double current;

        // Read conversion register
        if (read(i2c_fd, &raw_value, 2) != 2) {
            perror("Failed to read from ADS1115 conversion register");
            continue;
        }

        // Convert raw value to signed 16-bit
        converted_value = (int16_t) ((raw_value << 8) | (raw_value >> 8));

        // Convert to current
        current = converted_value * CURRENT_SCALE;

        // Update buffer and calculate average
        sum -= buffer[buffer_index];
        buffer[buffer_index] = converted_value;
        sum += buffer[buffer_index];
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        average = sum / BUFFER_SIZE;

        // Check threshold and set LED
        if (average > CURRENT_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100ms (10Hz)
        usleep(100000);
    }

    // Clean up
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

