#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_ID 0x44
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define CSV_FILE "color_log.csv"
#define HEADER "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    struct sigaction sa;
    uint8_t id;
    uint16_t clear, red, green, blue;
    int i2c_errors = 0;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read sensor ID
    uint8_t command = TCS34725_COMMAND_BIT | 0x00;
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write to I2C");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (read(i2c_fd, &id, 1) != 1) {
        perror("Failed to read from I2C");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (id != TCS34725_ID) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%02X, got 0x%02X\n", TCS34725_ID, id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Power on and enable sensor
    command = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    uint8_t enable = TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN;
    if (write(i2c_fd, &command, 1) != 1 || write(i2c_fd, &enable, 1) != 1) {
        perror("Failed to enable sensor");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(3000); // Wait at least 3 ms after power-on

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (ftell(csv_file) == 0) { // Check if file is empty
        fputs(HEADER, csv_file);
    }

    while (running) {
        // Read color data
        command = TCS34725_COMMAND_BIT | TCS34725_CDATAL;
        if (write(i2c_fd, &command, 1) != 1) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            i2c_errors++;
            if (i2c_errors >= 3) {
                break;
            }
            continue;
        }
        uint8_t data[8];
        if (read(i2c_fd, data, 8) != 8) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            i2c_errors++;
            if (i2c_errors >= 3) {
                break;
            }
            continue;
        }
        i2c_errors = 0; // Reset error count on successful read

        clear = (data[1] << 8) | data[0];
        red = (data[3] << 8) | data[2];
        green = (data[5] << 8) | data[4];
        blue = (data[7] << 8) | data[6];

        // Get current time
        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Write to CSV
        fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
        fflush(csv_file);

        // Wait for 1 second without blocking
        struct timespec ts = {1, 0};
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR);
    }

    // Clean up
    fclose(csv_file);
    close(i2c_fd);

    return i2c_errors >= 3 ? EXIT_FAILURE : EXIT_SUCCESS;
}
