volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int read_adc(int fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

void log_moisture(FILE *logfile, int moisture1, int moisture2) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(logfile, "%s,%d,%d\n", timestamp, moisture1, moisture2);
    fflush(logfile);
}

int main() {
    int spi_fd;
    FILE *logfile;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    logfile = fopen("moisture_log.csv", "a");
    if (!logfile) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (fprintf(logfile, "Timestamp,Moisture1,Moisture2\n") < 0) {
        perror("Failed to write header to log file");
        fclose(logfile);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int moisture1 = read_adc(spi_fd, CHANNEL_0);
        int moisture2 = read_adc(spi_fd, CHANNEL_1);

        if (moisture1 >= 0 && moisture2 >= 0) {
            log_moisture(logfile, moisture1, moisture2);
        } else {
            fprintf(stderr, "Error reading from ADC\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(logfile);
    close(spi_fd);

    return EXIT_SUCCESS;
}

