#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define CURRENT_THRESHOLD 10.0
#define ADC_REF_VOLTAGE 3.3
#define ADC_RESOLUTION 1024.0
#define CURRENT_SCALE 0.005 // 5 mA per LSB

static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (motor_shutdown_line) {
        gpiod_line_release(motor_shutdown_line);
        motor_shutdown_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    motor_shutdown_line = gpiod_chip_get_line(gpio_chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_shutdown_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(motor_shutdown_line, "motor_shutdown", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(motor_shutdown_line);
        motor_shutdown_line = NULL;
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    return 0;
}

int init_log_file() {
    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    struct stat st;
    if (stat("current_log.csv", &st) == 0 && st.st_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }

    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    int retries = 3;
    while (retries--) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 3) << 8) | rx[2];
        }
        perror("SPI transfer failed, retrying...");
        usleep(100000); // 100 ms delay
    }

    return -1;
}

void log_current(double current) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log_file, "%s,%f\n", timestamp, current);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_spi() < 0 || init_gpio() < 0 || init_log_file() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping sample...\n");
            continue;
        }

        double current = (adc_value / ADC_RESOLUTION) * ADC_REF_VOLTAGE / CURRENT_SCALE;
        log_current(current);

        if (current > CURRENT_THRESHOLD) {
            printf("Over-current detected: %.2f A\n", current);
            gpiod_line_set_value(motor_shutdown_line, 0);
            sleep(1);
            gpiod_line_set_value(motor_shutdown_line, 1);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

