#define I2C_BUS "/dev/i2c-1"
#define MLX90817_ADDR 0x24
#define MLX90817_REG_PRESSURE 0x00
#define LOG_FILE "pressure_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, log_fd;
    struct sigaction sa;
    struct timeval tv;
    char timestamp[30];
    uint16_t pressure_raw;
    float pressure_kpa;
    ssize_t bytes_read;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90817_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header to log file
    if (dprintf(log_fd, "Timestamp,Pressure (kPa)\n") < 0) {
        fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
        close(log_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read pressure from sensor
        bytes_read = read(i2c_fd, &pressure_raw, sizeof(pressure_raw));
        if (bytes_read != sizeof(pressure_raw)) {
            fprintf(stderr, "Failed to read pressure from sensor: %s\n", strerror(errno));
            continue;
        }

        // Convert raw pressure to kPa
        pressure_kpa = (pressure_raw * 110.0) / 32768.0;

        // Get current time
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&tv.tv_sec));

        // Write timestamp and pressure to log file
        if (dprintf(log_fd, "%s,%.2f\n", timestamp, pressure_kpa) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            continue;
        }

        // Flush log file
        if (fsync(log_fd) < 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
            continue;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close log file
    close(log_fd);

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

