#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define MLX90834_ADDR 0x5A
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_MUX_AIN1 0x5000
#define ADS1115_CONFIG_PGA_1 0x0200
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CQUE_1CONV 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_PGA_1 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD | ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CQUE_1CONV)

#define MLX90834_REG_STATUS 0x00
#define MLX90834_REG_PRESSURE 0x01
#define MLX90834_REG_TEMPERATURE 0x03

#define GPIO_LED 17
#define LED_ON 1
#define LED_OFF 0

#define MAX_RETRIES 3

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;

static void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static int i2c_write_reg(uint8_t addr, uint8_t reg, uint16_t data) {
    uint8_t buffer[3] = {reg, data >> 8, data & 0xFF};
    if (write(i2c_fd, buffer, 3) != 3) {
        perror("i2c_write_reg");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t addr, uint8_t reg, uint16_t *data) {
    uint8_t buffer[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("i2c_read_reg write");
        return -1;
    }
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read(i2c_fd, buffer, 2) == 2) {
            *data = (buffer[0] << 8) | buffer[1];
            return 0;
        }
        perror("i2c_read_reg read");
        usleep(100000); // 100ms delay before retry
    }
    return -1;
}

static int read_ads1115_channel(uint8_t channel, int16_t *value) {
    uint16_t config = ADS1115_CONFIG_DEFAULT;
    if (channel == 0) {
        config |= ADS1115_CONFIG_MUX_AIN0;
    } else if (channel == 1) {
        config |= ADS1115_CONFIG_MUX_AIN1;
    } else {
        fprintf(stderr, "Invalid channel\n");
        return -1;
    }
    if (i2c_write_reg(ADS1115_ADDR, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    usleep(13000); // Wait for conversion (128 SPS)
    if (i2c_read_reg(ADS1115_ADDR, ADS1115_REG_CONVERSION, (uint16_t *)value) < 0) {
        return -1;
    }
    return 0;
}

static int read_mlx90834_pressure(int16_t *pressure) {
    if (i2c_read_reg(MLX90834_ADDR, MLX90834_REG_PRESSURE, (uint16_t *)pressure) < 0) {
        return -1;
    }
    return 0;
}

static int read_mlx90834_temperature(int16_t *temperature) {
    if (i2c_read_reg(MLX90834_ADDR, MLX90834_REG_TEMPERATURE, (uint16_t *)temperature) < 0) {
        return -1;
    }
    return 0;
}

int main() {
    atexit(cleanup);
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "pressure_warning", LED_OFF) < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl ADS1115");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90834_ADDR) < 0) {
        perror("ioctl MLX90834");
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t pressure_raw, temperature_raw;
        if (read_ads1115_channel(0, &pressure_raw) < 0 || read_ads1115_channel(1, &temperature_raw) < 0) {
            fprintf(stderr, "Failed to read from ADS1115\n");
            continue;
        }

        if (read_mlx90834_pressure(&pressure_raw) < 0 || read_mlx90834_temperature(&temperature_raw) < 0) {
            fprintf(stderr, "Failed to read from MLX90834\n");
            continue;
        }

        float pressure_kPa = (pressure_raw * 0.00125) + 10.0; // Convert to kPa
        float temperature_C = (temperature_raw * 0.0625) - 273.15; // Convert to °C

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kPa, temperature_C);

        if (pressure_kPa > 105.0) {
            gpiod_line_set_value(led_line, LED_ON);
        } else {
            gpiod_line_set_value(led_line, LED_OFF);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

