#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define ADC_CHANNEL 0
#define GPIO_CHIP "gpiochip0"
#define GPIO_SHUTDOWN 27
#define CURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.txt"
#define ADC_RESOLUTION 1023.0
#define ADC_REF_VOLTAGE 3.3

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void log_current(FILE *log_file, double current) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f A\n", timestamp, current);
    fflush(log_file);
}

int main() {
    int spi_fd;
    FILE *log_file;
    struct gpiod_chip *chip;
    struct gpiod_line *shutdown_line;
    double current;
    int adc_value;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    shutdown_line = gpiod_chip_get_line(chip, GPIO_SHUTDOWN);
    if (!shutdown_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(shutdown_line, "motor_shutdown", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        current = (adc_value / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
        log_current(log_file, current);

        if (current > CURRENT_THRESHOLD) {
            fprintf(log_file, "%s,OVERCURRENT\n", timestamp);
            fflush(log_file);
            gpiod_line_set_value(shutdown_line, 1);
            fprintf(stderr, "OVERCURRENT: Shutting down motor\n");
            break;
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    gpiod_line_set_value(shutdown_line, 0);
    gpiod_line_release(shutdown_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

