        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alarm_line, "co_sensor", 0) < 0) {
        perror("Failed to request alarm GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
