This code continuously reads methane concentration from a Honeywell MICROpeL Model 41000-020 Combustible Gas Sensor using an MCP3008 ADC connected via SPI on a Raspberry Pi 4 Model B. It logs each reading with an ISO-8601 timestamp to a file and outputs an alarm message to stderr if the concentration exceeds a specified threshold. The program handles signals to gracefully shut down and checks for errors in SPI transfers, file operations, and time functions.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_1 0x0000
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define MIN_PRESSURE 0
#define MAX_PRESSURE 100000

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    FILE *log_file;
    struct timespec ts;
    int16_t adc_value;
    float pressure;

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_file = fopen("pressure_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure ADS1115
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_1 | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
                      ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CQUE_NONE;
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write to ADS1115");
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Start a conversion
        config |= ADS1115_CONFIG_OS_SINGLE;
        if (write(i2c_fd, &config, 2) != 2) {
            perror("Failed to start conversion");
            break;
        }

        // Wait for conversion to complete
        usleep(125000); // 125 ms for 128 SPS

        // Read conversion result
        if (read(i2c_fd, &adc_value, 2) != 2) {
            perror("Failed to read from ADS1115");
            break;
        }

        // Convert ADC value to pressure
        adc_value = ((uint16_t)adc_value[0] << 8) | adc_value[1];
        adc_value >>= 4; // 12-bit result
        pressure = (adc_value * 100000.0) / 32767.0; // Assuming 0-100 kPa range

        // Validate pressure value
        if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
            // Get current time
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                break;
            }

            // Log pressure and timestamp
            fprintf(log_file, "%ld-%02ld-%02ldT%02ld:%02ld:%02ld.%03ldZ %.2f kPa\n",
                    ts.tv_sec / 31536000, (ts.tv_sec / 2592000) % 12,
                    (ts.tv_sec / 86400) % 30, (ts.tv_sec / 3600) % 24,
                    (ts.tv_sec / 60) % 60, ts.tv_sec % 60, ts.tv_nsec / 1000000,
                    pressure);
            fflush(log_file);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    return 0;
}

