static struct gpiod_chip *chip;
static struct gpiod_line *ce0_line;
static int spi_fd;
static FILE *log_file;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

void init_gpio() {
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ce0_line = gpiod_chip_get_line(chip, CE0_PIN);
    if (!ce0_line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ce0_line, "humidity_sensor", 1) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc_channel(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (gpiod_line_set_value(ce0_line, 0) < 0) {
        perror("Failed to set CE0 low");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI message");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(ce0_line, 1) < 0) {
        perror("Failed to set CE0 high");
        cleanup();
        exit(EXIT_FAILURE);
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

double calculate_humidity(uint16_t adc_value) {
    // Placeholder for actual conversion formula
    return (adc_value / 4095.0) * 100.0;
}

double calculate_temperature(uint16_t adc_value) {
    // Placeholder for actual conversion formula
    return (adc_value / 4095.0) * 100.0;
}

void send_email_alert(double humidity) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "Subject: Humidity Alert\n\nHumidity exceeded 80%%: %.2f%%\n", humidity);

    FILE *mail = popen("ssmtp recipient@example.com", "w");
    if (!mail) {
        perror("Failed to open pipe to ssmtp");
        return;
    }

    fprintf(mail, "%s", buffer);
    pclose(mail);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_spi();
    init_log_file();

    while (1) {
        uint16_t humidity_adc = read_adc_channel(0);
        uint16_t temperature_adc = read_adc_channel(1);

        double humidity = calculate_humidity(humidity_adc);
        double temperature = calculate_temperature(temperature_adc);

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        sleep(60); // Log every minute
    }

    cleanup();
    return 0;
}

