#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 8
#define ADC_CHANNEL 0
#define ADC_BITS 12
#define ADC_REF_VOLTAGE 3.3
#define TMP36_SCALE 10.0
#define TMP36_OFFSET -50.0
#define SAMPLE_RATE 1

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer xfer;
    uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];
    int gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file = NULL;
    int first_run = 1;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set max speed
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(line, "mcp3208_ce", 1) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Write header if file is newly created
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
        fflush(log_file);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Set CE low
        gpiod_line_set_value(line, 0);

        // Perform SPI transfer
        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }

        // Set CE high
        gpiod_line_set_value(line, 1);

        // Combine received bytes
        uint16_t adc_value = ((rx[1] & 0x0F) << 8) | rx[2];

        // Validate ADC reading
        if (adc_value < 0 || adc_value > (1 << ADC_BITS)) {
            fprintf(stderr, "Invalid ADC reading: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to voltage
        double voltage = (adc_value * ADC_REF_VOLTAGE) / (1 << ADC_BITS);

        // Convert voltage to temperature in Celsius
        double temperature_celsius = (voltage - TMP36_OFFSET) * TMP36_SCALE;

        // Validate temperature range
        if (temperature_celsius < -40.0 || temperature_celsius > 125.0) {
            fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature_celsius);
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log the temperature
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature_celsius);
        fflush(log_file);

        // Sleep for the remaining time to achieve 1 Hz sampling rate
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

