        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }

        // Set CE high
        gpiod_line_set_value(line, 1);

        // Combine received bytes
        uint16_t adc_value = ((rx[1] & 0x0F) << 8) | rx[2];

        // Validate ADC reading
        if (adc_value < 0 || adc_value > (1 << ADC_BITS)) {
            fprintf(stderr, "Invalid ADC reading: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to voltage
        double voltage = (adc_value * ADC_REF_VOLTAGE) / (1 << ADC_BITS);

        // Convert voltage to temperature in Celsius
        double temperature_celsius = (voltage - TMP36_OFFSET) * TMP36_SCALE;

        // Validate temperature range
        if (temperature_celsius < -40.0 || temperature_celsius > 125.0) {
            fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature_celsius);
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log the temperature
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature_celsius);
        fflush(log_file);

        // Sleep for the remaining time to achieve 1 Hz sampling rate
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}
