#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_FULL_SCALE (1 << ADC_BITS)
#define ADC_VREF 3.3
#define SENSOR_SCALE 5.0 / ADC_VREF

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

void log_flow_rate(FILE *log_file, double flow_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));
    fprintf(log_file, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(log_file);
}

int main() {
    int spi_fd = -1;
    FILE *log_file = NULL;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (running) {
        uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t rx[3];
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
        };

        // Perform SPI transfer
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to perform SPI transfer");
            continue;
        }

        // Combine bytes and shift
        uint16_t adc_value = ((rx[1] & 3) << 8) | rx[2];

        // Check for sensor-absent conditions
        if (adc_value == 0 || adc_value == ADC_FULL_SCALE) {
            fprintf(stderr, "Sensor absent or invalid reading\n");
            continue;
        }

        // Convert ADC value to flow rate
        double flow_rate = (adc_value / (double)ADC_FULL_SCALE) * SENSOR_SCALE;

        // Validate flow rate
        if (flow_rate < 0.0 || flow_rate > 5.0) {
            fprintf(stderr, "Flow rate out of range: %.2f L/min\n", flow_rate);
            continue;
        }

        // Log flow rate
        log_flow_rate(log_file, flow_rate);

        // Sleep for 1 second
        sleep(1);
    }

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

