#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define I2C_CMD_HIGH_PRECISION 0x34
#define I2C_READ_LENGTH 6

#define CSV_FILE "environmental_data.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
}

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        log_error("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error("Failed to set I2C slave address");
        close_resources();
        return EXIT_FAILURE;
    }

    if ((csv_file = fopen(CSV_FILE, "a")) == NULL) {
        log_error("Failed to open CSV file");
        close_resources();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t cmd = I2C_CMD_HIGH_PRECISION;
        if (write(i2c_fd, &cmd, 1) != 1) {
            log_error("Failed to write I2C command");
            sleep(5);
            continue;
        }

        sleep(1); // Wait for conversion

        uint8_t data[I2C_READ_LENGTH];
        if (read(i2c_fd, data, I2C_READ_LENGTH) != I2C_READ_LENGTH) {
            log_error("Failed to read I2C data");
            sleep(5);
            continue;
        }

        int32_t pressure_raw = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | data[2];
        int32_t temperature_raw = ((int32_t)data[3] << 16) | ((int32_t)data[4] << 8) | data[5];

        // Apply calibration formulas (simplified for example)
        double pressure_pa = pressure_raw * 0.01; // Placeholder conversion
        double temperature_c = temperature_raw * 0.01; // Placeholder conversion

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
        fflush(csv_file);

        printf("%s - Pressure: %.2f Pa, Temperature: %.2f C\n", timestamp, pressure_pa, temperature_c);

        sleep(4); // Sample every 5 seconds
    }

    close_resources();
    return EXIT_SUCCESS;
}

