            break;
        }

        noise_cancellation(&sample1, &sample2, gain1, gain2);
        printf(CSV_FORMAT, sample1, sample2);
        fflush(stdout);

        usleep(10000); // 10ms delay
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

