#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX_VALUE (1 << ADC_BITS) - 1
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void append_to_log(const char *timestamp, int adc_value) {
    FILE *file = fopen("moisture_log.txt", "a");
    if (!file) {
        perror("fopen");
        return;
    }

    if (fprintf(file, "%s,%d\n", timestamp, adc_value) < 0) {
        perror("fprintf");
    }

    if (fclose(file) != 0) {
        perror("fclose");
    }
}

const char *get_iso8601_utc_timestamp() {
    static char timestamp[21];
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
    return timestamp;
}

int main() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        const char *timestamp = get_iso8601_utc_timestamp();
        append_to_log(timestamp, adc_value);

        sleep(SAMPLE_INTERVAL);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

