#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define BUZZER_GPIO 18
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 500
#define MAX_RETRIES 3
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int read_ambient_temp() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        perror("Failed to open ambient_temp.txt");
        return 250; // Default to 25.0°C
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        perror("Failed to read ambient_temp.txt");
        fclose(fp);
        return 250; // Default to 25.0°C
    }
    fclose(fp);
    return temp;
}

int read_adc(int fd, int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

void log_entry(int raw_adc, float voltage, float compensated_voltage, int temperature, int flame_detected) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log, "%s,%d,%.2f,%.2f,%d,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fclose(log);
}

int main() {
    signal(SIGINT, handle_sigint);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int raw_adc = -1;
        int retries = 0;
        while (retries < MAX_RETRIES) {
            raw_adc = read_adc(spi_fd, ADC_CHANNEL);
            if (raw_adc >= 0 && raw_adc <= 1023) {
                break;
            }
            retries++;
        }
        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", raw_adc);
            gpiod_line_set_value(buzzer_line, 0);
            continue;
        }

        float voltage = (raw_adc * 3.3) / 1023.0;
        int temperature = read_ambient_temp();
        float compensated_voltage = voltage * (25.0 / temperature);
        int flame_detected = (compensated_voltage > 1.0); // Threshold for flame detection

        log_entry(raw_adc, voltage, compensated_voltage, temperature, flame_detected);
        gpiod_line_set_value(buzzer_line, flame_detected);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

