void send_email(const char *email, const char *msmtp_config, int moisture_percent) {
    char email_body[256];
    snprintf(email_body, sizeof(email_body), EMAIL_BODY_TEMPLATE, moisture_percent);

    FILE *mail = popen("msmtp -C", "w");
    if (!mail) {
        fprintf(stderr, "Failed to open msmtp pipe\n");
        return;
    }

    fprintf(mail, "To: %s\n", email);
    fprintf(mail, "Subject: %s\n", EMAIL_SUBJECT);
    fprintf(mail, "\n");
    fprintf(mail, "%s\n", email_body);

    if (pclose(mail) == -1) {
        fprintf(stderr, "Failed to close msmtp pipe\n");
    }
}

int read_adc(struct gpiod_chip *chip, unsigned int adc_channel) {
