    if (gpiod_line_request_output(cs, "mcp3008", 1) < 0) {
        fprintf(stderr, "Failed to request CE0 line\n");
        gpiod_line_release(cs);
        return -1;
    }

    struct gpiod_line *clk = gpiod_chip_get_line(chip, 11); // SCLK
    if (!clk) {
        fprintf(stderr, "Failed to get SCLK line\n");
        gpiod_line_release(cs);
