#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define DEFAULT_INTERVAL 1

static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

unsigned int read_adc(unsigned char channel) {
    unsigned char tx[] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

void log_moisture(unsigned int adc_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    double moisture_percentage = (adc_value / 1023.0) * 100.0;
    fprintf(log_file, "%s, %u, %.2f%%\n", timestamp, adc_value, moisture_percentage);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    int interval = DEFAULT_INTERVAL;
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("soil_moisture.log", "a");
    if (!log_file) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open");
        cleanup();
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 8);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "spi-ce0", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        unsigned int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC read failed or sensor absent\n");
        } else {
            log_moisture(adc_value);
        }
        sleep(interval);
    }

    cleanup();
    return EXIT_SUCCESS;
}

