#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define ADC_MIN_VALUE 0
#define ADC_MAX_VALUE 1023
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3
#define VOLTAGE_REF 3.3
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *ce0;
    int spi_fd;
    struct spi_ioc_transfer xfer;
    uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ce0 = gpiod_chip_get_line(chip, 8);
    if (!ce0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(ce0, "mlx90823_ce0", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(ce0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(ce0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_line_release(ce0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        gpiod_line_release(ce0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        struct timespec ts;
        char timestamp[30];

        // Read ADC value
        gpiod_line_set_value(ce0, 0);
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = 3;
        xfer.speed_hz = 1000000;
        xfer.delay_usecs = 1;
        xfer.bits_per_word = 8;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }
        gpiod_line_set_value(ce0, 1);

        uint16_t adc_value = ((rx[1] & 3) << 8) | rx[2];
        if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "ADC value out of range: %u\n", adc_value);
            continue;
        }

        // Convert ADC value to voltage
        double voltage = (adc_value * VOLTAGE_REF) / ADC_MAX_VALUE;
        if (voltage == VOLTAGE_MIN || voltage == VOLTAGE_MAX) {
            fprintf(stderr, "Sensor absent or stuck voltage: %.2f V\n", voltage);
            continue;
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

        // Log the reading
        printf("%s: ADC Value = %u, Voltage = %.2f V\n", timestamp, adc_value, voltage);

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    close(spi_fd);
    gpiod_line_release(ce0);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

