#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define NUM_CHANNELS 4
#define CSV_FILE "environmental_data.csv"

static int spi_fd = -1;
static FILE *csv_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *ce0_line = NULL;

void cleanup() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (ce0_line) {
        gpiod_line_release(ce0_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

unsigned short read_adc_channel(int channel) {
    unsigned char tx[] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    ce0_line = gpiod_chip_get_line(gpio_chip, 8);
    if (!ce0_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce0_line, "mcp3008_ce0", 1) < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            unsigned short adc_value = read_adc_channel(channel);
            float voltage = (adc_value * 3.3) / 1023.0;
            fprintf(csv_file, "%s,Channel %d,%f\n", timestamp, channel, voltage);
        }

        fflush(csv_file);
        sleep(1);
    }

    return EXIT_SUCCESS;
}

