#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_PUMP 17
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    int moisture;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_entry(int moisture, int pump_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].moisture = moisture;
    log_buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_log_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (log_buffer[i].timestamp != 0) {
            printf("Timestamp: %s", ctime(&log_buffer[i].timestamp));
            printf("Moisture: %d\n", log_buffer[i].moisture);
            printf("Pump State: %s\n", log_buffer[i].pump_state ? "ON" : "OFF");
        }
    }
}

int read_mcp3008(int spi_fd) {
    unsigned char tx[3] = {1, 0, 0};
    unsigned char rx[3];
    int ret;

    ret = spi_xfer(spi_fd, tx, rx, 3);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *pump_line;
    int pump_state = 0;
    int moisture_level;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        gpioTerminate();
        return 1;
    }

    pump_line = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    spi_fd = spiOpen(SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    while (running) {
        moisture_level = read_mcp3008(spi_fd);
        if (moisture_level < 0) {
            continue;
        }

        if (moisture_level < LOW_THRESHOLD && !pump_state) {
            gpiod_line_set_value(pump_line, 1);
            pump_state = 1;
            log_entry(moisture_level, pump_state);
        } else if (moisture_level > HIGH_THRESHOLD && pump_state) {
            gpiod_line_set_value(pump_line, 0);
            pump_state = 0;
            log_entry(moisture_level, pump_state);
        }

        log_entry(moisture_level, pump_state);
        print_log_buffer();
        sleep(5);
    }

    gpiod_line_set_value(pump_line, 0);
    spiClose(spi_fd);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

