#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MAX30102_ADDR 0x57
#define MAX30102_PART_ID_REG 0xFE
#define MAX30102_PART_ID 0x15

#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100

#define LOG_FILE "health_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log, "[%s] %s\n", timestamp, message);
    fclose(log);
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *value) {
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    int result = i2c_smbus_read_byte(fd);
    if (result < 0) {
        perror("Failed to read from I2C register");
        return -1;
    }

    *value = (uint8_t)result;
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        log_message("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAX30102_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        log_message("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (read_i2c_register(i2c_fd, MAX30102_PART_ID_REG, &part_id) < 0) {
        log_message("Failed to read Part ID register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (part_id != MAX30102_PART_ID) {
        fprintf(stderr, "MAX30102 sensor not found (Part ID: 0x%02X)\n", part_id);
        log_message("MAX30102 sensor not found");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Simulate reading SpO2 and HR values
        uint8_t spo2 = 97; // Example value
        uint8_t hr = 98;   // Example value

        if (spo2 < SPO2_THRESHOLD || hr > HR_THRESHOLD) {
            char message[100];
            snprintf(message, sizeof(message), "SpO2: %d%%, HR: %dBPM", spo2, hr);
            log_message(message);
        }

        sleep(1);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

