    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log, "[%s] %s\n", timestamp, message);
    fclose(log);
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *value) {
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    int result = i2c_smbus_read_byte(fd);
    if (result < 0) {
        perror("Failed to read from I2C register");
        return -1;
    }

    *value = (uint8_t)result;
    return 0;
}

