    static char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp;
}

float read_mcp3008(int fd, int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1.0;
    }

    int data = ((rx[1] & 3) << 8) | rx[2];
    return (data * 3.3) / 1023.0;
}

int main() {
    signal(SIGINT, sigint_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *csv_fp = fopen(CSV_FILE, "a");
    if (!csv_fp) {
        perror("Failed to open CSV file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ftell(csv_fp) == 0) {
        write_csv_header(csv_fp);
    }

    struct gpiod_chip *chip;
    struct gpiod_line *ce0_line;
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(csv_fp);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ce0_line = gpiod_chip_get_line(chip, CE0_PIN);
    if (!ce0_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(csv_fp);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce0_line, "mcp3008_ce0", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        fclose(csv_fp);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        gpiod_line_set_value(ce0_line, 0);
        for (int channel = 0; channel < CHANNELS; channel++) {
            float voltage = read_mcp3008(spi_fd, channel);
            if (voltage >= 0.0) {
                const char *timestamp = get_iso8601_timestamp();
                write_csv_entry(csv_fp, timestamp, channel, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", channel);
            }
        }
        gpiod_line_set_value(ce0_line, 1);
        fflush(csv_fp);
        usleep(INTERVAL_US);
    }

    gpiod_line_release(ce0_line);
    gpiod_chip_close(chip);
    fclose(csv_fp);
    close(spi_fd);

    return EXIT_SUCCESS;
}

