#include <fcntl.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define BUZZER_GPIO 24
#define THRESHOLD 500
#define SAMPLE_INTERVAL 500000 // 500 ms in microseconds

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *buzzer_line;
    uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];
    int ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read from ADC
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx);
        if (ret < 0) {
            perror("Failed to read from SPI");
            break;
        }

        // Combine the 3 bytes to get the 10-bit ADC value
        uint16_t adc_value = ((rx[1] & 3) << 8) | rx[2];

        // Control buzzer based on ADC value
        if (adc_value >= THRESHOLD) {
            ret = gpiod_line_set_value(buzzer_line, 1);
            if (ret < 0) {
                perror("Failed to set GPIO line value");
                break;
            }
        } else {
            ret = gpiod_line_set_value(buzzer_line, 0);
            if (ret < 0) {
                perror("Failed to set GPIO line value");
                break;
            }
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

