#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_1 0x0200
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CQUE_1CONV 0x0000

#define RELAY_PIN 17
#define REED_PIN 27

#define SAMPLE_INTERVAL_US 200000
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_INTERVAL_US 50000
#define RELAY_PULSE_US 3000000

#define LOG_FILE "/var/log/door_events.log"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_event(const char *event) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%ld.%06ld %s\n", tv.tv_sec, tv.tv_usec, event);
        fclose(log);
    }
}

int read_adc(int i2c_fd) {
    uint8_t config[3] = {
        ADS1115_REG_CONFIG,
        (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_1 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD | ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CQUE_1CONV) >> 8,
        (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_1 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD | ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CQUE_1CONV) & 0xFF
    };

    if (ioctl(i2c_fd, I2C_RDWR, config) < 0) {
        perror("Failed to write to ADS1115");
        return -1;
    }

    usleep(10000); // Wait for conversion

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    int16_t value = (data[0] << 8) | data[1];
    return value;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request relay GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *reed_line = gpiod_chip_get_line(chip, REED_PIN);
    if (!reed_line) {
        perror("Failed to get reed GPIO line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(reed_line, "reed") < 0) {
