volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_spi_device(const char *device, uint32_t speed, uint8_t mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc_channel(int spi_fd, struct gpiod_chip *chip, unsigned int cs_pin, uint8_t channel) {
    struct spi_ioc_transfer xfer[2];
    uint8_t tx[2] = {1, (8 + channel) << 4};
    uint8_t rx[2] = {0, 0};

    xfer[0].tx_buf = (unsigned long)tx;
    xfer[0].rx_buf = (unsigned long)rx;
    xfer[0].len = 2;
    xfer[0].speed_hz = SPI_SPEED;
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 1;

    xfer[1].tx_buf = (unsigned long)tx;
    xfer[1].rx_buf = (unsigned long)rx;
    xfer[1].len = 2;
    xfer[1].speed_hz = SPI_SPEED;
    xfer[1].bits_per_word = 8;
    xfer[1].cs_change = 0;

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, cs_pin);
    if (!cs_line) {
        perror("Failed to get CS line");
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "spi_cs", 1) < 0) {
        perror("Failed to request CS line");
        gpiod_line_release(cs_line);
        return -1;
    }

    gpiod_line_set_value(cs_line, 0);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
        perror("Failed to transfer SPI message");
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        return -1;
    }

    gpiod_line_set_value(cs_line, 1);
    gpiod_line_release(cs_line);

    return ((rx[0] & 0x03) << 8) | rx[1];
}

void log_to_csv(FILE *file, struct timeval *tv, int sensor1, int sensor2, int sensor3) {
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv->tv_sec));

    fprintf(file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
}

