    setup_signals();

    int spi_fd = open_spi_device(SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("Failed to open CSV file");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ftell(file) == 0) {
        fprintf(file, "timestamp,sensor1,sensor2,sensor3\n");
    }

    while (running) {
        struct timeval tv;
        gettimeofday(&tv, NULL);

        int sensor1 = read_adc_channel(spi_fd, chip, CS0_PIN, ADC_CHANNEL);
        int sensor2 = read_adc_channel(spi_fd, chip, CS1_PIN, ADC_CHANNEL);
        int sensor3 = read_adc_channel(spi_fd, chip, CS2_PIN, ADC_CHANNEL);

        if (sensor1 < 0) sensor1 = -1;
        if (sensor2 < 0) sensor2 = -1;
        if (sensor3 < 0) sensor3 = -1;

        log_to_csv(file, &tv, sensor1, sensor2, sensor3);

        fflush(file);
        sleep(5);
    }

    fclose(file);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

