#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define GPIO_CHIP "gpiochip0"
#define GPIO_PUMP 18
#define DEFAULT_THRESHOLD 0.3
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60
#define LOG_FILE "irrigation.log"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        fprintf(log, "%s %s\n", ctime(&now), message);
        fclose(log);
    }
}

int read_adc(int fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    for (int i = 0; i < 3; i++) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) == -1) {
            perror("SPI_IOC_MESSAGE");
            continue;
        }
        int value = ((rx[1] & 3) << 8) + rx[2];
        return value;
    }

    log_message("SPI read failed after 3 retries");
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;
    double threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *pump_line = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(pump_line, "irrigation", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            sleep(sleep_interval);
            continue;
        }

        double moisture = (double)adc_value / 1023.0;
        char log[256];
        snprintf(log, sizeof(log), "Moisture level: %.2f%%", moisture * 100);
        log_message(log);

        if (moisture < threshold) {
            gpiod_line_set_value(pump_line, 1);
            snprintf(log, sizeof(log), "Pump activated for %d seconds", duration);
            log_message(log);
            sleep(duration);
            gpiod_line_set_value(pump_line, 0);
            snprintf(log, sizeof(log), "Pump deactivated");
            log_message(log);
        }

        sleep(sleep_interval);
    }

    gpiod_line_set_value(pump_line, 0);
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

