        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) == -1) {
            perror("SPI_IOC_MESSAGE");
            continue;
        }
        int value = ((rx[1] & 3) << 8) + rx[2];
        return value;
    }

    log_message("SPI read failed after 3 retries");
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;
    double threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *pump_line = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(pump_line, "irrigation", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            sleep(sleep_interval);
            continue;
        }

        double moisture = (double)adc_value / 1023.0;
        char log[256];
        snprintf(log, sizeof(log), "Moisture level: %.2f%%", moisture * 100);
        log_message(log);

        if (moisture < threshold) {
            gpiod_line_set_value(pump_line, 1);
            snprintf(log, sizeof(log), "Pump activated for %d seconds", duration);
            log_message(log);
            sleep(duration);
            gpiod_line_set_value(pump_line, 0);
            snprintf(log, sizeof(log), "Pump deactivated");
            log_message(log);
        }

        sleep(sleep_interval);
    }

    gpiod_line_set_value(pump_line, 0);
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}
```

This code fulfills the user's request by continuously reading the analog output of a Vegetronix VH400 soil moisture sensor connected to an MCP3008 ADC on SPI0, comparing the reading to a configurable threshold, and activating a relay-driven water pump on GPIO 18 for a configurable duration if the moisture level falls below the threshold. It logs every moisture reading and each pump activation or deactivation with timestamps to a file named `irrigation.log`. The program handles SPI communication errors by retrying up to three times per read and logs the error if all retries fail. It also ensures the pump is turned off on all exit paths, including any failure to open the SPI bus, by handling SIGINT and SIGTERM signals.

