        syslog(LOG_ERR, "Failed to set SPI bits per word: %m");
        close(spi_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed: %m");
        close(spi_fd);
        closelog();
        return EXIT_FAILURE;
