#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define PCF8591_ADDRESS 0x48
#define AIN0_CHANNEL 0x00

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    char buffer[1];

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Perform a dummy read to discard the previous conversion result
        if (read(i2c_fd, buffer, 1) != 1) {
            perror("Failed to read from I2C");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Write the channel selection to the PCF8591
        if (write(i2c_fd, &AIN0_CHANNEL, 1) != 1) {
            perror("Failed to write to I2C");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Read the current 8-bit sample
        if (read(i2c_fd, buffer, 1) != 1) {
            perror("Failed to read from I2C");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Print the sample value
        printf("AIN0: %d\n", buffer[0]);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close the I2C file descriptor
    close(i2c_fd);
    return 0;
}

