#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_1 0x0000
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CQUE_1CONV 0x0000

#define GPIO_PIN 27
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500
#define VOLTAGE_MAX 3.3
#define VOLTAGE_MIN 0.0
#define GAUSS_PER_VOLT 100.0

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int16_t adc_value;
    double voltage, gauss;
    double buffer[BUFFER_SIZE];
    double sum = 0.0;
    int buffer_index = 0;
    int threshold_crossed = 0;

    openlog("hall_sensor_monitor", LOG_PID, LOG_DAEMON);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "hall_sensor_monitor", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as output: %s", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_1 |
                      ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
                      ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW | ADS1115_CONFIG_CQUE_1CONV;

    if (write(i2c_fd, &config, 2) != 2) {
        syslog(LOG_ERR, "Failed to write to ADS1115 config register: %s", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        // Read ADC value
        if (read(i2c_fd, &adc_value, 2) != 2) {
            syslog(LOG_ERR, "Failed to read from ADS1115: %s", strerror(errno));
            continue;
        }

        adc_value = (adc_value >> 8) | (adc_value << 8); // Swap bytes

        // Convert ADC value to voltage
        voltage = (adc_value * VOLTAGE_MAX) / 32767.0;

        if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
            syslog(LOG_WARNING, "Voltage out of range: %f V", voltage);
            continue;
        }

        // Convert voltage to Gauss
        gauss = voltage * GAUSS_PER_VOLT;

        // Update buffer and calculate rolling average
        sum -= buffer[buffer_index];
        buffer[buffer_index] = gauss;
        sum += buffer[buffer_index];
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        double average_gauss = sum / BUFFER_SIZE;

        // Check threshold
        if (average_gauss > THRESHOLD_GAUSS && !threshold_crossed) {
            threshold_crossed = 1;
            if (gpiod_line_set_value(line, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO line HIGH: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Threshold crossed, GPIO set HIGH");
            }
        }

        // Log reading
        syslog(LOG_INFO, "Voltage: %f V, Gauss: %f G, Average Gauss: %f G", voltage, gauss, average_gauss);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    if (threshold_crossed) {
        if (gpiod_line_set_value(line, 0) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO line LOW: %s", strerror(errno));
        } else {
            syslog(LOG_INFO, "GPIO set LOW");
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    closelog();

    return EXIT_SUCCESS;
}

