    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(pump_line, "water_pump", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int moisture_level = read_adc(spi_fd, ADC_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        if (moisture_level < ADC_THRESHOLD) {
            gpiod_line_set_value(pump_line, 1);
            log_event("Watering started", moisture_level);
            sleep(PUMP_DURATION);
            gpiod_line_set_value(pump_line, 0);
            log_event("Watering stopped", moisture_level);
        }

        sleep(60);
    }

    gpiod_line_set_value(pump_line, 0);
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

