    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        gpioTerminate();
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install SIGTERM handler");
        gpioTerminate();
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
            .delay_usecs = 0,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to perform SPI transfer");
            continue;
        }

        adc_value = ((rx[1] & 3) << 8) | rx[2];
        pwm_value = (adc_value * PWM_RANGE) / 1023;
        gpioPWM(PWM_PIN, pwm_value);

        printf("ADC Value: %d, PWM Value: %d\n", adc_value, pwm_value);
        usleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    gpioTerminate();
    close(spi_fd);

    return EXIT_SUCCESS;
}
