#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_4_096 0x0200
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CQUE_NONE 0x0000

#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000
#define BLINK_INTERVAL 50

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static double threshold = DEFAULT_THRESHOLD;

static void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio() {
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        led_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    return 0;
}

static int read_adc() {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_4_096 | ADS1115_CONFIG_MODE_CONTINUOUS |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD |
                      ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW |
                      ADS1115_CONFIG_CQUE_NONE;

    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write to ADS1115");
        return -1;
    }

    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    int16_t raw_value = (buffer[0] << 8) | buffer[1];
    double voltage = raw_value * 4.096 / 32767.0;
    double gauss = voltage * 1000.0; // Assuming 1V = 1000 Gauss for SS49E

    return gauss;
}

static void blink_led() {
    for (int i = 0; i < BLINK_DURATION / BLINK_INTERVAL; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(BLINK_INTERVAL * 1000);
        gpiod_line_set_value(led_line, 0);
        usleep(BLINK_INTERVAL * 1000);
    }
}

int main(int argc, char *argv[]) {
    if (argc > 2) {
        fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (argc == 2) {
        if (strcmp(argv[1], "-t") != 0) {
            fprintf(stderr, "Invalid option: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
        threshold = atof(argv[2]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value: %f\n", threshold);
            return EXIT_FAILURE;
        }
    }

    if (init_i2c() < 0 || init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        double gauss = read_adc();
        if (gauss < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            blink_led();
        }

        usleep(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

