#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define GPIO_RELAY 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define HYS_THRESHOLD 5

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int read_mcp3008(int fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret;

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tx);
    if (ret < 0) {
        log_event("SPI transfer failed");
        return -1;
    }

    uint16_t result = ((rx[1] & 3) << 8) | rx[2];
    return result;
}

void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        log_event("MQTT connected");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
    } else {
        log_event("MQTT connection failed");
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (strcmp(msg->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp((char *)msg->payload, "pump_on") == 0) {
            gpioWrite(GPIO_RELAY, 1);
            log_event("Pump turned on via MQTT");
        } else if (strcmp((char *)msg->payload, "pump_off") == 0) {
            gpioWrite(GPIO_RELAY, 0);
            log_event("Pump turned off via MQTT");
        }
    }
}

int main() {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_event("Failed to initialize GPIO");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_event("Failed to open SPI device");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        log_event("Failed to set SPI mode");
        close(spi_fd);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        log_event("Failed to set SPI bits per word");
        close(spi_fd);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        log_event("Failed to set SPI speed");
        close(spi_fd);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct mosquitto *mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_event("Failed to create MQTT client");
        close(spi_fd);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        log_event("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        close(spi_fd);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_loop_start(mosq);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_moisture = -1;
    int current_moisture = -1;

    while (running) {
        current_moisture = read_mcp3008(spi_fd, 0);
        if (current_moisture < 0) {
            current_moisture = last_moisture;
        }

        if (current_moisture != last_moisture) {
            char buffer[32];
            snprintf(buffer, sizeof(buffer), "%d", current_moisture);
            mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(buffer), buffer, 0, false);
            last_moisture = current_moisture;
        }

        if (current_moisture < MOISTURE_THRESHOLD_LOW) {
            gpioWrite(GPIO_RELAY, 1);
        } else if (current_moisture > MOISTURE_THRESHOLD_HIGH) {
            gpioWrite(GPIO_RELAY, 0);
        }

        sleep(60);
    }

    mosquitto_loop_stop(mosq, true, 1000);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);

    close(spi_fd);
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();

    closelog();
    return EXIT_SUCCESS;
}

