#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_PIN 8
#define VREF 3.3
#define SAMPLE_RATE 5

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer xfer[3];
    uint8_t tx[3][3] = {
        {1, 0x80, 0x00},
        {1, 0x90, 0x00},
        {1, 0xA0, 0x00}
    };
    uint8_t rx[3][3];
    FILE *file;
    struct gpiod_chip *chip;
    struct gpiod_line *ce_line;
    struct timespec ts;
    char timestamp[20];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ce_line = gpiod_chip_get_line(chip, CE_PIN);
    if (!ce_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce_line, "mcp3008_ce", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set SPI mode and bits per word
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open CSV file
    file = fopen("sensor_data.csv", "a");
    if (!file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read from MCP3008
        for (int i = 0; i < 3; i++) {
            xfer[i].tx_buf = (unsigned long)(tx[i]);
            xfer[i].rx_buf = (unsigned long)(rx[i]);
            xfer[i].len = 3;
            xfer[i].speed_hz = speed;
            xfer[i].bits_per_word = bits;
            xfer[i].delay_usecs = 0;
            xfer[i].cs_change = 0;
        }

        gpiod_line_set_value(ce_line, 0);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), xfer) < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }
        gpiod_line_set_value(ce_line, 1);

        // Convert ADC values to voltages
        double voltages[3];
        for (int i = 0; i < 3; i++) {
            uint16_t adc_value = ((rx[i][1] & 0x03) << 8) | rx[i][2];
            voltages[i] = (adc_value * VREF) / 1023.0;
        }

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));

        // Write to CSV file
        fprintf(file, "%s,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2]);
        fflush(file);

        // Sleep for 5 seconds
        sleep(SAMPLE_RATE);
    }

    // Clean up
    fclose(file);
    close(spi_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

