#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR_PWM_FREQ 100
#define NOISE_THRESHOLD 500
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "vibration_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

void log_vibration_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);
    fclose(log_file);
}

int main() {
    int spi_fd;
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR1_PIN, MOTOR_PWM_FREQ);
    gpioSetPWMfrequency(MOTOR2_PIN, MOTOR_PWM_FREQ);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            gpioPWM(MOTOR1_PIN, adc_value);
            gpioPWM(MOTOR2_PIN, adc_value);
            log_vibration_event("Vibration event detected");
        } else {
            gpioPWM(MOTOR1_PIN, 0);
            gpioPWM(MOTOR2_PIN, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    close(spi_fd);

    return EXIT_SUCCESS;
}

