#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MCP3008_CHANNEL 0
#define MCP3008_SPI_MODE SPI_MODE_0
#define MCP3008_SPI_BITS_PER_WORD 8
#define MCP3008_SPI_SPEED 1000000
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = MCP3008_SPI_SPEED,
        .bits_per_word = MCP3008_SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int read_bh1750(int i2c_fd) {
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("I2C write");
        return -1;
    }

    usleep(180000);

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("I2C read");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

