#define GPIO_LINE 17
#define ADC_CHANNEL 0
#define MOISTURE_THRESHOLD 30
#define RETRY_COUNT 3
#define LOG_INTERVAL 60

static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static int spi_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };
    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int retries = RETRY_COUNT;

    while (retries--) {
        if (spi_transfer(tx, rx, sizeof(rx)) < 0) {
            perror("SPI transfer failed");
            continue;
        }
        return ((rx[1] & 3) << 8) | rx[2];
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", RETRY_COUNT);
    return 0;
}

int main() {
    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "water_pump", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Failed to set SPI bits per word");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t adc_value = read_adc(ADC_CHANNEL);
        float moisture_percentage = (adc_value / 1023.0) * 100.0;
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        printf("%s - Moisture: %.2f%%\n", timestamp, moisture_percentage);

        if (moisture_percentage < MOISTURE_THRESHOLD) {
            gpiod_line_set_value(gpio_line, 1);
        } else {
            gpiod_line_set_value(gpio_line, 0);
        }

        sleep(LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}

