#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define PWM_PIN 17
#define PWM_FREQ 100
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 3) << 8) + rx[2];
}

void log_data(FILE *log_file, int adc_values[3], int average, int pwm_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, ADC1: %d, ADC2: %d, ADC3: %d, Average: %d, PWM: %d\n",
            timestamp, adc_values[0], adc_values[1], adc_values[2], average, pwm_value);
    fflush(log_file);
}

int main() {
    int spi_fd;
    FILE *log_file;
    int adc_values[3];
    int average = 0;
    int valid_samples = 0;
    int pwm_value = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);

    while (running) {
        valid_samples = 0;
        average = 0;

        for (int i = 0; i < 3; i++) {
            adc_values[i] = read_adc(spi_fd, ADC_CHANNEL);
            if (adc_values[i] >= 0) {
                average += adc_values[i];
                valid_samples++;
            }
        }

        if (valid_samples > 0) {
            average /= valid_samples;
            pwm_value = (average * 100) / 1023; // Scale to 0-100
            gpioPWM(PWM_PIN, pwm_value);
        }

        log_data(log_file, adc_values, average, pwm_value);
        sleep(LOG_INTERVAL);
    }

    gpioPWM(PWM_PIN, 0);
    fclose(log_file);
    close(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

