#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 5
#define LOG_FILE "soil_data.txt"

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("SPI_IOC_MESSAGE");
            sleep(1 << attempt); // Exponential backoff
            continue;
        }

        uint16_t result = ((rx[1] & 3) << 8) | rx[2];
        if (result >= 0 && result <= 1023) {
            return result;
        }
    }

    return -1; // Indicate failure
}

void log_data(uint16_t adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline

    if (adc_value == -1) {
        fprintf(file, "%s: Error reading ADC\n", timestamp);
    } else {
        float moisture_percentage = (1023 - adc_value) * 100.0 / 1023;
        fprintf(file, "%s: ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);
    }

    fclose(file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "spi_cs", 1) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(cs_line, 0);
        uint16_t adc_value = read_adc(ADC_CHANNEL);
        gpiod_line_set_value(cs_line, 1);

        log_data(adc_value);
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

