volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int spi_transfer(int fd, uint8_t tx, uint8_t *rx) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &tx,
        .rx_buf = (unsigned long) rx,
        .len = 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

uint16_t read_adc(int fd) {
    uint8_t tx = 0b11000000 | (ADC_CHANNEL << 3); // Start bit, single-ended, channel
    uint8_t rx[2] = {0};
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (spi_transfer(fd, tx, rx) == 0) {
            return ((rx[0] & 0x03) << 8) | rx[1];
        }
        retries--;
        if (retries == 0) {
            perror("SPI transfer failed after retries");
            close(fd);
            fd = open(SPI_DEVICE, O_RDWR);
            if (fd < 0) {
                perror("Failed to reinitialize SPI");
                exit(EXIT_FAILURE);
            }
        }
        sleep(RETRY_DELAY);
    }
    return 0;
}

double compute_aqi(uint16_t adc_value) {
