            gpioWrite(FAN_GPIO, PI_HIGH);
        } else {
            gpioWrite(FAN_GPIO, PI_LOW);
        }

        sleep(5);
    }

    gpioWrite(FAN_GPIO, PI_LOW);
    gpioTerminate();
    fclose(log_file);
    close(spi_fd);

    return 0;
}

