#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0

#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

#define PWM_PERIOD 1000000 // 1 second
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000000

#define ACCELERATION_STEPS 10
#define DECELERATION_STEPS 10
#define CONSTANT_SPEED_DURATION 2

static struct gpiod_chip *chip;
static struct gpiod_line *motor1_enable, *motor1_direction, *motor2_enable, *motor2_direction;
static int spi_fd;

void cleanup() {
    if (motor1_enable) gpiod_line_release(motor1_enable);
    if (motor1_direction) gpiod_line_release(motor1_direction);
    if (motor2_enable) gpiod_line_release(motor2_enable);
    if (motor2_direction) gpiod_line_release(motor2_direction);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void set_motor_speed(struct gpiod_line *enable, struct gpiod_line *direction, uint16_t speed) {
    if (speed > PWM_DUTY_MAX) speed = PWM_DUTY_MAX;
    if (speed < PWM_DUTY_MIN) speed = PWM_DUTY_MIN;

    for (int i = 0; i < ACCELERATION_STEPS; i++) {
        gpiod_line_set_value(enable, 1);
        usleep((i + 1) * (PWM_PERIOD / ACCELERATION_STEPS));
    }

    usleep(CONSTANT_SPEED_DURATION * 1000000);

    for (int i = DECELERATION_STEPS; i > 0; i--) {
        gpiod_line_set_value(enable, 1);
        usleep((i - 1) * (PWM_PERIOD / DECELERATION_STEPS));
    }

    gpiod_line_set_value(enable, 0);
}

int main() {
    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

