        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor1_enable, "motor1_enable", 0) < 0 ||
        gpiod_line_request_output(motor1_direction, "motor1_direction", 0) < 0 ||
        gpiod_line_request_output(motor2_enable, "motor2_enable", 0) < 0 ||
        gpiod_line_request_output(motor2_direction, "motor2_direction", 0) < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t pot1_value = read_adc(POT1_CHANNEL);
        uint16_t pot2_value = read_adc(POT2_CHANNEL);

        if (pot1_value == 0 || pot2_value == 0) {
            printf("Potentiometer error, skipping cycle.\n");
            sleep(1);
            continue;
        }

        uint16_t motor1_speed = (pot1_value * PWM_DUTY_MAX) / 1023;
        uint16_t motor2_speed = (pot2_value * PWM_DUTY_MAX) / 1023;

        gpiod_line_set_value(motor1_direction, 0);
        gpiod_line_set_value(motor2_direction, 0);
        set_motor_speed(motor1_enable, motor1_direction, motor1_speed);
        set_motor_speed(motor2_enable, motor2_direction, motor2_speed);

        sleep(5);

        gpiod_line_set_value(motor1_direction, 1);
        gpiod_line_set_value(motor2_direction, 1);
        set_motor_speed(motor1_enable, motor1_direction, motor1_speed);
        set_motor_speed(motor2_enable, motor2_direction, motor2_speed);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

