        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

