            if (last_state == 0 || (current_time.tv_sec - last_toggle_time.tv_sec) * 1000 + (current_time.tv_nsec - last_toggle_time.tv_nsec) / 1000000 >= DEBOUNCE_MS) {
                gpiod_line_set_value(led_line, 1);
                last_state = 1;
                last_toggle_time = current_time;
