                gpiod_line_set_value(led_line, 0);
                last_state = 0;
            }
        }

        usleep(10000); // 10 ms
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(cs_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

