#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds

#define CALIBRATION_SLOPE 1.0
#define CALIBRATION_INTERCEPT 0.0

#define LOG_FILE "airflow_log.txt"

static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *ce_line = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (ce_line) {
        gpiod_line_release(ce_line);
        ce_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int read_adc(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        log_message("ERROR: ADC read failed");
        return -1;
    }

    int result = ((rx[1] & 3) << 8) + rx[2];
    return result;
}

double convert_voltage_to_airflow(int adc_value) {
    double voltage = (adc_value * 3.3) / 1023.0;
    return CALIBRATION_SLOPE * voltage + CALIBRATION_INTERCEPT;
}

int main() {
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO for chip enable
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    ce_line = gpiod_chip_get_line(gpio_chip, 8); // Assuming CE0 is on GPIO 8
    if (!ce_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce_line, "spi-ce", 1) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        // Trigger ADC read
        gpiod_line_set_value(ce_line, 0);
        int adc_value = read_adc(ADC_CHANNEL);
        gpiod_line_set_value(ce_line, 1);

        if (adc_value >= 0) {
            double airflow = convert_voltage_to_airflow(adc_value);
            char log_entry[100];
            snprintf(log_entry, sizeof(log_entry), "Airflow: %.2f m³/h", airflow);
            log_message(log_entry);
        }

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

