#define RETRY_DELAY 100000 // 100 ms
#define LOG_FILE "gas_log.txt"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };
    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

uint16_t read_adc_channel(int fd, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3] = {0};
    int ret;

    while (running) {
        ret = spi_transfer(fd, tx, rx, 3);
        if (ret < 0) {
            perror("SPI transfer failed");
            usleep(RETRY_DELAY);
            continue;
        }
        break;
    }

    if (!running) return 0;

    return ((rx[1] & 3) << 8) | rx[2];
}

void log_data(const char *filename, double voltage, double ppm) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, voltage, ppm);
    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t adc_value = read_adc_channel(spi_fd, ADC_CHANNEL);
        double voltage = (adc_value * 3.3) / 1023.0;
        double ppm = 100.0; // Placeholder PPM value

        printf("Voltage: %.2f V, PPM: %.2f\n", voltage, ppm);
        log_data(LOG_FILE, voltage, ppm);

        sleep(1);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

