This code sets up a Raspberry Pi to read from a Honeywell MICROpeL MP-741 combustible gas sensor using an MCP3008 ADC over SPI. It handles SPI initialization, retries on transfer failures, logs data with timestamps, and ensures proper cleanup on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_REF_VOLTAGE 3.3
#define ADC_RESOLUTION 1024.0
#define GRAVITY 9.81

#define GPIO_CS 8

#define KALMAN_Q 0.01
#define KALMAN_R 0.1

typedef struct {
    double x, y, z;
} Acceleration;

typedef struct {
    double x, y, z;
    double p_x, p_y, p_z;
} KalmanState;

KalmanState kalman_state = {0, 0, 0, 1, 1, 1};

void kalman_filter(double measurement, double *state, double *p) {
    *state = *state + *p * (measurement - *state);
    *p = *p * (1 - *p) + KALMAN_Q;
}

void handle_sigint(int sig) {
    printf("Exiting...\n");
    exit(0);
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    struct spi_ioc_transfer spi_transfer;
    uint8_t tx[3] = {1, 0, 0};
    uint8_t rx[3];
    double x, y, z;
    Acceleration raw_accel, filtered_accel;

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_CS);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "adxl335_mcp3008", 1) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        // Read X axis
        gpiod_line_set_value(cs_line, 0);
        spi_transfer.tx_buf = (unsigned long)tx;
        spi_transfer.rx_buf = (unsigned long)rx;
        spi_transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to transfer SPI message");
            break;
        }
        gpiod_line_set_value(cs_line, 1);
        raw_accel.x = ((rx[1] << 8) | rx[2]) & 0x3FF;

        // Read Y axis
        gpiod_line_set_value(cs_line, 0);
        spi_transfer.tx_buf = (unsigned long)tx;
        spi_transfer.rx_buf = (unsigned long)rx;
        spi_transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to transfer SPI message");
            break;
        }
        gpiod_line_set_value(cs_line, 1);
        raw_accel.y = ((rx[1] << 8) | rx[2]) & 0x3FF;

        // Read Z axis
        gpiod_line_set_value(cs_line, 0);
        spi_transfer.tx_buf = (unsigned long)tx;
        spi_transfer.rx_buf = (unsigned long)rx;
        spi_transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to transfer SPI message");
            break;
        }
        gpiod_line_set_value(cs_line, 1);
        raw_accel.z = ((rx[1] << 8) | rx[2]) & 0x3FF;

        // Convert raw values to voltage
        x = (raw_accel.x / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
        y = (raw_accel.y / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
        z = (raw_accel.z / ADC_RESOLUTION) * ADC_REF_VOLTAGE;

        // Convert voltage to acceleration in g
        filtered_accel.x = (x - 0.5) * 2 * GRAVITY;
        filtered_accel.y = (y - 0.5) * 2 * GRAVITY;
        filtered_accel.z = (z - 0.5) * 2 * GRAVITY;

        // Apply Kalman filter
        kalman_filter(filtered_accel.x, &kalman_state.x, &kalman_state.p_x);
        kalman_filter(filtered_accel.y, &kalman_state.y, &kalman_state.p_y);
        kalman_filter(filtered_accel.z, &kalman_state.z, &kalman_state.p_z);

        // Print filtered values
        printf("Filtered Acceleration: X = %.2f g, Y = %.2f g, Z = %.2f g\n",
               kalman_state.x, kalman_state.y, kalman_state.z);

        // Sleep for 100ms to achieve 10Hz
        usleep(100000);
    }

    // Clean up
    close(spi_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

