    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        // Read X axis
        gpiod_line_set_value(cs_line, 0);
        spi_transfer.tx_buf = (unsigned long)tx;
        spi_transfer.rx_buf = (unsigned long)rx;
        spi_transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to transfer SPI message");
            break;
        }
        gpiod_line_set_value(cs_line, 1);
        raw_accel.x = ((rx[1] << 8) | rx[2]) & 0x3FF;

        // Read Y axis
        gpiod_line_set_value(cs_line, 0);
        spi_transfer.tx_buf = (unsigned long)tx;
        spi_transfer.rx_buf = (unsigned long)rx;
        spi_transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to transfer SPI message");
            break;
        }
        gpiod_line_set_value(cs_line, 1);
        raw_accel.y = ((rx[1] << 8) | rx[2]) & 0x3FF;

        // Read Z axis
        gpiod_line_set_value(cs_line, 0);
        spi_transfer.tx_buf = (unsigned long)tx;
        spi_transfer.rx_buf = (unsigned long)rx;
        spi_transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to transfer SPI message");
            break;
        }
        gpiod_line_set_value(cs_line, 1);
        raw_accel.z = ((rx[1] << 8) | rx[2]) & 0x3FF;

        // Convert raw values to voltage
        x = (raw_accel.x / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
        y = (raw_accel.y / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
        z = (raw_accel.z / ADC_RESOLUTION) * ADC_REF_VOLTAGE;

        // Convert voltage to acceleration in g
        filtered_accel.x = (x - 0.5) * 2 * GRAVITY;
        filtered_accel.y = (y - 0.5) * 2 * GRAVITY;
        filtered_accel.z = (z - 0.5) * 2 * GRAVITY;

        // Apply Kalman filter
        kalman_filter(filtered_accel.x, &kalman_state.x, &kalman_state.p_x);
        kalman_filter(filtered_accel.y, &kalman_state.y, &kalman_state.p_y);
        kalman_filter(filtered_accel.z, &kalman_state.z, &kalman_state.p_z);

        // Print filtered values
        printf("Filtered Acceleration: X = %.2f g, Y = %.2f g, Z = %.2f g\n",
               kalman_state.x, kalman_state.y, kalman_state.z);

        // Sleep for 100ms to achieve 10Hz
        usleep(100000);
    }

    // Clean up
    close(spi_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
