        double sensor1_mT = convert_to_mT(sensor1_value);
        double sensor2_mT = convert_to_mT(sensor2_value);
        double sensor3_mT = convert_to_mT(sensor3_value);

        if (sensor1_mT < -100.0 || sensor1_mT > 100.0 ||
            sensor2_mT < -100.0 || sensor2_mT > 100.0 ||
            sensor3_mT < -100.0 || sensor3_mT > 100.0) {
            fprintf(stderr, "Magnetic field out of range\n");
            continue;
        }

        fprintf(log_file, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_US);
    }

    return EXIT_SUCCESS;
}

