#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

static struct gpiod_chip *chip;
static struct gpiod_line *pump_line;
static int spi_fd;
static volatile sig_atomic_t running = 1;

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), message);
    fclose(log);
}

void handle_signal(int sig) {
    running = 0;
    log_event("Received signal to terminate");
}

int read_adc(int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    int result = ((rx[1] & 3) << 8) + rx[2];
    return result;
}

void control_pump(int moisture) {
    int state = moisture < MOISTURE_THRESHOLD;
    if (gpiod_line_set_value(pump_line, state) < 0) {
        perror("Failed to set pump state");
    } else {
        log_event(state ? "Pump turned ON" : "Pump turned OFF");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO);
    if (!pump_line) {
        perror("Failed to get pump GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pump_line, "watering_system", 0) < 0) {
        perror("Failed to request pump GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (running) {
        int moisture = read_adc(ADC_CHANNEL);
        if (moisture < 0) {
            log_event("ADC read failed");
        } else {
            control_pump(moisture);
        }
        sleep(60);
    }

    gpiod_line_set_value(pump_line, 0);
    log_event("Pump turned OFF on shutdown");
    log_event("Program terminated");

    close(spi_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

