#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000

#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define MCP3008_CHANNEL_2 2

#define CSV_FILE "sensor_data.csv"

int spi_fd = -1;
FILE *csv_file = NULL;

void cleanup() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

void sigint_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(EXIT_SUCCESS);
}

unsigned short read_mcp3008_channel(int channel) {
    unsigned char tx[] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        cleanup();
        exit(EXIT_FAILURE);
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("fopen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        unsigned short channel0 = read_mcp3008_channel(MCP3008_CHANNEL_0);
        unsigned short channel1 = read_mcp3008_channel(MCP3008_CHANNEL_1);
        unsigned short channel2 = read_mcp3008_channel(MCP3008_CHANNEL_2);

        if (fprintf(csv_file, "%hu,%hu,%hu\n", channel0, channel1, channel2) < 0) {
            perror("fprintf");
            cleanup();
            exit(EXIT_FAILURE);
        }

        fflush(csv_file);
        sleep(1);
    }

    cleanup();
    return 0;
}

