#include <mosquitto.h>
#include <jansson.h>

#define LED_GPIO_LINE 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define MAX_RECONNECT_DELAY 60

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct mosquitto *mosq = NULL;
static int reconnect_delay = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "%s: %s\n", ctime(&now), message);
}

static void signal_handler(int signum) {
    if (mosq) {
        mosquitto_disconnect(mosq);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

static void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        log_error("Failed to connect to MQTT broker");
        reconnect_delay = 1;
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (strcmp(msg->topic, MQTT_TOPIC) == 0) {
        json_error_t error;
        json_t *root = json_loadb(msg->payload, msg->payloadlen, 0, &error);
        if (!root) {
            log_error("JSON parsing error");
            return;
        }

        json_t *led_state = json_object_get(root, "led_state");
        if (json_is_boolean(led_state)) {
            int value = json_boolean_value(led_state);
            if (gpiod_line_set_value(led_line, value) < 0) {
                log_error("Failed to set GPIO value");
            }
        } else {
            log_error("Invalid JSON payload");
        }

        json_decref(root);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("Unexpected disconnection from MQTT broker");
        sleep(reconnect_delay);
        if (reconnect_delay < MAX_RECONNECT_DELAY) {
            reconnect_delay *= 2;
        }
        mosquitto_reconnect(mosq);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "rpi_led_control", 0) < 0) {
        log_error("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_loop_start(mosq);

    while (1) {
        sleep(1);
    }

    mosquitto_loop_stop(mosq, true);
    mosquitto_destroy(mosq);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    mosquitto_lib_cleanup();

    return EXIT_SUCCESS;
}

