#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define SENSOR_GPIO 17
#define LED_GPIO 18
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *led_line;
    int ret;

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("gpiod_chip_get_line (sensor)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_input(sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input (sensor)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line (led)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (led)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("Sound level: %d\n", sensor_value);

        if (sensor_value == 0) {
            // Trigger alarm
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value (led on)");
                break;
            }
            usleep(1000000); // 1 second
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value (led off)");
                break;
            }
        }

        usleep(POLL_DELAY_US);
    }

    // Clean up
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

