#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define CONSUMER_LABEL "vibration-monitor"
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log, "[%s] %s\n", timestamp, message);
    fclose(log);

    printf("%s\n", message);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handlers");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_event(line, CONSUMER_LABEL);
    if (ret < 0) {
        perror("Failed to request event on GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!exit_flag) {
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for event on GPIO line");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read event on GPIO line");
            break;
        }

        if (event.type == GPIOD_LINE_EVENT_RISING_EDGE) {
            log_event("Rising edge detected (should not happen)");
        } else if (event.type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event("Falling edge detected: Vibration threshold exceeded");
            system("sudo shutdown -h now");
            break;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

