#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "altitude_log.txt"

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

