static struct gpiod_line *ce0_line;
static int spi_fd;
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;
static FILE *log_file = NULL;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_gpio() {
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ce0_line = gpiod_chip_get_line(chip, CE0_PIN);
    if (!ce0_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(ce0_line, "mcp3008_ce0", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

float read_temperature() {
    int adc_value = read_adc(0);
    if (adc_value < 0) {
        return -1.0;
    }
    return (adc_value * 330.0) / 1023.0;
}

void log_temperature(float temp) {
    buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (log_file) {
        if (fseek(log_file, 0, SEEK_SET) != 0) {
            perror("Failed to seek to start of log file");
            return;
        }
        if (fwrite(buffer, sizeof(float), BUFFER_SIZE, log_file) != BUFFER_SIZE) {
            perror("Failed to write to log file");
        }
        if (fflush(log_file) != 0) {
            perror("Failed to flush log file");
        }
    }
}

int main() {
    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("temp_log.dat", "wb+");
    if (!log_file) {
        perror("Failed to open log file");
        printf("Continuing without file logging.\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpiod_line_set_value(ce0_line, 0);
        float temp = read_temperature();
        gpiod_line_set_value(ce0_line, 1);

        if (temp >= 0.0) {
            printf("Temperature: %.2f °C\n", temp);
            log_temperature(temp);
        } else {
            printf("Failed to read temperature, skipping.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

