        log_file = NULL;
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up and exiting.\n", signum);
    cleanup();
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    int ret;

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request the line for input with a pull-down resistor
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        cleanup();
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_set_bias");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        int value;
        char timestamp[20];

        // Get the current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            cleanup();
            exit(EXIT_FAILURE);
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Read the line value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            cleanup();
            exit(EXIT_FAILURE);
        }

        // Log the event
        fprintf(log_file, "%s,%d,%d\n", timestamp, GPIO_LINE, value);
        fflush(log_file);

        // Print an alarm message if the sensor reports a HIGH
        if (value == 1) {
            printf("ALARM: Flame detected at %s\n", timestamp);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on normal termination
    cleanup();
    return 0;
}

