#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define TMP36_CHANNEL 0
#define MCP4725_ADDRESS 0x60
#define SPI_SPEED 500000
#define SAMPLE_INTERVAL 500000 // 0.5 seconds in microseconds

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };
    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

int i2c_write(int fd, uint8_t reg, uint16_t data) {
    uint8_t buf[3] = {reg, data >> 8, data & 0xFF};
    return write(fd, buf, 3);
}

double adc_to_temp(uint16_t adc) {
    return ((adc * 3300.0 / 1024.0) - 500.0) / 10.0;
}

uint16_t temp_to_dac(double temp) {
    return (uint16_t)(temp * 100.0);
}

int main() {
    int spi_fd = -1, i2c_fd = -1, log_fd = -1;
    uint8_t tx[3] = {1, 0, 0};
    uint8_t rx[3] = {0};
    uint16_t adc_value;
    double temperature;
    uint16_t dac_value;
    struct sigaction sa;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        goto cleanup;
    }

    // Open log file
    log_fd = open("temperature_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        goto cleanup;
    }

    while (running) {
        // Read ADC value
        tx[1] = (TMP36_CHANNEL << 6) | 0x80;
        if (spi_transfer(spi_fd, tx, rx, 3) < 0) {
            perror("SPI transfer failed");
            sleep(1);
            continue;
        }
        adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert ADC to temperature
        temperature = adc_to_temp(adc_value);

        // Convert temperature to DAC value
        dac_value = temp_to_dac(temperature);

        // Write DAC value
        if (i2c_write(i2c_fd, 0x40, dac_value) < 0) {
            perror("I2C write failed");
            sleep(1);
            continue;
        }

        // Log and print the data
        {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("%s, ADC: %u, Temp: %.2f°C, DAC: %u\n", timestamp, adc_value, temperature, dac_value);
            dprintf(log_fd, "%s, ADC: %u, Temp: %.2f°C, DAC: %u\n", timestamp, adc_value, temperature, dac_value);
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

cleanup:
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fd >= 0) close(log_fd);
    return 0;
}

