#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define LOG_FILE "soil_data.txt"

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;

static void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int signum) {
    printf("Received SIGINT, cleaning up and exiting.\n");
    cleanup();
    exit(0);
}

static uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0xFFFF; // Invalid value
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

static void log_data(uint16_t *values) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (values[i] == 0xFFFF) {
            fprintf(stderr, "Invalid ADC value for sensor %d\n", i);
            continue;
        }
        fprintf(log_file, "%s Sensor %d: %d\n", timestamp, i, values[i]);
    }
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
