#define RELAY3 23
#define RELAY4 24

#define ARRAY_SIZE(arr) (sizeof(arr) / sizeof((arr)[0]))

struct gpiod_chip *chip;
struct gpiod_line *relays[4];
volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void cleanup() {
    for (int i = 0; i < ARRAY_SIZE(relays); i++) {
        if (relays[i]) {
            gpiod_line_release(relays[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int ret;

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    for (int i = 0; i < ARRAY_SIZE(relays); i++) {
        relays[i] = gpiod_chip_get_line(chip, RELAY1 + i);
        if (!relays[i]) {
            perror("gpiod_chip_get_line");
            cleanup();
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_request_output(relays[i], "relay_seq", 0);
        if (ret < 0) {
            perror("gpiod_line_request_output");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    while (running) {
        for (int i = 0; i < ARRAY_SIZE(relays); i++) {
            ret = gpiod_line_set_value(relays[i], 1);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            sleep(1);
            ret = gpiod_line_set_value(relays[i], 0);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            sleep(1);
        }
    }

    // Cleanup
    cleanup();
    return 0;
}

