    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void setup_gpio() {
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "sound_sensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    setup_gpio();
    setup_spi();

    while (running) {
        uint16_t adc_value = read_adc(ADC_CHANNEL);
        if (adc_value > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            log_event("Sound threshold exceeded");
            usleep(DEBOUNCE_DELAY);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

