#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pthread.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define LOG_FILE "rain_log.txt"
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define PWM_DUTY 150
#define PWM_PERIOD 255
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

volatile sig_atomic_t stop_program = 0;

void signal_handler(int signum) {
    stop_program = 1;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };
    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

void log_rain_level(FILE *log_file, int rain_level) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file);
}

void control_motor(struct gpiod_chip *chip, int direction) {
    struct gpiod_line *in1 = gpiod_chip_get_line(chip, MOTOR_IN1);
    struct gpiod_line *in2 = gpiod_chip_get_line(chip, MOTOR_IN2);
    struct gpiod_line *ena = gpiod_chip_get_line(chip, MOTOR_ENA);

    if (!in1 || !in2 || !ena) {
        perror("Failed to get GPIO lines");
        return;
    }

    if (gpiod_line_request_output(in1, "rain_sensor", 0) < 0 ||
        gpiod_line_request_output(in2, "rain_sensor", 0) < 0 ||
        gpiod_line_request_output(ena, "rain_sensor", 0) < 0) {
        perror("Failed to request GPIO lines");
        return;
    }

    gpiod_line_set_value(in1, direction);
    gpiod_line_set_value(in2, !direction);
    gpiod_line_set_value(ena, 1);

    usleep(3000000);

    gpiod_line_set_value(ena, 0);
}

int main() {
    int spi_fd;
    FILE *log_file;
    struct gpiod_chip *chip;
    uint8_t tx[3] = {1, 0, 0};
    uint8_t rx[3];
    int rain_level;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (!stop_program) {
        tx[1] = 0x80 | (0x07 << 4);
        if (spi_transfer(spi_fd, tx, rx, 3) < 0) {
            perror("SPI transfer failed");
        } else {
            rain_level = ((rx[1] & 0x03) << 8) | rx[2];
            log_rain_level(log_file, rain_level);

            if (rain_level > RAIN_THRESHOLD) {
                control_motor(chip, MOTOR_FORWARD);
            } else {
                control_motor(chip, MOTOR_REVERSE);
            }
        }
        sleep(1);
    }

    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

