#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define ADC_PIN 26
#define LED_PIN 16
#define SAMPLES 10
#define THRESHOLD 500
#define DEBOUNCE_US 50000
#define LED_DURATION_US 500000

static struct gpiod_chip *chip;
static struct gpiod_line *adc_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (adc_line) {
        gpiod_line_release(adc_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int read_adc() {
    int sum = 0;
    for (int i = 0; i < SAMPLES; i++) {
        if (gpiod_line_set_value(adc_line, 1) < 0) {
            perror("Failed to set ADC line high");
            return -1;
        }
        usleep(1);
        if (gpiod_line_set_value(adc_line, 0) < 0) {
            perror("Failed to set ADC line low");
            return -1;
        }
        usleep(1);
        int value = gpiod_line_get_value(adc_line);
        if (value < 0) {
            perror("Failed to read ADC line");
            return -1;
        }
        sum += value;
    }
    return sum / SAMPLES;
}

int main() {
    signal(SIGINT, sigint_handler);
    atexit(cleanup);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    adc_line = gpiod_chip_get_line(chip, ADC_PIN);
    if (!adc_line) {
        perror("Failed to get ADC line");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line as output");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(adc_line, "adc") < 0) {
        perror("Failed to request ADC line as input");
        return EXIT_FAILURE;
    }

    struct timespec last_clap_time = {0};
    while (running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        if (adc_value > THRESHOLD) {
            if (timespec_subtract(&current_time, &last_clap_time) > DEBOUNCE_US) {
                last_clap_time = current_time;
                printf("Clap detected at %ld.%09ld\n", current_time.tv_sec, current_time.tv_nsec);

                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("Failed to set LED line high");
                    continue;
                }
                usleep(LED_DURATION_US);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("Failed to set LED line low");
                    continue;
                }
            }
        }
        usleep(10000); // 10 ms delay
    }

    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, struct timespec *x, struct timespec *y) {
    if (x->tv_nsec < y->tv_nsec) {
        int nsec = (y->tv_nsec - x->tv_nsec) / 1000000000 + 1;
        y->tv_nsec -= 1000000000 * nsec;
        y->tv_sec += nsec;
    }
    if (x->tv_nsec - y->tv_nsec > 1000000000) {
        int nsec = (x->tv_nsec - y->tv_nsec) / 1000000000;
        y->tv_nsec += 1000000000 * nsec;
        y->tv_sec -= nsec;
    }

    result->tv_sec = x->tv_sec - y->tv_sec;
    result->tv_nsec = x->tv_nsec - y->tv_nsec;

    return x->tv_sec < y->tv_sec;
}

