#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define RELAY_PIN 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down gracefully...\n");
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0xFFFF; // Invalid value
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void log_entry(uint16_t adc_value, int pump_status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    double moisture_percentage = (100.0 * (4095 - adc_value)) / 4095;
    fprintf(log_file, "%s, %.2f%%, %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        cleanup();
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "soil_moisture", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == 0xFFFF) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(60);
            continue;
        }

        int pump_status = 0;
        double moisture_percentage = (100.0 * (4095 - adc_value)) / 4095;
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            pump_status = 1;
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        log_entry(adc_value, pump_status);
        sleep(60);
    }

    cleanup();
    return EXIT_SUCCESS;
}

