    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    double moisture_percentage = (100.0 * (4095 - adc_value)) / 4095;
    fprintf(log_file, "%s, %.2f%%, %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

