    struct sigaction sa;
    struct spi_ioc_transfer xfer;
    uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];
    int ret;
    double current_A;
    struct timeval tv;
    char timestamp[20];

