    gpiod_line_set_value(gpio_line, 1);

    while (1) {
        // Read ADC
        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = sizeof(tx);
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("Failed to read from SPI");
            continue;
        }

        // Convert ADC reading to voltage
        uint16_t adc_value = ((rx[1] & 3) << 8) | rx[2];
        double voltage_V = adc_value * SENSOR_SCALE;

        // Convert voltage to current
        current_A = voltage_V * SENSOR_CURRENT_SCALE;

        // Get timestamp
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

        // Log current
        fprintf(log_file, "%s,%.3f\n", timestamp, current_A);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

