#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_DELAY_US 2000
#define DEBOUNCE_COUNT 5
#define LOG_INTERVAL_US 1000000

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;

void cleanup() {
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void sigint_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Failed to read sensor value");
        exit(EXIT_FAILURE);
    }
    return value;
}

int debounce_sensor(struct gpiod_line *line) {
    int count = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        int value = read_sensor(line);
        if (value == 0) {
            count++;
        }
        usleep(DEBOUNCE_DELAY_US);
    }
    return count > DEBOUNCE_COUNT / 2 ? 0 : 1;
}

int main() {
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

