#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>
#include <errno.h>

#define SPI_CHANNEL(0)
#define SPI_BAUD(1000000)
#define MCP3008_CHANNEL(0)
#define READ_DELAY(60)
#define MIN_ADC(300)
#define MAX_ADC(800)
#define LOG_FILE("soil_moisture_log.csv")

typedef struct {
    int channel;
    unsigned int speed_hz;
} spi_config_t;

volatile sig_atomic_t running = 1;

void signal_handler(int signal) {
    running = 0;
}

int spi_setup(spi_config_t config) {
    struct gpiod_chip *chip;
    struct gpiod_line *cs;
    int spi_fd;

    chip = gpiod_chip_open("/dev/spidev0.0");
    if (!chip) {
        perror("Failed to open SPI device");
        return -1;
    }

    cs = gpiod_chip_get_line(chip, 0);
    if (!cs) {
        perror("Failed to get SPI chip select line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs, "mcp3008_cs", 1) < 0) {
        perror("Failed to request SPI chip select line");
        gpiod_chip_close(chip);
        return -1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        return -1;
    }

    return spi_fd;
}

int read_mcp3008(int channel) {
    unsigned char tx[] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3];
    int spi_fd = spi_setup((spi_config_t){SPI_CHANNEL, SPI_BAUD});
    if (spi_fd < 0) {
        return -1;
    }

    if (write(spi_fd, tx, 3) != 3) {
        perror("Failed to write to SPI");
        close(spi_fd);
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("Failed to read from SPI");
        close(spi_fd);
        return -1;
    }

    close(spi_fd);
    return ((rx[1] & 3) << 8) + rx[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return 100.0 * (MAX_ADC - adc_value) / (MAX_ADC - MIN_ADC);
}

void log_data(double moisture_level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture_level);
    fprintf(stdout, "%s,%.2f\n", timestamp, moisture_level);

    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    return 0;
}

