#include <sys/stat.h>
#include <sys/wait.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_DELAY 200000 // 200 ms in microseconds
#define POLL_INTERVAL 50000   // 50 ms in microseconds
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_CMD "libcamera-still"
#define CAPTURE_ARGS { CAPTURE_CMD, "-o", NULL }

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int ensure_directory_exists(const char *path) {
    struct stat st;
    if (stat(path, &st) == -1) {
        if (mkdir(path, 0755) == -1) {
            perror("mkdir");
            return -1;
        }
    }
    return 0;
}

int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return -1;
    } else if (pid == 0) {
        char *args[] = CAPTURE_ARGS;
        args[2] = (char *)filename;
        execvp(args[0], args);
        perror("execvp");
        exit(EXIT_FAILURE);
    } else {
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            return -1;
        }
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            return 0;
        } else {
            return -1;
        }
    }
}

int main() {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    log_event("Startup");

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_event("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "security_cam");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        log_event("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_set_bias");
        log_event("Failed to set GPIO line bias to pull-down");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory_exists(CAPTURE_DIR) == -1) {
        log_event("Failed to ensure capture directory exists");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    struct timespec last_change_time;
    clock_gettime(CLOCK_MONOTONIC, &last_change_time);

    while (running) {
        int current_state = gpiod_line_get_value(line);
        if (current_state != last_state) {
            clock_gettime(CLOCK_MONOTONIC, &last_change_time);
            last_state = current_state;
        } else {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (now.tv_sec > last_change_time.tv_sec + 0.2) {
                if (current_state == 1) {
                    char filename[256];
                    time_t t = time(NULL);
                    struct tm tm = *localtime(&t);
                    snprintf(filename, sizeof(filename), "%s%d-%02d-%02dT%02d-%02d-%02d.jpg",
                             CAPTURE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                             tm.tm_hour, tm.tm_min, tm.tm_sec);

                    log_event("Motion detected, capturing image");
                    if (capture_image(filename) == 0) {
                        log_event("Capture successful");
                    } else {
                        log_event("Capture failed");
                    }
                }
                last_state = 0;
            }
        }
        usleep(POLL_INTERVAL);
    }

    log_event("Shutdown");
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

