        perror("ioctl VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; i++) {
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf[i]) == -1) {
            perror("ioctl VIDIOC_QUERYBUF");
            close(fd);
            return EXIT_FAILURE;
        }

        void *buffer_start = mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
        if (buffer_start == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return EXIT_FAILURE;
