            packet[10] = (total_fragments >> 8) & 0xFF;
            packet[11] = total_fragments & 0xFF;

            memcpy(packet + HEADER_SIZE, (char *)buf[0].m.offset + fragment_index * (UDP_PAYLOAD_SIZE - HEADER_SIZE), payload_size);

            if (sendto(sockfd, packet, HEADER_SIZE + payload_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
