        if (ioctl(fd, VIDIOC_QBUF, &buf[0]) == -1) {
            perror("ioctl VIDIOC_QBUF");
            break;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("ioctl VIDIOC_STREAMOFF");
    }

