#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void *start;
    size_t length;
};

static int fd = -1;
static struct buffer *buffers;
static unsigned int n_buffers;
static FILE *file = NULL;

void errno_exit(const char *s) {
    perror(s);
    exit(EXIT_FAILURE);
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    if (-1 == r) {
        errno_exit(s);
    }

    return r;
}

void process_image(const void *p, size_t len) {
    if (fwrite(p, 1, len, file) != len) {
        perror("fwrite");
        exit(EXIT_FAILURE);
    }
}

int init_device(void) {
    struct v4l2_capability cap;
    struct v4l2_cropcap cropcap;
    struct v4l2_crop crop;
    struct v4l2_format fmt;
    unsigned int min;

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is no V4L2 device\n", "/dev/video0");
        } else {
            perror("VIDIOC_QUERYCAP");
        }
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming i/o\n");
        return 1;
    }

    CLEAR(cropcap);

    cropcap.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (0 == xioctl(fd, VIDIOC_CROPCAP, &cropcap)) {
        crop.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        crop.c = cropcap.defrect; /* reset to default */

        if (-1 == xioctl(fd, VIDIOC_S_CROP, &crop)) {
            switch (errno) {
            case EINVAL:
                /* Cropping not supported. */
                break;
            default:
                /* Errors ignored. */
                break;
            }
        }
    } else {
        /* Errors ignored. */
    }

    CLEAR(fmt);

    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = 192;
    fmt.fmt.pix.height      = 144; /* Assuming 144 for MJPEG */
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        return 1;
    }

    /* Note VIDIOC_S_FMT may change width and height. */

    /* Buggy driver paranoia. */
    min = fmt.fmt.pix.width * 2;
    if (fmt.fmt.pix.bytesperline < min) {
        fmt.fmt.pix.bytesperline = min;
    }
    min = fmt.fmt.pix.bytesperline * fmt.fmt.pix.height;
    if (fmt.fmt.pix.sizeimage < min) {
        fmt.fmt.pix.sizeimage = min;
    }

    CLEAR(crop);

    crop.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    crop.c = fmt.fmt.pix;

    if (-1 == xioctl(fd, VIDIOC_S_CROP, &crop)) {
        switch (errno) {
        case EINVAL:
            /* Cropping not supported. */
            break;
        default:
            /* Errors ignored. */
            break;
        }
    }

    return 0;
}

int init_mmap(void) {
    struct v4l2_requestbuffers req;

    CLEAR(req);

    req.count               = 4;
    req.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory              = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", "/dev/video0");
        } else {
            perror("VIDIOC_REQBUFS");
        }
        return 1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", "/dev/video0");
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        return 1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start =
            mmap(NULL /* start anywhere */,
                  buf.length,
                  PROT_READ | PROT_WRITE /* required */,
                  MAP_SHARED /* recommended */,
                  fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            return 1;
        }
    }

    return 0;
}

int start_capturing(void) {
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            return 1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        return 1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct v4l2_buffer buf;
    unsigned int i;

    signal(SIGINT, exit);
    signal(SIGTERM, exit);

    fd = open("/dev/video0", O_RDWR /* required */);
    if (-1 == fd) {
        perror("Cannot open /dev/video0");
        exit(EXIT_FAILURE);
    }

    if (init_device()) {
        exit(EXIT_FAILURE);
    }

    if (init_mmap()) {
        exit(EXIT_FAILURE);
    }

    if (start_capturing()) {
        exit(EXIT_FAILURE);
    }

    file = fopen("image.jpg", "wb");
    if (!file) {
        perror("Cannot open image.jpg");
        exit(EXIT_FAILURE);
    }

    CLEAR(buf);

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        switch (errno) {
        case EAGAIN:
            fprintf(stderr, "Resource temporarily unavailable\n");
            break;
        case EIO:
            /* Could ignore EIO, see spec. */
            /* fall through */
        default:
            perror("VIDIOC_DQBUF");
            break;
        }
        exit(EXIT_FAILURE);
    }

    if (buf.bytesused > 0) {
        process_image(buffers[buf.index].start, buf.bytesused);
    } else {
        fprintf(stderr, "No data in buffer\n");
        exit(EXIT_FAILURE);
    }

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
        exit(EXIT_FAILURE);
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            perror("munmap");
            exit(EXIT_FAILURE);
        }
    }

    free(buffers);

    if (-1 == close(fd)) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    if (fclose(file)) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }

    return 0;
}
