    unsigned int duty_ns = PWM_MIN_DUTY_NS + (position * PWM_DUTY_STEP_NS);
    gpiod_line_set_value(line, 1);
    usleep(duty_ns / 1000);
    gpiod_line_set_value(line, 0);
    usleep((PWM_PERIOD_NS - duty_ns) / 1000);
}

