    button_tilt_down_line = gpiod_chip_get_line(chip, BUTTON_TILT_DOWN_PIN);
    button_pan_left_line = gpiod_chip_get_line(chip, BUTTON_PAN_LEFT_PIN);
    button_pan_right_line = gpiod_chip_get_line(chip, BUTTON_PAN_RIGHT_PIN);

    if (!servo_pan_line || !servo_tilt_line || !button_tilt_up_line || !button_tilt_down_line || !button_pan_left_line || !button_pan_right_line) {
