        gpiod_line_request_input(button_pan_left_line, "button_pan_left") < 0 ||
        gpiod_line_request_input(button_pan_right_line, "button_pan_right") < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    pan_position = MID_POSITION;
    tilt_position = MID_POSITION;

    while (1) {
        set_servo_position(servo_pan_line, pan_position);
        set_servo_position(servo_tilt_line, tilt_position);

        if (gpiod_line_get_value(button_tilt_up_line) == 0) {
            adjust_position(&tilt_position, POSITION_STEP);
        }
        if (gpiod_line_get_value(button_tilt_down_line) == 0) {
            adjust_position(&tilt_position, -POSITION_STEP);
        }
        if (gpiod_line_get_value(button_pan_left_line) == 0) {
            adjust_position(&pan_position, -POSITION_STEP);
        }
        if (gpiod_line_get_value(button_pan_right_line) == 0) {
            adjust_position(&pan_position, POSITION_STEP);
        }

        usleep(50000); // 50 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

