#include <linux/videodev2.h>
#include <jpeglib.h>
#include <signal.h>
#include <time.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void *start;
    size_t length;
};

static int fd = -1;
static struct buffer *buffers;
static unsigned int n_buffers;
static int stop = 0;

void signal_handler(int s) {
    stop = 1;
}

void errno_exit(const char *s) {
    perror(s);
    exit(EXIT_FAILURE);
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    if (-1 == r) {
        errno_exit(s);
    }

    return r;
}

void process_image(const void *p, int size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    JSAMPROW row_pointer[1];
    FILE *outfile;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return;
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = 640;
    cinfo.image_height = 480;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    unsigned char *yuyv = (unsigned char *)p;
    unsigned char *rgb = malloc(cinfo.image_width * cinfo.image_height * 3);
    if (!rgb) {
        fprintf(stderr, "Memory allocation failed\n");
        jpeg_destroy_compress(&cinfo);
        fclose(outfile);
        return;
    }

    for (int i = 0; i < cinfo.image_height; i++) {
        for (int j = 0; j < cinfo.image_width; j++) {
            int y = yuyv[(i * cinfo.image_width + j) * 2];
            int u = yuyv[(i * cinfo.image_width + j) * 2 + 1];
            int v = yuyv[((i * cinfo.image_width + j) * 2 + 2) % (cinfo.image_width * 2)];

            int r = y + 1.402 * (v - 128);
            int g = y - 0.34414 * (u - 128) - 0.71414 * (v - 128);
            int b = y + 1.772 * (u - 128);

            rgb[i * cinfo.image_width * 3 + j * 3] = r > 255 ? 255 : (r < 0 ? 0 : r);
            rgb[i * cinfo.image_width * 3 + j * 3 + 1] = g > 255 ? 255 : (g < 0 ? 0 : g);
            rgb[i * cinfo.image_width * 3 + j * 3 + 2] = b > 255 ? 255 : (b < 0 ? 0 : b);
        }
    }

    for (int i = 0; i < cinfo.image_height; i++) {
        row_pointer[0] = &rgb[i * cinfo.image_width * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    free(rgb);
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(outfile);
}

void init_device(void) {
    struct v4l2_capability cap;
    struct v4l2_cropcap cropcap;
    struct v4l2_crop crop;
