#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <string.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

void print_usage(const char *progname) {
    fprintf(stderr, "Usage: %s\n", progname);
}

void print_error(const char *msg) {
    perror(msg);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *device = "/dev/video0";
    int fd = open(device, O_RDWR);
    if (fd == -1) {
        print_error("Failed to open device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    CLEAR(cap);
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        print_error("Failed to query device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Device: %s\n", device);
    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Capabilities: 0x%x\n", cap.capabilities);

    struct v4l2_frmsizeenum frmsize;
    CLEAR(frmsize);
    frmsize.pixel_format = cap.formats[0].pixelformat;

    printf("Supported resolutions:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("  Width: %u, Height: %u\n", frmsize.discrete.width, frmsize.discrete.height);

        struct v4l2_frmivalenum frmival;
        CLEAR(frmival);
        frmival.pixel_format = frmsize.pixel_format;
        frmival.width = frmsize.discrete.width;
        frmival.height = frmsize.discrete.height;

        printf("    Supported frame rates:\n");
        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                printf("      %u/%u fps\n", frmival.discrete.numerator, frmival.discrete.denominator);
            } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
                printf("      Continuous range\n");
            } else if (frmival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
                printf("      Stepwise range\n");
            }
            frmival.index++;
        }

        frmsize.index++;
    }

    struct v4l2_queryctrl queryctrl;
    CLEAR(queryctrl);
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("Autofocus is supported\n");
    } else {
        if (errno == EINVAL) {
            printf("Autofocus is not supported\n");
        } else {
            print_error("Failed to query autofocus control");
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}
