static struct gpiod_line *pan_line;
static struct gpiod_line *tilt_line;
static struct gpiod_line *up_line;
static struct gpiod_line *down_line;
static struct gpiod_line *left_line;
static struct gpiod_line *right_line;

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void setup_gpio(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    pan_line = gpiod_chip_get_line(chip, PAN_GPIO);
    tilt_line = gpiod_chip_get_line(chip, TILT_GPIO);
    up_line = gpiod_chip_get_line(chip, UP_GPIO);
    down_line = gpiod_chip_get_line(chip, DOWN_GPIO);
    left_line = gpiod_chip_get_line(chip, LEFT_GPIO);
    right_line = gpiod_chip_get_line(chip, RIGHT_GPIO);

    if (!pan_line || !tilt_line || !up_line || !down_line || !left_line || !right_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0 ||
        gpiod_line_request_input(up_line, "up_button") < 0 ||
        gpiod_line_request_input(down_line, "down_button") < 0 ||
        gpiod_line_request_input(left_line, "left_button") < 0 ||
        gpiod_line_request_input(right_line, "right_button") < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(up_line, 1);
    gpiod_line_set_value(down_line, 1);
    gpiod_line_set_value(left_line, 1);
    gpiod_line_set_value(right_line, 1);
}

void cleanup_gpio(void) {
    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(up_line);
    gpiod_line_release(down_line);
    gpiod_line_release(left_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);
}

void set_servo_pulse(struct gpiod_line *line, int pulse_width) {
    if (pulse_width < PWM_MIN) pulse_width = PWM_MIN;
    if (pulse_width > PWM_MAX) pulse_width = PWM_MAX;

    int period = 1000000 / PWM_FREQ;
    int duty_cycle = (pulse_width * period) / 1000;

    gpiod_line_set_value(line, 1);
    usleep(duty_cycle);
    gpiod_line_set_value(line, 0);
    usleep(period - duty_cycle);
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_gpio();

    printf("Pan-Tilt Control Initialized\n");
    printf("PAN: GPIO%d, TILT: GPIO%d\n", PAN_GPIO, TILT_GPIO);
    printf("UP: GPIO%d, DOWN: GPIO%d, LEFT: GPIO%d, RIGHT: GPIO%d\n", UP_GPIO, DOWN_GPIO, LEFT_GPIO, RIGHT_GPIO);
    printf("Center Position: %dµs\n", PWM_CENTER);

    int pan_pos = PWM_CENTER;
    int tilt_pos = PWM_CENTER;

    while (running) {
        if (!gpiod_line_get_value(up_line)) {
            tilt_pos += PWM_STEP;
        }
        if (!gpiod_line_get_value(down_line)) {
            tilt_pos -= PWM_STEP;
        }
        if (!gpiod_line_get_value(left_line)) {
            pan_pos -= PWM_STEP;
        }
        if (!gpiod_line_get_value(right_line)) {
            pan_pos += PWM_STEP;
        }

        set_servo_pulse(pan_line, pan_pos);
        set_servo_pulse(tilt_line, tilt_pos);

        usleep(LOOP_DELAY);
    }

    cleanup_gpio();
    printf("Exiting cleanly\n");
    return 0;
}

