#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <libgpiod.h>
#include <curl/curl.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_TIME 2000000 // 2 seconds in microseconds
#define POLL_INTERVAL 100000  // 100 ms in microseconds
#define CAMERA_CMD "raspistill -o %s -q 85"
#define CAPTURE_DIR "motion_captures"
#define JSON_TEMPLATE "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":\"%s\",\"gpio_pin\":%d}"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

size_t write_data(void *ptr, size_t size, size_t nmemb, void *userdata) {
    return size * nmemb;
}

void post_to_server(const char *ip, const char *port, const char *filename, const char *timestamp, const char *motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    char json[1024];
    char url[1024];

    snprintf(json, sizeof(json), JSON_TEMPLATE, filename, timestamp, motion_status, gpio_pin);
    snprintf(url, sizeof(url), "http://%s:%s/upload", ip, port);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if(argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *ip = argv[1];
    const char *port = argv[2];

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec last_motion_time = {0};
    struct timespec current_time;
    char filename[256];
    char timestamp[100];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if(!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if(!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if(gpiod_line_request_input(line, "pir_monitor") < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if(gpiod_line_set_config(line, GPIOD_LINE_CONFIG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_set_config");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if(mkdir(CAPTURE_DIR, 0755) && errno != EEXIST) {
        perror("mkdir");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while(running) {
        if(gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_REALTIME, &current_time);
            if(current_time.tv_sec - last_motion_time.tv_sec > 2) {
                last_motion_time = current_time;
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", localtime(&current_time.tv_sec));
                snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);

                if(system(CAMERA_CMD) != 0) {
                    perror("system(raspistill)");
                } else {
                    post_to_server(ip, port, filename, timestamp, "detected", GPIO_LINE);
                }
            }
        }
        usleep(POLL_INTERVAL);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

