#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_TIMEOUT_US 50000
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t running = 1;

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log, "[%s] %s\n", timestamp, message);
    fclose(log);
}

void capture_image() {
    char filename[100];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%.3ld.jpg", tm_info, now % 1000);

    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s/%s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", IMAGE_DIR, filename);

    int status = system(command);
    if (status == -1) {
        log_message("Failed to execute capture command");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        log_message("Capture command failed with status");
    } else {
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Captured image: %s/%s", IMAGE_DIR, filename);
        log_message(log_message);
    }
}

void handle_signal(int sig) {
    running = 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
