        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_device();
    init_mmap();
    start_streaming();

    output_file = fopen("cropped.yuv", "wb");
    if (!output_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        perror("select");
        exit(EXIT_FAILURE);
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        exit(EXIT_FAILURE);
    } else {
        if (FD_ISSET(fd, &fds)) {
            if (read_frame() == -1) {
                exit(EXIT_FAILURE);
            }
        }
    }

    stop_streaming();
    unmap_buffers();
    close_device();
    close_output_file();

    return 0;
}
