#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define OLED_ADDR 0x3C
#define FONT_WIDTH 5
#define FONT_HEIGHT 7
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void oled_init(int fd) {
    uint8_t init_seq[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14,
        0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12, 0x81, 0xCF, 0xD9, 0xF1,
        0xDB, 0x40, 0xA4, 0xA6, 0xAF
    };
    i2c_write(fd, 0x00, init_seq, sizeof(init_seq));
}

void oled_clear(int fd) {
    uint8_t clear[128 * 8] = {0};
    for (int page = 0; page < 8; page++) {
        i2c_write(fd, 0xB0 + page, clear, 128);
    }
}

void oled_draw_char(int fd, int x, int y, char c) {
    static const uint8_t font[95][5] = {
        // Basic 5x7 font data (space to ~)
        {0x00, 0x00, 0x00, 0x00, 0x00}, // space
        // ... (other characters)
        {0x0E, 0x1F, 0x1F, 0x0E, 0x00}  // ~
    };
    if (c < ' ' || c > '~') return;
    c -= ' ';
    for (int i = 0; i < 5; i++) {
        i2c_write(fd, 0xB0 + y / 8, &font[c][i], 1);
        x++;
        if (x >= SCREEN_WIDTH) break;
    }
}

void oled_draw_string(int fd, int x, int y, const char *str) {
    while (*str) {
        oled_draw_char(fd, x, y, *str);
        x += FONT_WIDTH + 1;
        if (x >= SCREEN_WIDTH) {
            x = 0;
            y += FONT_HEIGHT;
        }
        str++;
    }
}

const char *read_cpu_temp() {
    static char temp_str[10];
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) return "Temp read error";
    if (fgets(temp_str, sizeof(temp_str), fp) == NULL) {
        fclose(fp);
        return "Temp read error";
    }
    fclose(fp);
    temp_str[strcspn(temp_str, "\n")] = '\0';
    return temp_str;
}

const char *read_cpu_usage() {
    static char usage_str[10];
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return "Usage read error";
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "cpu ", 4) == 0) {
            long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
            if (sscanf(line, "cpu %ld %ld %ld %ld %ld %ld %ld %ld %ld %ld",
                       &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
                fclose(fp);
                return "Usage parse error";
            }
            long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
            long idle_time = idle + iowait;
            long usage = 100 * (total - idle_time) / total;
            snprintf(usage_str, sizeof(usage_str), "%ld%%", usage);
            fclose(fp);
            return usage_str;
        }
    }
    fclose(fp);
    return "Usage read error";
}

int main() {
    signal(SIGINT, sigint_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OLED_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    oled_init(i2c_fd);

    while (running) {
        oled_clear(i2c_fd);

        const char *temp = read_cpu_temp();
        const char *usage = read_cpu_usage();

        oled_draw_string(i2c_fd, 0, 0, "Temp: ");
        oled_draw_string(i2c_fd, 40, 0, temp);
        oled_draw_string(i2c_fd, 0, 8, "Usage: ");
        oled_draw_string(i2c_fd, 40, 8, usage);

        usleep(1000000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

