        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "flow_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
}

void init_lcd(int fd) {
    wiringPiI2CWriteReg8(fd, 0x00, 0x33); // Function set: 8-bit, 2 lines, 5x7 font
    usleep(5000);
    wiringPiI2CWriteReg8(fd, 0x00, 0x32); // Function set: 8-bit, 2 lines, 5x7 font
    usleep(1000);
    wiringPiI2CWriteReg8(fd, 0x00, 0x06); // Entry mode set: cursor increment, no shift
    wiringPiI2CWriteReg8(fd, 0x00, 0x0C); // Display on, cursor off, blink off
    wiringPiI2CWriteReg8(fd, 0x00, 0x28); // Function set: 4-bit, 2 lines, 5x7 font
    wiringPiI2CWriteReg8(fd, 0x00, 0x01); // Clear display
    usleep(2000);
}

void lcd_command(int fd, unsigned char cmd) {
    wiringPiI2CWriteReg8(fd, 0x00, (cmd & 0xF0) | 0x04);
    wiringPiI2CWriteReg8(fd, 0x00, (cmd & 0xF0));
    wiringPiI2CWriteReg8(fd, 0x00, ((cmd << 4) & 0xF0) | 0x04);
    wiringPiI2CWriteReg8(fd, 0x00, ((cmd << 4) & 0xF0));
    usleep(1000);
}

void lcd_print(int fd, const char *str) {
    while (*str) {
        lcd_command(fd, 0x40 | (*str & 0xF0));
        lcd_command(fd, 0x40 | ((*str << 4) & 0xF0));
        str++;
    }
}

void lcd_clear(int fd) {
    lcd_command(fd, 0x01);
    usleep(2000);
}

void lcd_set_cursor(int fd, int row, int col) {
    int address = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_command(fd, address);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    double total_volume = 0.0;
    double last_flow_rate = 0.0;
    time_t last_sample_time = time(NULL);
    time_t last_lcd_update_time = time(NULL);
    unsigned int last_pulse_count = 0;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "flow_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    fd = wiringPiI2CSetup(LCD_I2C_ADDRESS);
    if (fd < 0) {
        perror("Failed to initialize I2C");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    init_lcd(fd);

    while (running) {
        unsigned int pulse_count = gpiod_line_get_value(line);
        time_t current_time = time(NULL);

        if (current_time - last_sample_time >= SAMPLE_INTERVAL) {
            double flow_rate = (pulse_count - last_pulse_count) / PULSE_PER_LITER / SAMPLE_INTERVAL;
            total_volume += flow_rate * SAMPLE_INTERVAL;
            last_flow_rate = flow_rate;
            last_pulse_count = pulse_count;
            last_sample_time = current_time;

            printf("Flow Rate: %.2f L/s, Total Volume: %.2f L\n", flow_rate, total_volume);
        }

        if (current_time - last_lcd_update_time >= LCD_UPDATE_INTERVAL) {
            lcd_clear(fd);
            lcd_set_cursor(fd, 0, 0);
            char buffer[32];
            snprintf(buffer, sizeof(buffer), "Flow: %.2f L/s", last_flow_rate);
            lcd_print(fd, buffer);
            lcd_set_cursor(fd, 1, 0);
            snprintf(buffer, sizeof(buffer), "Volume: %.2f L", total_volume);
            lcd_print(fd, buffer);
            last_lcd_update_time = current_time;
        }

        usleep(100000); // Sleep for 100ms
    }

    gpiod_chip_close(chip);
    return 0;
}
