    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(EXIT_FAILURE);
    }
    if (write(fd, data, len) != len) {
        perror("Failed to write to the i2c bus");
        exit(EXIT_FAILURE);
    }
}

void lcd_init(int fd) {
    uint8_t init_seq[] = {0x03, 0x03, 0x03, 0x02, 0x28, 0x0C, 0x06, 0x01};
    for (size_t i = 0; i < sizeof(init_seq); i++) {
        i2c_write(fd, LCD_ADDR, &init_seq[i], 1);
        usleep(10000);
    }
}

void lcd_set_cursor(int fd, uint8_t row, uint8_t col) {
    uint8_t cmd = 0x80 | (row * 0x40 + col);
    i2c_write(fd, LCD_ADDR, &cmd, 1);
}

void lcd_print(int fd, const char *str) {
    for (size_t i = 0; i < strlen(str); i++) {
        i2c_write(fd, LCD_ADDR, (uint8_t *)&str[i], 1);
    }
}

void lcd_clear(int fd) {
    uint8_t cmd = 0x01;
    i2c_write(fd, LCD_ADDR, &cmd, 1);
    usleep(2000);
}

void gpio_setup(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (gpiod_chip_get_line(chip, GPIO_LINE) < 0) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(line, "water_flow_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        exit(EXIT_FAILURE);
    }
}

void gpio_cleanup(struct gpiod_chip *chip, struct gpiod_line *line) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

void handle_sensor_absent() {
    printf("Sensor absent or not working.\n");
    exit(EXIT_FAILURE);
}

int main() {
    setup_signals();

    int i2c_fd = i2c_open(I2C_BUS);
    lcd_init(i2c_fd);

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "water_flow_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    unsigned int last_pulse_count = 0;
    time_t last_time = time(NULL);

    while (running) {
        unsigned int pulse_count = gpiod_line_get_value(line);
        if (pulse_count == 0) {
            time_t current_time = time(NULL);
            if (current_time - last_time > 10) { // 10 seconds
                handle_sensor_absent();
            }
        } else {
            last_time = time(NULL);
        }

        if (pulse_count != last_pulse_count) {
            last_pulse_count = pulse_count;
            double flow_rate = (pulse_count / PULSE_PER_LITER) * 60.0;
            lcd_clear(i2c_fd);
            lcd_set_cursor(i2c_fd, 0, 0);
            lcd_print(i2c_fd, "Flow Rate:");
            lcd_set_cursor(i2c_fd, 1, 0);
            char flow_str[10];
            snprintf(flow_str, sizeof(flow_str), "%.2f L/min", flow_rate);
            lcd_print(i2c_fd, flow_str);
        }

        usleep(100000); // 100ms
    }

    gpio_cleanup(chip, line);
    close(i2c_fd);

    return 0;
}
