#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define ROWS 8
#define COLS 8

const int row_gpios[ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_gpios[COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

int fd;
struct gpiohandle_request req;
struct gpiohandle_data data;

void cleanup() {
    if (fd >= 0) {
        close(fd);
    }
}

void sigint_handler(int sig) {
    cleanup();
    exit(EXIT_FAILURE);
}

void init_gpio() {
    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    req.lineoffsets = row_gpios;
    req.lines = ROWS;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    strncpy(req.consumer_label, "led_matrix", sizeof(req.consumer_label));

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("Failed to get line handle for rows");
        cleanup();
        exit(EXIT_FAILURE);
    }

    req.lineoffsets = col_gpios;
    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("Failed to get line handle for columns");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void set_row(int row, int value) {
    data.values[row] = value;
    if (ioctl(req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set row value");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void set_col(int col, int value) {
    data.values[col] = value;
    if (ioctl(req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set column value");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void clear_matrix() {
    for (int i = 0; i < ROWS; i++) {
        set_row(i, 0);
    }
    for (int i = 0; i < COLS; i++) {
        set_col(i, 1);
    }
}

void render_wave_left_to_right(int frame) {
    clear_matrix();
    for (int i = 0; i < ROWS; i++) {
        set_row(i, 1);
        set_col((frame + i) % COLS, 0);
        usleep(800);
        set_row(i, 0);
    }
}

void render_wave_right_to_left(int frame) {
    clear_matrix();
    for (int i = 0; i < ROWS; i++) {
        set_row(i, 1);
        set_col((COLS - 1 - ((frame + i) % COLS)), 0);
        usleep(800);
        set_row(i, 0);
    }
}

int main() {
    atexit(cleanup);
    signal(SIGINT, sigint_handler);

    init_gpio();

    for (int frame = 0; ; frame++) {
        render_wave_left_to_right(frame);
        render_wave_right_to_left(frame);
    }

    return 0;
}

