#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}
#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_US 150000

static struct gpiod_chip *chip;
static struct gpiod_line_bulk rows, cols;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int ret;
    struct gpiod_line *row, *col;
    unsigned int row_pins[NUM_ROWS] = ROW_PINS;
    unsigned int col_pins[NUM_COLS] = COL_PINS;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request row pins as output
    ret = gpiod_chip_get_lines(chip, row_pins, NUM_ROWS, &rows);
    if (ret < 0) {
        perror("Failed to get row lines");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_bulk_output(&rows, "led_matrix_rows", 0);
    if (ret < 0) {
        perror("Failed to request row lines as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request column pins as output
    ret = gpiod_chip_get_lines(chip, col_pins, NUM_COLS, &cols);
    if (ret < 0) {
        perror("Failed to get column lines");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_bulk_output(&cols, "led_matrix_cols", 1);
    if (ret < 0) {
        perror("Failed to request column lines as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        for (int col_idx = 0; col_idx < NUM_COLS; col_idx++) {
            // Clear the matrix
            ret = gpiod_line_set_value_bulk(&cols, 1);
            if (ret < 0) {
                perror("Failed to set column lines high");
                cleanup();
                return EXIT_FAILURE;
            }
            ret = gpiod_line_set_value_bulk(&rows, 0);
            if (ret < 0) {
                perror("Failed to set row lines low");
                cleanup();
                return EXIT_FAILURE;
            }

            // Light the LEDs sequentially
            for (int row_idx = 0; row_idx < NUM_ROWS; row_idx++) {
                row = gpiod_line_bulk_get_line(&rows, row_idx);
                ret = gpiod_line_set_value(row, 1);
                if (ret < 0) {
                    perror("Failed to set row line high");
                    cleanup();
                    return EXIT_FAILURE;
                }

                col = gpiod_line_bulk_get_line(&cols, col_idx);
                ret = gpiod_line_set_value(col, 0);
                if (ret < 0) {
                    perror("Failed to set column line low");
                    cleanup();
                    return EXIT_FAILURE;
                }

                usleep(DELAY_US);

                ret = gpiod_line_set_value(row, 0);
                if (ret < 0) {
                    perror("Failed to set row line low");
                    cleanup();
                    return EXIT_FAILURE;
                }
            }

            // Wait for the next column
            usleep(DELAY_US);
        }
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

