        perror("I2C read");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, uint16_t reg, const uint8_t *data, size_t len) {
    uint8_t buf[len + 2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    memcpy(buf + 2, data, len);
    if (write(fd, buf, len + 2) != len + 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    int i2c_fd = open(I2C_BUS_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L3CX_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (i2c_read(i2c_fd, VL53L3CX_REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (model_id != VL53L3CX_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Stub for proprietary firmware download
    printf("Performing proprietary firmware download...\n");
    // TODO: Implement firmware download sequence

    while (running) {
        uint8_t range_status;
        if (i2c_read(i2c_fd, VL53L3CX_REG_RESULT_RANGE_STATUS, &range_status, 1) < 0) {
            fprintf(stderr, "Failed to read range status\n");
            break;
        }

        if (range_status & 0x01) {
            uint8_t num_targets;
            if (i2c_read(i2c_fd, VL53L3CX_REG_RESULT_NUMBER_OF_TARGETS, &num_targets, 1) < 0) {
                fprintf(stderr, "Failed to read number of targets\n");
                break;
            }

            for (uint8_t i = 0; i < num_targets && i < VL53L3CX_MAX_TARGETS; i++) {
                uint8_t target_status;
                if (i2c_read(i2c_fd, VL53L3CX_REG_RESULT_TARGET_STATUS + i, &target_status, 1) < 0) {
                    fprintf(stderr, "Failed to read target status for target %d\n", i);
                    break;
                }

                if (target_status & 0x01) {
                    uint16_t distance_mm;
                    uint8_t distance_bytes[2];
                    if (i2c_read(i2c_fd, VL53L3CX_REG_RESULT_DISTANCE_MM + i * 4, distance_bytes, 2) < 0) {
                        fprintf(stderr, "Failed to read distance for target %d\n", i);
                        break;
                    }
                    distance_mm = (distance_bytes[0] << 8) | distance_bytes[1];

                    print_iso8601_timestamp();
                    printf(" Target %d: %d mm\n", i, distance_mm);
                }
            }
        }

        usleep(100000); // 100 ms
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}
