volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct sigaction sa;

    // Set up signal handler for graceful shutdown
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("depth_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write header if file is newly created
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }

    while (running) {
        uint8_t reg = MLX75031_REG_RESULT;
        uint16_t distance = 0;
        struct timespec ts;

        // Write register address
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            fprintf(log_file, "%ld.%06ld,-1\n", ts.tv_sec, ts.tv_nsec / 1000);
            fflush(log_file);
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to re-open I2C bus");
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            continue;
        }

        // Read distance data
        if (read(i2c_fd, &distance, 2) != 2) {
            perror("Failed to read distance data");
            fprintf(log_file, "%ld.%06ld,-1\n", ts.tv_sec, ts.tv_nsec / 1000);
            fflush(log_file);
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to re-open I2C bus");
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            continue;
        }

        // Convert distance to mm
        distance = (distance >> 6) * 10;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            close(i2c_fd);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Write timestamped distance to log file
        fprintf(log_file, "%ld.%06ld,%u\n", ts.tv_sec, ts.tv_nsec / 1000, distance);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL_US);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

