#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS_PATH "/dev/i2c-1"
#define SI1145_I2C_ADDRESS 0x5A
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_CMD 0x01
#define SI1145_REG_DATA0 0x02
#define SI1145_REG_DATA1 0x03
#define SI1145_REG_DATA2 0x04
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x13
#define SI1145_CMD_PROX_FORCE 0x0F

#define LOG_FILE "biometric_log.txt"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *data) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int i2c_write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

void sensor_init(int fd) {
    uint8_t part_id;
    if (i2c_read_register(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read part ID from sensor\n");
        exit(EXIT_FAILURE);
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Sensor part ID mismatch: expected 0x45, got 0x%02X\n", part_id);
        exit(EXIT_FAILURE);
    }
    i2c_write_register(fd, SI1145_REG_CMD, SI1145_CMD_RESET);
    usleep(10000);
    i2c_write_register(fd, SI1145_REG_CMD, SI1145_CMD_ALS_FORCE);
    i2c_write_register(fd, SI1145_REG_CMD, SI1145_CMD_PROX_FORCE);
}

void log_data(FILE *log_file) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    int fd = open(I2C_BUS_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return;
    }
    if (ioctl(fd, I2C_SLAVE, SI1145_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return;
    }

    uint8_t data0, data1, data2;
    if (i2c_read_register(fd, SI1145_REG_DATA0, &data0) < 0 ||
        i2c_read_register(fd, SI1145_REG_DATA1, &data1) < 0 ||
        i2c_read_register(fd, SI1145_REG_DATA2, &data2) < 0) {
        fprintf(log_file, "%s: I2C read failed\n", timestamp);
        close(fd);
        return;
    }

    fprintf(log_file, "%s: Proximity: %d, Ambient Light: %d\n", timestamp, data1, (data0 << 8) | data2);
    close(fd);
}

int main() {
    signal(SIGINT, sigint_handler);

    int fd = open(I2C_BUS_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, I2C_SLAVE, SI1145_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    sensor_init(fd);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        log_data(log_file);
        fflush(log_file);
        usleep(500000);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

