#define POLL_INTERVAL_US 100000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction sa;
    struct timespec last_detection = {0};
    int ret;

    // Setup signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(NULL);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        chip = gpiod_chip_open_by_name("the library's API call");
        if (!chip) {
            perror("gpiod_chip_open_by_name fallback");
            return EXIT_FAILURE;
        }
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("gpiod_chip_get_line sensor");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(sensor_line, "proximity_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input sensor");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line led");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(led_line, "led_blink", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output led");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("gpiod_line_get_value");
            cleanup();
            return EXIT_FAILURE;
        }

        if (sensor_value == 0) { // Object detected
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec != last_detection.tv_sec || now.tv_nsec != last_detection.tv_nsec) {
                FILE *log_file = fopen(LOG_FILE, "a");
                if (!log_file) {
                    perror("fopen");
                    cleanup();
                    return EXIT_FAILURE;
                }

