#include <signal.h>
#include <errno.h>

#define SI1145_I2C_ADDRESS 0x5A
#define SI1145_PART_ID 0x45
#define SI1145_CMD 0x00
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x2C
#define SI1145_REG_PROX_DATA0 0x28

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    // Assuming there's a cleanup function for the sensor
    // sensor_cleanup();
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (i2c_write_byte(fd, SI1145_CMD, reg) < 0) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    if (i2c_write_byte(fd, SI1145_CMD, reg) < 0) {
        return -1;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2c_read_byte(i2c_fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID from sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Incorrect PART_ID: expected 0x%02X, got 0x%02X\n", SI1145_PART_ID, part_id);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t als_vis_data, prox_data;
        if (i2c_read_word(i2c_fd, SI1145_REG_ALS_VIS_DATA0, &als_vis_data) < 0 ||
            i2c_read_word(i2c_fd, SI1145_REG_PROX_DATA0, &prox_data) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            cleanup();
            return EXIT_FAILURE;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s,%u,%u\n", timestamp, prox_data, als_vis_data);
        fflush(log_file);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

