#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TIMEOUT_US 30000
#define LOG_FILE "distance_log.txt"
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define WATER_THRESHOLD 15

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get TRIGGER line");
        cleanup();
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get ECHO line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0) < 0) {
        perror("Failed to request TRIGGER line as output");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "ultrasonic_echo") < 0) {
        perror("Failed to request ECHO line as input");
        cleanup();
        return -1;
    }

    return 0;
}

int measure_distance() {
    struct timespec start, end;
    long echo_duration;

    // Trigger pulse
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo rise
    if (gpiod_line_event_wait(echo_line, TIMEOUT_US * 1000) < 0) {
        perror("Failed to wait for echo rise");
        return -1;
    }

    if (gpiod_line_get_value(echo_line) == 0) {
        fprintf(log_file, "Error: Echo never rose\n");
        return -1;
    }

