    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("Failed to get start time");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get end time");
            return -1;
        }
        if (timespec_subtract(&end, &start) > TIMEOUT_US * 1000) {
            fprintf(log_file, "Error: Echo timeout\n");
            return -1;
        }
    }

    echo_duration = timespec_subtract(&end, &start);

    // Calculate distance
    int distance = (echo_duration * 34000) / 2 / 1000000;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(log_file, "Error: Distance out of range\n");
        return -1;
    }

    return distance;
}

long timespec_subtract(struct timespec *end, struct timespec *start) {
    long diff = (end->tv_sec - start->tv_sec) * 1000000 +
               (end->tv_nsec - start->tv_nsec) / 1000;
    return diff;
}

void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s - Distance: %d cm\n", timestamp, distance);
    if (distance < WATER_THRESHOLD) {
        fprintf(log_file, "Time to water the plant!\n");
    }
    fflush(log_file);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int distance = measure_distance();
        if (distance >= 0) {
            log_distance(distance);
        }
        sleep(60);
    }

    cleanup();
    return EXIT_SUCCESS;
}

