#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define APDS9960_ADDR 0x39
#define PROXIMITY_THRESHOLD 200
#define CSV_FILE "color_proximity_log.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, uint8_t *buf, size_t len) {
    if (i2c_write_byte(reg | 0x80, 0) < 0) {
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int init_apds9960() {
    if (i2c_write_byte(0x80 | 0x00, 0x01) < 0) { // Enable power
        return -1;
    }
    if (i2c_write_byte(0x80 | 0x01, 0x02) < 0) { // Enable proximity and gesture
