#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L0X_I2C_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0012
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_DISTANCE_MM 0x001E

#define TIMEOUT_MS 100

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd = -1;
    int gpio_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct sigaction sa;
    struct timespec ts;
    struct timeval tv;
    char log_entry[100];

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    // Verify sensor presence
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Configure GPIO line as input with pull-up
    if (gpiod_line_request_input(line, "vl53l0x_trigger") < 0) {
        perror("Failed to request GPIO line as input");
        goto cleanup;
    }
    if (gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        perror("Failed to set GPIO line bias to pull-up");
        goto cleanup;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Main loop
    while (running) {
        // Wait for falling edge
        if (gpiod_line_event_wait(line, NULL) < 0) {
            perror("Failed to wait for GPIO event");
            continue;
        }

        // Trigger measurement
        if (write(i2c_fd, "\x00\x00", 2) != 2) {
            perror("Failed to trigger measurement");
            continue;
        }

        // Poll RESULT_INTERRUPT_STATUS with timeout
        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (1) {
            uint8_t status;
            if (read(i2c_fd, &status, 1) != 1) {
                perror("Failed to read RESULT_INTERRUPT_STATUS");
                break;
            }
            if (status & 0x04) {
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (timespec_diff_ms(&now, &start) > TIMEOUT_MS) {
                fprintf(stderr, "Timeout waiting for measurement result\n");
                break;
            }
            usleep(10000); // 10 ms
        }

        // Read distance
        uint16_t distance;
        if (read(i2c_fd, &distance, 2) != 2) {
            perror("Failed to read distance");
            continue;
        }
        distance = (distance >> 8) | (distance << 8); // Swap bytes

        // Log distance
        gettimeofday(&tv, NULL);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", localtime(&tv));
        fprintf(log_file, "%s,%u\n", log_entry, distance);
        fflush(log_file);
    }

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

int timespec_diff_ms(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000 + (a->tv_nsec - b->tv_nsec) / 1000000;
}

