    }

    // Configure lines as input
    ret = gpiod_line_request_input(sensor1, "sensor1");
    if (ret < 0) {
        perror("Failed to request input for sensor 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(sensor2, "sensor2");
    if (ret < 0) {
        perror("Failed to request input for sensor 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        int sensor1_value, sensor2_value;

        // Read sensor values
        sensor1_value = gpiod_line_get_value(sensor1);
        if (sensor1_value < 0) {
            fprintf(stderr, "Failed to read sensor 1: %s\n", strerror(errno));
        }

        sensor2_value = gpiod_line_get_value(sensor2);
        if (sensor2_value < 0) {
            fprintf(stderr, "Failed to read sensor 2: %s\n", strerror(errno));
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            continue;
        }

        // Log the readings
        fprintf(log_file, "%ld.%09ld, %d, %d\n", ts.tv_sec, ts.tv_nsec, sensor1_value, sensor2_value);
        fflush(log_file);

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

