#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x52
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define DISTANCE_THRESHOLD_CM 20

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static FILE *log_file;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "ultrasonic_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void setup_log() {
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void read_distance() {
    uint8_t command[] = {0x00}; // Command to read distance
    uint8_t response[2];

    if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to write to I2C");
        return;
    }

    if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read from I2C");
        return;
    }

    uint16_t distance_mm = (response[0] << 8) | response[1];
    double distance_cm = distance_mm / 10.0;

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log_file, "%s.%03ld, Distance: %.2f cm\n", timestamp, tv.tv_usec / 1000, distance_cm);
    fflush(log_file);

    if (distance_cm < DISTANCE_THRESHOLD_CM) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_i2c();
    setup_log();

    while (1) {
        read_distance();
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

