#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x5A
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_CMD 0x08
#define SI1182_REG_DATA0 0x09
#define SI1182_REG_DATA1 0x0A
#define SI1182_REG_DATA2 0x0B
#define SI1182_CMD_ALS_FORCE 0x13
#define SI1182_CMD_PROX_FORCE 0x0F
#define SI1182_PART_ID 0x45

#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[1] = {reg};
    if (write(fd, buf, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct sigaction sa;
    struct timespec ts;
    uint8_t part_id;
    uint8_t data[3];

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if the sensor is present
    if (i2c_read(i2c_fd, SI1182_REG_PART_ID, &part_id, 1) < 0 || part_id != SI1182_PART_ID) {
        fprintf(stderr, "Sensor not found or I2C error\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen("biometric_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Force ALS measurement
        if (i2c_write(i2c_fd, SI1182_REG_CMD, SI1182_CMD_ALS_FORCE) < 0) {
            fprintf(stderr, "Failed to write ALS command\n");
