#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x52
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VAL 0x78
#define DISTANCE_REG 0x02
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    int threshold = DEFAULT_THRESHOLD;
    FILE *log_file;

    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (write(i2c_fd, &WHO_AM_I_REG, 1) != 1 || read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request line for output
    if (gpiod_line_request_output(led_line, "tof_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("tof_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        uint8_t distance_data[2];
        uint16_t distance;

        // Read distance
        if (write(i2c_fd, &DISTANCE_REG, 1) != 1 || read(i2c_fd, distance_data, 2) != 2) {
            perror("Failed to read distance");
            continue;
        }
        distance = (distance_data[0] << 8) | distance_data[1];

        // Log distance with timestamp
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Distance: %d mm\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, distance);
        fflush(log_file);

        // Light LED if distance is below threshold
        gpiod_line_set_value(led_line, distance < threshold);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

