#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x52
#define COMMAND_FRAME {0x00, 0x01, 0x00, 0x00}
#define RESPONSE_LENGTH 15
#define HEADER_VALUE 0x59
#define SAMPLES_PER_CYCLE 10
#define CYCLE_DELAY_MS 100
#define DISTANCE_THRESHOLD 1000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    uint8_t command_frame[] = COMMAND_FRAME;
    uint8_t response_buffer[RESPONSE_LENGTH];
    struct timespec ts;
    FILE *log_file = NULL;

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("intrusion_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        uint32_t total_distance = 0;
        int valid_samples = 0;

        for (int i = 0; i < SAMPLES_PER_CYCLE; i++) {
            // Send command frame
            if (write(i2c_fd, command_frame, sizeof(command_frame)) != sizeof(command_frame)) {
                perror("Failed to write to I2C device");
                break;
            }

            // Wait at least 10 ms
            usleep(10000);

            // Read response
            if (read(i2c_fd, response_buffer, RESPONSE_LENGTH) != RESPONSE_LENGTH) {
                perror("Failed to read from I2C device");
                break;
            }

            // Verify header
            if (response_buffer[0] != HEADER_VALUE) {
                fprintf(stderr, "Invalid header value\n");
                break;
            }

            // Extract distance
            uint16_t distance = (response_buffer[11] << 8) | response_buffer[12];
            total_distance += distance;
            valid_samples++;
        }

        if (valid_samples > 0) {
            uint32_t average_distance = total_distance / valid_samples;

            // Check for intrusion
            if (average_distance < DISTANCE_THRESHOLD) {
                // Get current time
                if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                    perror("clock_gettime");
                    break;
                }

                // Log timestamp and average distance
                fprintf(log_file, "%ld.%09ld, %u\n", ts.tv_sec, ts.tv_nsec, average_distance);
                fflush(log_file);
            }
        }

        // Delay for 100 ms
        usleep(CYCLE_DELAY_MS * 1000);
    }

    // Close resources
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

