#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L0X_I2C_ADDRESS 0x29
#define VL53L0X_MODEL_ID 0xE5
#define VL53L0X_RESULT_INTERRUPT_STATUS 0x0B
#define VL53L0X_MODEL_ID_REG 0xC0

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint8_t model_id;
    uint8_t interrupt_status;
    uint16_t distance;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor presence by reading model ID
    if (i2c_smbus_read_byte_data(i2c_fd, VL53L0X_MODEL_ID_REG) != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Sensor model ID mismatch\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Poll RESULT_INTERRUPT_STATUS with 100ms timeout
        struct timespec timeout = {0, 100000000}; // 100ms
        if (nanosleep(&timeout, NULL) != 0) {
            perror("nanosleep");
            continue;
        }

        if (i2c_smbus_read_byte_data(i2c_fd, VL53L0X_RESULT_INTERRUPT_STATUS) < 0) {
