#define SI1182_I2C_ADDRESS 0x5A
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_CMD 0x08
#define SI1182_CMD_ALS_FORCE 0x0F
#define SI1182_REG_ALS_VIS_DATA0 0x22

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    char *i2c_dev = "/dev/i2c-1";
    uint8_t buffer[2];
    struct sigaction sa;

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is present
    buffer[0] = SI1182_REG_PART_ID;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, buffer, 1) != 1) {
        if (errno == EREMOTEIO) {
            fprintf(stderr, "Sensor not present (NACK received)\n");
        } else {
            perror("Failed to read from I2C");
        }
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Force an ALS measurement
        buffer[0] = SI1182_REG_CMD;
        buffer[1] = SI1182_CMD_ALS_FORCE;
        if (write(i2c_fd, buffer, 2) != 2) {
            perror("Failed to write to I2C");
            break;
        }

        // Read the proximity data
        buffer[0] = SI1182_REG_ALS_VIS_DATA0;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C");
            break;
        }
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C");
            break;
        }

        uint16_t proximity = (buffer[0] << 8) | buffer[1];
        printf("Proximity: %d\n", proximity);

        // Wait for 500 ms
        usleep(500000);
    }

    // Close the I2C bus
    close(i2c_fd);
    return 0;
}

