#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3101_ADDR 0x44
#define OPT3101_RESULT_REG 0x00
#define OPT3101_CONFIG_REG 0x01
#define OPT3101_LOW_LIMIT_REG 0x02
#define OPT3101_HIGH_LIMIT_REG 0x03
#define OPT3101_MANUFACTURER_ID_REG 0x7E
#define OPT3101_DEVICE_ID_REG 0x7F

#define MEASUREMENT_INTERVAL 500000 // 500 ms in microseconds

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint16_t result;
    uint8_t config;
    uint8_t error_flags;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read manufacturer ID and device ID to verify sensor presence
    uint16_t manufacturer_id, device_id;
    if (i2c_smbus_read_word_data(i2c_fd, OPT3101_MANUFACTURER_ID_REG) < 0 ||
        i2c_smbus_read_word_data(i2c_fd, OPT3101_DEVICE_ID_REG) < 0) {
        perror("Failed to read sensor ID");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Read result register
        result = i2c_smbus_read_word_data(i2c_fd, OPT3101_RESULT_REG);
        if (result < 0) {
            perror("Failed to read result register");
            continue;
        }

        // Read config register to check error flags
        config = i2c_smbus_read_byte_data(i2c_fd, OPT3101_CONFIG_REG);
        if (config < 0) {
            perror("Failed to read config register");
            continue;
        }

        // Extract error flags
        error_flags = (config >> 12) & 0x0F;

        // Calculate distance and ambient light
        float distance = (result * 0.01); // Assuming 1 cm per LSB
        float ambient_light = (result * 0.01); // Assuming 1 lux per LSB

        // Log the results
        printf("Distance: %.2f cm, Ambient Light: %.2f lux, Error Flags: 0x%02X\n", distance, ambient_light, error_flags);

        // Sleep for the specified interval
        usleep(MEASUREMENT_INTERVAL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

