#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_DURATION 10
#define TIMEOUT 200000 // 200 ms in microseconds
#define MAX_DISTANCE 38000 // 38 ms in microseconds

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct timespec start_time, end_time;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get trigger and echo lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines
    ret = gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0);
    if (ret < 0) {
        perror("Failed to request trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "ultrasonic_echo");
    if (ret < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_DURATION);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo rising edge
        ret = gpiod_line_event_wait(echo_line, TIMEOUT);
        if (ret < 0) {
            perror("Failed to wait for echo rising edge");
            break;
