#include <errno.h>

#define UART_DEVICE "/dev/serial0"
#define LED_GPIO_LINE 17
#define MAGIC_WORD 0x0201040306050807
#define DATA_FRAME_SIZE 128
#define DISTANCE_THRESHOLD 1.0f
#define CSV_FILE "intrusion_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_intrusion(float distance) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f\n", timestamp, distance);
    fclose(file);
}

void activate_alert_led(struct gpiod_chip *chip, struct gpiod_line *line) {
    int ret = gpiod_line_request_output(line, "alert_led", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return;
    }

    gpiod_line_set_value(line, 1);
    sleep(2);
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("Failed to open UART device");
        return EXIT_FAILURE;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &options);

    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(uart_fd);
        return EXIT_FAILURE;
    }

    uint64_t magic_word;
    uint16_t distance_bins[64];
    while (running) {
        ssize_t bytes_read = read(uart_fd, &magic_word, sizeof(magic_word));
        if (bytes_read != sizeof(magic_word)) {
            if (bytes_read < 0 && errno != EAGAIN) {
                perror("Failed to read UART");
            }
            continue;
        }

        if (magic_word != MAGIC_WORD) {
            continue;
        }

        bytes_read = read(uart_fd, distance_bins, DATA_FRAME_SIZE);
        if (bytes_read != DATA_FRAME_SIZE) {
            if (bytes_read < 0 && errno != EAGAIN) {
                perror("Failed to read UART");
            }
            continue;
        }

        for (int i = 0; i < 64; i++) {
            float distance = (distance_bins[i] * 0.002f); // Convert to meters
            if (distance <= DISTANCE_THRESHOLD) {
                log_intrusion(distance);
                activate_alert_led(chip, line);
                break;
            }
        }
    }

    gpiod_chip_close(chip);
    close(uart_fd);
    return EXIT_SUCCESS;
}

