#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_US 100000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
        sensor_line = NULL;
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int ret;
    struct timespec ts;
    int last_state = 1; // Assume no obstacle initially

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(sensor_line, "obstacle_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        perror("Failed to request buzzer line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int current_state;

        // Read the sensor state
        current_state = gpiod_line_get_value(sensor_line);
        if (current_state < 0) {
            perror("Failed to read sensor state");
            break;
        }

        // Log state transition
        if (current_state != last_state) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld-%02ld-%02ldT%02ld:%02ld:%02ld.%09ldZ: Obstacle %s\n",
                    ts.tv_sec / 31536000, (ts.tv_sec / 86400) % 30, (ts.tv_sec / 3600) % 24,
                    (ts.tv_sec / 60) % 60, ts.tv_sec % 60, ts.tv_nsec);
            fflush(log_file);
            last_state = current_state;
        }

        // Update the buzzer state
        ret = gpiod_line_set_value(buzzer_line, !current_state);
        if (ret < 0) {
            perror("Failed to set buzzer state");
            break;
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

