#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x50
#define LED_PIN 18
#define SDA_PIN 2
#define SCL_PIN 3
#define SAMPLE_INTERVAL_US 100000
#define MAX_I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_reg(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        if (write(i2c_fd, buf, 2) == 2) {
            return 0;
        }
        retries++;
        usleep(I2C_RETRY_DELAY_US);
    }
    perror("I2C write failed");
    return -1;
}

int i2c_read_reg(int reg, uint8_t *value) {
    uint8_t buf[1] = {reg};
    int retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        if (write(i2c_fd, buf, 1) == 1 && read(i2c_fd, value, 1) == 1) {
            return 0;
        }
        retries++;
        usleep(I2C_RETRY_DELAY_US);
    }
    perror("I2C read failed");
    return -1;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    int led_state = 0;
    int last_distance = 0;

    while (running) {
        uint8_t distance;
        if (i2c_read_reg(0x00, &distance) < 0) {
            fprintf(stderr, "Sensor absent or I2C error\n");
            cleanup();
            return EXIT_FAILURE;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1e6 + (current_time.tv_nsec - start_time.tv_nsec) / 1e3;
        printf("Time: %.3f ms, Distance: %d cm, LED Frequency: %.2f Hz\n", elapsed_time / 1000, distance, 1000.0 / (distance * 10));

        int blink_period = distance * 10; // 10 ms per cm
        if (blink_period < 10) blink_period = 10; // Minimum 10 ms blink period

        if (elapsed_time % (blink_period * 2) < blink_period) {
            led_state = 1;
        } else {
            led_state = 0;
        }

        gpiod_line_set_value(led_line, led_state);

        last_distance = distance;
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

