#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x50
#define MLX75030_CMD 0x00
#define MLX75030_DELAY_US 100000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "distance_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct timespec ts;
    uint8_t cmd = MLX75030_CMD;
    uint8_t distance_data[2];
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Write command to trigger measurement
        if (write(i2c_fd, &cmd, 1) != 1) {
            perror("Failed to write to I2C device");
            goto retry;
        }

        // Wait for measurement
        usleep(MLX75030_DELAY_US);

        // Read distance data
        if (read(i2c_fd, distance_data, 2) != 2) {
            perror("Failed to read from I2C device");
            goto retry;
        }

        // Calculate distance in cm
        uint16_t distance_cm = (distance_data[0] << 8) | distance_data[1];

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            goto retry;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write to log file
        fprintf(log_file, "%s,%u\n", timestamp, distance_cm);
        fflush(log_file);

retry:
        // Sleep for the next sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

