#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define DEBOUNCE_TIME_US 50000
#define POLL_INTERVAL_US 10000
#define LOG_FILE "proximity_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void log_event(int sensor_id, const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event);
    fflush(log_file);
}

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Failed to get GPIO line for sensor 1");
        ret = EXIT_FAILURE;
        goto exit_chip;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Failed to get GPIO line for sensor 2");
        ret = EXIT_FAILURE;
        goto exit_sensor1;
    }

    // Configure lines as input
    ret = gpiod_line_request_input(sensor1_line, "sensor1");
    if (ret < 0) {
        perror("Failed to request input for sensor 1");
        ret = EXIT_FAILURE;
        goto exit_sensor2;
    }

    ret = gpiod_line_request_input(sensor2_line, "sensor2");
    if (ret < 0) {
        perror("Failed to request input for sensor 2");
        ret = EXIT_FAILURE;
        goto exit_sensor1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        ret = EXIT_FAILURE;
        goto exit_sensor2;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        ret = EXIT_FAILURE;
        goto exit_log;
    }

    // Initial state reading
    int sensor1_state = gpiod_line_get_value(sensor1_line);
    int sensor2_state = gpiod_line_get_value(sensor2_line);

    while (running) {
        // Poll sensor 1
        int new_state = gpiod_line_get_value(sensor1_line);
        if (new_state != sensor1_state) {
            usleep(DEBOUNCE_TIME_US);
            new_state = gpiod_line_get_value(sensor1_line);
            if (new_state != sensor1_state) {
                if (new_state == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
                sensor1_state = new_state;
            }
        }

        // Poll sensor 2
        new_state = gpiod_line_get_value(sensor2_line);
        if (new_state != sensor2_state) {
            usleep(DEBOUNCE_TIME_US);
            new_state = gpiod_line_get_value(sensor2_line);
            if (new_state != sensor2_state) {
                if (new_state == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
                sensor2_state = new_state;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

exit_log:
    fclose(log_file);
exit_sensor2:
    gpiod_line_release(sensor2_line);
exit_sensor1:
    gpiod_line_release(sensor1_line);
exit_chip:
    gpiod_chip_close(chip);

    return ret;
}

