#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x52
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x10

#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_distance(FILE *csv_file, int distance_mm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(csv_file, "%s,%d\n", timestamp, distance_mm);
    fflush(csv_file);
}

int i2c_combined_write_then_read(int fd, uint8_t reg, uint8_t *data, size_t data_len, uint8_t *read_data, size_t read_len) {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data msgset;

    msgs[0].addr = SENSOR_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = data_len;
    msgs[0].buf = data;

    msgs[1].addr = SENSOR_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = read_len;
    msgs[1].buf = read_data;

    msgset.nmsgs = 2;
    msgset.msgs = msgs;

    if (ioctl(fd, I2C_RDWR, &msgset) < 0) {
        perror("ioctl(I2C_RDWR)");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen("distance_log.csv", "a");
    if (!csv_file) {
        perror("fopen");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t reg = MEAS_STATUS_REG;
        uint8_t status = 0;

        if (i2c_combined_write_then_read(i2c_fd, reg, &reg, 1, &status, 1) < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            continue;
        }

        if (status & 0x01) { // Check if measurement is ready
            uint8_t distance_data[2];
            if (i2c_combined_write_then_read(i2c_fd, DISTANCE_REG, &reg, 1, distance_data, 2) < 0) {
                fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
                continue;
            }

            int distance_mm = (distance_data[0] << 8) | distance_data[1];
            log_distance(csv_file, distance_mm);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(csv_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

