#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VL53L5CX_I2C_ADDR 0x29

#define VL53L5CX_SYSTEM_START_ROI 0x0000
#define VL53L5CX_SYSTEM_ROI_CONFIG 0x0004
#define VL53L5CX_SYSTEM_ZONE_CONFIG 0x0008
#define VL53L5CX_SYSTEM_RESULTS 0x0010

#define VL53L5CX_ROI_CONFIG_MODE_ROI 0x01
#define VL53L5CX_ROI_CONFIG_ROI_XY_SIZE 0x08
#define VL53L5CX_ROI_CONFIG_ROI_XY_OFFSET 0x00

#define VL53L5CX_ZONE_CONFIG_XY_SIZE 0x08
#define VL53L5CX_ZONE_CONFIG_XY_OFFSET 0x00

#define VL53L5CX_ZONE_RESULTS_BASE 0x0010

#define ZONE_COUNT 64

int i2c_fd = -1;
volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_reg16(int reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value & 0xFF;
    if (write(i2c_fd, buf, 3) != 3) {
        perror("i2c_write_reg16");
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int reg, uint16_t *value) {
    uint8_t buf[2] = {(reg >> 8) & 0xFF, reg & 0xFF};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("i2c_read_reg16 write");
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        perror("i2c_read_reg16 read");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    atexit(cleanup);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return EXIT_FAILURE;
    }

    // Initialize ROI and zone configuration
    if (i2c_write_reg16(VL53L5CX_SYSTEM_START_ROI, 0x01) < 0) {
        return EXIT_FAILURE;
    }

    if (i2c_write_reg16(VL53L5CX_SYSTEM_ROI_CONFIG, VL53L5CX_ROI_CONFIG_MODE_ROI | VL53L5CX_ROI_CONFIG_ROI_XY_SIZE | VL53L5CX_ROI_CONFIG_ROI_XY_OFFSET) < 0) {
        return EXIT_FAILURE;
    }

    if (i2c_write_reg16(VL53L5CX_SYSTEM_ZONE_CONFIG, VL53L5CX_ZONE_CONFIG_XY_SIZE | VL53L5CX_ZONE_CONFIG_XY_OFFSET) < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t distances[ZONE_COUNT];
        for (int i = 0; i < ZONE_COUNT; i++) {
            int reg = VL53L5CX_ZONE_RESULTS_BASE + (i * 2);
            if (i2c_read_reg16(reg, &distances[i]) < 0) {
                return EXIT_FAILURE;
            }
        }

        for (int i = 0; i < ZONE_COUNT; i++) {
            printf("Zone %02d: %d mm\n", i, distances[i]);
        }
        printf("\n");

        usleep(500000); // 500 ms
    }

    return EXIT_SUCCESS;
}

