    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    atexit(cleanup);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return EXIT_FAILURE;
    }

    // Initialize ROI and zone configuration
    if (i2c_write_reg16(VL53L5CX_SYSTEM_START_ROI, 0x01) < 0) {
        return EXIT_FAILURE;
    }

    if (i2c_write_reg16(VL53L5CX_SYSTEM_ROI_CONFIG, VL53L5CX_ROI_CONFIG_MODE_ROI | VL53L5CX_ROI_CONFIG_ROI_XY_SIZE | VL53L5CX_ROI_CONFIG_ROI_XY_OFFSET) < 0) {
        return EXIT_FAILURE;
    }

    if (i2c_write_reg16(VL53L5CX_SYSTEM_ZONE_CONFIG, VL53L5CX_ZONE_CONFIG_XY_SIZE | VL53L5CX_ZONE_CONFIG_XY_OFFSET) < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t distances[ZONE_COUNT];
        for (int i = 0; i < ZONE_COUNT; i++) {
            int reg = VL53L5CX_ZONE_RESULTS_BASE + (i * 2);
            if (i2c_read_reg16(reg, &distances[i]) < 0) {
                return EXIT_FAILURE;
            }
        }

        for (int i = 0; i < ZONE_COUNT; i++) {
            printf("Zone %02d: %d mm\n", i, distances[i]);
        }
        printf("\n");

        usleep(500000); // 500 ms
    }

    return EXIT_SUCCESS;
}
```

This code initializes the VL53L5CX sensor on the I2C bus, configures it for an 8x8 zone grid, and reads the distance data from each zone every 500 ms. It includes error handling for I2C communication and ensures that resources are released properly on exit.

