#define VL53L4CX_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_RESULT_IO_RANGE_MILLIMETRES 0x001E

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L4CX_I2C_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t status;
        if (write(i2c_fd, &VL53L4CX_SYSTEM_INTERRUPT_STATUS, 1) != 1) {
            perror("write");
            continue;
        }
        if (read(i2c_fd, &status, 1) != 1) {
            perror("read");
            continue;
        }

        if (status & 0x01) {
            if (write(i2c_fd, &VL53L4CX_RESULT_RANGE_STATUS, 1) != 1) {
                perror("write");
                continue;
            }
            uint8_t range_status;
            if (read(i2c_fd, &range_status, 1) != 1) {
                perror("read");
                continue;
            }

            if (range_status == 0x04) {
                if (write(i2c_fd, &VL53L4CX_RESULT_IO_RANGE_MILLIMETRES, 1) != 1) {
                    perror("write");
                    continue;
                }
                uint8_t distance[2];
                if (read(i2c_fd, distance, 2) != 2) {
                    perror("read");
                    continue;
                }

                uint16_t distance_mm = (distance[0] << 8) | distance[1];

                struct timespec ts;
                if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                    perror("clock_gettime");
                    continue;
                }

                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));
                printf("Timestamp: %s.%06ld, Distance: %u mm\n", timestamp, ts.tv_nsec / 1000, distance_mm);
            }
        }

        usleep(500000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

