#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define TIMEOUT_US 50000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define MIN_ANGLE -90
#define MAX_ANGLE 90
#define LOOP_INTERVAL_US 200000

volatile sig_atomic_t running = 1;

void cleanup(int sig) {
    running = 0;
    gpioTerminate();
    printf("Exiting...\n");
    exit(EXIT_SUCCESS);
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioServo(SERVO_PIN, 0);

    return 0;
}

int measure_distance() {
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    usleep(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    struct timespec start, end;
    if (gpioTick() == 0) {
        return -1; // Error in gpioTick
    }

    if (gpioWaitForEdge(ECHO_PIN, RISING_EDGE, TIMEOUT_US) < 0) {
        return -1; // Timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    if (gpioWaitForEdge(ECHO_PIN, FALLING_EDGE, TIMEOUT_US) < 0) {
        return -1; // Timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    int distance_cm = duration / 58;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -1; // Out of range
    }

    return distance_cm;
}

int map_distance_to_angle(int distance_cm) {
    return MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
}

void log_distance(int distance_cm) {
    FILE *log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    fprintf(log_file, "%s.%03ld, %d cm\n", time_str, ts.tv_nsec / 1000000, distance_cm);
    fclose(log_file);
}

int main() {
    if (setup_gpio() < 0) {
        fprintf(stderr, "Failed to set up GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (running) {
        int distance_cm = measure_distance();
        if (distance_cm >= 0) {
            int angle = map_distance_to_angle(distance_cm);
            gpioServo(SERVO_PIN, angle * 1000 / 180 + 1500);
            log_distance(distance_cm);
        }

        usleep(LOOP_INTERVAL_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

