#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <mqueue.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDR 0x29
#define GPIO_CHIP "gpiochip0"
#define BUZZER_PIN 23
#define MESSAGE_QUEUE "/vl53l1x_queue"
#define QUEUE_PERMISSIONS 0666
#define QUEUE_SIZE 10
#define QUEUE_MSG_SIZE sizeof(int)

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *gpio_chip;
    struct gpiod_line *buzzer_line;
    mqd_t mq;
    struct sigaction sa;
    struct i2c_msg msgs[2];
    uint8_t reg[2];
    uint8_t data[2];
    int distance;

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    if (!(gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP))) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Get buzzer line
    if (!(buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_PIN))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request buzzer line for output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open message queue
    if ((mq = mq_open(MESSAGE_QUEUE, O_CREAT | O_RDWR, QUEUE_PERMISSIONS, NULL)) == (mqd_t)-1) {
