#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define TIMEOUT_US 100000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define BUZZER_THRESHOLD_CM 30

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void sigint_handler(int sig) {
    running = 0;
}

static int measure_distance(void) {
    struct timespec start, end;
    int ret;

    // Generate a 10us HIGH pulse on the trigger pin
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for the echo pin to go HIGH
    ret = gpiod_line_event_wait(echo_line, TIMEOUT_US * 1000);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout: No echo received\n");
        return -1;
    }

    // Read the start time
    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("clock_gettime");
        return -1;
    }

    // Wait for the echo pin to go LOW
    ret = gpiod_line_event_wait(echo_line, TIMEOUT_US * 1000);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout: Echo did not stop\n");
        return -1;
    }

    // Read the end time
    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        perror("clock_gettime");
        return -1;
    }

    // Calculate the echo time in microseconds
    long echo_time_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Calculate the distance in centimeters
    int distance_cm = (echo_time_us * 34000) / 200000;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Invalid reading: Distance out of range\n");
        return -1;
    }

    return distance_cm;
}

int main(void) {
    int ret;
    struct sigaction sa;

    // Initialize signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request the trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure the trigger line as output
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure the echo line as input with rising and falling edge events
    ret = gpiod_line_request_both_edges_events(echo_line, "echo");
    if (ret < 0) {
        perror("gpiod_line_request_both_edges_events");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure the buzzer line as output
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int distance_cm = measure_distance();
        if (distance_cm >= 0) {
            printf("Distance: %d cm\n", distance_cm);
            if (distance_cm < BUZZER_THRESHOLD_CM) {
                gpiod_line_set_value(buzzer_line, 1);
            } else {
                gpiod_line_set_value(buzzer_line, 0);
            }
        }
        usleep(100000); // 100ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

