#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDR 0x29
#define SERVO_GPIO 18
#define SERVO_OPEN_US 1000
#define SERVO_CLOSE_US 1500
#define DISTANCE_THRESHOLD 200  // 20 cm in mm

#define LOG_FILE "gate_log.txt"

volatile sig_atomic_t running = 1;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), event);
    fclose(log);
}

void handle_signal(int sig) {
    running = 0;
}

int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

void i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
    }
}

uint16_t i2c_read16(int fd, uint8_t reg) {
    uint8_t buf[2] = {reg, 0};
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return 0;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return 0;
    }
    return (buf[0] << 8) | buf[1];
}

void vl53l1x_init(int fd) {
    i2c_write(fd, 0x0000, 0x00);  // Software reset
    usleep(100000);  // Wait for boot
    i2c_write(fd, 0x0008, 0x01);  // Start ranging
}

uint16_t vl53l1x_read_distance(int fd) {
    return i2c_read16(fd, 0x001E);  // Read distance in mm
}

void servo_init(int gpio) {
    gpioSetMode(gpio, PI_OUTPUT);
    gpioSetPWMfrequency(gpio, 50);  // 50 Hz PWM
}

void servo_set_position(int gpio, int us) {
    gpioSetPWMrange(gpio, us);
    gpioPWM(gpio, us);
}

void force_open() {
    log_event("Force open command received");
    servo_set_position(SERVO_GPIO, SERVO_OPEN_US);
}

void force_close() {
    log_event("Force close command received");
    servo_set_position(SERVO_GPIO, SERVO_CLOSE_US);
}

void status_request() {
    log_event("Status request command received");
}

void remote_control_callback(int cmd) {
    switch (cmd) {
        case 1:
            force_open();
            break;
        case 2:
            force_close();
            break;
        case 3:
            status_request();
            break;
        default:
            log_event("Unknown command received");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = i2c_init(I2C_BUS, VL53L1X_I2C_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    vl53l1x_init(i2c_fd);

    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    servo_init(SERVO_GPIO);

    while (running) {
        uint16_t distance = vl53l1x_read_distance(i2c_fd);
        char event[100];
        snprintf(event, sizeof(event), "Distance: %d mm", distance);
        log_event(event);

        if (distance < DISTANCE_THRESHOLD) {
            servo_set_position(SERVO_GPIO, SERVO_OPEN_US);
            log_event("Gate opened");
        } else {
            servo_set_position(SERVO_GPIO, SERVO_CLOSE_US);
            log_event("Gate closed");
