#include <errno.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 200000
#define TRIGGER_PULSE_US 10
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define TIMEOUT_US 60000

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    running = 0;
}

static void log_message(const char *message) {
    fprintf(stdout, "%s\n", message);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
}

static void log_distance(uint64_t timestamp, uint64_t pulse_duration) {
    double distance_cm = pulse_duration * 0.034 / 2.0;
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", localtime(&timestamp));
    fprintf(stdout, "%s: Distance = %.2f cm\n", timestamp_str, distance_cm);
    fprintf(log_file, "%s: Distance = %.2f cm\n", timestamp_str, distance_cm);
    fflush(log_file);
}

static void echo_callback(struct gpiod_line *line, unsigned int event_type, uint64_t timestamp) {
    static uint64_t rising_tick = 0;
    static uint64_t falling_tick = 0;

    if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        rising_tick = timestamp;
    } else if (event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        falling_tick = timestamp;

        if (falling_tick < rising_tick) {
            falling_tick += UINT64_MAX;
        }

        uint64_t pulse_duration = falling_tick - rising_tick;

        if (pulse_duration < MIN_PULSE_WIDTH_US || pulse_duration > MAX_PULSE_WIDTH_US) {
            log_message("Warning: Invalid pulse width");
        } else {
            time_t now = time(NULL);
            log_distance(now, pulse_duration);
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("Failed to get TRIG line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get ECHO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(trig_line, "ultrasonic_trig", 0);
    if (ret < 0) {
        perror("Failed to request TRIG line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "ultrasonic_echo");
    if (ret < 0) {
        perror("Failed to request ECHO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_event(echo_line, "ultrasonic_echo_event");
    if (ret < 0) {
        perror("Failed to request ECHO line event");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        gpiod_line_set_value(trig_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trig_line, 0);

        struct gpiod_line_event event;
        uint64_t start_time = gpiod_line_event_get_timestamp_ns(&event);

        while (running) {
            ret = gpiod_line_event_wait(echo_line, NULL);
            if (ret < 0) {
                perror("Failed to wait for ECHO event");
                break;
            }

            ret = gpiod_line_event_read(echo_line, &event);
            if (ret < 0) {
                perror("Failed to read ECHO event");
                break;
            }

            echo_callback(echo_line, event.event_type, gpiod_line_event_get_timestamp_ns(&event) / 1000);

            if (gpiod_line_event_get_timestamp_ns(&event) - start_time > TIMEOUT_US * 1000) {
                log_message("Warning: Timeout waiting for echo");
                break;
            }
        }

        usleep(SAMPLE_INTERVAL_US - TRIGGER_PULSE_US);
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

