#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <vl53l1x_api.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_18 18
#define GPIO_PIN_19 19
#define LOG_FILE "gate_events.log"
#define POLL_INTERVAL_US 500000
#define MAX_DISTANCE_MM 200

static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line_18 = NULL;
static struct gpiod_line *gpio_line_19 = NULL;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static bool running = true;

void cleanup() {
    if (gpio_chip) {
        if (gpio_line_18) {
            gpiod_line_release(gpio_line_18);
        }
        if (gpio_line_19) {
            gpiod_line_release(gpio_line_19);
        }
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    running = false;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize VL53L1X sensor
    VL53L1X_Dev_t dev;
    if (VL53L1X_Init(&dev, i2c_fd) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Perform soft reset
    if (VL53L1X_SensorInit(&dev) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to perform soft reset on VL53L1X sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set timing budget
    if (VL53L1X_SetTimingBudgetInMs(&dev, 10) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to set timing budget on VL53L1X sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Start ranging
    if (VL53L1X_StartRanging(&dev) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to start ranging on VL53L1X sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    gpio_line_18 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_18);
    gpio_line_19 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_19);
    if (!gpio_line_18 || !gpio_line_19) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure GPIO lines
    if (gpiod_line_request_output(gpio_line_18, "gate_control", 0) < 0 ||
        gpiod_line_request_output(gpio_line_19, "gate_control", 1) < 0) {
        perror("Failed to request GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t distance_mm;
        if (VL53L1X_GetDistance(&dev, &distance_mm) != VL53L1X_ERROR_NONE) {
            fprintf(stderr, "Failed to read distance from VL53L1X sensor\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (distance_mm <= MAX_DISTANCE_MM) {
            gpiod_line_set_value(gpio_line_18, 1);
            gpiod_line_set_value(gpio_line_19, 0);
            log_event("Gate opened");
        } else {
            gpiod_line_set_value(gpio_line_18, 0);
            gpiod_line_set_value(gpio_line_19, 1);
            log_event("Gate closed");
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

