This code initializes the VL53L1X sensor, configures it, and continuously polls for distance measurements. It controls GPIO pins based on the distance and logs events to a file. It handles signals to ensure proper cleanup on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDR 0x29
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define GPIO_TRIGGER 24

#define VL53L1X_SOFT_RESET 0x0000
#define VL53L1X_START_MEASURE 0x0011
#define VL53L1X_STATUS 0x0013
#define VL53L1X_DISTANCE 0x0014

#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void stop_motor() {
    gpioWrite(GPIO_FORWARD, PI_LOW);
    gpioWrite(GPIO_BACKWARD, PI_LOW);
}

void cleanup(int i2c_fd) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    stop_motor();
    gpioTerminate();
}

int i2c_write(int fd, uint16_t reg, uint16_t value) {
    uint8_t buffer[3];
    buffer[0] = (reg >> 8) & 0xFF;
    buffer[1] = reg & 0xFF;
    buffer[2] = value & 0xFF;
    int retries = 0;
    while (write(fd, buffer, 3) != 3) {
        if (errno == EIO) {
            if (retries < 5) {
                retries++;
                usleep(1000 << retries);
                continue;
            }
        }
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint16_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = (reg >> 8) & 0xFF;
    buffer[1] = reg & 0xFF;
    int retries = 0;
    while (write(fd, buffer, 2) != 2) {
        if (errno == EIO) {
            if (retries < 5) {
                retries++;
                usleep(1000 << retries);
                continue;
            }
        }
        perror("I2C write failed");
        return -1;
    }
    retries = 0;
    while (read(fd, buffer, 2) != 2) {
        if (errno == EIO) {
            if (retries < 5) {
                retries++;
                usleep(1000 << retries);
                continue;
            }
        }
        perror("I2C read failed");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void sensor_reset(int i2c_fd) {
    if (i2c_write(i2c_fd, VL53L1X_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        cleanup(i2c_fd);
        exit(EXIT_FAILURE);
    }
    usleep(1000);
}

void start_measurement(int i2c_fd) {
    if (i2c_write(i2c_fd, VL53L1X_START_MEASURE, 0x00) < 0) {
        fprintf(stderr, "Failed to start measurement\n");
        cleanup(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance(int i2c_fd) {
    uint16_t status;
    while (1) {
        if (i2c_read(i2c_fd, VL53L1X_STATUS, &status) < 0) {
            fprintf(stderr, "Failed to read status\n");
            cleanup(i2c_fd);
            exit(EXIT_FAILURE);
        }
        if (status & 0x01) {
            break;
        }
        usleep(1000);
    }
    uint16_t distance;
    if (i2c_read(i2c_fd, VL53L1X_DISTANCE, &distance) < 0) {
        fprintf(stderr, "Failed to read distance\n");
        cleanup(i2c_fd);
        exit(EXIT_FAILURE);
    }
    return distance;
}

void handle_trigger(int gpio, int level, uint32_t tick) {
    if (level == PI_RISING) {
        int i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            return;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
            perror("Failed to set I2C address");
            close(i2c_fd);
            return;
        }
        sensor_reset(i2c_fd);
        start_measurement(i2c_fd);
        uint16_t distance = read_distance(i2c_fd);
        printf("Distance: %d mm\n", distance);
        if (distance < DISTANCE_THRESHOLD_LOW) {
            gpioWrite(GPIO_FORWARD, PI_HIGH);
            gpioWrite(GPIO_BACKWARD, PI_LOW);
            printf("Motor: Forward\n");
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            gpioWrite(GPIO_FORWARD, PI_LOW);
            gpioWrite(GPIO_BACKWARD, PI_HIGH);
            printf("Motor: Backward\n");
        } else {
            stop_motor();
            printf("Motor: Stop\n");
        }
        close(i2c_fd);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetISRFunc(GPIO_TRIGGER, EITHER_EDGE, 0, handle_trigger);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    while (running) {
        usleep(100000);
    }
    cleanup(-1);
    return EXIT_SUCCESS;
}

