#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define MPR121_ELE0_11 0x00
#define MPR121_SOFT_RESET 0x80
#define MPR121_SOFT_RESET_VALUE 0x63
#define GPIO_CHIP "gpiochip0"
#define LED_PINS {17, 18, 27, 22}

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    printf("%s: %s\n", ctime(&now), event);
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Soft reset the MPR121
    if (i2c_write(i2c_fd, MPR121_SOFT_RESET, MPR121_SOFT_RESET_VALUE) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait for reset to complete

