        i2c_write_reg(MPR121_ESI, 0x00) < 0 ||
        i2c_write_reg(MPR121_DEBOUNCE, 0x10) < 0 ||
        i2c_write_reg(MPR121_AFE_CONFIG, 0x10) < 0 ||
        i2c_write_reg(MPR121_BASELINE_FILTER, 0x20) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

