    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "proximity_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity detector initialized. Monitoring for touch events...\n");

    while (1) {
        uint8_t touch_status;
        if (i2c_read_reg(MPR121_ELE_TOUCH_STATUS, &touch_status) < 0) {
            continue;
        }
        if (touch_status) {
            printf("Touch detected: 0x%02X\n", touch_status);
            gpiod_line_set_value(led_line, 1);
            sleep(1);
            gpiod_line_set_value(led_line, 0);
            log_event("Touch event detected");
        }
        usleep(100000); // 100ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

