#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 30000
#define DISTANCE_MIN 2
#define DISTANCE_MAX 400
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int sig) {
    sigint_received = 1;
}

void log_distance(FILE *log_file, double distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

double measure_distance(struct gpiod_chip *chip) {
    struct gpiod_line *trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("gpiod_line_request_input");
        return -1;
    }

    // Trigger pulse
    gpiod_line_set_value(trigger_line, 0);
    usleep(5);
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo rising edge
    struct timespec start, end;
    if (gpiod_line_event_wait(echo_line, TIMEOUT_US * 1000) < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    }

    if (gpiod_line_get_value(echo_line) == 0) {
        fprintf(stderr, "Echo never rose\n");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Wait for echo falling edge
    if (gpiod_line_event_wait(echo_line, TIMEOUT_US * 1000) < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
        perror("clock_gettime");
        return -1;
    }

    long pulse_width_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    double distance_cm = pulse_width_us * 0.0343 / 2;

    if (distance_cm < DISTANCE_MIN || distance_cm > DISTANCE_MAX) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance_cm);
        return -1;
    }

    return distance_cm;
}

int main() {
    signal(SIGINT, sigint_handler);

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!sigint_received) {
        double distance = measure_distance(chip);
        if (distance >= 0) {
            log_distance(log_file, distance);
        }
        sleep(1);
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

