#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDRESS 0x29
#define XSHUT_PIN 27

#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L1X_REG_RESULT_DISTANCE_MM 0x1E

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *xshut_line;
    int i2c_fd;
    char i2c_filename[20];
    uint8_t buffer[3];
    uint16_t distance;
    uint8_t status;

    openlog("vl53l1x_sensor", LOG_PID, LOG_USER);

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    xshut_line = gpiod_chip_get_line(chip, XSHUT_PIN);
    if (!xshut_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d", XSHUT_PIN);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(xshut_line, "vl53l1x_xshut", 1) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %d as output", XSHUT_PIN);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Initialize I2C
    snprintf(i2c_filename, 19, I2C_BUS);
    i2c_fd = open(i2c_filename, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s", I2C_BUS);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X", VL53L1X_I2C_ADDRESS);
        close(i2c_fd);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        // Start ranging
        buffer[0] = VL53L1X_REG_SYSRANGE_START;
        buffer[1] = 0x01;
        if (write(i2c_fd, buffer, 2) != 2) {
            syslog(LOG_ERR, "Failed to start ranging");
            continue;
        }

        // Wait for measurement to complete
        usleep(100000);

        // Read status and distance
        buffer[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
        if (write(i2c_fd, buffer, 1) != 1) {
            syslog(LOG_ERR, "Failed to write to RESULT_RANGE_STATUS register");
            continue;
        }

        if (read(i2c_fd, &status, 1) != 1) {
            syslog(LOG_ERR, "Failed to read RESULT_RANGE_STATUS register");
            continue;
        }

        if (status & 0x01) {
            buffer[0] = VL53L1X_REG_RESULT_DISTANCE_MM;
            if (write(i2c_fd, buffer, 1) != 1) {
                syslog(LOG_ERR, "Failed to write to RESULT_DISTANCE_MM register");
                continue;
            }

            if (read(i2c_fd, buffer, 2) != 2) {
                syslog(LOG_ERR, "Failed to read RESULT_DISTANCE_MM register");
                continue;
            }

            distance = (buffer[0] << 8) | buffer[1];
            syslog(LOG_INFO, "Distance: %d mm, Status: 0x%02X", distance, status);
        } else {
            syslog(LOG_ERR, "Measurement failed, Status: 0x%02X", status);
        }

        usleep(100000);
    }

    // Cleanup
    close(i2c_fd);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

