#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 24
#define DISTANCE_THRESHOLD 200 // 20 cm in mm

#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS_GPIO 0x13
#define VL53L1X_REG_RESULT_DISTANCE_MM 0x1E

#define VL53L1X_SYSRANGE_MODE_BACKTOBACK 0x04

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(line, "gate_actuator", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t sysrange_start[] = {VL53L1X_REG_SYSRANGE_START, VL53L1X_SYSRANGE_MODE_BACKTOBACK};
    if (write(i2c_fd, sysrange_start, sizeof(sysrange_start)) != sizeof(sysrange_start)) {
        perror("Failed to write to VL53L1X");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t range_status;
        if (read(i2c_fd, &range_status, 1) != 1) {
            perror("Failed to read range status from VL53L1X");
            break;
        }

        if (range_status & 0x01) {
            uint8_t distance_mm[2];
            if (read(i2c_fd, distance_mm, 2) != 2) {
                perror("Failed to read distance from VL53L1X");
                break;
            }

            uint16_t distance = (distance_mm[0] << 8) | distance_mm[1];
            float distance_cm = distance / 10.0;

            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %.1f cm", distance_cm);
            log_message(log_message);

            int current_state = gpiod_line_get_value(line);
            if (distance_cm < DISTANCE_THRESHOLD && current_state == 0) {
                gpiod_line_set_value(line, 1);
                log_message("Gate opened");
            } else if (distance_cm >= DISTANCE_THRESHOLD && current_state == 1) {
                gpiod_line_set_value(line, 0);
                log_message("Gate closed");
            }

            usleep(100000); // 100 ms
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    log_message("Program terminated");

    return EXIT_SUCCESS;
}

