    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(line, "gate_actuator", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t sysrange_start[] = {VL53L1X_REG_SYSRANGE_START, VL53L1X_SYSRANGE_MODE_BACKTOBACK};
    if (write(i2c_fd, sysrange_start, sizeof(sysrange_start)) != sizeof(sysrange_start)) {
        perror("Failed to write to VL53L1X");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t range_status;
        if (read(i2c_fd, &range_status, 1) != 1) {
            perror("Failed to read range status from VL53L1X");
            break;
        }

        if (range_status & 0x01) {
            uint8_t distance_mm[2];
            if (read(i2c_fd, distance_mm, 2) != 2) {
                perror("Failed to read distance from VL53L1X");
                break;
            }

            uint16_t distance = (distance_mm[0] << 8) | distance_mm[1];
            float distance_cm = distance / 10.0;

            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %.1f cm", distance_cm);
            log_message(log_message);

            int current_state = gpiod_line_get_value(line);
            if (distance_cm < DISTANCE_THRESHOLD && current_state == 0) {
                gpiod_line_set_value(line, 1);
                log_message("Gate opened");
            } else if (distance_cm >= DISTANCE_THRESHOLD && current_state == 1) {
                gpiod_line_set_value(line, 0);
                log_message("Gate closed");
            }

            usleep(100000); // 100 ms
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    log_message("Program terminated");

    return EXIT_SUCCESS;
}
