#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TIMEOUT_US 30000
#define SAMPLES 5
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

volatile sig_atomic_t running = 1;
volatile sig_atomic_t new_pulse = 0;
volatile uint32_t pulse_width = 0;

void sigint_handler(int sig) {
    running = 0;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;

    if (level == PI_TIMEOUT) {
        pulse_width = 0;
        new_pulse = 1;
    } else if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        pulse_width = tick - start_tick;
        new_pulse = 1;
    }
}

double calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) {
        return -1.0;
    }
    double distance = (pulse_width / 2.0) * 0.0343; // cm
    return distance;
}

int main() {
    FILE *log_file = fopen("distance_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    fflush(log_file);

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO modes");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        perror("Failed to set alert function");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(SERVO_PIN, 50);
    gpioServo(SERVO_PIN, 1500); // 90 degrees

    signal(SIGINT, sigint_handler);

    double distances[SAMPLES] = {0};
    int index = 0;
    double filtered_distance = 0;

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (new_pulse) {
            double distance = calculate_distance(pulse_width);
            new_pulse = 0;

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                distances[index] = distance;
                index = (index + 1) % SAMPLES;
                filtered_distance = 0;
                for (int i = 0; i < SAMPLES; i++) {
                    filtered_distance += distances[i];
                }
                filtered_distance /= SAMPLES;
            } else {
                filtered_distance = -1.0;
                gpioServo(SERVO_PIN, 1500); // 90 degrees
            }
        }

        fprintf(log_file, "%s,%.1f,90\n", timestamp, filtered_distance);
        fflush(log_file);

        usleep(100000); // 100 ms
    }

    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

