#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define DEFAULT_I2C_ADDRESS 0x5A
#define DEFAULT_THRESHOLD 1000
#define GPIO_LINE 27
#define LOG_FILE "proximity.log"

static int i2c_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;
static uint16_t threshold = DEFAULT_THRESHOLD;
static uint16_t i2c_address = DEFAULT_I2C_ADDRESS;
static volatile int interrupt_flag = 0;

void sigint_handler(int sig) {
    running = 0;
}

void *interrupt_handler_thread(void *arg) {
    while (running) {
        if (interrupt_flag) {
            pthread_mutex_lock(&log_mutex);
            interrupt_flag = 0;

            // Read proximity value
            uint8_t buffer[2];
            if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x0F, 2, buffer) != 2) {
                fprintf(stderr, "Failed to read proximity value: %s\n", strerror(errno));
                pthread_mutex_unlock(&log_mutex);
                continue;
            }
            uint16_t proximity = (buffer[0] << 8) | buffer[1];

            // Get current timestamp
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            // Determine status
            const char *status = (proximity <= threshold) ? "SAFE" : "ALERT";

            // Write to log file
            dprintf(log_fd, "%s %u %s\n", timestamp, proximity, status);
            if (fflush(stdout) == EOF) {
                fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
            }

            pthread_mutex_unlock(&log_mutex);
        }
        usleep(1000); // Sleep for 1ms
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    // Parse command-line options
    int opt;
    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                threshold = strtoul(optarg, NULL, 10);
                break;
            case 'a':
                i2c_address = strtoul(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-a i2c_address]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_rising_edge_events(gpio_line, "proximity_sensor") < 0) {
        fprintf(stderr, "Failed to request rising edge events: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Start interrupt handler thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, interrupt_handler_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create interrupt handler thread: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(gpio_line, NULL) < 0) {
            fprintf(stderr, "Failed to wait for GPIO event: %s\n", strerror(errno));
            break;
        }
        if (gpiod_line_event_read(gpio_line, &event) < 0) {
            fprintf(stderr, "Failed to read GPIO event: %s\n", strerror(errno));
            break;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            interrupt_flag = 1;
        }
    }

    // Clean up
    pthread_join(thread, NULL);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    close(log_fd);

    return 0;
}

