#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000
#define LOOP_INTERVAL_US 500000

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct timespec start_time, end_time;
    long long pulse_duration;
    double distance;
    int ret;

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Configure trigger pin as output
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line (trigger)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (trigger)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure echo pin as input
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line (echo)");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_input(echo_line, "ultrasonic_echo");
    if (ret < 0) {
        perror("gpiod_line_request_input (echo)");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!exit_flag) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for the echo pulse
        ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        } else if (ret == 0) {
            printf("Invalid reading\n");
            continue;
        }

        // Measure the pulse duration
        if (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("clock_gettime (start)");
                break;
            }
            while (gpiod_line_get_value(echo_line) == 1 && !exit_flag) {
                if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
                    perror("clock_gettime (end)");
                    break;
                }
                pulse_duration = (end_time.tv_sec - start_time.tv_sec) * 1000000LL +
                                 (end_time.tv_nsec - start_time.tv_nsec) / 1000LL;
                if (pulse_duration > TIMEOUT_US) {
                    printf("Invalid reading\n");
                    break;
                }
            }
        } else {
            printf("Invalid reading\n");
            continue;
        }

        // Calculate distance
        distance = pulse_duration * 0.034 / 2.0;

        // Check distance validity
        if (distance < 2.0 || distance > 400.0) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0) {
                printf(" Too close!");
            }
            printf("\n");
        }

        // Wait for the next loop
        usleep(LOOP_INTERVAL_US - pulse_duration);
    }

    // Clean up
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return 0;
}

