#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1175_ADDRESS 0x5A
#define SI1175_REG_PART_ID 0x00
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

#define LOG_FILE "proximity_log.csv"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is present
    uint8_t part_id;
    if (write(i2c_fd, &SI1175_REG_PART_ID, 1) != 1) {
        perror("Failed to write to I2C");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, &part_id, 1) != 1) {
        perror("Failed to read from I2C");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (part_id != 0x45) { // Expected part ID for Si1175
        fprintf(stderr, "Sensor not found or incorrect part ID\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Write header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }

    while (1) {
        // Read ambient light value
        uint8_t data[2];
        if (write(i2c_fd, &SI1175_REG_ALS_VIS_DATA0, 1) != 1) {
            perror("Failed to write to I2C");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from I2C");
            cleanup();
            exit(EXIT_FAILURE);
        }
        uint16_t als_visible = (data[1] << 8) | data[0];

        // Get current time
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        // Write to log file
        fprintf(log_file, "%s,%u\n", timestamp, als_visible);
        fflush(log_file);

        // Wait for 5 seconds
        sleep(5);
    }

    cleanup();
    return 0;
}

