#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define SI1120_I2C_ADDR 0x60
#define SI1120_PART_ID_REG 0x00
#define SI1120_PART_ID_VALUE 0x40
#define SI1120_RESET_CMD_REG 0x07
#define SI1120_RESET_CMD_VALUE 0x11
#define SI1120_ALS_VIS_DATA_REG 0x22
#define SI1120_PROX_DATA_REG 0x26
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "si1120_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *data, size_t len) {
    for (int i = 0; i <= MAX_RETRIES; i++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, data, len) == len) {
                return 0;
            }
        }
        if (i < MAX_RETRIES) {
            usleep(RETRY_DELAY_US);
        } else {
            fprintf(stderr, "Failed to read from I2C register 0x%02X\n", reg);
            return -1;
        }
    }
    return -1;
}

int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    for (int i = 0; i <= MAX_RETRIES; i++) {
        if (write(fd, data, 2) == 2) {
            return 0;
        }
        if (i < MAX_RETRIES) {
            usleep(RETRY_DELAY_US);
        } else {
            fprintf(stderr, "Failed to write to I2C register 0x%02X\n", reg);
            return -1;
        }
    }
    return -1;
}

void log_data(FILE *log, uint16_t als, uint16_t prox) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log, "%s ALS: %u, Prox: %u\n", timestamp, als, prox);
}

int main() {
    signal(SIGINT, sigint_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1120_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2c_read_register(i2c_fd, SI1120_PART_ID_REG, &part_id, 1) < 0) {
        fprintf(stderr, "Failed to read part ID\n");
        fclose(log);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (part_id != SI1120_PART_ID_VALUE) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        fclose(log);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_register(i2c_fd, SI1120_RESET_CMD_REG, SI1120_RESET_CMD_VALUE) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        fclose(log);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t als_data[2], prox_data[2];
        if (i2c_read_register(i2c_fd, SI1120_ALS_VIS_DATA_REG, als_data, 2) < 0 ||
            i2c_read_register(i2c_fd, SI1120_PROX_DATA_REG, prox_data, 2) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        uint16_t als = (als_data[1] << 8) | als_data[0];
        uint16_t prox = (prox_data[1] << 8) | prox_data[0];

        log_data(log, als, prox);

        usleep(500000);
    }

    fclose(log);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

