    uint8_t part_id;
    if (i2c_read_byte(i2c_fd, SI1145_REG_PART_ID, &part_id) != 0) {
        log_message("Failed to read part ID");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        log_message("Incorrect part ID");
        return -1;
