    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_si1145() != 0) {
        log_message("Failed to initialize SI1145");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "[%s] Proximity: %d\n", timestamp, proximity);
            fflush(log_file);
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

