#define ECHO_PIN 18
#define BUZZER_PIN 27
#define TRIGGER_PULSE_US 10
#define DISTANCE_THRESHOLD_CM 20

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    running = 0;
}

static void echo_callback(struct gpiod_line *line, unsigned int event_type, unsigned long long timestamp) {
    static unsigned long long start_time = 0;
    static unsigned long long end_time = 0;

    if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        start_time = timestamp;
    } else if (event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        end_time = timestamp;
        unsigned long long pulse_width = end_time - start_time;
        double distance_cm = (pulse_width * 0.034) / 2.0; // Speed of sound is approximately 340 m/s

        printf("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < DISTANCE_THRESHOLD_CM) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }
    }
}

int main() {
    struct sigaction sa;
    struct gpiod_line_event_config event_config = GPIOD_LINE_EVENT_CONFIG_RISING_EDGE | GPIOD_LINE_EVENT_CONFIG_FALLING_EDGE;

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        exit(EXIT_FAILURE);
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);

    if (!trigger_line || !echo_line || !buzzer_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure lines
    if (gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "ultrasonic_echo") < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up echo line event monitoring
    if (gpiod_line_event_request(echo_line, &event_config) < 0) {
        perror("gpiod_line_event_request");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Generate trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for events
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(echo_line, NULL) < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        while (gpiod_line_event_read(echo_line, &event) == 0) {
            echo_callback(echo_line, event.event_type, event.timestamp_ns);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 0;
}
