#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <time.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define TIMEOUT_US 1000000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

double measure_distance(struct gpiod_chip *chip) {
    struct gpiod_line *trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger || !echo) {
        perror("Failed to get GPIO lines");
        return -1.0;
    }

    if (gpiod_line_request_output(trigger, "trigger", 0) < 0) {
        perror("Failed to request trigger line");
        return -1.0;
    }
    if (gpiod_line_request_input(echo, "echo") < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger);
        return -1.0;
    }

    gpiod_line_set_value(trigger, 1);
    usleep(10);
    gpiod_line_set_value(trigger, 0);

    struct timespec start, end;
    if (gpiod_line_event_wait(echo, NULL) < 0) {
        perror("Failed to wait for echo event");
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        return -1.0;
    }

    if (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("Failed to get start time");
            gpiod_line_release(trigger);
            gpiod_line_release(echo);
            return -1.0;
        }
        while (gpiod_line_get_value(echo) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get end time");
                gpiod_line_release(trigger);
                gpiod_line_release(echo);
                return -1.0;
            }
            if (timespec_subtract(&end, &start) > TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                gpiod_line_release(trigger);
                gpiod_line_release(echo);
                return -1.0;
            }
        }
    } else {
        fprintf(stderr, "Echo not detected\n");
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        return -1.0;
    }

    long duration = timespec_subtract(&end, &start);
    double distance = (duration * 0.0343) / 2; // Speed of sound in cm/us / 2
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    return distance;
}

int set_servo_angle(struct gpiod_chip *chip, double distance) {
    struct gpiod_line *servo = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(servo, "servo", 0) < 0) {
        perror("Failed to request servo line");
        return -1;
    }

    int pulse_width = 500 + (distance - MIN_DISTANCE) * (2500 - 500) / (MAX_DISTANCE - MIN_DISTANCE);
    gpiod_line_set_value(servo, 1);
    usleep(pulse_width);
    gpiod_line_set_value(servo, 0);
    gpiod_line_release(servo);
    return 0;
}

long timespec_subtract(struct timespec *end, struct timespec *start) {
    long diff = (end->tv_sec - start->tv_sec) * 1000000 + (end->tv_nsec - start->tv_nsec) / 1000;
    return diff;
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        double distance = measure_distance(chip);
        if (distance < 0) {
            continue;
        }
        printf("Distance: %.2f cm\n", distance);

        if (set_servo_angle(chip, distance) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        usleep(100000); // 100 ms
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

