#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDRESS 0x29
#define VL53L1X_MODEL_ID_REG 0xC0
#define VL53L1X_MODEL_ID 0xE3
#define VL53L1X_TIMING_BUDGET_REG 0x4B
#define VL53L1X_DISTANCE_REG 0x8F
#define GPIO_SERVO 18
#define PULSE_WIDTH_MIN 1000
#define PULSE_WIDTH_MAX 2000
#define PULSE_WIDTH_STEP 100
#define PULSE_WIDTH_TRANSITION_TIME 100000 // 100 ms

int i2c_fd = -1;
int servo_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (servo_fd != -1) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_word(int reg) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(VL53L1X_TIMING_BUDGET_REG, 0x20) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int model_id = i2c_read_word(VL53L1X_MODEL_ID_REG);
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: %04X\n", model_id);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SERVO, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_SERVO, 50); // 50 Hz

    if ((log_file = fopen("gate_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    int current_pulse_width = PULSE_WIDTH_MIN;
    int last_distance = -1;

    while (running) {
        int distance = i2c_read_word(VL53L1X_DISTANCE_REG);
        if (distance < 0) {
            continue;
        }

        int target_pulse_width;
        if (distance > 250) {
            target_pulse_width = PULSE_WIDTH_MIN;
        } else if (distance < 200) {
            target_pulse_width = PULSE_WIDTH_MAX;
        } else {
            target_pulse_width = current_pulse_width;
        }

        if (target_pulse_width != current_pulse_width) {
            if (target_pulse_width > current_pulse_width) {
                for (int i = current_pulse_width; i <= target_pulse_width; i += PULSE_WIDTH_STEP) {
                    gpioPWM(GPIO_SERVO, i);
                    usleep(PULSE_WIDTH_TRANSITION_TIME);
                }
            } else {
                for (int i = current_pulse_width; i >= target_pulse_width; i -= PULSE_WIDTH_STEP) {
                    gpioPWM(GPIO_SERVO, i);
                    usleep(PULSE_WIDTH_TRANSITION_TIME);
                }
            }
            current_pulse_width = target_pulse_width;
            if (distance > 250) {
                log_event("Gate opened");
            } else {
                log_event("Gate closed");
            }
        }

        last_distance = distance;
        usleep(100000); // 100 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

