#define I2C_BUS_PATH "/dev/i2c-1"
#define SI7005_ADDRESS 0x40
#define CONFIG_REGISTER 0x00
#define TEMP_REGISTER 0x03

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int open_i2c_bus(const char *bus_path, int address) {
    int fd = open(bus_path, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void close_i2c_bus(int fd) {
    close(fd);
}

int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C register");
        return -1;
    }
    return 0;
}

int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C register");
        return -1;
    }
    return 0;
}

int read_temperature(int fd) {
    uint8_t temp;
    if (write_register(fd, TEMP_REGISTER, 0) != 0) {
        return -1;
    }
    usleep(10000);

    if (read_register(fd, TEMP_REGISTER, &temp) != 0) {
        return -1;
    }
    return temp;
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open_i2c_bus(I2C_BUS_PATH, SI7005_ADDRESS);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        if (write_register(fd, CONFIG_REGISTER, 0x00) != 0) {
            close_i2c_bus(fd);
            fd = open_i2c_bus(I2C_BUS_PATH, SI7005_ADDRESS);
            if (fd < 0) {
                break;
            }
            continue;
        }
        usleep(10000);

        int temp = read_temperature(fd);
        if (temp < 0) {
            close_i2c_bus(fd);
            fd = open_i2c_bus(I2C_BUS_PATH, SI7005_ADDRESS);
            if (fd < 0) {
                break;
            }
            continue;
        }

        printf("Temperature: %d\n", temp);
        sleep(2);
    }

    close_i2c_bus(fd);
    return EXIT_SUCCESS;
}

