#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define ACCEL_XOUT_H_REG 0x3B
#define ACCEL_XOUT_L_REG 0x3C
#define ACCEL_YOUT_H_REG 0x3D
#define ACCEL_YOUT_L_REG 0x3E
#define ACCEL_ZOUT_H_REG 0x3F
#define ACCEL_ZOUT_L_REG 0x40
#define TEMP_OUT_H_REG 0x41
#define TEMP_OUT_L_REG 0x42
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x44
#define GYRO_YOUT_H_REG 0x45
#define GYRO_YOUT_L_REG 0x46
#define GYRO_ZOUT_H_REG 0x47
#define GYRO_ZOUT_L_REG 0x48

#define MPU6050_WHO_AM_I 0x68

int i2c_fd = -1;
volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    printf("Clean shutdown\n");
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "Sensor not found: expected 0x%02X, got 0x%02X\n", MPU6050_WHO_AM_I, who_am_i);
        cleanup();
        exit(EXIT_FAILURE);
    }

    printf("MPU6050 sensor found and initialized\n");

    while (running) {
        uint8_t buffer[14];
        if (write(i2c_fd, &ACCEL_XOUT_H_REG, 1) != 1) {
            perror("Failed to write register address");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (read(i2c_fd, buffer, 14) != 14) {
            perror("Failed to read sensor data");
            cleanup();
            exit(EXIT_FAILURE);
        }

        int16_t accel_x = (buffer[0] << 8) | buffer[1];
        int16_t accel_y = (buffer[2] << 8) | buffer[3];
        int16_t accel_z = (buffer[4] << 8) | buffer[5];
        int16_t temp = (buffer[6] << 8) | buffer[7];
        int16_t gyro_x = (buffer[8] << 8) | buffer[9];
        int16_t gyro_y = (buffer[10] << 8) | buffer[11];
        int16_t gyro_z = (buffer[12] << 8) | buffer[13];

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        printf("Temp: %d\n", temp);
        printf("Gyro X: %d, Y: %d, Z: %d\n", gyro_x, gyro_y, gyro_z);

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

