#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF
#define SHT40_READ_INTERVAL 5000000 // 5 seconds in microseconds

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int sht40_read_temp_hum(float *temp, float *hum) {
    uint8_t cmd = SHT40_CMD_HIGH_REP;
    uint8_t response[SHT40_RESPONSE_LEN];

    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("I2C write error");
        return -1;
    }

    usleep(10000); // Wait at least 10 ms

    if (read(i2c_fd, response, SHT40_RESPONSE_LEN) != SHT40_RESPONSE_LEN) {
        perror("I2C read error");
        return -1;
    }

    uint8_t temp_crc = sht40_crc8(response, SHT40_TEMP_LEN);
    uint8_t hum_crc = sht40_crc8(response + SHT40_TEMP_LEN + SHT40_CRC_LEN, SHT40_HUM_LEN);

    if (temp_crc != response[SHT40_TEMP_LEN] || hum_crc != response[SHT40_TEMP_LEN + SHT40_CRC_LEN + SHT40_HUM_LEN]) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    *temp = ((response[0] << 8) | response[1]) * 175.0 / 65535.0 - 45.0;
    *hum = ((response[2] << 8) | response[3]) * 100.0 / 65535.0;

    return 0;
}

void close_i2c() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

