#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_TA 0x06
#define MLX90614_TOBJ1 0x07

#define BUFFER_SIZE 1024

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;

    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

float convert_to_celsius(uint16_t raw) {
    return (raw * 0.02) - 273.15;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t ambient_raw, object_raw;
        float ambient_temp, object_temp;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (i2c_read_word(i2c_fd, MLX90614_TA, &ambient_raw) < 0) {
            fprintf(stderr, "Failed to read ambient temperature\n");
            sleep(5);
            continue;
        }

        if (i2c_read_word(i2c_fd, MLX90614_TOBJ1, &object_raw) < 0) {
            fprintf(stderr, "Failed to read object temperature\n");
            sleep(5);
            continue;
        }

        ambient_temp = convert_to_celsius(ambient_raw);
        object_temp = convert_to_celsius(object_raw);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
        fflush(log_file);

        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

