#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x3615
#define MEASUREMENT_CMD 0x0000
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t config_cmd[2] = {CONTINUOUS_MEASUREMENT_CMD >> 8, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    if (write(i2c_fd, config_cmd, sizeof(config_cmd)) != sizeof(config_cmd)) {
        perror("Failed to send configuration command");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    while (running) {
        uint8_t measurement_cmd[2] = {MEASUREMENT_CMD >> 8, MEASUREMENT_CMD & 0xFF};
        if (write(i2c_fd, measurement_cmd, sizeof(measurement_cmd)) != sizeof(measurement_cmd)) {
            perror("Failed to send measurement command");
            break;
        }

        usleep(1000); // Wait at least 1 ms

        uint8_t data[9];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read measurement data");
            break;
        }

        if (calculate_crc8(data, 3) != data[3] || calculate_crc8(data + 4, 3) != data[7] || calculate_crc8(data + 8, 3) != data[11]) {
            fprintf(stderr, "CRC8 validation failed\n");
