int i2c_write(int fd, uint16_t command) {
    uint8_t buf[2] = {command >> 8, command & 0xFF};
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(fd, buf, 2) == 2) {
            return 0;
        }
        retries++;
        usleep(BACKOFF_BASE_US * (1 << retries));
    }
    return -1;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(fd, buf, len) == len) {
            return 0;
        }
        retries++;
        usleep(BACKOFF_BASE_US * (1 << retries));
    }
    return -1;
}

