    uint16_t pressure_raw = (response[0] << 8) | response[1];
    uint16_t temperature_raw = (response[4] << 8) | response[5];

    *pressure_pa = (pressure_raw * 100.0f) / 2048.0f;
    *temperature_c = (temperature_raw * 175.0f) / 65535.0f - 45.0f;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
