#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7015_ADDR 0x40
#define SI7015_TEMP_NO_HOLD 0xF3
#define SI7015_HUM_NO_HOLD 0xF5
#define SAMPLE_INTERVAL 5

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int sig) {
    running = 0;
}

int i2c_write(uint8_t reg) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(uint16_t *value) {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_and_print(const char *message, double value) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %.2f\n", timestamp, value);
    printf("%s: %.2f\n", timestamp, value);
}

int main() {
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7015_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        // Read temperature
        if (i2c_write(SI7015_TEMP_NO_HOLD) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(20000); // Wait for measurement to be ready
        uint16_t temp_raw;
        if (i2c_read(&temp_raw) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        double temperature = (175.72 * temp_raw / 65536.0) - 46.85;

        // Read humidity
        if (i2c_write(SI7015_HUM_NO_HOLD) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
