#define I2C_DEVICE "/dev/i2c-1"
#define SDP800_I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x3615
#define CRC8_POLYNOMIAL 0x31
#define BUFFER_SIZE 9

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd;
    uint8_t buffer[BUFFER_SIZE];
    struct timespec ts;
    FILE *file = fopen("airflow_data.txt", "w");

    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,Pressure (Pa),Temperature (C)\n");

    if (signal(SIGINT, handle_signal) == SIG_ERR ||
        signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        fclose(file);
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        fclose(file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        fclose(file);
        return EXIT_FAILURE;
    }

    uint16_t command = htons(CONTINUOUS_MEASUREMENT_COMMAND);
    if (write(i2c_fd, &command, sizeof(command)) != sizeof(command)) {
        perror("Failed to send command");
        close(i2c_fd);
        fclose(file);
        return EXIT_FAILURE;
    }

    while (running) {
        nanosleep((const struct timespec[]){{0, 45000000L}}, NULL);

        if (read(i2c_fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
            perror("Failed to read data");
            close(i2c_fd);
            fclose(file);
            return EXIT_FAILURE;
        }

        if (calculate_crc8(buffer, 3) != buffer[3] ||
            calculate_crc8(buffer + 3, 3) != buffer[6] ||
            calculate_crc8(buffer + 6, 3) != buffer[9]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        int32_t pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        int32_t temperature = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
        int32_t scale_factor = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        pressure = (pressure * 100) / scale_factor;
        temperature = (temperature * 200) / scale_factor - 50000;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, pressure, temperature);

        fflush(file);
        nanosleep((const struct timespec[]){{0, 100000000L}}, NULL);
    }

    close(i2c_fd);
    fclose(file);
    return EXIT_SUCCESS;
}

