        return;
    }
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(file, "[%s] %s\n", timestamp, message);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        log_message("error_log.txt", "Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        log_message("error_log.txt", "Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t cmd[2] = {STS30_CMD >> 8, STS30_CMD & 0xFF};
    uint8_t response[3];

    while (running) {
        if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
            perror("Failed to write to I2C device");
            log_message("error_log.txt", "Failed to write to I2C device");
            break;
        }

        usleep(15000); // Wait at least 15 ms for conversion

