            log_message("error_log.txt", "Failed to read from I2C device");
            break;
        }

        uint8_t calculated_crc = crc8(response, 2, CRC8_INIT);
        if (calculated_crc != response[2]) {
            log_message("error_log.txt", "CRC mismatch");
            continue;
        }

        uint16_t raw_temp = (response[0] << 8) | response[1];
        double temperature = -45.0 + 175.0 * raw_temp / 65535.0;

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Temperature: %.2f°C", temperature);
        log_message("enclosure_temp_log.txt", log_message);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

