            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_reading(FILE *log_file, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
}

