    if (read(i2c_fd, buffer, 6) != 6) {
        perror("I2C read error");
        return -1;
    }
    if (crc8(buffer, 2, CRC8_INIT) != buffer[2] || crc8(buffer + 4, 2, CRC8_INIT) != buffer[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
