#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SI7021_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_COUNT 3
#define FAN_DELAY_US 10000

typedef struct {
    time_t timestamp;
    float temperature;
} TempReading;

TempReading buffer[BUFFER_SIZE];
int buffer_index = 0;
int fan_state = 0;
int i2c_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *fan_line = NULL;

void handle_sigint(int sig) {
    if (fan_state) {
        gpiod_line_set_value(fan_line, 0);
        fan_state = 0;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

float read_temperature() {
    uint8_t command = 0xF3; // Start temperature measurement
    uint8_t data[2];
    int retries = RETRY_COUNT;

    while (retries--) {
        if (write(i2c_fd, &command, 1) != 1) {
            perror("I2C write failed");
            continue;
        }

        usleep(100000); // Wait for measurement to complete

        if (read(i2c_fd, data, 2) != 2) {
            perror("I2C read failed");
            continue;
        }

        // Convert raw data to temperature
        int16_t raw_temp = (data[0] << 8) | data[1];
        float temperature = (raw_temp * 175.72 / 65536.0) - 46.85;
        return temperature;
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1.0;
}

void update_fan_state(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH && !fan_state) {
        gpiod_line_set_value(fan_line, 1);
        fan_state = 1;
        usleep(FAN_DELAY_US);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_state) {
        gpiod_line_set_value(fan_line, 0);
        fan_state = 0;
    }
}

void buffer_temperature(float temperature) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        float temperature = read_temperature();
        if (temperature >= 0.0) {
            update_fan_state(temperature);
            buffer_temperature(temperature);
            printf("Timestamp: %s - Temperature: %.2f°C\n", ctime(&buffer[buffer_index].timestamp), temperature);
        }
        sleep(2);
    }

    return 0;
}

