#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SCD40_ADDR 0x62
#define SCD40_CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_CMD_READ_MEASUREMENT 0xEC05
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int signum) {
    if (signum == SIGINT) {
        uint16_t cmd = SCD40_CMD_STOP_PERIODIC_MEASUREMENT;
        if (write(i2c_fd, &cmd, 2) != 2) {
            fprintf(stderr, "Failed to send stop command: %s\n", strerror(errno));
        }
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void log_data(uint16_t co2, int16_t temp, uint16_t humidity) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2, temp / 100.0, humidity / 1000.0);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    // Initialize GPIO for LED (optional, for indication)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, 17); // GPIO 17
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "scd40_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Start periodic measurement
    uint16_t cmd = SCD40_CMD_START_PERIODIC_MEASUREMENT;
    if (write(i2c_fd, &cmd, 2) != 2) {
        fprintf(stderr, "Failed to send start command: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Wait at least one second before the first read
    sleep(1);

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Poll data-ready flag
        uint16_t read_cmd = SCD40_CMD_READ_MEASUREMENT;
        if (write(i2c_fd, &read_cmd, 2) != 2) {
            fprintf(stderr, "Failed to send read command: %s\n", strerror(errno));
            continue;
        }

        uint8_t data[9];
        if (read(i2c_fd, data, 9) != 9) {
            fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
            continue;
        }

        // Verify CRCs
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        // Extract values
        uint16_t co2 = (data[0] << 8) | data[1];
        int16_t temp = (data[3] << 8) | data[4];
        uint16_t humidity = (data[6] << 8) | data[7];

        // Log data
        log_data(co2, temp, humidity);

        // Toggle LED (optional, for indication)
        gpiod_line_set_value(led_line, 1);
        usleep(100000);
        gpiod_line_set_value(led_line, 0);

        // Wait five seconds before the next read
        sleep(5);
    }

    cleanup();
    return 0;
}

