typedef struct {
    uint16_t co2;
    int16_t temperature;
    int16_t humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

struct gpiod_chip *chip;
struct gpiod_line *led_line;

void sigint_handler(int sig) {
    if (chip) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
    }
    exit(0);
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        perror("i2c write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (i2c_write(fd, reg, NULL, 0) < 0) {
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("i2c read");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

