        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    uint8_t start_cmd[] = {0x21, 0xB1};
    if (i2c_write(i2c_fd, 0, start_cmd, sizeof(start_cmd)) < 0) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        sleep(5);

        uint8_t data[9];
        if (i2c_read(i2c_fd, 0, data, sizeof(data)) < 0) {
            continue;
        }

        uint16_t co2 = (data[0] << 8) | data[1];
        int16_t temperature = ((data[3] << 8) | data[4]) / 100.0;
        int16_t humidity = ((data[6] << 8) | data[7]) / 100.0;

        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        buffer[buffer_index].co2 = co2;
        buffer[buffer_index].temperature = temperature;
        buffer[buffer_index].humidity = humidity;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        printf("CO2: %u ppm, Temperature: %.2f C, Humidity: %.2f %%\n", co2, temperature, humidity);

        if (co2 > 1000) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
    }

    return 0;
}

