#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 5000000 // 5 seconds
#define TIMEOUT 50000 // 50 ms
#define VALID_TEMP_MIN -40.0
#define VALID_TEMP_MAX 150.0
#define CONSECUTIVE_FAILURES_THRESHOLD 3

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int consecutive_failures = 0;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

void log_entry(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

double calculate_temperature(unsigned long long high_time, unsigned long long total_time) {
    if (total_time == 0) {
        return 0.0; // Division by zero guard
    }
    double duty_cycle = (double)high_time / total_time;
    // TMP05 specific calculation (example formula, adjust as needed)
    double temperature = 25.0 * duty_cycle; // Placeholder formula
    return temperature;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "tmp05_reader");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        unsigned long long high_time = 0;
        unsigned long long total_time = 0;
        int high = 0;
        struct timespec start, end;

        // Wait for the first edge
        ret = gpiod_line_event_wait(line, TIMEOUT);
        if (ret < 0) {
            perror("Failed to wait for edge");
            continue;
        }

        // Measure high time
        if (gpiod_line_get_value(line) == 1) {
            high = 1;
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                if (timespec_diff_ns(&end, &start) > TIMEOUT) {
                    log_entry("Timeout waiting for high edge");
                    break;
                }
            }
            high_time = timespec_diff_ns(&end, &start);
        }

        // Measure low time
        if (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                if (timespec_diff_ns(&end, &start) > TIMEOUT) {
                    log_entry("Timeout waiting for low edge");
                    break;
                }
            }
            total_time = timespec_diff_ns(&end, &start);
        }

        if (high_time == 0 || total_time == 0) {
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES_THRESHOLD) {
                log_entry("SENSOR MALFUNCTION");
                consecutive_failures = 0;
            }
            continue;
        }

        double temperature = calculate_temperature(high_time, total_time);
        if (temperature >= VALID_TEMP_MIN && temperature <= VALID_TEMP_MAX) {
            char message[100];
            snprintf(message, sizeof(message), "Temperature: %.2f°C", temperature);
            log_entry(message);
            consecutive_failures = 0;
        } else {
            log_entry("Invalid temperature reading");
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES_THRESHOLD) {
                log_entry("SENSOR MALFUNCTION");
                consecutive_failures = 0;
            }
        }

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

unsigned long long timespec_diff_ns(const struct timespec *a, const struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000000ULL + (a->tv_nsec - b->tv_nsec);
}

