    int32_t temperature_raw = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    double pressure_pa = pressure_raw * 2.0 / scale_factor;
    double temperature_c = temperature_raw / 200.0;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fflush(csv_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t cmd = htons(CONTINUOUS_MEASUREMENT_CMD);
    if (write(i2c_fd, &cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send continuous measurement command");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen("airflow.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    fflush(csv_file);

    while (running) {
        read_and_log_data();
        sleep(1);
    }

    fclose(csv_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

