#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    close_resources();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht35(float *temperature, float *humidity) {
    uint8_t cmd[2] = {(SHT35_CMD >> 8) & 0xFF, SHT35_CMD & 0xFF};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to write to I2C");
        return -1;
    }
    usleep(15000); // Wait at least 15 ms

    uint8_t data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read from I2C");
        return -1;
    }

    if (calculate_crc8(data, 2) != data[2] || calculate_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *temperature = ((data[0] << 8) | data[1]) * 175.0 / 65535.0 - 45.0;
    *humidity = ((data[3] << 8) | data[4]) * 100.0 / 65535.0;
    return 0;
}

void log_reading(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_resources();
        return EXIT_FAILURE;
    }

    log_file = fopen("environment.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        if (fprintf(log_file, "Timestamp,Temperature (C),Humidity (%)\n") < 0) {
            perror("Failed to write header to log file");
            close_resources();
            return EXIT_FAILURE;
        }
    }

    while (1) {
        float temperature, humidity;
        if (read_sht35(&temperature, &humidity) == 0) {
            log_reading(temperature, humidity);
        }
        sleep(5);
    }

    close_resources();
    return EXIT_SUCCESS;
}

