int read_sensor(int i2c_fd, uint8_t command, float *value) {
    uint8_t buffer[3];
    struct timespec timeout = {0, 100000000}; // 100 ms

    if (write(i2c_fd, &command, 1) != 1) {
        perror("I2C write command");
        return -1;
    }

    while (1) {
        if (read(i2c_fd, buffer, 3) == 3) {
            if (buffer[2] == crc8(buffer, 2)) {
                *value = (buffer[0] << 8) | buffer[1];
