#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x3615
#define CONVERSION_TIME_US 1000000
#define CRC8_POLYNOMIAL 0x31

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    close_resources();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close_resources();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("airflow.dat", "wb");
    if (!log_file) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    // Start continuous measurement
    uint8_t cmd[2] = {CONTINUOUS_MEASUREMENT_CMD >> 8, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write command");
        close_resources();
        return EXIT_FAILURE;
    }

    while (1) {
        // Wait for conversion
        usleep(CONVERSION_TIME_US);

        // Read 9 bytes of data
        uint8_t data[9];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read data");
            close_resources();
            return EXIT_FAILURE;
        }

        // Validate CRC-8 for pressure and temperature
        if (calculate_crc8(data, 3) != data[3] || calculate_crc8(data + 4, 3) != data[7]) {
            fprintf(stderr, "CRC-8 validation failed\n");
            continue;
        }

        // Convert raw data to floating-point values
        uint32_t pressure_raw = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
        uint32_t temperature_raw = ((uint32_t)data[4] << 16) | ((uint32_t)data[5] << 8) | data[6];
        float pressure = (float)pressure_raw / 100.0f;
        float temperature = (float)temperature_raw / 200.0f - 50.0f;

        // Log the data
        if (fwrite(&pressure, sizeof(pressure), 1, log_file) != 1 ||
            fwrite(&temperature, sizeof(temperature), 1, log_file) != 1) {
            perror("Failed to write to log file");
            close_resources();
            return EXIT_FAILURE;
        }

        // Flush the log file to ensure data is written
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

