#define LPS33HW_PRESS_OUT_XL 0x28
#define LPS33HW_TEMP_OUT_L 0x2C
#define LPS33HW_CTRL_REG1 0x10

volatile sig_atomic_t terminate = 0;

void handle_sigint(int sig) {
    terminate = 1;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct sigaction sa;
    struct tm *tm_info;
    char timestamp[20];
    char log_entry[100];
    uint8_t reg;
    uint8_t data[3];
    int32_t pressure;
    int16_t temperature;
    float pressure_hpa;
    float temperature_c;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LPS33HW_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Enable sensor
    reg = 0xB1; // Enable sensor, 1 Hz data rate
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        // Read pressure
        reg = LPS33HW_PRESS_OUT_XL;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to I2C device");
            goto error;
        }
        if (read(i2c_fd, data, 3) != 3) {
            perror("Failed to read from I2C device");
            goto error;
        }
        pressure = (data[2] << 16) | (data[1] << 8) | data[0];
        pressure_hpa = pressure / 4096.0;

        // Read temperature
        reg = LPS33HW_TEMP_OUT_L;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to I2C device");
            goto error;
        }
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from I2C device");
            goto error;
        }
        temperature = (data[1] << 8) | data[0];
        temperature_c = temperature / 100.0;

        // Get current time
        time_t now = time(NULL);
        localtime_r(&now, tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Create log entry
        snprintf(log_entry, sizeof(log_entry), "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
                 timestamp, pressure_hpa, temperature_c);

        // Write log entry to file
        if (fprintf(log_file, "%s", log_entry) < 0) {
            perror("Failed to write to log file");
            goto error;
        }
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
        continue;

error:
        // Write error message to stderr and log file
        snprintf(log_entry, sizeof(log_entry), "%s, Error: %s\n", timestamp, strerror(errno));
        fprintf(stderr, "%s", log_entry);
        if (fprintf(log_file, "%s", log_entry) < 0) {
            perror("Failed to write to log file");
        }
        fflush(log_file);

        // Sleep for 1 second before retrying
        sleep(1);
    }

    // Close log file and I2C device
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

