#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SCD30_ADDR 0x61
#define LOG_FILE "air_quality.log"

#define CO2_MIN 800
#define CO2_LOW 1199
#define CO2_HIGH 1200

#define CMD_CONTINUOUS_MEASUREMENT 0x0219
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_DATA_READY 0x0202

#define CRC8_POLYNOMIAL 0x31

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write(int fd, uint8_t cmd, const uint8_t *data, size_t len) {
    uint8_t buffer[2 + len];
    buffer[0] = cmd >> 8;
    buffer[1] = cmd & 0xFF;
    memcpy(buffer + 2, data, len);
    if (write(fd, buffer, 2 + len) != 2 + len) {
        perror("i2c write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t cmd, uint8_t *data, size_t len) {
    if (i2c_write(fd, cmd, NULL, 0) < 0) {
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("i2c read");
        return -1;
    }
    return 0;
}

int scd30_data_ready(int fd) {
    uint16_t ready;
    if (i2c_read(fd, CMD_DATA_READY, (uint8_t *)&ready, 2) < 0) {
        return -1;
    }
    return ready;
}

int scd30_read_measurement(int fd, float *co2, float *temp, float *humidity) {
    uint8_t buffer[18];
    if (i2c_read(fd, CMD_READ_MEASUREMENT, buffer, 18) < 0) {
        return -1;
    }
    for (int i = 0; i < 6; i++) {
        if (buffer[i * 3 + 2] != calculate_crc8(buffer + i * 3, 2)) {
            fprintf(stderr, "CRC mismatch\n");
            return -1;
        }
    }
    *co2 = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    *temp = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
    *humidity = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];
    return 0;
}

void log_data(FILE *log, float co2, float temp, float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    fprintf(log, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temp / 100.0, humidity / 100.0);
    fflush(log);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SCD30_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, CMD_CONTINUOUS_MEASUREMENT, NULL, 0) < 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

