#define CMD_READ_MEASUREMENT 0x0300
#define CMD_DATA_READY 0x0202

#define CRC8_POLYNOMIAL 0x31

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write(int fd, uint8_t cmd, const uint8_t *data, size_t len) {
    uint8_t buffer[2 + len];
    buffer[0] = cmd >> 8;
    buffer[1] = cmd & 0xFF;
    memcpy(buffer + 2, data, len);
    if (write(fd, buffer, 2 + len) != 2 + len) {
        perror("i2c write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t cmd, uint8_t *data, size_t len) {
    if (i2c_write(fd, cmd, NULL, 0) < 0) {
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("i2c read");
        return -1;
    }
    return 0;
}

int scd30_data_ready(int fd) {
    uint16_t ready;
    if (i2c_read(fd, CMD_DATA_READY, (uint8_t *)&ready, 2) < 0) {
        return -1;
    }
    return ready;
}

int scd30_read_measurement(int fd, float *co2, float *temp, float *humidity) {
    uint8_t buffer[18];
    if (i2c_read(fd, CMD_READ_MEASUREMENT, buffer, 18) < 0) {
        return -1;
    }
    for (int i = 0; i < 6; i++) {
        if (buffer[i * 3 + 2] != calculate_crc8(buffer + i * 3, 2)) {
            fprintf(stderr, "CRC mismatch\n");
            return -1;
        }
    }
    *co2 = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    *temp = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
    *humidity = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];
    return 0;
}

