    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t config = HDC1000_CONFIG;
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write configuration to HDC1000");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t temp_reg[2] = {HDC1000_TEMP_REG, 0};
        if (write(i2c_fd, temp_reg, 2) != 2) {
            perror("Failed to initiate temperature conversion");
            continue;
        }

        usleep(20000); // Wait for conversion

        uint8_t temp_data[4];
        if (read(i2c_fd, temp_data, 4) != 4) {
            perror("Failed to read temperature data");
            continue;
        }

        uint16_t temp_raw = (temp_data[0] << 8) | temp_data[1];
        float temperature = (temp_raw / 65536.0) * 165.0 - 40.0;

        uint8_t hum_reg[2] = {HDC1000_HUM_REG, 0};
        if (write(i2c_fd, hum_reg, 2) != 2) {
            perror("Failed to initiate humidity conversion");
            continue;
        }

        usleep(20000); // Wait for conversion

        if (read(i2c_fd, temp_data, 4) != 4) {
            perror("Failed to read humidity data");
            continue;
        }

        uint16_t hum_raw = (temp_data[0] << 8) | temp_data[1];
        float humidity = (hum_raw / 65536.0) * 100.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        sleep(5);
    }

    return EXIT_SUCCESS;
}
