#define I2C_BUS "/dev/i2c-1"
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xF3
#define READ_TEMP_CMD 0xE0
#define I2C_TIMEOUT_MS 1000
#define LOG_INTERVAL_S 5

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int i2c_read(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[3];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    if (ioctl(fd, I2C_TIMEOUT, I2C_TIMEOUT_MS) < 0) {
        perror("I2C set timeout failed");
        return -1;
    }

    if (read(fd, buffer, 3) != 3) {
        perror("I2C read failed");
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

double convert_temp(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

