        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7051_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (i2c_read(i2c_fd, MEASURE_TEMP_CMD, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
        } else {
            temp_celsius = convert_temp(raw_temp);
            printf("Temperature: %.2f°C\n", temp_celsius);
        }

        sleep(LOG_INTERVAL_S);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

