#define I2C_BUS "/dev/i2c-1"
#define MLX90833_ADDR 0x24
#define MLX90833_REG_PRESSURE 0x00
#define MLX90833_REG_STATUS 0x01

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        exit(EXIT_FAILURE);
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(I2C_BUS)");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90833_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        uint8_t status;
        if (write(i2c_fd, &MLX90833_REG_STATUS, 1) != 1) {
            perror("write(MLX90833_REG_STATUS)");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        if (read(i2c_fd, &status, 1) != 1) {
            perror("read(MLX90833_REG_STATUS)");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        if (!(status & 0x01)) {
            fprintf(stderr, "Sensor not ready\n");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        uint8_t pressure_data[3];
        if (write(i2c_fd, &MLX90833_REG_PRESSURE, 1) != 1) {
            perror("write(MLX90833_REG_PRESSURE)");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        if (read(i2c_fd, pressure_data, 3) != 3) {
            perror("read(MLX90833_REG_PRESSURE)");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        uint32_t pressure = (pressure_data[0] << 16) | (pressure_data[1] << 8) | pressure_data[2];
        double pressure_pa = pressure * 0.01; // Convert to Pascals

        time_t now = time(NULL);
        printf("%sPressure: %.2f Pa\n", ctime(&now), pressure_pa);

        usleep(500000); // Sleep for 500 ms
    }

    close(i2c_fd);
    return 0;
}

