#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ICP10101_ADDR 0x60
#define ICP10101_CMD_START_TEMP 0x10
#define ICP10101_CMD_START_PRESS 0x30
#define ICP10101_CMD_READ 0x00
#define ICP10101_DEFAULT_VALUE 0xFFFF

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

int read_sensor(int i2c_fd, uint8_t cmd, int32_t *value) {
    uint8_t data[3];
    int ret;

    // Start measurement
    data[0] = cmd;
    ret = write(i2c_fd, data, 1);
    if (ret < 0) {
        perror("I2C write");
        return -1;
    }

    // Wait for measurement
    usleep(7000);

    // Read data
    data[0] = ICP10101_CMD_READ;
    ret = write(i2c_fd, data, 1);
    if (ret < 0) {
        perror("I2C write");
        return -1;
    }

    ret = read(i2c_fd, data, 3);
    if (ret < 0) {
        perror("I2C read");
        return -1;
    }

    // Combine bytes to form 24-bit value
    *value = (data[0] << 16) | (data[1] << 8) | data[2];

    // Check for default value
    if (*value == ICP10101_DEFAULT_VALUE) {
        fprintf(stderr, "Sensor read returned default value, assuming sensor is absent\n");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    int32_t temp, press;
    double temp_c, press_pa;
    struct timespec ts;
    char timestamp[21];

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP10101_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Install signal handlers
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install SIGTERM handler");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read temperature
        if (read_sensor(i2c_fd, ICP10101_CMD_START_TEMP, &temp) < 0) {
            continue;
        }
        temp_c = (temp >> 8) * 0.01;

        // Read pressure
        if (read_sensor(i2c_fd, ICP10101_CMD_START_PRESS, &press) < 0) {
            continue;
        }
        press_pa = (press >> 8) * 0.1;

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

        // Print result
        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temp_c, press_pa);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

