    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_I2C_ADDRESS) < 0) {
        perror("Failed to set the I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read pressure data from the sensor
        if (read(i2c_fd, i2c_buffer, 3) != 3) {
            fprintf(stderr, "Failed to read from the MLX90819 sensor: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        // Convert the raw data to pressure value
        pressure = ((uint16_t)i2c_buffer[0] << 8) | i2c_buffer[1];
        pressure = (pressure * 100) / 4096; // Convert to hPa

        // Get current time
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        // Print the timestamp and pressure value
        printf("%s: Pressure = %u hPa\n", timestamp, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    return 0;
}
