    if ((log_file = fopen("pressure_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t command[2] = {MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF};
        uint8_t response[9];

        // Trigger measurement
        if (write(i2c_fd, command, 2) != 2) {
            perror("Failed to write to I2C device");
            break;
        }

        // Wait for measurement to complete
        usleep(45000);

