                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                pressure, temperature);

        fflush(log_file);
        sleep(1); // Sample every second
    }

    // Close resources
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

