#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x24
#define MLX90821_REG_PRESSURE 0x00
#define MLX90821_MIN_PRESSURE 200000
#define MLX90821_MAX_PRESSURE 250000

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int open_i2c_bus() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_pressure(unsigned int *pressure) {
    unsigned char buffer[3];
    if (read(i2c_fd, buffer, 3) != 3) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (open_i2c_bus() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct stat st;
    if (fstat(fileno(log_file), &st) < 0) {
        perror("Failed to stat log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (st.st_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    while (1) {
        unsigned int pressure;
        if (read_pressure(&pressure) < 0) {
            if (open_i2c_bus() < 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            if (read_pressure(&pressure) < 0) {
                fprintf(stderr, "Failed to read pressure after retry\n");
                sleep(1);
                continue;
            }
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

        fprintf(log_file, "%s,%u\n", timestamp, pressure / 1000);

        if (pressure < MLX90821_MIN_PRESSURE || pressure > MLX90821_MAX_PRESSURE) {
            fprintf(stderr, "Warning: Pressure %u kPa is outside the safe tire range\n", pressure / 1000);
        }

        fflush(log_file);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

