#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNCHRONIZATION_TICKS 56
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define FILENAME "pressure_log.txt"

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

unsigned int read_ticks(struct gpiod_chip *chip, struct gpiod_line *line) {
    unsigned int ticks = 0;
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_nsec - start.tv_nsec > 1000000) {
            log_error("Timeout waiting for signal");
            return 0;
        }
    }

    while (gpiod_line_get_value(line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_nsec - start.tv_nsec > 1000000) {
            log_error("Timeout waiting for signal");
            return 0;
        }
        ticks++;
        usleep(TICK_TIME_US);
    }

    return ticks;
}

unsigned int read_nibble(struct gpiod_chip *chip, struct gpiod_line *line) {
    unsigned int ticks = read_ticks(chip, line);
    if (ticks < MIN_NIBBLE_TICKS || ticks > MAX_NIBBLE_TICKS) {
        log_error("Out-of-range pulse width");
        return 0xFF; // Invalid nibble
    }
    return (ticks - MIN_NIBBLE_TICKS) / 9;
}

unsigned int read_byte(struct gpiod_chip *chip, struct gpiod_line *line) {
    unsigned int nibble1 = read_nibble(chip, line);
    unsigned int nibble2 = read_nibble(chip, line);
    if (nibble1 == 0xFF || nibble2 == 0xFF) {
        return 0xFF; // Invalid byte
    }
    return (nibble1 << 4) | nibble2;
}

void log_pressure(unsigned int pressure) {
    FILE *file = fopen(FILENAME, "a");
    if (!file) {
        log_error("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s, Pressure: %04u.%02u Pa\n", timestamp, pressure / 100, pressure % 100);
    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "mlx90824");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        unsigned int ticks = read_ticks(chip, line);
        if (ticks != SYNCHRONIZATION_TICKS) {
            log_error("Synchronization pulse mismatch");
            continue;
        }

        unsigned int status = read_byte(chip, line);
        unsigned int data1 = read_byte(chip, line);
        unsigned int data2 = read_byte(chip, line);
        unsigned int data3 = read_byte(chip, line);
        unsigned int checksum = read_byte(chip, line);

        if (status == 0xFF || data1 == 0xFF || data2 == 0xFF || data3 == 0xFF || checksum == 0xFF) {
            log_error("Invalid data received");
            continue;
        }

        unsigned int calculated_checksum = (status + data1 + data2 + data3) & 0xFF;
        if (calculated_checksum != checksum) {
            log_error("Checksum mismatch");
            continue;
        }

        unsigned int pressure = (data1 << 8) | data2;
        log_pressure(pressure);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

