#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <endian.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TMP117_I2C_ADDRESS 0x48
#define TMP117_DEVICE_ID 0x0D30
#define TMP117_TEMP_REG 0x00
#define LOG_FILE "greenhouse_temps.dat"
#define INTERVAL 60

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, log_fd;
    struct sigaction sa;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint16_t device_id;
    float temperature;
    uint8_t temp_data[2];

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify device ID
    if (i2c_smbus_read_word_data(i2c_fd, 0x0F) != TMP117_DEVICE_ID) {
        fprintf(stderr, "Device ID verification failed\n");
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read temperature
        if (i2c_smbus_read_i2c_block_data(i2c_fd, TMP117_TEMP_REG, 2, temp_data) != 2) {
            perror("Failed to read temperature");
            sleep(INTERVAL);
            continue;
        }

        // Convert temperature to float
        int16_t raw_temp = (temp_data[0] << 8) | temp_data[1];
        temperature = (raw_temp * 0.0078125f);

        // Write temperature to log file
        if (write(log_fd, &temperature, sizeof(temperature)) != sizeof(temperature)) {
            perror("Failed to write to log file");
        }

        // Sleep for 60 seconds
        sleep(INTERVAL);
    }

    // Close resources
    close(i2c_fd);
    close(log_fd);

    return EXIT_SUCCESS;
}

