#define SAMPLE_INTERVAL 5

static int i2c_fd = -1;
static FILE *log_file = NULL;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void write_buffer_to_file() {
    if (log_file) {
        rewind(log_file);
        if (fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, log_file) != BUFFER_SIZE) {
            perror("Failed to write to log file");
        }
        fflush(log_file);
    }
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        write_buffer_to_file();
        fclose(log_file);
    }
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_temperature(float *temp) {
    uint16_t raw_temp;
    uint8_t buffer[2];

    if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 2, buffer) != 2) {
        perror("Failed to read temperature");
        return -1;
    }

    raw_temp = (buffer[0] << 8) | buffer[1];
    *temp = (raw_temp >> 4) * 0.0625;

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.dat", "r+b");
    if (!log_file) {
        log_file = fopen("temperature_log.dat", "wb");
        if (!log_file) {
            perror("Failed to open log file");
            cleanup();
            return EXIT_FAILURE;
        }
