        float temp;
        if (read_temperature(&temp) == 0) {
            temperature_buffer[buffer_index] = temp;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            write_buffer_to_file();
        } else {
            fprintf(stderr, "Error reading temperature, skipping sample\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

