#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SHTC3_I2C_ADDRESS 0x70
#define SHTC3_CMD_MEASURE_HIGH_PRECISION 0x7CA2
#define SHTC3_CMD_SOFT_RESET 0x805D

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUM_MIN 0.0
#define HUM_MAX 100.0

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *scl_line = NULL;
static struct gpiod_line *sda_line = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (scl_line) {
        gpiod_line_release(scl_line);
        scl_line = NULL;
    }
    if (sda_line) {
        gpiod_line_release(sda_line);
        sda_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void handle_sigint(int sig) {
    fprintf(stderr, "Received SIGINT, cleaning up...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write(uint8_t *data, size_t len) {
    if (write(i2c_fd, data, len) != len) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t *data, size_t len) {
    if (read(i2c_fd, data, len) != len) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int shtc3_measure(float *temperature, float *humidity) {
    uint8_t cmd[] = {SHTC3_CMD_MEASURE_HIGH_PRECISION >> 8, SHTC3_CMD_MEASURE_HIGH_PRECISION & 0xFF};
    if (i2c_write(cmd, sizeof(cmd)) < 0) {
        return -1;
    }
    usleep(12400); // Wait at least 12.4 ms

    uint8_t data[6];
    if (i2c_read(data, sizeof(data)) < 0) {
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *temperature = (temp_raw * 175.0 / 65535.0) - 45.0;
    *humidity = (hum_raw * 100.0 / 65535.0);

    if (*temperature < TEMP_MIN || *temperature > TEMP_MAX || *humidity < HUM_MIN || *humidity > HUM_MAX) {
        fprintf(stderr, "Out of range: Temperature = %.2f C, Humidity = %.2f %%\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHTC3_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    scl_line = gpiod_chip_get_line(chip, 3); // GPIO3
    sda_line = gpiod_chip_get_line(chip, 2); // GPIO2

    if (!scl_line || !sda_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(scl_line, "shtc3_scl", 0) < 0 || gpiod_line_request_output(sda_line, "shtc3_sda", 0) < 0) {
        perror("Failed to request GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("shtc3_environment.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        float temperature, humidity;
        if (shtc3_measure(&temperature, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fprintf(stdout, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(log_file);
        }
        sleep(5);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;
}

