#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define SENSOR_NAME "Honeywell HAFUHH0025PA3"
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct sigaction sa;
    struct timespec ts;
    uint8_t buffer[4];
    int ret;

    // Set up signal handler for SIGINT and SIGTERM
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Discard first two reads after power-up
    for (int i = 0; i < 2; i++) {
        if (read(i2c_fd, buffer, 4) != 4) {
            perror("Failed to read initial data");
            close(i2c_fd);
            fclose(log_file);
            return EXIT_FAILURE;
        }
    }

    while (running) {
        // Read 4 bytes from the sensor
        if (read(i2c_fd, buffer, 4) != 4) {
            perror("Failed to read data from sensor");
            // Attempt to reinitialize I2C handle
            close(i2c_fd);
            i2c_fd = open(I2C_DEVICE, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to reinitialize I2C device");
                fclose(log_file);
                return EXIT_FAILURE;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                fclose(log_file);
                return EXIT_FAILURE;
            }
            continue;
        }

        // Extract flow and temperature values
        uint16_t flow = ((buffer[0] << 8) | buffer[1]) & 0x3FFF;
        uint16_t temp = ((buffer[2] << 8) | buffer[3]) & 0x0FFF;

        // Convert flow to SLPM and temperature to °C
        float flow_slpm = flow * 0.001; // Assuming conversion factor
        float temp_c = temp * 0.0625 - 50.0; // Assuming conversion factor

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write to log file
        fprintf(log_file, "%s, Flow: %.3f SLPM, Temperature: %.2f °C\n", timestamp, flow_slpm, temp_c);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

