#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define GPIO_PIN 4
#define DHT11_START_LOW_US 18000
#define DHT11_RESPONSE_LOW_US 80
#define DHT11_RESPONSE_HIGH_US 80
#define DHT11_DATA_LOW_US 50
#define DHT11_DATA_HIGH_0_US 26
#define DHT11_DATA_HIGH_1_US 70
#define DHT11_MIN_INTERVAL_US 2000000

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

void log_reading(int humidity, int temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] Humidity: %d%%, Temperature: %d°C\n", timestamp, humidity, temperature);
    fflush(log_file);
}

int read_bit() {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timespec_diff_us(&end, &start) > 100000) {
            log_error("Timeout waiting for data bit low");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timespec_diff_us(&end, &start) > 100000) {
            log_error("Timeout waiting for data bit high");
            return -1;
        }
    }

    int duration = timespec_diff_us(&end, &start);
    return (duration > 40) ? 1 : 0;
}

int read_byte() {
    int byte = 0;
    for (int i = 0; i < 8; i++) {
        int bit = read_bit();
        if (bit < 0) {
            return -1;
        }
        byte = (byte << 1) | bit;
    }
    return byte;
}

int read_dht11() {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    gpiod_line_set_value(line, 0);
    usleep(DHT11_START_LOW_US);
    gpiod_line_set_value(line, 1);

    while (gpiod_line_get_value(line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timespec_diff_us(&end, &start) > 100000) {
            log_error("Timeout waiting for response low");
            return -1;
        }
    }

    if (gpiod_line_get_value(line) == 0) {
        usleep(DHT11_RESPONSE_LOW_US);
        if (gpiod_line_get_value(line) == 1) {
            usleep(DHT11_RESPONSE_HIGH_US);
        } else {
            log_error("Sensor response high pulse not detected");
            return -1;
        }
    } else {
        log_error("Sensor response low pulse not detected");
        return -1;
    }

