void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

void log_reading(int humidity, int temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] Humidity: %d%%, Temperature: %d°C\n", timestamp, humidity, temperature);
    fflush(log_file);
}

int read_bit() {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timespec_diff_us(&end, &start) > 100000) {
            log_error("Timeout waiting for data bit low");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timespec_diff_us(&end, &start) > 100000) {
            log_error("Timeout waiting for data bit high");
            return -1;
        }
    }

    int duration = timespec_diff_us(&end, &start);
    return (duration > 40) ? 1 : 0;
}

int read_byte() {
    int byte = 0;
    for (int i = 0; i < 8; i++) {
        int bit = read_bit();
        if (bit < 0) {
            return -1;
        }
        byte = (byte << 1) | bit;
    }
    return byte;
}

