#define I2C_DEVICE "/dev/i2c-1"
#define SHT31D_ADDR 0x44
#define SHT31D_MEASURE_NO_HOLD 0x2C06
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sda_line = NULL, *scl_line = NULL;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Open log file
    log_file = fopen("sht31d_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Initialize GPIO for I2C (not necessary with libgpiod, but shown for completeness)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    sda_line = gpiod_chip_get_line(chip, 2);
    scl_line = gpiod_chip_get_line(chip, 3);
    if (!sda_line || !scl_line) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_output(sda_line, "sht31d_sda", 0) < 0 ||
        gpiod_line_request_output(scl_line, "sht31d_scl", 0) < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        uint8_t command[2] = {SHT31D_MEASURE_NO_HOLD >> 8, SHT31D_MEASURE_NO_HOLD & 0xFF};
        uint8_t data[6];
        int retries = 3;

        // Send measurement command
        while (retries > 0) {
            if (write(i2c_fd, command, 2) == 2) {
                break;
            }
            retries--;
            perror("Failed to send measurement command");
            if (retries == 0) {
                fprintf(log_file, "%s: Failed to send measurement command\n", timestamp());
                fflush(log_file);
                sleep(1);
            }
        }

        // Wait at least 15ms
        usleep(15000);

        // Read data
        retries = 3;
        while (retries > 0) {
            if (read(i2c_fd, data, 6) == 6) {
                break;
            }
            retries--;
            perror("Failed to read data");
            if (retries == 0) {
                fprintf(log_file, "%s: Failed to read data\n", timestamp());
                fflush(log_file);
                sleep(1);
            }
        }

        // Validate CRCs
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(log_file, "%s: CRC validation failed\n", timestamp());
            fflush(log_file);
            sleep(1);
            continue;
        }

        // Calculate temperature and humidity
        int16_t temp_raw = (data[0] << 8) | data[1];
        int16_t humidity_raw = (data[3] << 8) | data[4];
        float temperature = -45.0 + 175.0 * temp_raw / 65535.0;
        float humidity = 100.0 * humidity_raw / 65535.0;

        // Log data
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp(), temperature, humidity);
        fflush(log_file);

        // Wait 5 seconds
        sleep(5);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (sda_line) {
        gpiod_line_release(sda_line);
    }
    if (scl_line) {
        gpiod_line_release(scl_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

const char *timestamp() {
    static char buf[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm_info);
    return buf;
}

