#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADPD105_ADDR1 0x30
#define ADPD105_ADDR2 0x31
#define ADPD105_REG_STATUS 0x00
#define ADPD105_REG_DATA 0x01
#define ADPD105_REG_CONFIG 0x02

#define BUFFER_SIZE 1024

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_i2c_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("I2C read");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

int write_i2c_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buffer[3];
    buffer[0] = reg;
    buffer[1] = (value >> 8) & 0xFF;
    buffer[2] = value & 0xFF;
    if (write(fd, buffer, 3) != 3) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

double compute_cct(uint16_t sensor1, uint16_t sensor2) {
    // Placeholder for actual CCT computation logic
    return (sensor1 + sensor2) / 2.0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd1 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C device 1");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd1, I2C_SLAVE, ADPD105_ADDR1) < 0) {
        perror("Failed to set I2C address 1");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }

    int i2c_fd2 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C device 2");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, ADPD105_ADDR2) < 0) {
        perror("Failed to set I2C address 2");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("cct_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    while (running) {
        uint16_t sensor1_data, sensor2_data;
        if (read_i2c_register(i2c_fd1, ADPD105_REG_DATA, &sensor1_data) < 0 ||
            read_i2c_register(i2c_fd2, ADPD105_REG_DATA, &sensor2_data) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue;
        }

        double average_cct = compute_cct(sensor1_data, sensor2_data);
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd1);
    close(i2c_fd2);

    return EXIT_SUCCESS;
}

