#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LM75B_ADDRESS 0x48
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define AVG_THRESHOLD_HIGH 28.0
#define AVG_THRESHOLD_LOW 26.0
#define HYSTERESIS 2.0

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *fan_line;
    int i2c_fd;
    float temperatures[BUFFER_SIZE];
    int buffer_index = 0;
    float sum = 0.0;
    float avg = 0.0;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75B_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data[2];
        float temp;

        // Read temperature from LM75B
        if (read(i2c_fd, data, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        temp = (data[0] << 8 | data[1]) * 0.0078125;

        // Update circular buffer and running average
        sum -= temperatures[buffer_index];
        temperatures[buffer_index] = temp;
        sum += temp;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        avg = sum / BUFFER_SIZE;

        // Control fan with hysteresis
        if (avg > AVG_THRESHOLD_HIGH + HYSTERESIS) {
            gpiod_line_set_value(fan_line, 1);
        } else if (avg < AVG_THRESHOLD_LOW - HYSTERESIS) {
            gpiod_line_set_value(fan_line, 0);
        }

        sleep(1);
    }

    // Clean up
    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

