#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP810_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x7610
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

static void log_reading(const char *timestamp, float pressure, float temperature) {
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
}

static void read_sensor() {
    uint8_t command[2] = {MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF};
    if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
        perror("I2C write failed");
        return;
    }
    usleep(45000); // Wait 45 ms

    uint8_t buffer[9];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("I2C read failed");
        return;
    }

    uint8_t expected_crc = crc8(buffer, 8);
    if (buffer[8] != expected_crc) {
        fprintf(stderr, "CRC mismatch\n");
        return;
    }

    int32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    int16_t temperature_raw = (buffer[3] << 8) | buffer[4];

    float pressure = pressure_raw * 2.0f / 2097152.0f; // Convert to Pa
    float temperature = temperature_raw * 200.0f / 131072.0f - 50.0f; // Convert to °C

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    log_reading(timestamp, pressure, temperature);

    if (pressure > 5.0f) {
        fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,differential_pressure(Pa),temperature(°C)\n");
    fflush(log_file);

    while (1) {
        read_sensor();
        sleep(1);
    }

    return EXIT_SUCCESS;
}

