#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x4A
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define I2C_FAILURE_THRESHOLD 5

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static int i2c_failure_count = 0;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_temperature(float *temperature) {
    uint8_t data[2];
    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data ioctl_data;

    msgs[0].addr = I2C_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = sizeof(data);
    msgs[0].buf = data;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("I2C read failed");
        i2c_failure_count++;
        if (i2c_failure_count >= I2C_FAILURE_THRESHOLD) {
            fprintf(stderr, "Too many I2C failures, exiting.\n");
            cleanup();
            exit(EXIT_FAILURE);
        }
        return -1;
    }

    *temperature = ((data[0] << 8) | data[1]) * 0.0078125;
    i2c_failure_count = 0;
    return 0;
}

void set_led(int value) {
    if (gpiod_line_set_value(led_line, value) < 0) {
        perror("Failed to set LED value");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main() {
    float temperature;
    int led_state = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "temperature_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f°C\n", temperature);

            if (temperature > TEMP_THRESHOLD_HIGH && !led_state) {
                set_led(1);
                led_state = 1;
            } else if (temperature < TEMP_THRESHOLD_LOW && led_state) {
                set_led(0);
                led_state = 0;
            }
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

