#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x0036
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *reset_line = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (reset_line != NULL) {
        gpiod_line_release(reset_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip and get reset line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    reset_line = gpiod_chip_get_line(chip, 17); // Assuming GPIO 17 is connected to reset
    if (!reset_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(reset_line, "sdp800_reset", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Reset sensor
    gpiod_line_set_value(reset_line, 1);
    usleep(100000); // 100 ms
    gpiod_line_set_value(reset_line, 0);
    usleep(100000); // 100 ms

    // Start measurement
    uint8_t command[2] = {0x00, 0x36};
    if (write(i2c_fd, command, 2) != 2) {
        perror("Failed to send measurement command");
        cleanup();
        return EXIT_FAILURE;
    }

    // Wait for measurement to complete
    usleep(45000); // 45 ms

    // Read measurement result
    uint8_t result[9];
    if (read(i2c_fd, result, 9) != 9) {
        perror("Failed to read measurement result");
        cleanup();
        return EXIT_FAILURE;
    }

    // Validate CRCs
    if (calculate_crc8(result, 2) != result[2] || calculate_crc8(result + 3, 2) != result[5]) {
        fprintf(stderr, "CRC validation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Extract and log values
    int32_t differential_pressure = (result[0] << 16) | (result[1] << 8) | result[2];
    int32_t temperature = (result[3] << 16) | (result[4] << 8) | result[5];
    int32_t scale_factor = (result[6] << 16) | (result[7] << 8) | result[8];

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Differential Pressure: %d, Temperature: %d, Scale Factor: %d\n",
            timestamp, differential_pressure, temperature, scale_factor);
    fflush(log_file);

    cleanup();
    return EXIT_SUCCESS;
}

