#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define CMD_MEASURE_RH_NO_HOLD 0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_TEMP_PREV_RH 0xE0
#define RETRY_COUNT 3

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sda_line = NULL;
static struct gpiod_line *scl_line = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (sda_line) {
        gpiod_line_release(sda_line);
        sda_line = NULL;
    }
    if (scl_line) {
        gpiod_line_release(scl_line);
        scl_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_FAILURE);
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int i2c_write_byte(unsigned char byte) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (write(i2c_fd, &byte, 1) == 1) {
            return 0;
        }
        perror("i2c_write_byte");
        usleep(100000); // 100 ms delay before retry
    }
    return -1;
}

int i2c_read_bytes(unsigned char *buffer, int length) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (read(i2c_fd, buffer, length) == length) {
            return 0;
        }
        perror("i2c_read_bytes");
        usleep(100000); // 100 ms delay before retry
    }
    return -1;
}

int read_electronic_id(unsigned char *id) {
    if (i2c_write_byte(0xFA) < 0) {
        return -1;
    }
    if (i2c_read_bytes(id, 8) < 0) {
        return -1;
    }
    return 0;
}

int read_firmware_revision(unsigned char *revision) {
    if (i2c_write_byte(0x84) < 0) {
        return -1;
    }
    if (i2c_write_byte(0x88) < 0) {
        return -1;
    }
    if (i2c_read_bytes(revision, 2) < 0) {
        return -1;
    }
    return 0;
}

int read_temperature() {
    if (i2c_write_byte(CMD_MEASURE_TEMP_NO_HOLD) < 0) {
        return -1;
    }
    usleep(100000); // 100 ms delay
    unsigned char buffer[2];
    if (i2c_read_bytes(buffer, 2) < 0) {
        return -1;
    }
    int temp = (buffer[0] << 8) | buffer[1];
    return (temp * 17572 / 65536) - 4685;
}

int read_humidity() {
    if (i2c_write_byte(CMD_MEASURE_RH_NO_HOLD) < 0) {
        return -1;
    }
    usleep(100000); // 100 ms delay
    unsigned char buffer[2];
    if (i2c_read_bytes(buffer, 2) < 0) {
        return -1;
    }
    int rh = (buffer[0] << 8) | buffer[1];
    return (rh * 125 / 65536) - 6;
}

void log_reading(int temp, int rh) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(log_file, "%s,%d,%d\n", timestamp, temp, rh);
    fflush(log_file);
    printf("%s,%d,%d\n", timestamp, temp, rh);
}

int main() {
    atexit(cleanup);
    setup_signals();

    log_file = fopen("environment.log", "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    unsigned char id[8];
    unsigned char revision[2];
    if (read_electronic_id(id) < 0 || read_firmware_revision(revision) < 0) {
        fprintf(stderr, "Sensor not found or communication error\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int temp = read_temperature();
        int rh = read_humidity();
        if (temp < 0 || rh < 0) {
            fprintf(stderr, "Failed to read temperature or humidity\n");
            return EXIT_FAILURE;
        }
        log_reading(temp, rh);
        sleep(60);
    }

    return EXIT_SUCCESS;
}

