        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Trigger temperature and humidity measurement
        uint8_t trigger_data = HDC1080_TEMP_REG;
        if (write(i2c_fd, &trigger_data, 1) != 1) {
