        temperature = (temp_raw / 65536.0) * 165.0 - 40.0;
        humidity = (hum_raw / 65536.0) * 100.0;

        // Get current time
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S", time_info);

