            perror("Failed to open log file");
            sleep(LOG_INTERVAL);
            continue;
        }

        fprintf(log_file, "%s,%.2f,%.2f\n", log_buffer, temperature, humidity);
        fclose(log_file);

        // Sleep for the remaining time until the next log interval
        sleep(LOG_INTERVAL);
    }

    // Close the I2C bus
    close(i2c_fd);

    return 0;
