#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x4A
#define CRC8_POLYNOMIAL 0x31
#define CRC8_SEED 0xFF

int i2c_fd = -1;
FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    close_resources();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_SEED;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close_resources();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t command[2] = {0x2C, 0x06}; // Command to start measurement
        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            perror("Failed to write to I2C device");
            continue;
        }

        usleep(10000); // Wait for 10 ms

        uint8_t data[3];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read from I2C device");
            continue;
        }

        uint8_t calculated_crc = calculate_crc8(data, 2);
        if (calculated_crc != data[2]) {
            fprintf(stderr, "CRC8 mismatch\n");
            continue;
        }

        uint16_t raw_temp = (data[0] << 8) | data[1];
        double temperature = -45.0 + 175.0 * raw_temp / 65535.0;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        fflush(log_file);
        sleep(5); // Sample every 5 seconds
    }

    return EXIT_SUCCESS;
}

