#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP810_ADDRESS 0x25
#define SDP810_TRIGGER_MEASUREMENT 0x0036
#define SDP810_READ_MEASUREMENT 0x0000
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write(uint8_t *data, size_t length) {
    if (write(i2c_fd, data, length) != length) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t *data, size_t length) {
    if (read(i2c_fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO (if needed, for example, for reset or other control signals)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        uint8_t command[2] = {SDP810_TRIGGER_MEASUREMENT >> 8, SDP810_TRIGGER_MEASUREMENT & 0xFF};
        if (i2c_write(command, sizeof(command)) < 0) {
            fprintf(log_file, "%s, I2C write error\n", ctime(NULL));
            continue;
        }

        usleep(50000); // Wait at least 50 ms

        uint8_t response[9];
        if (i2c_read(response, sizeof(response)) < 0) {
            fprintf(log_file, "%s, I2C read error\n", ctime(NULL));
            continue;
        }

        // Validate CRCs
        if (calculate_crc8(response, 2) != response[2] || calculate_crc8(response + 4, 2) != response[6]) {
            fprintf(log_file, "%s, CRC error\n", ctime(NULL));
            continue;
        }

        // Extract and log data
        int32_t pressure = (response[0] << 16) | (response[1] << 8) | response[2];
        int32_t temperature = (response[4] << 16) | (response[5] << 8) | response[6];
        int32_t scale_factor = (response[7] << 16) | (response[8] << 8) | 0;

        pressure = (pressure >> 4) * scale_factor / 1000;
        temperature = (temperature >> 4) * 175 / 32768 - 45;

        fprintf(log_file, "%s, %d, %d\n", ctime(NULL), pressure, temperature);
        fflush(log_file);

        sleep(1);
    }

    cleanup();
    return 0;
}

