    if (pthread_create(&log_thread, NULL, logging_thread, NULL) != 0) {
        perror("Failed to create logging thread");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t read_cmd[] = {0xEC, 0x05};
        if (i2c_write(i2c_fd, read_cmd, sizeof(read_cmd)) < 0) {
            continue;
        }

        sleep(5);

        uint8_t data[9];
        if (i2c_read(i2c_fd, data, sizeof(data)) < 0) {
            continue;
        }

        uint8_t co2_crc = crc8(data, 2);
        uint8_t temp_crc = crc8(data + 3, 2);
        uint8_t humid_crc = crc8(data + 6, 2);

        if (co2_crc != data[2] || temp_crc != data[5] || humid_crc != data[8]) {
            log_error("CRC check failed");
            continue;
        }

