        reading.co2 = (data[0] << 8) | data[1];
        reading.temperature = (data[3] << 8) | data[4];
        reading.humidity = (data[6] << 8) | data[7];
        reading.timestamp = time(NULL);

        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_tail] = reading;
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        } else {
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        }
        pthread_cond_signal(&buffer_cond);
        pthread_mutex_unlock(&buffer_mutex);
    }

    pthread_join(log_thread, NULL);

    uint8_t stop_cmd[] = {0x3F, 0x86};
    i2c_write(i2c_fd, stop_cmd, sizeof(stop_cmd));

    close(i2c_fd);
    return EXIT_SUCCESS;
