#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP810_ADDRESS 0x25
#define TRIGGER_COMMAND 0x0036
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (line != NULL) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sdp810_data(uint16_t *pressure, int16_t *temperature, uint16_t *scale_factor) {
    uint8_t buffer[9];
    if (write(i2c_fd, &TRIGGER_COMMAND, 2) != 2) {
        perror("I2C write error");
        return -1;
    }
    usleep(45000); // Wait at least 45 ms for the measurement to complete
    if (read(i2c_fd, buffer, 9) != 9) {
        perror("I2C read error");
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    if (calculate_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CRC8 validation failed for pressure\n");
        return -1;
    }

    *temperature = (buffer[3] << 8) | buffer[4];
    if (calculate_crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC8 validation failed for temperature\n");
        return -1;
    }

    *scale_factor = (buffer[6] << 8) | buffer[7];
    if (calculate_crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC8 validation failed for scale factor\n");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t pressure;
        int16_t temperature;
        uint16_t scale_factor;

        if (read_sdp810_data(&pressure, &temperature, &scale_factor) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%u,%d\n", timestamp, pressure, temperature);
            fflush(log_file);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

