#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x76
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 95000

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;

void sigint_handler(int sig) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

unsigned short calculate_crc(unsigned char *data, int length) {
    unsigned short crc = 0xFFFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc = (crc >> 1) ^ 0xA001;
            } else {
                crc = crc >> 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(unsigned char *buffer) {
    if (write(i2c_fd, "\x00", 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    usleep(20000); // 20 ms delay

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "pressure_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    unsigned char buffer[6];
    while (1) {
        if (read_sensor_data(buffer) < 0) {
            continue;
        }

        unsigned short pressure = (buffer[0] << 8) | buffer[1];
        unsigned short temperature = (buffer[2] << 8) | buffer[3];
        unsigned short crc = (buffer[4] << 8) | buffer[5];

        unsigned short calculated_crc = calculate_crc(buffer, 4);
        if (crc != calculated_crc) {
            fprintf(stderr, "CRC mismatch: expected 0x%04X, got 0x%04X\n", calculated_crc, crc);
            continue;
        }

        printf("Pressure: %u Pa, Temperature: %u C\n", pressure, temperature);

        int blink_interval = pressure < PRESSURE_THRESHOLD ? 100 : 500;
        for (int i = 0; i < 2; i++) {
            gpiod_line_set_value(led_line, 1);
            usleep(blink_interval * 1000);
            gpiod_line_set_value(led_line, 0);
            usleep(blink_interval * 1000);
        }
        usleep(800000); // 800 ms delay to make the total period 1 second
    }

    // Cleanup
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

