#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_TA 0x06
#define MLX90614_TOBJ1 0x07
#define FAN_GPIO 18
#define FAN_ON_THRESHOLD 30.0
#define FAN_OFF_THRESHOLD 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY 10000 // 10 ms

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

float read_temperature(int i2c_fd, uint8_t reg) {
    uint8_t buffer[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("I2C write failed");
            retries--;
            usleep(RETRY_DELAY);
            continue;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("I2C read failed");
            retries--;
            usleep(RETRY_DELAY);
            continue;
        }

        uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
        return (raw_temp * 0.02) - 273.15; // Convert to Celsius
    }

    return -1.0; // Invalid reading
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient_temp = read_temperature(i2c_fd, MLX90614_TA);
        float object_temp = read_temperature(i2c_fd, MLX90614_TOBJ1);

        if (ambient_temp >= 0.0 && object_temp >= 0.0) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            fprintf(log_file, "%s - Ambient: %.2f°C, Object: %.2f°C\n", timestamp, ambient_temp, object_temp);
            fflush(log_file);

            if (object_temp > FAN_ON_THRESHOLD) {
                gpiod_line_set_value(fan_line, 1);
            } else if (object_temp < FAN_OFF_THRESHOLD) {
                gpiod_line_set_value(fan_line, 0);
            }
        }

        usleep(2000000); // 2 seconds
    }

    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

