            continue;
        }

        // Convert raw temperature to Celsius
        raw_temp = (raw_temp >> 4) & 0xFFF;
        if (raw_temp & 0x800) {
            raw_temp = ~raw_temp + 1;
            temperature = -((float)raw_temp / 16.0);
        } else {
            temperature = (float)raw_temp / 16.0;
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }

        // Format and write to CSV
        fprintf(csv_file, "%ld-%02ld-%02ld %02ld:%02ld:%02ld,%.2f\n",
                ts.tv_sec / 31536000, (ts.tv_sec / 2592000) % 12, (ts.tv_sec / 86400) % 30,
                (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60, ts.tv_sec % 60,
                temperature);

        // Flush CSV file
        fflush(csv_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close CSV file
    fclose(csv_file);

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

