#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG_REG 0x0F
#define MAX_RETRIES 3
#define TIMEOUT_US 500000
#define READ_INTERVAL_US 5000000

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    shutdown_flag = 1;
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buffer[1] = {reg};
    if (write(fd, buffer, 1) != 1) {
        perror("i2c write");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("i2c read");
        return -1;
    }
    return 0;
}

int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("i2c write");
        return -1;
    }
    return 0;
}

int read_hdc2010_measurements(int fd) {
    uint8_t status;
    int retries = 0;
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (i2c_read_register(fd, MEASUREMENT_CONFIG_REG, &status, 1) != 0) {
            return -1;
        }
        if (!(status & 0x01)) {
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - start.tv_sec > 0 || now.tv_nsec - start.tv_nsec > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for measurement to complete\n");
            return -1;
        }
        if (retries < MAX_RETRIES) {
            retries++;
            usleep(10000); // 10 ms delay before retry
        } else {
            fprintf(stderr, "Max retries reached\n");
            return -1;
        }
    }

    uint8_t temp_buffer[2], humidity_buffer[2];
    if (i2c_read_register(fd, 0x00, temp_buffer, 2) != 0) {
        return -1;
    }
    if (i2c_read_register(fd, 0x02, humidity_buffer, 2) != 0) {
        return -1;
    }

    int16_t temp_raw = (temp_buffer[0] << 8) | temp_buffer[1];
    int16_t humidity_raw = (humidity_buffer[0] << 8) | humidity_buffer[1];

    float temperature = (temp_raw / 65536.0) * 165.0 - 40.0;
    float humidity = (humidity_raw / 65536.0) * 100.0;

    printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_register(fd, 0x0E, 0x01) != 0) { // Set measurement configuration
        fprintf(stderr, "Failed to set measurement configuration\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (!shutdown_flag) {
        if (read_hdc2010_measurements(fd) != 0) {
            fprintf(stderr, "Failed to read measurements\n");
        }
        usleep(READ_INTERVAL_US);
    }

    close(fd);
    return EXIT_SUCCESS;
}

