#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDRESS 0x25
#define MEASUREMENT_DELAY_US 45000
#define LOGGING_INTERVAL_US 500000

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd;
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    uint8_t command[2] = {0x00, 0x78}; // Start measurement command
    uint8_t buffer[6];

    while (running) {
        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            perror("Failed to send measurement command");
            break;
        }

        usleep(MEASUREMENT_DELAY_US);

        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read measurement data");
            break;
        }

        uint16_t pressure = (buffer[0] << 8) | buffer[1];
        uint8_t pressure_crc = buffer[2];
        uint16_t temperature = (buffer[3] << 8) | buffer[4];
        uint8_t temperature_crc = buffer[5];

        if (calculate_crc8(buffer, 2) != pressure_crc) {
            fprintf(stderr, "Pressure CRC error\n");
            break;
        }

        if (calculate_crc8(buffer + 3, 2) != temperature_crc) {
            fprintf(stderr, "Temperature CRC error\n");
            break;
        }

        printf("Pressure: 0x%04X, Temperature: 0x%04X\n", pressure, temperature);

        usleep(LOGGING_INTERVAL_US);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}
```

This code fulfills the user's request by:

1. Opening the I2C bus and setting the slave address.
2. Sending the measurement command and waiting for the measurement to complete.
3. Reading the six bytes of data (two bytes pressure, one CRC, two bytes temperature, one CRC).
4. Calculating and validating the CRC-8 checksums.
5. Logging the raw pressure and temperature values every 500 ms.
6. Handling sensor-absent and bus-error conditions gracefully.
7. Performing a clean shutdown on receipt of a SIGINT by closing the I2C handle and exiting the program.

