#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define GPIO_PIN 17

#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"

#define PID_Kp 1.0
#define PID_Ki 0.1
#define PID_Kd 0.05

typedef struct {
    double setpoint;
    double integral;
    double prev_error;
} PIDController;

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int spi_init(const char *device, uint32_t speed, uint8_t mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer data over SPI");
        return -1;
    }

    return 0;
}

double read_temperature(int spi_fd) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0x00, 0x00};

    if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
        return -1.0;
    }

    uint16_t data = (rx[0] << 8) | rx[1];
    if (data & 0x4) {
        fprintf(stderr, "Sensor absent or bus error\n");
        return -1.0;
    }

    return (data >> 3) * 0.25;
}

int gpio_init(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "reflow_oven", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return gpiod_line_release(line), gpiod_chip_close(chip), 0;
}

void set_ssr_duty_cycle(int gpio_fd, double duty_cycle) {
    if (duty_cycle < 0.0 || duty_cycle > 1.0) {
        fprintf(stderr, "Invalid duty cycle: %f\n", duty_cycle);
        return;
    }

    int value = (int)(duty_cycle * 100);
    if (gpiod_line_set_value(gpio_fd, value) < 0) {
        perror("Failed to set GPIO value");
    }
}

double pid_update(PIDController *pid, double setpoint, double measured) {
    double error = setpoint - measured;
    pid->integral += error;
    double derivative = error - pid->prev_error;
    pid->prev_error = error;

    return PID_Kp * error + PID_Ki * pid->integral + PID_Kd * derivative;
}

void load_profile(double *setpoints, int *times, int *count) {
    FILE *file = fopen(PROFILE_FILE, "r");
    if (!file) {
        perror("Failed to open profile file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d,%lf", &times[*count], &setpoints[*count]) == 2) {
            (*count)++;
        }
    }

    fclose(file);
}

int main() {
    init_signal_handler();

    int spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    int gpio_fd = gpio_init(GPIO_PIN);
    if (gpio_fd < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    double setpoints[100];
    int times[100];
    int count = 0;
    load_profile(setpoints, times, &count);
    if (count == 0) {
        fprintf(stderr, "No valid profile data found\n");
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    PIDController pid = {0};
    int profile_index = 0;
    double start_time = time(NULL);

    while (running) {
        double current_time = time(NULL) - start_time;
        if (profile_index < count && current_time >= times[profile_index]) {
            pid.setpoint = setpoints[profile_index];
            profile_index++;
        }

        double temperature = read_temperature(spi_fd);
        if (temperature < 0.0) {
            continue;
        }

        double duty_cycle = pid_update(&pid, pid.setpoint, temperature);
        set_ssr_duty_cycle(gpio_fd, duty_cycle);

        fprintf(log_file, "%.2f,%.2f\n", current_time, temperature);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    close(spi_fd);
    return EXIT_SUCCESS;
}

