#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>
#include <wiringPi.h>

#define DS18B20_PATH "/sys/bus/w1/devices/28-*/w1_slave"
#define LOG_FILE "greenhouse.log"
#define PWM_CHANNEL 1
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *pwm_line;
static FILE *log_file;
static int running = 1;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (pwm_line) {
        gpiod_line_release(pwm_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    printf("Cleanup complete\n");
}

void signal_handler(int signum) {
    running = 0;
}

double read_temperature() {
    FILE *fp;
    char path[100], line[128];
    double temperature = -1.0;

    snprintf(path, sizeof(path), DS18B20_PATH);
    fp = fopen(path, "r");
    if (!fp) {
        perror("Failed to open DS18B20 file");
        return temperature;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Failed to read DS18B20 line");
        fclose(fp);
        return temperature;
    }

    if (strstr(line, "YES") == NULL) {
        fclose(fp);
        return temperature;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Failed to read DS18B20 temperature line");
        fclose(fp);
        return temperature;
    }

    fclose(fp);

    char *pos = strstr(line, "t=");
    if (pos) {
        pos += 2;
        temperature = atof(pos) / 1000.0;
    }

    return temperature;
}

void log_data(double temperature, double setpoint, double pid_output, int pwm_duty) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, temperature, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

double pid_control(double temperature, double setpoint, double *integral, double *prev_error, double Kp, double Ki, double Kd) {
    double error = setpoint - temperature;
    *integral += error;
    double derivative = error - *prev_error;
    *prev_error = error;

    return Kp * error + Ki * *integral + Kd * derivative;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, 17);
    if (!relay_line) {
        perror("Failed to get relay line");
        cleanup();
        return EXIT_FAILURE;
    }

    pwm_line = gpiod_chip_get_line(chip, 18);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "greenhouse", 0) < 0) {
        perror("Failed to request relay line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse", 0) < 0) {
        perror("Failed to request PWM line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (wiringPiSetup() == -1) {
        perror("Failed to setup wiringPi");
        cleanup();
        return EXIT_FAILURE;
    }

    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(19200000 / PWM_FREQ / PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    double integral = 0.0;
    double prev_error = 0.0;
    int pwm_duty = 0;

    while (running) {
        double temperature = read_temperature();
        if (temperature < 0.0) {
            printf("Failed to read temperature\n");
            continue;
        }

        double pid_output = pid_control(temperature, setpoint, &integral, &prev_error, Kp, Ki, Kd);
        pwm_duty = (int)pid_output;

        if (pwm_duty < 0) {
            pwm_duty = 0;
        } else if (pwm_duty > PWM_RANGE) {
            pwm_duty = PWM_RANGE;
        }

        pwmWrite(PWM_CHANNEL, pwm_duty);
        gpiod_line_set_value(relay_line, pwm_duty > 0);

        log_data(temperature, setpoint, pid_output, pwm_duty);

        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

