    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, 17);
    if (!relay_line) {
        perror("Failed to get relay line");
        cleanup();
        return EXIT_FAILURE;
    }

    pwm_line = gpiod_chip_get_line(chip, 18);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "greenhouse", 0) < 0) {
        perror("Failed to request relay line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse", 0) < 0) {
        perror("Failed to request PWM line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (wiringPiSetup() == -1) {
        perror("Failed to setup wiringPi");
        cleanup();
        return EXIT_FAILURE;
    }

    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(19200000 / PWM_FREQ / PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    double integral = 0.0;
    double prev_error = 0.0;
    int pwm_duty = 0;

    while (running) {
        double temperature = read_temperature();
        if (temperature < 0.0) {
            printf("Failed to read temperature\n");
            continue;
        }

        double pid_output = pid_control(temperature, setpoint, &integral, &prev_error, Kp, Ki, Kd);
        pwm_duty = (int)pid_output;

        if (pwm_duty < 0) {
            pwm_duty = 0;
        } else if (pwm_duty > PWM_RANGE) {
            pwm_duty = PWM_RANGE;
        }

        pwmWrite(PWM_CHANNEL, pwm_duty);
        gpiod_line_set_value(relay_line, pwm_duty > 0);

        log_data(temperature, setpoint, pid_output, pwm_duty);

        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}
