#define AHT20_STATUS_BUSY 0x80
#define AHT20_STATUS_CALIBRATED 0x08
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define MAX_RETRIES 3
#define RETRY_DELAY 10000 // 10 ms
#define POLL_INTERVAL 5000000 // 5 seconds

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data msgset[1];

    msgs[0].addr = AHT20_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = len + 1;
    msgs[0].buf = malloc(len + 1);
    if (!msgs[0].buf) {
        perror("malloc");
        return -1;
    }
    msgs[0].buf[0] = reg;
    memcpy(msgs[0].buf + 1, data, len);

    msgset[0].msgs = msgs;
    msgset[0].nmsgs = 1;

    int ret = ioctl(fd, I2C_RDWR, &msgset);
    free(msgs[0].buf);
    return ret;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data msgset[1];

    msgs[0].addr = AHT20_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    msgs[1].addr = AHT20_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = len;
    msgs[1].buf = data;

    msgset[0].msgs = msgs;
    msgset[0].nmsgs = 2;

    return ioctl(fd, I2C_RDWR, &msgset);
}

int aht20_trigger_measurement(int fd) {
    uint8_t cmd[3] = {AHT20_CMD_TRIGGER, 0x33, 0x00};
    return i2c_write(fd, 0, cmd, 3);
}

int aht20_read_status(int fd) {
    uint8_t status;
    if (i2c_read(fd, AHT20_CMD_STATUS, &status, 1) < 0) {
        return -1;
    }
    return status;
}

int aht20_read_humidity(int fd, float *humidity) {
    uint8_t data[6];
    if (i2c_read(fd, 0, data, 6) < 0) {
        return -1;
    }

    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    *humidity = (raw_humidity * 100.0f) / 1048576.0f;
    return 0;
}

