    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = NULL;
    setup_gpio(chip, line);

    while (running) {
        if (aht20_trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            goto retry;
        }

        usleep(80000); // 80 ms

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            int status = aht20_read_status(i2c_fd);
            if (status < 0) {
                fprintf(stderr, "Failed to read status\n");
                goto retry;
            }

            if ((status & AHT20_STATUS_BUSY) == 0 && (status & AHT20_STATUS_CALIBRATED) != 0) {
                float humidity;
                if (aht20_read_humidity(i2c_fd, &humidity) < 0) {
                    fprintf(stderr, "Failed to read humidity\n");
                    goto retry;
                }

                time_t now = time(NULL);
                printf("%s: Humidity: %.2f%%\n", ctime(&now), humidity);

                if (humidity > 60.0f) {
                    gpiod_line_set_value(line, 1);
                } else if (humidity < 55.0f) {
                    gpiod_line_set_value(line, 0);
                }

                break;
            }

            usleep(RETRY_DELAY);
        }

retry:
        usleep(POLL_INTERVAL);
    }

    cleanup_gpio(chip, line);
    close(i2c_fd);
    return 0;
}

