#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <errno.h>

#define HTU21D_I2C_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define HTTP_SERVER "api.example.com"
#define HTTP_PORT 80
#define HTTP_PATH "/humidity"
#define POLL_INTERVAL 60

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint16_t read_i2c_word(int fd, uint8_t reg) {
    uint8_t cmd[1] = {reg};
    uint8_t data[2];
    uint16_t value;

    if (write(fd, cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return 0xFFFF;
    }

    if (read(fd, data, 2) != 2) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return 0xFFFF;
    }

    value = (data[0] << 8) | data[1];
    return value;
}

float calculate_humidity(uint16_t raw_humidity) {
    return -6 + 125.0 * (raw_humidity / 65535.0);
}

int send_http_post(float humidity) {
    int sockfd;
    struct sockaddr_in server_addr;
    char request[256];
    ssize_t bytes_sent;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation error: %s", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    if (inet_pton(AF_INET, HTTP_SERVER, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: 20\r\n"
             "\r\n"
             "{\"humidity\":%.2f}\r\n",
             HTTP_PATH, HTTP_SERVER, humidity);

    bytes_sent = send(sockfd, request, strlen(request), 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    int i2c_fd;
    uint16_t raw_humidity;
    float humidity;

    openlog("htu21d_humidity", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open the i2c bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        raw_humidity = read_i2c_word(i2c_fd, 0xF5);
        if (raw_humidity == 0xFFFF) {
            syslog(LOG_ERR, "Failed to read humidity from HTU21D");
        } else {
            humidity = calculate_humidity(raw_humidity);
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (send_http_post(humidity) < 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST");
            }
        }
        sleep(POLL_INTERVAL);
    }

    close(i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

