        float temperature = read_tmp117();
        float humidity = read_aht20();
        int motion = read_pir();

        if (temperature < 0) {
            fprintf(stderr, "Warning: Failed to read temperature\n");
            temperature = -1.0;
        }
        if (humidity < 0) {
            fprintf(stderr, "Warning: Failed to read humidity\n");
            humidity = -1.0;
        }
        if (motion < 0) {
            fprintf(stderr, "Warning: Failed to read motion sensor\n");
            motion = -1;
        }

        fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
        fflush(log_file);

        sleep(1);

        time_t current_time = time(NULL);
        if (difftime(current_time, now) >= 86400) { // Check if a new day has started
            open_log_file();
        }
    }

    cleanup();
    return 0;
}

