#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24

static struct gpiod_chip *chip;
static struct gpiod_line *rain_sensor_line;
static struct gpiod_line *motor_ena_line;
static struct gpiod_line *motor_in1_line;
static struct gpiod_line *motor_in2_line;

void log_message(const char *message) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strcspn(time_str, "\n")] = '\0'; // Remove newline
    printf("%s: %s\n", time_str, message);
}

void cleanup() {
    if (motor_ena_line) {
        gpiod_line_release(motor_ena_line);
    }
    if (motor_in1_line) {
        gpiod_line_release(motor_in1_line);
    }
    if (motor_in2_line) {
        gpiod_line_release(motor_in2_line);
    }
    if (rain_sensor_line) {
        gpiod_line_release(rain_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    log_message("Signal received, stopping motor and cleaning up.");
    if (motor_ena_line) {
        gpiod_line_set_value(motor_ena_line, 0);
    }
    cleanup();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_GPIO);
    motor_ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_GPIO);
