#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define SAMPLE_INTERVAL 500000 // 500 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void set_rgb(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int read_cpu_load() {
    static unsigned long long prev_idle = 0;
    static unsigned long long prev_total = 0;

    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        return -1;
    }

    unsigned long long idle, total = 0;
    if (fscanf(fp, "cpu %llu %llu %llu %llu", &total, &idle, &total, &total) != 4) {
        perror("Failed to read /proc/stat");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    unsigned long long diff_idle = idle - prev_idle;
    unsigned long long diff_total = total - prev_total;

    prev_idle = idle;
    prev_total = total;

    if (diff_total == 0) {
        return 0;
    }

    return (int)((100.0 * (diff_total - diff_idle)) / diff_total);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int cpu_load = read_cpu_load();
        if (cpu_load < 0) {
            fprintf(stderr, "Failed to read CPU load\n");
            break;
        }

        int red, green, blue;
        if (cpu_load <= 50) {
            red = 0;
            green = 255 - (cpu_load * 5);
            blue = cpu_load * 5;
        } else {
            red = (cpu_load - 50) * 5;
            green = 255 - red;
            blue = 0;
        }

        set_rgb(red, green, blue);

        usleep(SAMPLE_INTERVAL);
    }

    set_rgb(0, 0, 0);
    gpioTerminate();

    return 0;
}

