#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <json-c/json.h>

#define BMP280_I2C_ADDRESS 0x76
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9

#define I2C_DEVICE "/dev/i2c-1"
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000
#define INTERVAL 5

static int i2c_fd = -1;
static int udp_sock = -1;
static struct gpiod_chip *chip = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (udp_sock != -1) {
        close(udp_sock);
        udp_sock = -1;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_sensor_data(float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_read_bytes(BMP280_REG_TEMP_MSB, data, 6) != 0) {
        return -1;
    }

    int32_t temp_raw = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | data[2];
    int32_t press_raw = ((int32_t)data[3] << 16) | ((int32_t)data[4] << 8) | data[5];

    *temperature = temp_raw / 100.0;
    *pressure = press_raw / 100.0;

    return 0;
}

void send_udp(const char *json_str) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_IP, &server_addr.sin_addr);

    if (sendto(udp_sock, json_str, strlen(json_str), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("UDP sendto failed");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(BMP280_REG_CTRL_MEAS, 0x27) != 0 || i2c_write_byte(BMP280_REG_CONFIG, 0xA0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sock < 0) {
        perror("Failed to create UDP socket");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        float temperature, pressure;
        if (read_sensor_data(&temperature, &pressure) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            sleep(INTERVAL);
            continue;
        }

        struct json_object *json_obj = json_object_new_object();
        json_object_object_add(json_obj, "temperature", json_object_new_double(temperature));
        json_object_object_add(json_obj, "pressure", json_object_new_double(pressure));
        const char *json_str = json_object_to_json_string(json_obj);

        send_udp(json_str);

        json_object_put(json_obj);
        sleep(INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

