#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define FAN_GPIO 18
#define FAN_PWM_PERIOD 1000000 // 1 kHz
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_sigint(int sig) {
    // Stop PWM, close SPI, print buffer, terminate library, exit
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "fan_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0);

    gpiod_chip_close(chip);

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    close(fd);

    printf("Log Buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (log_buffer[i].timestamp != 0) {
            printf("%ld: Temp = %.2f°C, Duty = %d\n", log_buffer[i].timestamp, log_buffer[i].temperature, log_buffer[i].duty_cycle);
        }
    }

    exit(EXIT_SUCCESS);
}

float read_temperature(int spi_fd) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1.0;
    }

    if (rx[3] & 0x01) {
