#define BMP180_REG_RESULT 0xF6
#define BMP180_REG_CALIBRATION 0xAA
#define BMP180_OSS 3
#define BMP180_TEMP_CONVERSION_TIME 4.5
#define BMP180_PRESSURE_CONVERSION_TIME 25.5

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t logging_active = 0;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, uint8_t *buf, size_t len) {
    if (i2c_write_byte(reg, 0) < 0) {
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_calibration_data(int16_t *calibration) {
    uint8_t buf[22];
    if (i2c_read_bytes(BMP180_REG_CALIBRATION, buf, 22) < 0) {
        return -1;
    }
    for (int i = 0; i < 11; i++) {
        calibration[i] = (buf[i * 2] << 8) | buf[i * 2 + 1];
    }
    return 0;
}

int read_temperature(int16_t *temperature) {
    if (i2c_write_byte(BMP180_REG_CONTROL, 0x2E) < 0) {
        return -1;
    }
    usleep(BMP180_TEMP_CONVERSION_TIME * 1000000);
    uint8_t buf[2];
    if (i2c_read_bytes(BMP180_REG_RESULT, buf, 2) < 0) {
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];
    return 0;
}

int read_pressure(int16_t *pressure) {
    if (i2c_write_byte(BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) {
        return -1;
    }
    usleep(BMP180_PRESSURE_CONVERSION_TIME * 1000000);
    uint8_t buf[3];
    if (i2c_read_bytes(BMP180_REG_RESULT, buf, 3) < 0) {
        return -1;
    }
    *pressure = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    *pressure >>= (8 - BMP180_OSS);
    return 0;
}

double calculate_temperature(int16_t temperature, int16_t *calibration) {
    int32_t x1, x2;
    x1 = ((temperature - calibration[0]) * calibration[1]) >> 11;
    x2 = ((calibration[2] * ((temperature * temperature) >> 11)) >> 11);
    return ((x1 + x2) + 2048) >> 11;
}

double calculate_pressure(int16_t pressure, int16_t temperature, int16_t *calibration) {
    int32_t x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;
    x1 = ((temperature - calibration[0]) * calibration[1]) >> 11;
    x2 = ((calibration[2] * ((temperature * temperature) >> 11)) >> 11);
    x3 = ((x1 + x2) + 2048) >> 11;
    b5 = x3 + calibration[3];
    b6 = b5 - 4000;
    x1 = (calibration[4] * ((b6 * b6) >> 12)) >> 11;
    x2 = (calibration[5] * b6) >> 11;
    x3 = ((x1 + x2) + 2 + (1 << 10)) >> 11;
    b4 = (calibration[6] * ((uint32_t)x3 + 32768)) >> 15;
    b7 = ((uint32_t)pressure - b4) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000) {
        p = (b7 << 1) / b4;
    } else {
        p = (b7 / b4) << 1;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_falling_edge_events(gpio_line, "bmp180_logger") < 0) {
        perror("Failed to request falling edge events");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_set_config(gpio_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP) < 0) {
        perror("Failed to set GPIO pull-up");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    int16_t calibration[11];
    if (read_calibration_data(calibration) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(gpio_line, NULL) > 0) {
            if (gpiod_line_event_read(gpio_line, &event) > 0) {
                logging_active = !logging_active;
            }
        }

        if (logging_active) {
            int16_t temperature, pressure;
            if (read_temperature(&temperature) < 0 || read_pressure(&pressure) < 0) {
                continue;
            }
            double temp_c = calculate_temperature(temperature, calibration);
            double press_pa = calculate_pressure(pressure, temperature, calibration);

            struct timeval tv;
            gettimeofday(&tv, NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp_c, press_pa);
            fflush(log_file);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

