#define BME280_CONFIG_REG 0xF5
#define BME280_PRESS_MSB_REG 0xF7
#define BME280_TEMP_MSB_REG 0xFA
#define BME280_HUM_MSB_REG 0xFD

#define I2C_BUS "/dev/i2c-1"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, uint8_t *buf, int len) {
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDRESS) < 0) {
        perror("I2C ioctl failed");
        return -1;
    }
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_chip_id() {
    uint8_t chip_id;
    if (i2c_read_bytes(BME280_CHIP_ID_REG, &chip_id, 1) < 0) {
        return -1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: expected 0x%02X, got 0x%02X\n", BME280_CHIP_ID, chip_id);
        return -1;
    }
    return 0;
}

int read_sensor_data(float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    if (i2c_read_bytes(BME280_PRESS_MSB_REG, data, 8) < 0) {
        return -1;
    }

    int32_t adc_p = ((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | (data[2] >> 4);
    int32_t adc_t = ((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | (data[5] >> 4);
    int32_t adc_h = ((uint32_t)data[6] << 8) | data[7];

    *temperature = (adc_t / 100.0);
    *humidity = (adc_h / 1024.0);
    *pressure = (adc_p / 256.0);

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (read_chip_id() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(BME280_CTRL_MEAS_REG, 0x27) < 0 || i2c_write_byte(BME280_CONFIG_REG, 0xA0) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("bme280_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        float temperature, humidity, pressure;
        if (read_sensor_data(&temperature, &humidity, &pressure) < 0) {
            fprintf(log_file, "Error reading sensor data\n");
        } else {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
        }
        fflush(log_file);
        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

