#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP180_ADDR 0x77
#define BUFFER_SIZE 1200 // 60 seconds * 20 readings per second
#define TIMER_PERIOD 50000 // 50 ms in nanoseconds
#define ALERT_GPIO 24
#define PRESSURE_DEVIATION_THRESHOLD 500 // 5 hPa in Pa

typedef struct {
    struct timespec timestamp;
    int pressure;
} PressureReading;

PressureReading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_count = 0;

struct gpiod_chip *chip;
struct gpiod_line *alert_line;
int i2c_fd;
timer_t timer_id;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    timer_delete(timer_id);
    exit(EXIT_SUCCESS);
}

void timer_handler(union sigval sv) {
    static int reading_count = 0;
    struct timespec current_time;
    uint8_t data[3];
    int pressure;

    clock_gettime(CLOCK_REALTIME, &current_time);

    // Read pressure from BMP180
    if (write(i2c_fd, "\xF4\x2E", 2) != 2) {
        fprintf(stderr, "Failed to write to BMP180: %s\n", strerror(errno));
        return;
    }
    usleep(50000); // Wait for conversion
    if (read(i2c_fd, data, 3) != 3) {
        fprintf(stderr, "Failed to read from BMP180: %s\n", strerror(errno));
        return;
    }

    pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> 3;

    // Store in circular buffer
    buffer[buffer_head].timestamp = current_time;
    buffer[buffer_head].pressure = pressure;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }

    // Calculate rolling average
    int sum = 0;
    for (int i = 0; i < buffer_count; i++) {
        sum += buffer[(buffer_head - i + BUFFER_SIZE) % BUFFER_SIZE].pressure;
    }
    int average_pressure = sum / buffer_count;

    // Check for deviation
    if (abs(pressure - average_pressure) > PRESSURE_DEVIATION_THRESHOLD) {
        gpiod_line_set_value(alert_line, 1);
        fprintf(stderr, "Alert: Pressure deviation detected at %ld.%09ld\n",
                current_time.tv_sec, current_time.tv_nsec);
    } else {
        gpiod_line_set_value(alert_line, 0);
    }

    reading_count++;
}

int main() {
    struct sigevent sev;
    struct itimerspec its;
    struct sigaction sa;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    alert_line = gpiod_chip_get_line(chip, ALERT_GPIO);
    if (!alert_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(alert_line, "bmp180_alert", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up timer
    sa.sa_handler = NULL;
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_value.sival_ptr = &timer_id;
    sev.sigev_notify_function = timer_handler;
    sev.sigev_notify_attributes = NULL;
    timer_create(CLOCK_REALTIME, &sev, &timer_id);

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = TIMER_PERIOD;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = TIMER_PERIOD;
    timer_settime(timer_id, 0, &its, NULL);

    // Set up signal handler for SIGINT
    struct sigaction sigint_action;
    sigint_action.sa_handler = handle_sigint;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);

    // Main loop
    while (1) {
        pause();
    }

    return 0;
}

