#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP180_ADDR 0x77
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_COMMAND_TEMPERATURE 0x2E
#define BMP180_COMMAND_PRESSURE 0x34
#define BMP180_OVERSAMPLING_ULTRA_LOW_POWER 0

typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration;

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buffer[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C");
        return -1;
    }
    return 0;
}

int read_calibration_data(int fd, bmp180_calibration *cal) {
    cal->ac1 = i2c_read_word(fd, BMP180_REG_CAL_AC1);
    cal->ac2 = i2c_read_word(fd, BMP180_REG_CAL_AC2);
    cal->ac3 = i2c_read_word(fd, BMP180_REG_CAL_AC3);
    cal->ac4 = i2c_read_word(fd, BMP180_REG_CAL_AC4);
    cal->ac5 = i2c_read_word(fd, BMP180_REG_CAL_AC5);
    cal->ac6 = i2c_read_word(fd, BMP180_REG_CAL_AC6);
    cal->b1 = i2c_read_word(fd, BMP180_REG_CAL_B1);
    cal->b2 = i2c_read_word(fd, BMP180_REG_CAL_B2);
    cal->mb = i2c_read_word(fd, BMP180_REG_CAL_MB);
    cal->mc = i2c_read_word(fd, BMP180_REG_CAL_MC);
    cal->md = i2c_read_word(fd, BMP180_REG_CAL_MD);
    if (cal->ac1 == -1 || cal->ac2 == -1 || cal->ac3 == -1 || cal->ac4 == -1 ||
        cal->ac5 == -1 || cal->ac6 == -1 || cal->b1 == -1 || cal->b2 == -1 ||
        cal->mb == -1 || cal->mc == -1 || cal->md == -1) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }
    return 0;
}

int read_temperature(int fd, bmp180_calibration *cal) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_COMMAND_TEMPERATURE) != 0) {
        return -1;
    }
    usleep(4500); // Wait for conversion
    int16_t ut = i2c_read_word(fd, BMP180_REG_RESULT);
    if (ut == -1) {
        return -1;
    }
    int32_t x1 = ((ut - cal->ac6) * cal->ac5) >> 15;
    int32_t x2 = (cal->mc << 11) / (x1 + cal->md);
    int32_t b5 = x1 + x2;
    int32_t t = (b5 + 8) >> 4;
    return t;
}

int read_pressure(int fd, bmp180_calibration *cal) {
