#define THERMAL_ZONE_PATH "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE_PATH "fan_log.txt"
#define GPIO_PIN 18
#define PWM_FREQ 25000
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define MIN_DUTY 0
#define MAX_DUTY 255

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_temperature(const char *path, int *temp) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fscanf(file, "%d", temp) != 1) {
        perror("Failed to read temperature");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int map_temperature_to_duty(int temp) {
    if (temp < MIN_TEMP) {
        return MIN_DUTY;
    } else if (temp > MAX_TEMP) {
        return MAX_DUTY;
    } else {
        return (temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP);
    }
}

void log_temperature(int temp, int duty) {
    FILE *log_file = fopen(LOG_FILE_PATH, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d°C, %d%%\n", timestamp, temp / 1000, duty);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int temp;
        if (read_temperature(THERMAL_ZONE_PATH, &temp) < 0) {
            sleep(1);
            continue;
        }

        int duty = map_temperature_to_duty(temp);
        gpioPWM(GPIO_PIN, duty);

        log_temperature(temp, duty);

        sleep(5);
    }

    gpioPWM(GPIO_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

