#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define BUFFER_SIZE 60
#define LED_GPIO 18
#define TEMP_THRESHOLD 28.0

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static float running_average = 0.0;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    pthread_mutex_destroy(&buffer_mutex);
}

void signal_handler(int signum) {
    running = 0;
}

float read_temperature() {
    uint16_t raw_temp;
    float temp;

    if (i2c_smbus_read_word_data(i2c_fd, 0) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1.0;
    }

    raw_temp = i2c_smbus_read_word_data(i2c_fd, 0);
    if (raw_temp < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1.0;
    }

    temp = (raw_temp >> 8) | (raw_temp << 8);
    temp = temp / 32.0;

    return temp;
}

void *alert_thread(void *arg) {
    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        if (running_average > TEMP_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
        pthread_mutex_unlock(&buffer_mutex);
        sleep(1);
    }
    return NULL;
}

int main() {
    struct sigaction sa;
    pthread_t alert_tid;
    float temp;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    atexit(cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_label("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "lm75_alert", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        perror("Failed to create alert thread");
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        temp = read_temperature();
        if (temp < 0) {
            continue;
        }

        pthread_mutex_lock(&buffer_mutex);
        temperature_buffer[buffer_index] = temp;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        running_average = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            running_average += temperature_buffer[i];
        }
        running_average /= BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        sleep(1);
    }

    pthread_join(alert_tid, NULL);
    cleanup();
    return EXIT_SUCCESS;
}

