#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <json-c/json.h>

#define SPI_BUS 0
#define SPI_CS 0
#define SPI_MODE 1
#define SPI_SPEED 500000
#define REF_RESISTOR 430.0
#define PT100_NOMINAL_RESISTANCE 100.0
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PID_INTERVAL 100000 // 100 ms in microseconds
#define TARGET_TEMP_DEFAULT 25.0
#define Kp_DEFAULT 1.0
#define Ki_DEFAULT 0.1
#define Kd_DEFAULT 0.01
#define FAILSAFE_TEMP 80.0

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

double read_temperature(int spi_fd) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2];
    if (spi_xfer(spi_fd, tx, rx, 2) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1.0;
    }

    uint16_t adc_value = (rx[0] << 8) | rx[1];
    double resistance = (adc_value * REF_RESISTOR) / (4095.0 - adc_value);
    double temperature = (resistance / PT100_NOMINAL_RESISTANCE) * 100.0 - 25.0;
    return temperature;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioSetPWMdutycycle(PWM_GPIO, 0);
}

void cleanup_gpio() {
    gpioSetPWMdutycycle(PWM_GPIO, 0);
    gpioTerminate();
}

void setup_spi() {
    int spi_fd = spiOpen(SPI_BUS, SPI_CS, SPI_MODE | SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_spi(int spi_fd) {
    spiClose(spi_fd);
}

void load_config(const char *config_file, double *target_temp, double *Kp, double *Ki, double *Kd) {
    struct json_object *parsed_json;
    parsed_json = json_object_from_file(config_file);
    if (parsed_json == NULL) {
        fprintf(stderr, "Failed to load config file: %s\n", config_file);
        *target_temp = TARGET_TEMP_DEFAULT;
        *Kp = Kp_DEFAULT;
        *Ki = Ki_DEFAULT;
        *Kd = Kd_DEFAULT;
        return;
    }

    json_object *target_temp_obj = json_object_object_get(parsed_json, "target_temp");
    json_object *Kp_obj = json_object_object_get(parsed_json, "Kp");
    json_object *Ki_obj = json_object_object_get(parsed_json, "Ki");
    json_object *Kd_obj = json_object_object_get(parsed_json, "Kd");

    *target_temp = target_temp_obj ? json_object_get_double(target_temp_obj) : TARGET_TEMP_DEFAULT;
    *Kp = Kp_obj ? json_object_get_double(Kp_obj) : Kp_DEFAULT;
    *Ki = Ki_obj ? json_object_get_double(Ki_obj) : Ki_DEFAULT;
    *Kd = Kd_obj ? json_object_get_double(Kd_obj) : Kd_DEFAULT;

    json_object_put(parsed_json);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *config_file = argv[1];
    double target_temp, Kp, Ki, Kd;
    load_config(config_file, &target_temp, &Kp, &Ki, &Kd);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    setup_gpio();
    int spi_fd = setup_spi();

    double integral = 0.0;
    double last_error = 0.0;
    struct timespec last_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double dt = (current_time.tv_sec - last_time.tv_sec) + (current_time.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = current_time;

        double temperature = read_temperature(spi_fd);
        if (temperature < 0.0) {
            cleanup_gpio();
            cleanup_spi(spi_fd);
            return EXIT_FAILURE;
        }

        if (temperature > FAILSAFE_TEMP) {
            fprintf(stderr, "Temperature exceeds failsafe threshold: %.2f°C\n", temperature);
            cleanup_gpio();
            cleanup_spi(spi_fd);
            return EXIT_FAILURE;
        }

        double error = target_temp - temperature;
        integral += error * dt;
        double derivative = (error - last_error) / dt;
        last_error = error;

        double output = Kp * error + Ki * integral + Kd * derivative;
        if (output < 0.0) output = 0.0;
        if (output > PWM_RANGE) output = PWM_RANGE;

        gpioSetPWMdutycycle(PWM_GPIO, (uint32_t)output);

        usleep(PID_INTERVAL);
    }

    cleanup_gpio();
    cleanup_spi(spi_fd);
    return EXIT_SUCCESS;
}

