    parsed_json = json_object_from_file(config_file);
    if (parsed_json == NULL) {
        fprintf(stderr, "Failed to load config file: %s\n", config_file);
        *target_temp = TARGET_TEMP_DEFAULT;
        *Kp = Kp_DEFAULT;
        *Ki = Ki_DEFAULT;
        *Kd = Kd_DEFAULT;
        return;
    }

    json_object *target_temp_obj = json_object_object_get(parsed_json, "target_temp");
    json_object *Kp_obj = json_object_object_get(parsed_json, "Kp");
    json_object *Ki_obj = json_object_object_get(parsed_json, "Ki");
    json_object *Kd_obj = json_object_object_get(parsed_json, "Kd");

    *target_temp = target_temp_obj ? json_object_get_double(target_temp_obj) : TARGET_TEMP_DEFAULT;
    *Kp = Kp_obj ? json_object_get_double(Kp_obj) : Kp_DEFAULT;
    *Ki = Ki_obj ? json_object_get_double(Ki_obj) : Ki_DEFAULT;
    *Kd = Kd_obj ? json_object_get_double(Kd_obj) : Kd_DEFAULT;

    json_object_put(parsed_json);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *config_file = argv[1];
    double target_temp, Kp, Ki, Kd;
    load_config(config_file, &target_temp, &Kp, &Ki, &Kd);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    setup_gpio();
    int spi_fd = setup_spi();

    double integral = 0.0;
    double last_error = 0.0;
    struct timespec last_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double dt = (current_time.tv_sec - last_time.tv_sec) + (current_time.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = current_time;

        double temperature = read_temperature(spi_fd);
        if (temperature < 0.0) {
            cleanup_gpio();
            cleanup_spi(spi_fd);
            return EXIT_FAILURE;
        }

        if (temperature > FAILSAFE_TEMP) {
            fprintf(stderr, "Temperature exceeds failsafe threshold: %.2f°C\n", temperature);
            cleanup_gpio();
            cleanup_spi(spi_fd);
            return EXIT_FAILURE;
        }

        double error = target_temp - temperature;
        integral += error * dt;
        double derivative = (error - last_error) / dt;
        last_error = error;

        double output = Kp * error + Ki * integral + Kd * derivative;
        if (output < 0.0) output = 0.0;
        if (output > PWM_RANGE) output = PWM_RANGE;

        gpioSetPWMdutycycle(PWM_GPIO, (uint32_t)output);

        usleep(PID_INTERVAL);
    }

    cleanup_gpio();
    cleanup_spi(spi_fd);
    return EXIT_SUCCESS;
}
