#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CALIB_START 0xAA
#define BMP180_REG_CALIB_END 0xBF
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34
#define OSS 0
#define BUFFER_SIZE 60
#define FAN_GPIO 18

typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

struct gpiod_chip *chip;
struct gpiod_line *fan_line;
int i2c_fd;
int timer_fd;

void cleanup() {
    if (fan_line) {
        gpiod_line_release(fan_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (timer_fd >= 0) {
        close(timer_fd);
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

void read_calib_data(uint16_t *calib) {
    uint8_t data[22];
    if (write(i2c_fd, &BMP180_REG_CALIB_START, 1) != 1) {
        perror("Failed to write to I2C");
        return;
    }
    if (read(i2c_fd, data, 22) != 22) {
        perror("Failed to read from I2C");
        return;
    }
    for (int i = 0; i < 11; i++) {
        calib[i] = (data[i * 2] << 8) | data[i * 2 + 1];
    }
}

void read_temperature(uint16_t *temp) {
    if (write(i2c_fd, &(uint8_t){BMP180_CMD_TEMP}, 1) != 1) {
        perror("Failed to write to I2C");
        return;
    }
    usleep(4500);
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C");
        return;
    }
    *temp = (data[0] << 8) | data[1];
}

void read_pressure(uint16_t *pressure) {
    if (write(i2c_fd, &(uint8_t){BMP180_CMD_PRESSURE + (OSS << 6)}, 1) != 1) {
        perror("Failed to write to I2C");
        return;
    }
    usleep(4500 + 2500 * OSS);
    uint8_t data[3];
    if (read(i2c_fd, data, 3) != 3) {
        perror("Failed to read from I2C");
        return;
    }
    *pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
}

void timer_callback() {
    uint16_t calib[11];
    read_calib_data(calib);

    uint16_t temp_raw;
    read_temperature(&temp_raw);

    uint16_t pressure_raw;
    read_pressure(&pressure_raw);

    if (temp_raw == 0 || pressure_raw == 0) {
        return;
    }

    int ac1 = calib[0];
    int ac2 = calib[1];
    int ac3 = calib[2];
    unsigned int ac4 = calib[3];
    unsigned int ac5 = calib[4];
    unsigned int ac6 = calib[5];
    int b1 = calib[6];
    int b2 = calib[7];
    int mb = calib[8];
    int mc = calib[9];
    int md = calib[10];

    int x1 = (temp_raw - ac6) * ac5 / 32768;
    int x2 = mc * 2048 / (x1 + md);
    int b5 = x1 + x2;

    float temperature = (b5 + 8) / 16.0;

    int b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / 4096)) / 2048;
    x2 = ac2 * b6 / 2048;
    int x3 = x1 + x2;
    int b3 = (((ac1 * 4 + x3) << OSS) + 2) / 4;
    x1 = ac3 * b6 / 8192;
    x2 = (b1 * (b6 * b6 / 4096)) / 65536;
    x3 = ((x1 + x2) + 2) / 4;
    unsigned int b4 = ac4 * (unsigned int)(32768 + x3) / 32768;
    unsigned int b7 = (unsigned int)(pressure_raw - b3) * (50000 >> OSS);
    int pressure;
    if (b7 < 0x80000000) {
        pressure = (b7 * 2) / b4;
    } else {
        pressure = (b7 / b4) * 2;
    }
    x1 = (pressure / 256) * (pressure / 256);
    x1 = (x1 * 3038) / 65536;
    x2 = (-7357 * pressure) / 65536;
    pressure = pressure + (x1 + x2 + 3791) / 16;

    Reading reading = {time(NULL), temperature, pressure};
    buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }

    printf("Timestamp: %s", ctime(&reading.timestamp));
    printf("Temperature: %.2f °C\n", reading.temperature);
    printf("Pressure: %.2f hPa\n", pressure / 100.0);

    if (reading.temperature > 30.0) {
        gpiod_line_set_value(fan_line, 1);
    } else {
        gpiod_line_set_value(fan_line, 0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
