            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temp, red, green, blue);
        usleep(500000);
    }

    gpioSetPWM(RED_PIN, 255);
    gpioSetPWM(GREEN_PIN, 255);
    gpioSetPWM(BLUE_PIN, 255);
    gpioTerminate();
    fclose(temp_file);

    return EXIT_SUCCESS;
}

