#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <libgpiod.h>
#include <json-c/json.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DHT22_RESPONSE_BITS 40
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void init_signals() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int read_dht22(struct gpiod_chip *chip, struct gpiod_line *line, int *humidity, int *temperature) {
    int ret;
    uint8_t data[5] = {0};
    int bit_count = 0;
    int byte_count = 0;
    int last_state = 1;
    struct timespec start, end;
    uint64_t duration;

    // Start signal: pull low for at least 1ms
    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    gpiod_line_release(line);

    // Switch to input mode
    ret = gpiod_line_request_input(line, "dht22");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        return -1;
    }

    // Wait for the sensor to respond
    while (gpiod_line_get_value(line) == 1) {
        if (!running) {
            return -1;
        }
        usleep(10);
    }

    // Read the 40 bits
    for (int i = 0; i < DHT22_RESPONSE_BITS; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == last_state) {
            if (!running) {
                return -1;
            }
            usleep(10);
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        last_state = gpiod_line_get_value(line);
        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (duration > 50) {
            data[byte_count] |= (1 << (7 - bit_count));
        }
        bit_count++;
        if (bit_count == 8) {
            byte_count++;
            bit_count = 0;
        }
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum mismatch\n");
        return -1;
    }

    *humidity = (data[0] << 8) | data[1];
    *temperature = (data[2] << 8) | data[3];
    return 0;
}

int send_http_request(int humidity, int temperature) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];
    int n;

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Fill server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    if (inet_pton(AF_INET, "yourserver.com", &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(sockfd);
        return -1;
    }

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connection with the server failed");
        close(sockfd);
        return -1;
    }

    // Prepare JSON payload
    struct json_object *root = json_object_new_object();
    json_object_object_add(root, "humidity", json_object_new_int(humidity));
    json_object_object_add(root, "temperature", json_object_new_int(temperature));
    const char *json_str = json_object_to_json_string(root);

    // Send HTTP request
    snprintf(buffer, sizeof(buffer), "POST /api/humidity HTTP/1.1\r\n"
                                     "Host: yourserver.com\r\n"
                                     "Content-Type: application/json\r\n"
                                     "Content-Length: %zu\r\n"
                                     "\r\n"
                                     "%s",
             strlen(json_str), json_str);

    send(sockfd, buffer, strlen(buffer), 0);

    // Read response
    n = read(sockfd, buffer, sizeof(buffer) - 1);
    if (n < 0) {
        perror("read");
        close(sockfd);
        return -1;
    }
    buffer[n] = '\0';
    printf("Response: %s\n", buffer);

    close(sockfd);
    json_object_put(root);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int humidity, temperature;
    int retries = 0;

    init_signals();

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running && retries < MAX_RETRIES) {
        if (read_dht22(chip, line, &humidity, &temperature) == 0) {
            if (send_http_request(humidity, temperature) == 0) {
                break;
            }
        } else {
            fprintf(stderr, "Failed to read from DHT22 or send HTTP request, retrying...\n");
        }
        retries++;
        sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Max retries reached, exiting.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

