    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running && retries < MAX_RETRIES) {
        if (read_dht22(chip, line, &humidity, &temperature) == 0) {
            if (send_http_request(humidity, temperature) == 0) {
                break;
            }
        } else {
            fprintf(stderr, "Failed to read from DHT22 or send HTTP request, retrying...\n");
        }
        retries++;
        sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Max retries reached, exiting.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
