#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DHT22_READ_INTERVAL 10
#define POST_RETRY_INTERVAL 2
#define POST_MAX_RETRIES 3
#define DHT22_READ_RETRIES 3
#define DEFAULT_URL "http://your-the-library’s-API-call.com/api/humidity"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int read_dht22(struct gpiod_chip *chip, struct gpiod_line *line, int *humidity, int *temperature) {
    int retries = DHT22_READ_RETRIES;
    while (retries--) {
        // Start signal
        gpiod_line_request_output(line, "dht22");
        gpiod_line_set_value(line, 0);
        usleep(1000);
        gpiod_line_set_value(line, 1);
        usleep(20);
        gpiod_line_release(line);

        // Switch to input
        gpiod_line_request_input(line, "dht22");

        // Wait for response
        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (now.tv_sec - start.tv_sec > 2) {
                log_event("DHT22: No response");
                break;
            }
        }

        // Read data
        int bits[40] = {0};
        for (int i = 0; i < 40; i++) {
            // Wait for low
            while (gpiod_line_get_value(line) == 0);
            // Wait for high
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &now);
                if (now.tv_sec - start.tv_sec > 2) {
                    log_event("DHT22: Timeout reading bit");
                    break;
                }
            }
            // Calculate bit duration
            struct timespec end;
            clock_gettime(CLOCK_MONOTONIC, &end);
            long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            bits[i] = (duration > 80);
        }

        // Validate checksum
        int sum = 0;
        for (int i = 0; i < 40; i++) {
            sum += bits[i];
        }
        if (sum % 2 == 0) {
            *humidity = (bits[0] << 8) | bits[1];
            *temperature = (bits[2] << 8) | bits[3];
            return 0;
        }
        log_event("DHT22: Checksum failed");
    }
    return -1;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t totalSize = size * nmemb;
    return totalSize;
}

int post_data(const char *url, int humidity, int temperature) {
    CURL *curl;
    CURLcode res;
    char json[100];
    snprintf(json, sizeof(json), "{\"humidity\": %d, \"temperature\": %d}", humidity, temperature);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            log_event(curl_easy_strerror(res));
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                log_event("POST successful");
                curl_slist_free_all(headers);
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                return 0;
            }
        }
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return -1;
}

int main(int argc, char *argv[]) {
    openlog("dht22_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    const char *url = DEFAULT_URL;
    if (argc > 2 && strcmp(argv[1], "-s") == 0) {
        url = argv[2];
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int humidity, temperature;
        if (read_dht22(chip, line, &humidity, &temperature) == 0) {
            int retries = POST_MAX_RETRIES;
            while (retries--) {
                if (post_data(url, humidity, temperature) == 0) {
                    break;
                }
                sleep(POST_RETRY_INTERVAL);
            }
        }
        sleep(DHT22_READ_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

