size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t totalSize = size * nmemb;
    return totalSize;
}

int post_data(const char *url, int humidity, int temperature) {
    CURL *curl;
    CURLcode res;
    char json[100];
    snprintf(json, sizeof(json), "{\"humidity\": %d, \"temperature\": %d}", humidity, temperature);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            log_event(curl_easy_strerror(res));
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                log_event("POST successful");
                curl_slist_free_all(headers);
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                return 0;
            }
        }
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return -1;
}

int main(int argc, char *argv[]) {
    openlog("dht22_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    const char *url = DEFAULT_URL;
    if (argc > 2 && strcmp(argv[1], "-s") == 0) {
        url = argv[2];
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int humidity, temperature;
        if (read_dht22(chip, line, &humidity, &temperature) == 0) {
            int retries = POST_MAX_RETRIES;
            while (retries--) {
                if (post_data(url, humidity, temperature) == 0) {
                    break;
                }
                sleep(POST_RETRY_INTERVAL);
            }
        }
        sleep(DHT22_READ_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}
