#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define PWM_CHIP "pwmchip0"
#define PWM_CHANNEL 0
#define PWM_PERIOD 1000000 // 1 kHz
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000000 // 100%

#define TARGET_TEMP 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define LOG_FILE "heater_log.txt"

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

double read_temperature(int spi_fd) {
    uint8_t tx[4] = {0};
    uint8_t rx[4] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1.0;
    }

    uint32_t data = (rx[0] << 24) | (rx[1] << 16) | (rx[2] << 8) | rx[3];
    if (data & 0x1) {
        // Fault detected
        uint8_t fault = (data >> 16) & 0x7;
        switch (fault) {
            case 1:
                fprintf(stderr, "Open circuit\n");
                break;
            case 2:
                fprintf(stderr, "Short to GND\n");
                break;
            case 4:
                fprintf(stderr, "Short to VCC\n");
                break;
        }
        return -1.0;
    }

    int temp = (data >> 18) & 0x3FFF;
    if (temp & 0x2000) {
        temp |= 0xFFFFC000; // Sign extend
    }
    return temp * 0.25;
}

void set_pwm_duty(struct gpiod_chip *chip, int channel, int duty) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, channel);
    if (!line) {
        perror("gpiod_chip_get_line");
        return;
    }

    if (gpiod_line_request_output(line, "heater", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        return;
    }

    if (gpiod_line_set_value(line, duty > 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        return;
    }

    gpiod_line_release(line);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *pwm_chip = gpiod_chip_open_by_name(PWM_CHIP);
    if (!pwm_chip) {
        perror("gpiod_chip_open_by_name");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *pwm_line = gpiod_chip_get_line(pwm_chip, PWM_CHANNEL);
    if (!pwm_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(pwm_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pwm_line, "heater", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(pwm_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(pwm_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(pwm_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    double integral = 0.0;
    double prev_error = 0.0;
    time_t last_log_time = time(NULL);

    while (running) {
        double temp = read_temperature(spi_fd);
        if (temp < 0 || temp > 100) {
            fprintf(stderr, "Temperature out of bounds: %.2f\n", temp);
            set_pwm_duty(pwm_chip, PWM_CHANNEL, 0);
            integral = 0.0;
            prev_error = 0.0;
            continue;
        }

        double error = TARGET_TEMP - temp;
        integral += error;
        double derivative = error - prev_error;
        double output = Kp * error + Ki * integral + Kd * derivative;
        int duty = (int)(output * PWM_DUTY_MAX / 100.0);
        if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
        if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

        set_pwm_duty(pwm_chip, PWM_CHANNEL, duty);

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            fprintf(log_file, "%.2f, %d, %.2f\n", temp, duty, output);
            fflush(log_file);
            last_log_time = current_time;
        }

        prev_error = error;
        usleep(100000); // 100 ms
    }

    set_pwm_duty(pwm_chip, PWM_CHANNEL, 0);
    fclose(log_file);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(pwm_chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

