#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_MUX_ADDRESS 0x70
#define SENSOR1_ADDRESS 0x40
#define SENSOR2_ADDRESS 0x41
#define CRC8_POLYNOMIAL 0x07
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int i2c_fd, uint8_t sensor_address, uint8_t *data) {
    if (ioctl(i2c_fd, I2C_SLAVE, sensor_address) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(i2c_fd, data, 3) == 3) {
            uint8_t calculated_crc = calculate_crc8(data, 2);
            if (calculated_crc == data[2]) {
                return 0;
            } else {
                fprintf(stderr, "CRC check failed for sensor at address 0x%02X\n", sensor_address);
            }
        } else {
            perror("Failed to read from sensor");
        }
    }
    return -1;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_MUX_ADDRESS) < 0) {
        perror("Failed to set I2C mux address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t data1[3], data2[3];
    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Select sensor 1
        uint8_t channel1 = 0x04; // Assuming channel 0 is selected by default
        if (write(i2c_fd, &channel1, 1) != 1) {
            perror("Failed to select sensor 1");
            break;
        }

        if (read_sensor(i2c_fd, SENSOR1_ADDRESS, data1) == 0) {
            // Select sensor 2
            uint8_t channel2 = 0x08; // Assuming channel 1 is selected by default
            if (write(i2c_fd, &channel2, 1) != 1) {
                perror("Failed to select sensor 2");
                break;
            }

            if (read_sensor(i2c_fd, SENSOR2_ADDRESS, data2) == 0) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s,%d,%d\n", timestamp, (data1[0] << 8) | data1[1], (data2[0] << 8) | data2[1]);
                fflush(log_file);
            }
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

