#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_A 17
#define GPIO_B 18
#define PULSES_PER_REVOLUTION 360
#define DEGREES_PER_PULSE (360.0 / PULSES_PER_REVOLUTION)

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    int ret;
    FILE *log_file;
    int current_state = 0;
    int previous_state = 0;
    int pulse_count = 0;
    double angle = 0.0;
    struct timespec ts;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line_a = gpiod_chip_get_line(chip, GPIO_A);
    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (!line_a || !line_b) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO lines as open-drain outputs with pull-up resistors
    ret = gpiod_line_request_output(line_a, "encoder", 1);
    if (ret < 0) {
        perror("Failed to request GPIO A");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_b, "encoder", 1);
    if (ret < 0) {
        perror("Failed to request GPIO B");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("encoder_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Quadrature state machine
    while (running) {
        int a = gpiod_line_get_value(line_a);
        int b = gpiod_line_get_value(line_b);
        current_state = (a << 1) | b;

        if (current_state != previous_state) {
            switch ((previous_state << 2) | current_state) {
                case 0b0001: case 0b0111: case 0b1110: case 0b1000:
                    pulse_count++;
                    break;
                case 0b0010: case 0b1011: case 0b1101: case 0b0100:
                    pulse_count--;
                    break;
            }

            // Normalize angle
            angle = (pulse_count % PULSES_PER_REVOLUTION) * DEGREES_PER_PULSE;
            if (angle < 0) {
                angle += 360.0;
            }

            // Log timestamped position change
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%.6f: %.2f\n", ts.tv_sec + ts.tv_nsec / 1e9, angle);
            fflush(log_file);

            previous_state = current_state;
        }

        // Sleep briefly to reduce CPU usage
        usleep(1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

