#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x58
#define LED_GPIO 17
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define IR_THRESHOLD 2000

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
