#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define PULSE_PER_REVOLUTION 1
#define INTERVAL_SECONDS 1

volatile sig_atomic_t running = 1;
pthread_mutex_t pulse_mutex;
unsigned int pulse_count = 0;
FILE *log_file = NULL;

void signal_handler(int signum) {
    running = 0;
}

void *count_pulses(void *arg) {
    struct gpiod_chip *chip = (struct gpiod_chip *)arg;
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_rising_edge_events(line, "mlx90254_rpm");
    if (ret < 0) {
        perror("Failed to request rising edge events");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for events");
            break;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read event");
            break;
        }

        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }

    gpiod_line_release(line);
    return NULL;
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("rpm_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        fclose(log_file);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pthread_t pulse_thread;
    if (pthread_create(&pulse_thread, NULL, count_pulses, chip) != 0) {
        perror("Failed to create pulse counting thread");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        pthread_join(pulse_thread, NULL);
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        sleep(INTERVAL_SECONDS);

        pthread_mutex_lock(&pulse_mutex);
        unsigned int count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = (count * 60.0) / INTERVAL_SECONDS;
        if (rpm == 0.0) {
            fprintf(log_file, "0.00 RPM\n");
        } else {
            fprintf(log_file, "%.2f RPM\n", rpm);
        }
        fflush(log_file);
    }

    pthread_join(pulse_thread, NULL);
    pthread_mutex_destroy(&pulse_mutex);
    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

