#define GPIO_CHIP "gpiochip0"
#define GPIO_OUT_PIN 17
#define GPIO_GAIN_PIN 18
#define SAMPLE_INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *level) {
    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s %s\n", timestamp, level);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *out_line, *gain_line;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request output line for gain control
    gain_line = gpiod_chip_get_line(chip, GPIO_GAIN_PIN);
    if (!gain_line) {
