        tvoc = i2c_smbus_read_word_data(i2c_fd, TVOC_REG);

        // Read eCO2
        if (i2c_smbus_read_word_data(i2c_fd, ECO2_REG) < 0) {
            perror("Failed to read eCO2");
            continue;
