        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log data
        fprintf(log_file, "%s,%u,%u,%u\n", timestamp, iaq, tvoc, eco2);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanup
    gpiod_line_release(reset_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

