#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER_LABEL "ttp223_tamper"
#define POLL_INTERVAL_US 100000
#define INTRUSION_THRESHOLD_US 5000000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t running = 1;

void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main(void) {
    struct timespec start_time, current_time;
    int ret;

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure line as input
    ret = gpiod_line_request_input(line, CONSUMER_LABEL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize start time
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
        fprintf(stderr, "Failed to get start time: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int value;

        // Read GPIO line value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (value == 1) {
            // Touch detected, check duration
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }

            if (timespec_subtract(&current_time, &start_time) >= INTRUSION_THRESHOLD_US) {
                printf("Intrusion alert: Touch detected for more than 5 seconds.\n");
                // Reset start time
                if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                    fprintf(stderr, "Failed to get start time: %s\n", strerror(errno));
                    cleanup();
                    return EXIT_FAILURE;
                }
            }
        } else {
            // Touch released, reset start time
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                fprintf(stderr, "Failed to get start time: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
        }

        // Sleep for poll interval
        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, struct timespec *x) {
    if (x->tv_nsec < result->tv_nsec) {
