#include <sys/stat.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define PCM_DEVICE "default"
#define SAMPLE_RATE 16000
#define CHANNELS 2
#define FORMAT SND_PCM_FORMAT_S16_LE
#define BUFFER_SIZE 1024
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int ret;
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *params;
    snd_pcm_uframes_t frames;
    char *buffer;
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Set up signal handler for graceful termination
    signal(SIGINT, sigint_handler);

    // Open ALSA PCM device
    if ((ret = snd_pcm_open(&handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Cannot open audio device %s (%s)\n", PCM_DEVICE, snd_strerror(ret));
        return EXIT_FAILURE;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&params);

    // Initialize hardware parameters
    if ((ret = snd_pcm_hw_params_any(handle, params)) < 0) {
        fprintf(stderr, "Cannot initialize hardware parameters (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Set access type
    if ((ret = snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Cannot set access type (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Set sample format
    if ((ret = snd_pcm_hw_params_set_format(handle, params, FORMAT)) < 0) {
        fprintf(stderr, "Cannot set sample format (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((ret = snd_pcm_hw_params_set_rate_near(handle, params, &rate, 0)) < 0) {
        fprintf(stderr, "Cannot set sample rate (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Set number of channels
    if ((ret = snd_pcm_hw_params_set_channels(handle, params, CHANNELS)) < 0) {
        fprintf(stderr, "Cannot set channel count (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Apply hardware parameters
    if ((ret = snd_pcm_hw_params(handle, params)) < 0) {
        fprintf(stderr, "Cannot set hardware parameters (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Prepare the PCM device
    if ((ret = snd_pcm_prepare(handle)) < 0) {
        fprintf(stderr, "Cannot prepare audio interface for use (%s)\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Allocate buffer
    buffer = (char *)malloc(BUFFER_SIZE);
    if (!buffer) {
        fprintf(stderr, "Cannot allocate buffer\n");
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open GPIO chip %s\n", GPIO_CHIP);
        free(buffer);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        free(buffer);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "i2s_channel_select", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        free(buffer);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Open output file
    fd = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Cannot open output file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        free(buffer);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Set GPIO line to select left channel
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Cannot set GPIO line value\n");
            break;
        }

        // Read audio data
        frames = snd_pcm_readi(handle, buffer, BUFFER_SIZE / (2 * CHANNELS));
        if (frames < 0) {
            frames = snd_pcm_recover(handle, frames, 0);
            if (frames < 0) {
                fprintf(stderr, "Read from audio interface failed (%s)\n", snd_strerror(frames));
                break;
            }
        }

        // Write audio data to file
        if (write(fd, buffer, frames * 2 * CHANNELS) != frames * 2 * CHANNELS) {
            fprintf(stderr, "Write to file failed: %s\n", strerror(errno));
            break;
        }
    }

    // Clean up
    close(fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    free(buffer);
    snd_pcm_close(handle);

    return EXIT_SUCCESS;
}

