#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define FAN_PIN 18
#define DEBOUNCE_TIME_US 50000
#define TIMEOUT_US 1000000
#define PWM_FREQ 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *event, FILE *log_file) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *fan_line;
    FILE *log_file;
    int ret;

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO library");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request fan line
    fan_line = gpiod_chip_get_line(chip, FAN_PIN);
    if (!fan_line) {
        perror("Failed to get fan line");
        gpiod_chip_close(chip);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure sensor line as input
    ret = gpiod_line_request_input(sensor_line, "flame_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line as input");
        gpiod_chip_close(chip);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure fan line as output
    ret = gpiod_line_request_output(fan_line, "fan", 0);
    if (ret < 0) {
        perror("Failed to request fan line as output");
        gpiod_chip_close(chip);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Log program start
    log_event("Program start", log_file);

    // Main loop
    int last_state = 1;
    struct timespec last_change;
    clock_gettime(CLOCK_MONOTONIC, &last_change);

    while (running) {
        int current_state;
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        // Check for timeout
        if (timespec_subtract(&now, &last_change) > TIMEOUT_US) {
            log_event("Sensor absent", log_file);
            break;
        }

        // Read sensor state
        current_state = gpiod_line_get_value(sensor_line);
        if (current_state < 0) {
            perror("Failed to read sensor state");
            break;
        }

        // Apply debounce
        if (current_state != last_state) {
            clock_gettime(CLOCK_MONOTONIC, &last_change);
            last_state = current_state;
            continue;
        }

        if (timespec_subtract(&now, &last_change) < DEBOUNCE_TIME_US) {
            continue;
        }

        // Handle flame detection
        if (current_state == 0) {
            log_event("Flame detected", log_file);
            gpioHardwarePWM(FAN_PIN, PWM_FREQ, 500000); // 50% duty cycle
        } else {
            log_event("Flame end", log_file);
            gpioHardwarePWM(FAN_PIN, 0, 0);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Log program shutdown
    log_event("Program shutdown", log_file);

    // Clean up
    gpioHardwarePWM(FAN_PIN, 0, 0);
    gpiod_line_release(sensor_line);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, struct timespec *x, struct timespec *y) {
    if (x->tv_sec < y->tv_sec) return -1;
    if (x->tv_sec > y->tv_sec) return 1;
    if (x->tv_nsec < y->tv_nsec) return -1;
    if (x->tv_nsec > y->tv_nsec) return 1;
    return 0;
}

