        close(log_fd);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        if (gpiod_line_get_value(data_ready) == 1) {
            struct spi_ioc_transfer xfer = {
                .tx_buf = 0,
                .rx_buf = (unsigned long)frame,
                .len = FRAME_SIZE,
                .speed_hz = SPI_SPEED,
                .bits_per_word = 8,
                .delay_usecs = 0,
                .cs_change = 0,
                .tx_nbits = 0,
                .rx_nbits = 0,
                .pad = 0,
            };

            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
                perror("Failed to perform SPI transfer");
                free(frame);
                close(log_fd);
                gpiod_chip_close(chip);
                close(spi_fd);
                exit(EXIT_FAILURE);
            }

            log_frame(log_fd, frame, FRAME_SIZE);
        }

        usleep(100000); // 100 ms
    }

    free(frame);
    close(log_fd);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

