#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_state(FILE *log_file, int state) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s - Flame %s\n", timestamp, state ? "Detected" : "Cleared");
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int current_state = 0;
    int previous_state = 0;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Request the line for input
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        goto cleanup;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (running) {
        // Read the current state
        current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        // Check for state change
        if (current_state != previous_state) {
            log_state(log_file, current_state);
            previous_state = current_state;
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_US);
    }

cleanup:
    // Release resources
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

