#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define OPT3001_CONFIG_REG 0x01
#define OPT3001_RESULT_REG 0x00
#define OPT3001_CONFIG_CONTINUOUS 0xC400
#define OPT3001_CONFIG_AUTO_FULL_SCALE 0x0000
#define OPT3001_CONFIG_DEFAULT (OPT3001_CONFIG_CONTINUOUS | OPT3001_CONFIG_AUTO_FULL_SCALE)
#define FILE_NAME "light_data.txt"
#define RETRY_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void write_timestamped_lux(FILE *file, float lux) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
    fprintf(file, "%s.%06ld,%.2f\n", timestamp, tv.tv_usec, lux);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t config = OPT3001_CONFIG_DEFAULT;
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write configuration to OPT3001");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(FILE_NAME, "a");
    if (!file) {
        perror("Failed to open file for writing");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t result;
        if (read(i2c_fd, &result, 2) != 2) {
            perror("Failed to read from OPT3001");
            usleep(RETRY_DELAY);
            continue;
        }

        float lux = (result >> 4) * 0.01f;
        write_timestamped_lux(file, lux);
        fflush(file);
        usleep(100000); // Wait for 100 ms
    }

    fclose(file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

