    ret = gpiod_line_request_input(left_line, "ky033_left");
    if (ret < 0) {
        perror("Failed to request left GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(center_line, "ky033_center");
    if (ret < 0) {
        perror("Failed to request center GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(right_line, "ky033_right");
    if (ret < 0) {
