static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[GPIO_LINES];
static volatile sig_atomic_t running = 1;

void cleanup() {
    for (int i = 0; i < GPIO_LINES; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    int ret;

    // Set up signal handler for graceful shutdown
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSET + i);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            cleanup();
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_request_input(lines[i], "ttp226_reader");
        if (ret < 0) {
            perror("gpiod_line_request_input");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    while (running) {
        int values[GPIO_LINES];

        // Read the state of each line
        for (int i = 0; i < GPIO_LINES; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                perror("gpiod_line_get_value");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            cleanup();
            exit(EXIT_FAILURE);
        }

        // Print the timestamped state
        printf("%ld.%09ld: ", ts.tv_sec, ts.tv_nsec);
        for (int i = 0; i < GPIO_LINES; i++) {
            printf("%d", values[i]);
        }
        printf("\n");

        // Sleep for 100 ms
        usleep(100000);
    }

    // Cleanup resources
    cleanup();
    return 0;
}

