#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    struct timespec start_time, current_time;
    long elapsed_time_ms;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines with pull-down resistors
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_BASE + i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            ret = EXIT_FAILURE;
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226_reader");
        if (ret < 0) {
            perror("Failed to request GPIO line as input");
            ret = EXIT_FAILURE;
            goto cleanup;
        }

        ret = gpiod_line_set_bias(lines[i], GPIOD_LINE_BIAS_PULL_DOWN);
        if (ret < 0) {
            perror("Failed to set GPIO line bias to pull-down");
            ret = EXIT_FAILURE;
            goto cleanup;
        }
    }

    // Get start time
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
        perror("Failed to get start time");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Main loop
    while (running) {
        int values[NUM_CHANNELS];

        // Read values from the lines
        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                perror("Failed to read GPIO line value");
                ret = EXIT_FAILURE;
                goto cleanup;
            }
        }

        // Get current time
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) < 0) {
            perror("Failed to get current time");
            ret = EXIT_FAILURE;
            goto cleanup;
        }

        // Calculate elapsed time in milliseconds
        elapsed_time_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                         (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

        // Print the values
        printf("[%ld ms] ", elapsed_time_ms);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("CH%d=%d ", i + 1, values[i]);
        }
        printf("\n");

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    // Release resources
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

