#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS];
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void release_resources() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    int ret;

    // Set up SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            release_resources();
            return EXIT_FAILURE;
        }
        ret = gpiod_line_request_input(lines[i], "ttp226_reader");
        if (ret < 0) {
            perror("gpiod_line_request_input");
            release_resources();
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (running) {
        char timestamp[30];
        int values[NUM_CHANNELS];

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

        // Read line values
        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                perror("gpiod_line_get_value");
                break;
            }
        }

        // Print CSV line
        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n", timestamp, values[0], values[1], values[2], values[3], values[4], values[5], values[6], values[7]);

        // Sleep for poll interval
        usleep(POLL_INTERVAL_US);
    }

    // Release resources
    release_resources();

    return EXIT_SUCCESS;
}

