This code sets up a Raspberry Pi to read an 8-channel TTP226 capacitive touch sensor array using the `libgpiod` library. It configures each GPIO line as an input with bias disabled, polls the state of all channels every 50 ms, and writes the state to the console in CSV format with an ISO-8601 timestamp. The program handles errors and ensures that all resources are released on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define POLL_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;
    int last_state = -1;

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto exit_chip;
    }

    // Request line as input with pull-up
    ret = gpiod_line_request_input(line, "tilt_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        goto exit_line;
    }

    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_set_bias");
        goto exit_line;
    }

    // Print startup banner
    printf("Tilt Sensor Polling Started\n");
    fflush(stdout);

    // Main loop
    while (running) {
        int current_state;

        // Read GPIO line
        current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            perror("gpiod_line_get_value");
            goto exit_line;
        }

        // Check for state change
        if (current_state != last_state) {
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = current_state;
        }

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_US);
    }

exit_line:
    gpiod_line_release(line);
exit_chip:
    gpiod_chip_close(chip);

    return 0;
}

