This code sets up a Raspberry Pi Zero W to continuously poll an Omron D7E-1 tilt sensor connected to GPIO4 (BCM pin 7). It uses the `libgpiod` library to interact with the GPIO pins, ensuring proper initialization, error handling, and resource cleanup. The program includes a SIGINT handler to allow clean termination on Ctrl-C.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_CMD 0x08
#define SI1145_CMD_RESET 0x11
#define SI1145_CMD_ALS_VIS_DATA 0x02
#define SI1145_CMD_ALS_IR_DATA 0x03
#define SI1145_CMD_UV_INDEX_DATA 0x04

#define LOG_FILE "uv_als_log.csv"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg) {
    if (i2c_write_byte(fd, SI1145_REG_CMD, reg) < 0) {
        return -1;
    }
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (buffer[1] << 8) | buffer[0];
}

int init_si1145(int fd) {
    if (i2c_write_byte(fd, SI1145_REG_CMD, SI1145_CMD_RESET) < 0) {
        return -1;
    }
    sleep(1); // Wait for reset to complete
    uint8_t part_id = i2c_read_word(fd, SI1145_REG_PART_ID) & 0xFF;
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid Si1145 part ID: 0x%02X\n", part_id);
        return -1;
    }
    return 0;
}

void sample_sensor() {
    int uv_index = i2c_read_word(i2c_fd, SI1145_CMD_UV_INDEX_DATA);
    int als_visible = i2c_read_word(i2c_fd, SI1145_CMD_ALS_VIS_DATA);
    if (uv_index < 0 || als_visible < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("Timestamp: %s, UV Index: %d, ALS Visible: %d\n", timestamp, uv_index, als_visible);

    fprintf(log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
    fflush(log_file);

    while (1) {
        sample_sensor();
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

