    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
    fflush(log_file);

    while (1) {
        sample_sensor();
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}
