#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define ALARM_GPIO 17
#define LOG_FILE "flow_log.txt"
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define START_COMMAND 0x10
#define MEASUREMENT_COMMAND 0x00
#define MEASUREMENT_LENGTH 3
#define MEASUREMENT_INTERVAL 1000000 // 1 second in microseconds
#define ALARM_THRESHOLD 0.5 // ml/min

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int i2c_fd, uint8_t addr, uint16_t *flow_rate) {
    uint8_t buffer[MEASUREMENT_LENGTH];
    struct i2c_msg msgs[2] = {
        { .addr = addr, .flags = 0, .len = 1, .buf = (uint8_t[]){ MEASUREMENT_COMMAND } },
        { .addr = addr, .flags = I2C_M_RD, .len = MEASUREMENT_LENGTH, .buf = buffer }
    };
    struct i2c_rdwr_ioctl_data ioctl_data = { .msgs = msgs, .nmsgs = 2 };

    if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("I2C read failed");
        return -1;
    }

    if (crc8(buffer, 2, CRC8_INIT) != buffer[2]) {
        fprintf(stderr, "CRC check failed for sensor at address 0x%02X\n", addr);
        return -1;
    }

    *flow_rate = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &START_COMMAND, 1) != 1) {
        perror("Failed to send start command to sensor 1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 2");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &START_COMMAND, 1) != 1) {
        perror("Failed to send start command to sensor 2");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        uint16_t flow_rate1 = 0, flow_rate2 = 0;
        int valid_readings = 0;

        if (read_sensor(i2c_fd, SENSOR1_ADDR, &flow_rate1) == 0) {
            valid_readings++;
        }

        if (read_sensor(i2c_fd, SENSOR2_ADDR, &flow_rate2) == 0) {
            valid_readings++;
        }

        if (valid_readings > 0) {
            double average_flow_rate = (flow_rate1 + flow_rate2) / (2.0 * valid_readings);
            fprintf(log_file, "%.2f ml/min\n", average_flow_rate);
            fflush(log_file);

            if (average_flow_rate < ALARM_THRESHOLD) {
                gpiod_line_set_value(alarm_line, 1);
            } else {
                gpiod_line_set_value(alarm_line, 0);
            }
        }

        usleep(MEASUREMENT_INTERVAL);
    }

    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

