#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 50000

typedef struct {
    struct timespec timestamp;
    int detected;
} Detection;

Detection buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_count = 0;

void handle_sigint(int sig) {
    // Signal handler to clean up resources
    exit(0);
}

void dump_buffer() {
    for (int i = 0; i < buffer_count; i++) {
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[(buffer_head + i) % BUFFER_SIZE].timestamp));
        printf("%s: %s\n", time_str, buffer[(buffer_head + i) % BUFFER_SIZE].detected ? "Detected" : "No Detection");
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure line as input with pull-up
    ret = gpiod_line_request_input(line, "obstacle_sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (1) {
        int value;
        struct timespec current_time;

        // Read the sensor value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        // Record the detection
        clock_gettime(CLOCK_REALTIME, &current_time);
        buffer[buffer_head].timestamp = current_time;
        buffer[buffer_head].detected = value == 0; // LOW indicates detection

        // Emit alert on detection
        if (buffer[buffer_head].detected) {
            printf("Obstacle detected at %ld.%09ld\n", current_time.tv_sec, current_time.tv_nsec);
        }

        // Update buffer pointers
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    // Clean up resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Dump the buffer on exit
    dump_buffer();

    return EXIT_SUCCESS;
}

