#define POLL_INTERVAL 500000 // 500 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd = -1;
    FILE *csv_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sda_line = NULL, *scl_line = NULL;
    struct timespec start_time, current_time;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Set I2C speed
    if (ioctl(i2c_fd, I2C_SET_SPEED, &I2C_SPEED) < 0) {
        perror("Failed to set I2C speed");
        goto cleanup;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    // Request SDA and SCL lines
    sda_line = gpiod_chip_get_line(chip, 2);
    scl_line = gpiod_chip_get_line(chip, 3);
    if (!sda_line || !scl_line) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    // Configure SDA and SCL lines
    ret = gpiod_line_request_output(sda_line, "i2c_sda", 0);
    if (ret < 0) {
        perror("Failed to request SDA line");
        goto cleanup;
    }
    ret = gpiod_line_request_output(scl_line, "i2c_scl", 0);
    if (ret < 0) {
        perror("Failed to request SCL line");
        goto cleanup;
    }

    // Switch sensor to active mode
    uint8_t mode_data = ACTIVE_MODE;
    if (write(i2c_fd, &mode_data, 1) != 1) {
        perror("Failed to write mode to sensor");
        goto cleanup;
    }

    // Wait for sensor to become active
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (timespec_diff(&current_time, &start_time) > 1000000) { // 1 second
            fprintf(stderr, "Sensor did not become active within 1 second\n");
            goto cleanup;
        }

        // Poll sensor status
        uint8_t status;
        if (read(i2c_fd, &status, 1) != 1) {
            perror("Failed to read sensor status");
            continue;
        }

        if (status & 0x01) { // Sensor active
            break;
        }

        usleep(100000); // 100 ms
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        goto cleanup;
    }

    // Write header if file is newly created
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop
    while (running) {
        // Read acceleration data
        uint8_t x_data[2], y_data[2], z_data[2];
        if (write(i2c_fd, &X_ACCEL_REGISTER, 1) != 1 ||
            read(i2c_fd, x_data, 2) != 2 ||
            write(i2c_fd, &Y_ACCEL_REGISTER, 1) != 1 ||
            read(i2c_fd, y_data, 2) != 2 ||
            write(i2c_fd, &Z_ACCEL_REGISTER, 1) != 1 ||
            read(i2c_fd, z_data, 2) != 2) {
            perror("Failed to read acceleration data");
            continue;
        }

        // Convert data to signed 16-bit integers
        int16_t x = (x_data[0] << 8) | x_data[1];
        int16_t y = (y_data[0] << 8) | y_data[1];
        int16_t z = (z_data[0] << 8) | z_data[1];

        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));

        // Write data to CSV
        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(csv_file);

        // Sleep for 500 ms
        usleep(POLL_INTERVAL);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    if (sda_line) {
        gpiod_line_release(sda_line);
    }
    if (scl_line) {
        gpiod_line_release(scl_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

// Helper function to calculate the difference between two timespecs in microseconds
long timespec_diff(const struct timespec *a, const struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}
