            perror("Failed to read GPIO lines");
            break;
        }

        // Check for stall
        if (sensor1_value == 0 && sensor2_value == 0) {
            if (!stall_detected) {
                clock_gettime(CLOCK_REALTIME, &start_time);
                stall_detected = 1;
            } else {
