                if (current_time.tv_sec - start_time.tv_sec >= STALL_DURATION) {
                    // Log stall event
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
                    fprintf(log_file, "Stall detected at %s\n", timestamp);
                    fflush(log_file);
                    stall_detected = 0;
                }
            }
        } else {
            stall_detected = 0;
        }

        // Sleep for a short period
        usleep(100000); // 100 ms
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

