#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x1E
#define CONFIG_REG 0x00
#define DATA_REG 0x01
#define CONTINUOUS_MODE 0x00
#define ALL_AXES_ENABLED 0x07
#define RANGE_50mT 0x00

#define CSV_FILE "magnetic_log.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        exit(EXIT_FAILURE);
    }

    uint8_t config = (CONTINUOUS_MODE << 6) | (ALL_AXES_ENABLED << 3) | RANGE_50mT;
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write to the sensor configuration register");
        cleanup();
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    while (running) {
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read from the sensor data register");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(csv_file);

        usleep(100000);
    }

    cleanup();
    return 0;
}

