#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>
#include <atomic>
#include <iostream>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define LOG_FILE "rpm_log.txt"

std::atomic<unsigned int> pulse_count(0);
volatile sig_atomic_t running = 1;

void log_rpm(unsigned int rpm) {
    time_t now = time(nullptr);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s %u\n", timestamp, rpm);
    fflush(log_file);
    fclose(log_file);

    printf("%s %u\n", timestamp, rpm);
}

void alert_callback(const struct gpiod_line_event *event, void *data) {
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        pulse_count.fetch_add(1, std::memory_order_relaxed);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = nullptr;
    struct gpiod_line *line = nullptr;
    struct gpiod_line_event event;
    struct sigaction sa;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request line as input with pull-up
    int ret = gpiod_line_request_input(line, "mlx90217_rpm");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set GPIO line bias to pull-up");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request line event monitoring
    ret = gpiod_line_request_event(line, "mlx90217_rpm");
    if (ret < 0) {
        perror("Failed to request GPIO line event monitoring");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Install signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, nullptr);
    sigaction(SIGTERM, &sa, nullptr);

    while (running) {
        pulse_count.store(0, std::memory_order_relaxed);
        time_t start_time = time(nullptr);

        while (running && (time(nullptr) - start_time < 1)) {
            ret = gpiod_line_event_wait(line, nullptr);
            if (ret < 0) {
                perror("Failed to wait for GPIO line event");
                break;
            }

            if (ret > 0) {
                ret = gpiod_line_event_read(line, &event);
                if (ret < 0) {
                    perror("Failed to read GPIO line event");
                    break;
                }

                alert_callback(&event, nullptr);
            }
        }

        unsigned int rpm = pulse_count.load(std::memory_order_relaxed) * 60;
        log_rpm(rpm);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

