#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_A 17
#define GPIO_B 27
#define LOG_FILE "rotation_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line_a, *line_b;
static FILE *log_file;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
static volatile int running = 1;
static int prev_state = 0;

void signal_handler(int signum) {
    pthread_mutex_lock(&mutex);
    running = 0;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }
}

void log_event(const char *direction) {
    struct timespec ts;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts));
        fprintf(log_file, "%s.%03ld %s\n", timestamp, ts.tv_nsec / 1000000, direction);
        fflush(log_file);
    }
}

int get_quadrature_state(int a, int b) {
    return (a << 1) | b;
}

void handle_interrupt(const struct gpiod_line_event *event) {
    int a, b, current_state, direction;

    pthread_mutex_lock(&mutex);

    a = gpiod_line_get_value(line_a);
    b = gpiod_line_get_value(line_b);
    current_state = get_quadrature_state(a, b);

    if (current_state != prev_state) {
        if ((prev_state == 0 && current_state == 3) || (prev_state == 1 && current_state == 0) ||
            (prev_state == 2 && current_state == 1) || (prev_state == 3 && current_state == 2)) {
            log_event("Clockwise");
        } else {
            log_event("Counter-Clockwise");
        }
        prev_state = current_state;
    }

    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

int main() {
    struct sigaction sa;
    struct gpiod_line_request_config config = {
        .consumer = "mlx90217_quad",
        .request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE,
    };

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, GPIO_A);
    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (!line_a || !line_b) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_event(line_a, &config) < 0 || gpiod_line_request_event(line_b, &config) < 0) {
        perror("Failed to request GPIO line events");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        struct gpiod_line_event event;

        pthread_mutex_lock(&mutex);
        while (running && gpiod_line_event_wait(line_a, NULL) == 0) {
            pthread_cond_wait(&cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);

        if (!running) {
            break;
        }

        if (gpiod_line_event_read(line_a, &event) == 0) {
            handle_interrupt(&event);
        }
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

