#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define SENSOR_GPIO 23
#define LED_GPIO 18
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up SIGINT handler: %m");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up SIGTERM handler: %m");
        exit(EXIT_FAILURE);
    }
}

void cleanup(struct gpiod_chip *chip, struct gpiod_line *sensor_line, struct gpiod_line *led_line) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main() {
    openlog("ttt223b_led", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting TTP223B LED control program");

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        exit(EXIT_FAILURE);
