#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define CHIP "gpiochip0"
#define TOUCH_LINE 17
#define LED_LINE 18
#define DEBOUNCE_US 50000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line_event event;
    struct timespec ts;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto exit;
    }

    // Request the touch line for input
    touch_line = gpiod_chip_get_line(chip, TOUCH_LINE);
    if (!touch_line) {
        perror("Failed to get touch line");
        goto exit;
    }

    ret = gpiod_line_request_input(touch_line, "touch_sensor");
    if (ret < 0) {
        perror("Failed to request touch line as input");
        goto exit;
    }

    // Request the LED line for output
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get LED line");
        goto exit;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        goto exit;
    }

    // Main loop
    while (running) {
        ret = gpiod_line_event_wait(touch_line, NULL);
        if (ret < 0) {
            perror("Failed to wait for line event");
            goto exit;
        }

        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            perror("Failed to read line event");
            goto exit;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Debounce
            clock_gettime(CLOCK_MONOTONIC, &ts);
            ts.tv_nsec += DEBOUNCE_US * 1000;
            if (ts.tv_nsec >= 1000000000) {
                ts.tv_sec++;
                ts.tv_nsec -= 1000000000;
            }

            ret = clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);
            if (ret < 0) {
                perror("Failed to sleep for debounce");
                goto exit;
            }

            // Toggle LED
            ret = gpiod_line_get_value(led_line);
            if (ret < 0) {
                perror("Failed to get LED value");
                goto exit;
            }

            ret = gpiod_line_set_value(led_line, !ret);
            if (ret < 0) {
                perror("Failed to set LED value");
                goto exit;
            }
        }
    }

exit:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

