#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define BUFFER_SIZE 100
#define DEBOUNCE_MS 50

typedef struct {
    int pin;
    time_t timestamp;
    int state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;
int overflow_count = 0;

struct gpiod_chip *chip;
struct gpiod_line *sensor1, *sensor2, *led1, *led2;

void cleanup() {
    if (led1) {
        gpiod_line_release(led1);
    }
    if (led2) {
        gpiod_line_release(led2);
    }
    if (sensor1) {
        gpiod_line_release(sensor1);
    }
    if (sensor2) {
        gpiod_line_release(sensor2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    fprintf(stderr, "Received signal %d, shutting down...\n", sig);
    cleanup();
    exit(0);
}

void log_event(int pin, int state) {
    time_t now = time(NULL);
    if (log_index >= BUFFER_SIZE) {
        overflow_count++;
        log_index = 0;
    }
    log_buffer[log_index].pin = pin;
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].state = state;
    log_index++;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor1 = gpiod_chip_get_line(chip, 4);
    sensor2 = gpiod_chip_get_line(chip, 17);
    led1 = gpiod_chip_get_line(chip, 27);
    led2 = gpiod_chip_get_line(chip, 22);

    if (!sensor1 || !sensor2 || !led1 || !led2) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor1, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2, "sensor2") < 0 ||
        gpiod_line_request_output(led1, "led1", 0) < 0 ||
        gpiod_line_request_output(led2, "led2", 0) < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    int last_state1 = 0, last_state2 = 0;

    while (1) {
        int state1 = gpiod_line_get_value(sensor1);
        int state2 = gpiod_line_get_value(sensor2);

        if (state1 != last_state1) {
            gpiod_line_set_value(led1, state1);
            log_event(4, state1);
            last_state1 = state1;
        }

        if (state2 != last_state2) {
            gpiod_line_set_value(led2, state2);
            log_event(17, state2);
            last_state2 = state2;
        }

        usleep(DEBOUNCE_MS * 1000);
    }

    return EXIT_SUCCESS;
}

