#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log, "[%s] %s\n", timestamp, message);
    fclose(log);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request line for input with pull-up
    ret = gpiod_line_request_input(line, "rain_sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_config(line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set pull-up resistor");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int last_state = 1; // Assume no rain initially

    while (running) {
        int current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            perror("Failed to read GPIO line");
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            last_state = current_state;
        }

        usleep(500000); // Poll every 500 ms
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

