#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_US 5000
#define CSV_FILE "shaft_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_line_event event;
    struct timespec last_event_time = {0};
    int sensor1_state = 0, sensor2_state = 0;
    int rpm = 0;
    int event_count = 0;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor1_line || !sensor2_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines as input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        perror("Failed to request input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header to log file if it's empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,sensor1_state,sensor2_state\n");
    }

    while (running) {
        // Read sensor states
        sensor1_state = gpiod_line_get_value(sensor1_line);
        sensor2_state = gpiod_line_get_value(sensor2_line);

        // Log the current state
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file);

        // Check for state changes
        if (gpiod_line_event_wait(sensor1_line, NULL) > 0) {
            gpiod_line_event_read(sensor1_line, &event);
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                event_count++;
            }
        }

        if (gpiod_line_event_wait(sensor2_line, NULL) > 0) {
            gpiod_line_event_read(sensor2_line, &event);
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                event_count++;
            }
        }

        // Calculate RPM
        if (event_count >= 2) {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long elapsed_us = (current_time.tv_sec - last_event_time.tv_sec) * 1000000 +
                              (current_time.tv_nsec - last_event_time.tv_nsec) / 1000;
            if (elapsed_us > DEBOUNCE_US) {
                rpm = (event_count / 2) * (60000000 / elapsed_us);
                printf("RPM: %d\n", rpm);
                last_event_time = current_time;
                event_count = 0;
            }
        }

        // Sleep briefly to reduce CPU usage
        usleep(1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

