#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27
#define LOG_FILE "bridge_integrity.log"
#define POLL_INTERVAL_US 100000
#define ALARM_THRESHOLD_US 2000000

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static struct gpiod_line *alarm_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int ret;
    struct sigaction sa;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!sensor1_line || !sensor2_line || !alarm_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines
    ret = gpiod_line_request_input(sensor1_line, "sensor1");
    if (ret < 0) {
        perror("gpiod_line_request_input sensor1");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(sensor2_line, "sensor2");
    if (ret < 0) {
        perror("gpiod_line_request_input sensor2");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(alarm_line, "alarm", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output alarm");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    int sensor1_state = 0;
    int sensor2_state = 0;
    struct timespec start_time;
    struct timespec current_time;
    int alarm_active = 0;

    while (running) {
        ret = gpiod_line_get_value(sensor1_line);
        if (ret < 0) {
            perror("gpiod_line_get_value sensor1");
            break;
        }
        ret = gpiod_line_get_value(sensor2_line);
        if (ret < 0) {
            perror("gpiod_line_get_value sensor2");
            break;
        }

        if (sensor1_state == 0 && ret == 1) {
            log_event("Tilt-start sensor1");
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        } else if (sensor1_state == 1 && ret == 0) {
            log_event("Tilt-end sensor1");
        }
        sensor1_state = ret;

        if (sensor2_state == 0 && ret == 1) {
            log_event("Tilt-start sensor2");
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        } else if (sensor2_state == 1 && ret == 0) {
            log_event("Tilt-end sensor2");
        }
        sensor2_state = ret;

        if ((sensor1_state == 1 || sensor2_state == 1) && !alarm_active) {
            log_event("Threshold-exceeded");
            alarm_active = 1;
            gpiod_line_set_value(alarm_line, 1);
        } else if ((sensor1_state == 0 && sensor2_state == 0) && alarm_active) {
            log_event("Threshold-cleared");
            alarm_active = 0;
            gpiod_line_set_value(alarm_line, 0);
        }

        if (alarm_active) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (timespec_subtract(&current_time, &start_time) >= ALARM_THRESHOLD_US) {
                log_event("Alarm activated");
                gpiod_line_set_value(alarm_line, 1);
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, struct timespec *x) {
    if (x->tv_nsec < result->tv_nsec) {
        int nsec = (result->tv_nsec - x->tv_nsec) / 1000000000 + 1;
        result->tv_nsec -= 1000000000 * nsec;
        result->tv_sec += nsec;
    }
    if (x->tv_nsec - result->tv_nsec > 1000000000) {
        int nsec = (x->tv_nsec - result->tv_nsec) / 1000000000;
        result->tv_nsec += 1000000000 * nsec;
        result->tv_sec -= nsec;
    }

    result->tv_sec = x->tv_sec - result->tv_sec;
    result->tv_nsec = x->tv_nsec - result->tv_nsec;

    return x->tv_sec < result->tv_sec;
}

