#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x18
#define CTRL1_REG 0x20
#define STATUS_REG 0x27
#define OUT_X_L_REG 0x28
#define OUT_Y_L_REG 0x2A
#define OUT_Z_L_REG 0x2C
#define THRESHOLD 500
#define LED_PIN 17
#define RETRIES 3

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    FILE *log_file;
    int retries;
    uint8_t ctrl1, status;
    int16_t x, y, z;
    double magnitude;
    char timestamp[30];

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    if (!(chip = gpiod_chip_open("/dev/gpiochip0"))) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get LED line
    if (!(led_line = gpiod_chip_get_line(chip, LED_PIN))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request line for output
    if (gpiod_line_request_output(led_line, "seismic_alert", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if (!(log_file = fopen("seismic_events.log", "a"))) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    retries = RETRIES;
    while (retries--) {
        if (write(i2c_fd, &CTRL1_REG, 1) == 1 && read(i2c_fd, &ctrl1, 1) == 1) {
            if (ctrl1 & 0x01) {
                ctrl1 &= ~0x01; // Clear power-down bit
                if (write(i2c_fd, &CTRL1_REG, 1) == 1 && write(i2c_fd, &ctrl1, 1) == 1) {
                    break;
                }
            }
        }
        usleep(100000); // Wait 100 ms before retrying
    }
    if (retries < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        fclose(log_file);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    while (running) {
        retries = RETRIES;
        while (retries--) {
            if (write(i2c_fd, &STATUS_REG, 1) == 1 && read(i2c_fd, &status, 1) == 1) {
                if (status & 0x08) { // Data ready
                    uint8_t data[6];
                    if (write(i2c_fd, &OUT_X_L_REG, 1) == 1 && read(i2c_fd, data, 6) == 6) {
                        x = (data[1] << 8) | data[0];
                        y = (data[3] << 8) | data[2];
                        z = (data[5] << 8) | data[4];
                        magnitude = sqrt(x * x + y * y + z * z);
                        if (magnitude > THRESHOLD) {
                            time_t now = time(NULL);
                            struct tm *tm_info = localtime(&now);
                            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
                            fprintf(log_file, "%s, Peak Vibration: %.2f\n", timestamp, magnitude);
                            fflush(log_file);
                            gpiod_line_set_value(led_line, 1);
                            usleep(1000000); // Turn on LED for 1 second
                            gpiod_line_set_value(led_line, 0);
                        }
                        break;
                    }
                }
            }
            usleep(100000); // Wait 100 ms before retrying
        }
        if (retries < 0) {
            fprintf(stderr, "I2C communication error\n");
        }
        usleep(100000); // Poll every 100 ms
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
