        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            perror("gpiod_chip_get_line");
            goto cleanup;
        }
        ret = gpiod_line_request_input(sensor_lines[i], "obstacle_sensor");
        if (ret < 0) {
            perror("gpiod_line_request_input");
            goto cleanup;
        }
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    // Main loop
    while (running) {
        int any_object_detected = 0;
        for (i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(sensor_lines[i]);
            if (value < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }
            if (value == 0) { // Active-low sensor
                any_object_detected = 1;
                break;
            }
        }
        gpiod_line_set_value(led_line, any_object_detected);
        usleep(POLL_INTERVAL_US);
    }

cleanup:
    for (i = 0; i < 4; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

