#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define DEBOUNCE_DELAY 50000 // 50 ms in microseconds
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void log_event(const char *message) {
    syslog(LOG_USER, "%s", message);
}

void log_error(const char *message) {
    syslog(LOG_USER | LOG_ERR, "%s", message);
}

void append_to_log(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return;
    }

    if (flock(fileno(log_file), LOCK_EX) == -1) {
        log_error("Failed to lock log file");
        fclose(log_file);
        return;
    }

    if (fprintf(log_file, "%s\n", message) < 0) {
        log_error("Failed to write to log file");
    }

    if (fflush(log_file) == EOF) {
        log_error("Failed to flush log file");
    }

    flock(fileno(log_file), LOCK_UN);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int gpio_pins[NUM_SENSORS] = GPIO_PINS;
    int i;

    openlog("flame_monitor", LOG_PID, LOG_USER);
    log_event("Flame monitor started");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            log_error("Failed to get line for GPIO %d", gpio_pins[i]);
            terminate = 1;
            break;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            log_error("Failed to request input for GPIO %d", gpio_pins[i]);
            terminate = 1;
            break;
        }
    }

    if (terminate) {
        for (i = 0; i < NUM_SENSORS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                log_error("Failed to read GPIO %d", gpio_pins[i]);
                continue;
            }

            if (value == 0) {
                usleep(DEBOUNCE_DELAY);
                int new_value = gpiod_line_get_value(lines[i]);
                if (new_value < 0) {
                    log_error("Failed to read GPIO %d after debounce", gpio_pins[i]);
                    continue;
                }

                if (new_value == 0) {
                    char timestamp[30];
                    time_t now = time(NULL);
                    struct tm *tm_info = gmtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

                    char log_message[100];
                    snprintf(log_message, sizeof(log_message), "%s - Sensor ID: %d (GPIO %d) - Flame Detected",
                             timestamp, i + 1, gpio_pins[i]);
                    append_to_log(log_message);
                }
            }
        }

        sleep(1);
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

