    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
    printf("%s.%06ld: Sensor %d (Pin %s): %s\n", time_str, ts.tv_nsec / 1000, sensor_index, pin_names[sensor_index], is_touched ? "Touched" : "Released");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk bulk;
    struct gpiod_line *lines[NUM_PINS];
    int prev_states[NUM_PINS] = {0};

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            perror("gpiod_line_request_input");
            goto cleanup;
        }
    }

    gpiod_line_bulk_init_array(&bulk, lines, NUM_PINS);

    while (running) {
        if (gpiod_line_get_value_bulk(&bulk, prev_states) < 0) {
            perror("gpiod_line_get_value_bulk");
            goto cleanup;
        }

        for (int i = 0; i < NUM_PINS; i++) {
            int current_state = gpiod_line_get_value(lines[i]);
            if (current_state < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }

            if (current_state != prev_states[i]) {
                log_state_change(i, pin_numbers[i], current_state);
                prev_states[i] = current_state;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_FAILURE;
}
