#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define LUX_REG 0x04
#define PWM_PIN 18
#define PWM_FREQ 1000
#define LOG_FILE "grow_log.txt"

volatile sig_atomic_t running = 1;

