    running = 0;
}

void log_entry(FILE *log, int lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log, "%s, %d, %d, %d\n", timestamp, lux, brightness, error_code);
    fflush(log);
}

int read_lux(int i2c_fd) {
    uint8_t lux_data[2];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, LUX_REG, 2, lux_data) != 2) {
        perror("Failed to read lux data");
        return -1;
    }
    return (lux_data[0] << 8) | lux_data[1];
}

int map_lux_to_brightness(int lux) {
    if (lux < 100) return 100;
    if (lux < 500) return 75;
    if (lux < 1000) return 50;
    return 25;
}

