    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        fclose(log);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        fclose(log);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        close(i2c_fd);
        fclose(log);
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    gpioSetPWMrange(PWM_PIN, 100);

    while (running) {
        int lux = read_lux(i2c_fd);
        int brightness = map_lux_to_brightness(lux);
        gpioPWM(PWM_PIN, brightness);
        log_entry(log, lux, brightness, lux == -1 ? 1 : 0);
        sleep(1);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    close(i2c_fd);
    fclose(log);

    return EXIT_SUCCESS;
}

