#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define LED_PIN 17
#define SENSOR_PINS 8
#define SENSOR_PIN_OFFSET 2
#define DEBOUNCE_TIME 50000 // 50 ms in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *sensor_lines[SENSOR_PINS];
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_touch_event(int channel) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s – Channel %d Touched\n", timestamp, channel);
    fclose(log_file);
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < SENSOR_PINS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_PIN_OFFSET + i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get sensor line %d: %s\n", SENSOR_PIN_OFFSET + i, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_input(sensor_lines[i], "sensor") < 0) {
            fprintf(stderr, "Failed to request sensor line %d as input: %s\n", SENSOR_PIN_OFFSET + i, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_set_bias(sensor_lines[i], GPIOD_LINE_BIAS_PULL_DOWN) < 0) {
            fprintf(stderr, "Failed to set bias for sensor line %d: %s\n", SENSOR_PIN_OFFSET + i, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio() {
    gpiod_line_release(led_line);
    for (int i = 0; i < SENSOR_PINS; i++) {
        gpiod_line_release(sensor_lines[i]);
    }
    gpiod_chip_close(chip);
}

int main() {
    setup_gpio();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int last_state[SENSOR_PINS] = {0};
    struct timespec last_time[SENSOR_PINS] = {{0}};

    while (running) {
        for (int i = 0; i < SENSOR_PINS; i++) {
            int current_state = gpiod_line_get_value(sensor_lines[i]);
            if (current_state != last_state[i]) {
                struct timespec current_time;
                clock_gettime(CLOCK_MONOTONIC, &current_time);

                if (current_state == 1) {
                    if (timespec_subtract(&current_time, &last_time[i]) >= DEBOUNCE_TIME) {
                        log_touch_event(i + 1);
                        last_state[i] = current_state;
                        gpiod_line_set_value(led_line, 1);
                    }
                } else {
                    last_state[i] = current_state;
                }

                last_time[i] = current_time;
            }
        }

        int all_released = 1;
        for (int i = 0; i < SENSOR_PINS; i++) {
            if (last_state[i] == 1) {
                all_released = 0;
                break;
            }
        }

        if (all_released) {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(50000); // 50 ms
    }

    cleanup_gpio();
    return 0;
}

int timespec_subtract(struct timespec *result, struct timespec *x, struct timespec *y) {
    if (x->tv_nsec < y->tv_nsec) {
        int nsec = (y->tv_nsec - x->tv_nsec) / 1000000;
        y->tv_sec -= nsec + 1;
        y->tv_nsec += 1000000000L;
    }

    result->tv_sec = y->tv_sec - x->tv_sec;
    result->tv_nsec = y->tv_nsec - x->tv_nsec;

    return result->tv_sec < 0;
}

