#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define OPT3001_CONFIG_REG 0x01
#define OPT3001_RESULT_REG 0x00

#define CONFIG_VALUE 0xC400 // Continuous conversion mode, 100 ms conversion time

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
}

void sigint_handler(int sig) {
    fprintf(stderr, "Received SIGINT, cleaning up...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

uint16_t byte_swap(uint16_t value) {
    return ((value & 0xFF) << 8) | ((value >> 8) & 0xFF);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t config_value = byte_swap(CONFIG_VALUE);
    if (write(i2c_fd, &config_value, 2) != 2) {
        perror("Failed to write configuration to OPT3001");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t result;
        if (read(i2c_fd, &result, 2) != 2) {
            perror("Failed to read result from OPT3001");
            continue;
        }

        result = byte_swap(result);
        float lux = result * 0.01;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        printf("%s, %.2f\n", timestamp, lux);

        fflush(log_file);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

