        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    int ret;
    struct sigaction sa;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Setup signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    // Request line as input with pull-down
    ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line bias: %s\n", strerror(errno));
        release_resources();
        return EXIT_FAILURE;
    }

    int last_state = 0;
    while (running) {
        int current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO line value: %s\n", strerror(errno));
            release_resources();
            return EXIT_FAILURE;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                log_event("Touch Detected");
            } else {
                log_event("Touch Released");
            }
            last_state = current_state;
        }

        usleep(DEBOUNCE_INTERVAL_US);
    }

    release_resources();
    return EXIT_SUCCESS;
}

