#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x48
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_to_csv(const char *timestamp, float flow_rate, uint8_t status) {
    static FILE *file = NULL;
    if (!file) {
        file = fopen("cooling_log.csv", "a");
        if (!file) {
            perror("Failed to open CSV file");
            return;
        }
        fprintf(file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    fprintf(file, "%s,%.2f,%s\n", timestamp, flow_rate, status == 0 ? "VALID" : "INVALID");
    fflush(file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t command = 0x10; // Command to start flow measurement
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to send command to sensor");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    usleep(2000); // Wait at least 2 ms before the first read

    while (running) {
        uint8_t buffer[3];
        if (read(i2c_fd, buffer, 3) != 3) {
            perror("Failed to read from sensor");
            log_to_csv("ERROR", 0.0, 1);
            close(i2c_fd);
            i2c_fd = open(I2C_DEVICE, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to re-open I2C device");
                return EXIT_FAILURE;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                return EXIT_FAILURE;
            }
            continue;
        }

        uint16_t flow_value = (buffer[0] << 8) | buffer[1];
        uint8_t calculated_crc = calculate_crc8(buffer, 2);
        if (calculated_crc != buffer[2]) {
            fprintf(stderr, "CRC error\n");
            log_to_csv("ERROR", 0.0, 1);
            continue;
        }

        float flow_rate = flow_value * 0.01; // Convert to ml/min
        uint8_t status = (flow_rate >= MIN_FLOW_RATE && flow_rate <= MAX_FLOW_RATE) ? 0 : 1;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        log_to_csv(timestamp, flow_rate, status);

        sleep(1);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

