#define EVENT_FILE "flame_events.txt"

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *message) {
    FILE *file = fopen(EVENT_FILE, "a");
    if (!file) {
        perror("Failed to open event file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(stdout, "[%s] %s\n", timestamp, message);
    fprintf(file, "[%s] %s\n", timestamp, message);
    fclose(file);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Configure the line for input with edge detection
    ret = gpiod_line_request_falling_edge_events(line, "flame_sensor");
    if (ret < 0) {
        perror("Failed to request falling edge events");
        ret = EXIT_FAILURE;
        goto exit;
    }

    printf("Monitoring flame sensor on GPIO %d (BCM numbering)...\n", GPIO_LINE);

    while (running) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for line event");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            log_event("Flame detected!");
        }
    }

exit:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

