#define GPIO_CHIP "/dev/gpiochip4"
#define TOUCH_SENSOR_LINE 23
#define LED_LINE 24
#define LOG_FILE "touch_log.txt"
#define TIMEOUT_MS 1000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_sensor_line) {
        gpiod_line_release(touch_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_line_event event;
    struct timespec timeout;
    int ret;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request touch sensor line
    touch_sensor_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_LINE);
    if (!touch_sensor_line) {
        perror("Failed to get touch sensor line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(touch_sensor_line, "touch_sensor");
    if (ret < 0) {
        perror("Failed to request touch sensor line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request LED line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        timeout.tv_sec = TIMEOUT_MS / 1000;
        timeout.tv_nsec = (TIMEOUT_MS % 1000) * 1000000;

        ret = gpiod_line_event_wait(touch_sensor_line, &timeout);
        if (ret < 0) {
            perror("Failed to wait for line event");
            cleanup();
            return EXIT_FAILURE;
        } else if (ret == 0) {
            continue; // Timeout, no event
        }

        ret = gpiod_line_event_read(touch_sensor_line, &event);
        if (ret < 0) {
            perror("Failed to read line event");
            cleanup();
            return EXIT_FAILURE;
        }

        if (event.type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Toggle LED
            int current_state = gpiod_line_get_value(led_line);
            gpiod_line_set_value(led_line, !current_state);

            // Log event
            time_t now = time(NULL);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            fprintf(log_file, "%s: Touch detected, LED state: %d\n", timestamp, !current_state);
            fflush(log_file);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

