#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define POLL_INTERVAL_US 500000
#define BUZZER_DURATION_US 2000000
#define SLICE_DURATION_US 100000

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: %s\n", asctime(tm_info), message);
    fflush(log_file);
}

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct sigaction sa;
    int ret;

    // Open log file
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(sensor_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Log system start
    log_message("System started");

    // Main loop
    int last_state = gpiod_line_get_value(sensor_line);
    while (running) {
        int current_state = gpiod_line_get_value(sensor_line);
        if (current_state == 0 && last_state == 1) {
            // Flame detected
            log_message("FLAME DETECTED");
            for (int i = 0; i < BUZZER_DURATION_US / SLICE_DURATION_US; i++) {
                if (!running) break;
                gpiod_line_set_value(buzzer_line, 1);
                usleep(SLICE_DURATION_US);
                gpiod_line_set_value(buzzer_line, 0);
                usleep(SLICE_DURATION_US);
            }
        }
        last_state = current_state;
        for (int i = 0; i < POLL_INTERVAL_US / SLICE_DURATION_US; i++) {
            if (!running) break;
            usleep(SLICE_DURATION_US);
        }
    }

    // Log system stop
    log_message("System stopped");

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

