#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnet_log.txt"

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void sigterm_handler(int sig) {
    running = 0;
}

void log_state_change(FILE *log_file, int sensor_id, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state ? "Removed" : "Present");
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor1, *sensor2, *sensor3;
    int sensor1_state, sensor2_state, sensor3_state;
    int initial_read = 1;
    FILE *log_file;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for sensors
    sensor1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    sensor3 = gpiod_chip_get_line(chip, SENSOR3_PIN);

    if (!sensor1 || !sensor2 || !sensor3) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines as inputs with pull-up
    if (gpiod_line_request_input(sensor1, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2, "sensor2") < 0 ||
        gpiod_line_request_input(sensor3, "sensor3") < 0) {
        perror("Failed to request input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_bias(sensor1, GPIOD_LINE_BIAS_PULL_UP) < 0 ||
        gpiod_line_set_bias(sensor2, GPIOD_LINE_BIAS_PULL_UP) < 0 ||
        gpiod_line_set_bias(sensor3, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        perror("Failed to set pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        // Read sensor states
        sensor1_state = gpiod_line_get_value(sensor1);
        sensor2_state = gpiod_line_get_value(sensor2);
        sensor3_state = gpiod_line_get_value(sensor3);

        if (sensor1_state < 0 || sensor2_state < 0 || sensor3_state < 0) {
            perror("Failed to read sensor state");
            continue;
        }

        // Log initial state without generating a false transition
        if (initial_read) {
            log_state_change(log_file, 1, sensor1_state);
            log_state_change(log_file, 2, sensor2_state);
            log_state_change(log_file, 3, sensor3_state);
            initial_read = 0;
        } else {
            // Log state changes
            if (sensor1_state != gpiod_line_get_value(sensor1)) {
                log_state_change(log_file, 1, sensor1_state);
            }
            if (sensor2_state != gpiod_line_get_value(sensor2)) {
                log_state_change(log_file, 2, sensor2_state);
            }
            if (sensor3_state != gpiod_line_get_value(sensor3)) {
                log_state_change(log_file, 3, sensor3_state);
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean shutdown
    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

