#define HW_REV_REG 0x01
#define HR_DATA_REG 0x05
#define PART_ID_VAL 0x42
#define HW_REV_VAL 0x08
#define SAMPLES 5
#define CSV_FILE "heart_rate.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    uint8_t buffer[2];
    uint16_t raw_data[SAMPLES];
    uint16_t filtered_bpm;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Register signal handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    if ((csv_file = fopen(CSV_FILE, "a")) == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Check PART_ID and HW_REV
    if (i2c_smbus_read_byte_data(i2c_fd, PART_ID_REG) != PART_ID_VAL ||
        i2c_smbus_read_byte_data(i2c_fd, HW_REV_REG) != HW_REV_VAL) {
        fprintf(stderr, "Sensor not found or wrong type\n");
        fclose(csv_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        int retries = 0;
        int valid = 0;

        // Read raw data
        for (int i = 0; i < SAMPLES; i++) {
            while (retries < 3) {
                if (i2c_smbus_read_i2c_block_data(i2c_fd, HR_DATA_REG, 2, buffer) == 2) {
                    raw_data[i] = (buffer[0] << 8) | buffer[1];
                    valid = 1;
                    break;
                } else {
                    retries++;
                    perror("I2C read error, retrying...");
                    usleep(100000); // 100ms delay
                }
            }
            if (!valid) {
                fprintf(stderr, "Failed to read sensor data after 3 retries\n");
                break;
            }
        }

        if (valid) {
            // Calculate moving average
            uint32_t sum = 0;
            for (int i = 0; i < SAMPLES; i++) {
                sum += raw_data[i];
            }
            filtered_bpm = sum / SAMPLES;

            // Validate BPM
            if (filtered_bpm >= 30 && filtered_bpm <= 220) {
                // Get current time
                time(&now);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                // Write to CSV
                fprintf(csv_file, "%s,%u\n", timestamp, filtered_bpm);
                fflush(csv_file);
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    fclose(csv_file);
    close(i2c_fd);
    return 0;
}
