    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_set_bias");
        cleanup();
        exit(EXIT_FAILURE);
    }

    int last_state = gpiod_line_get_value(line);
    while (running) {
        int current_state = gpiod_line_get_value(line);
        if (last_state == 1 && current_state == 0) {
            // Flame detected
            printf("FLAME DETECTED\n");

            // Get current time
            time_t now = time(NULL);
            char *time_str = ctime(&now);
            time_str[strlen(time_str) - 1] = '\0'; // Remove newline

            // Write to log file
            fprintf(log_file, "%s: FLAME DETECTED\n", time_str);
            fflush(log_file);
        }
        last_state = current_state;
        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}

