#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/time.h>

#define SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define COUNTER_PINS {17, 18, 19, 20, 21, 22, 23, 24}
#define SENSOR_PIN_COUNT 8
#define COUNTER_PIN_COUNT 8
#define STABILIZATION_DELAY_MS 200
#define POLL_INTERVAL_MS 10
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk sensor_lines = GPIOD_LINE_BULK_INITIALIZER;
    struct gpiod_line_bulk counter_lines = GPIOD_LINE_BULK_INITIALIZER;
    int sensor_pins[SENSOR_PIN_COUNT] = SENSOR_PINS;
    int counter_pins[COUNTER_PIN_COUNT] = COUNTER_PINS;
    unsigned int counter = 0;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request sensor lines
    if (gpiod_chip_get_lines(chip, sensor_pins, SENSOR_PIN_COUNT, &sensor_lines) < 0) {
        fprintf(stderr, "Failed to get sensor lines: %s\n", strerror(errno));
        goto cleanup;
    }
    for (unsigned int i = 0; i < SENSOR_PIN_COUNT; i++) {
        if (gpiod_line_request_input(sensor_lines.lines[i], "touch_counter") < 0) {
            fprintf(stderr, "Failed to request input on sensor line %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    // Request counter lines
    if (gpiod_chip_get_lines(chip, counter_pins, COUNTER_PIN_COUNT, &counter_lines) < 0) {
        fprintf(stderr, "Failed to get counter lines: %s\n", strerror(errno));
        goto cleanup;
    }
    for (unsigned int i = 0; i < COUNTER_PIN_COUNT; i++) {
        if (gpiod_line_request_output(counter_lines.lines[i], "touch_counter", 0) < 0) {
            fprintf(stderr, "Failed to request output on counter line %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    // Stabilization delay
    usleep(STABILIZATION_DELAY_MS * 1000);

    while (running) {
        int sensor_values[SENSOR_PIN_COUNT];
        struct timespec ts;
        char timestamp[32];

        // Read sensor lines
        if (gpiod_line_get_value_bulk(&sensor_lines, sensor_values) < 0) {
            fprintf(stderr, "Failed to read sensor lines: %s\n", strerror(errno));
            continue;
        }

        // Get current time for logging
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts));

        // Check for rising edges
        for (unsigned int i = 0; i < SENSOR_PIN_COUNT; i++) {
            if (sensor_values[i]) {
                // Increment counter and wrap if necessary
                counter = (counter + 1) % 256;

                // Update counter lines
                unsigned int counter_bits[COUNTER_PIN_COUNT];
                for (unsigned int j = 0; j < COUNTER_PIN_COUNT; j++) {
                    counter_bits[j] = (counter >> j) & 1;
                }
                if (gpiod_line_set_value_bulk(&counter_lines, counter_bits) < 0) {
                    fprintf(stderr, "Failed to set counter lines: %s\n", strerror(errno));
                }

                // Log event
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "%s, Channel: %u, Counter: %u", timestamp, i + 1, counter);
                log_event(log_message);

                // Print to stdout
                printf("Touch on channel %u | Counter: %u\n", i + 1, counter);
            }
        }

        // Poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    // Reset counter lines
    unsigned int reset_bits[COUNTER_PIN_COUNT] = {0};
    gpiod_line_set_value_bulk(&counter_lines, reset_bits);

    // Release resources
    gpiod_line_release_bulk(&sensor_lines);
    gpiod_line_release_bulk(&counter_lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

