    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2);
    sensor3 = gpiod_chip_get_line(chip, SENSOR3);
    sensor4 = gpiod_chip_get_line(chip, SENSOR4);

    if (!sensor1 || !sensor2 || !sensor3 || !sensor4) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return EXIT_FAILURE;
