    if (gpiod_line_request_input(sensor1, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2, "sensor2") < 0 ||
        gpiod_line_request_input(sensor3, "sensor3") < 0 ||
        gpiod_line_request_input(sensor4, "sensor4") < 0) {
        fprintf(stderr, "Failed to request input on GPIO lines\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("tracking_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    while (running) {
        int s1 = gpiod_line_get_value(sensor1);
        int s2 = gpiod_line_get_value(sensor2);
        int s3 = gpiod_line_get_value(sensor3);
        int s4 = gpiod_line_get_value(sensor4);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "Failed to read GPIO values\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4);
        fflush(log_file);

        usleep(POLL_INTERVAL_US);
    }

    return EXIT_SUCCESS;
}
