    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Failed to get GPIO17 line");
        cleanup();
        return EXIT_FAILURE;
    }
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Failed to get GPIO18 line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines as inputs with pull-up
    ret = gpiod_line_request_input(sensor1_line, "tilt_sensor1");
    if (ret < 0) {
