            perror("Failed to read GPIO18");
            continue;
        }

        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);

        if (state1 == 0 && last_state1 == 1) {
            if (timespec_subtract(&current_time, &last_time1) >= DEBOUNCE_US) {
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));
                fprintf(log_file, "%s, Sensor 1 tilted\n", timestamp);
                fflush(log_file);
                last_time1 = current_time;
            }
        }
        if (state2 == 0 && last_state2 == 1) {
            if (timespec_subtract(&current_time, &last_time2) >= DEBOUNCE_US) {
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));
                fprintf(log_file, "%s, Sensor 2 tilted\n", timestamp);
                fflush(log_file);
                last_time2 = current_time;
            }
        }

        last_state1 = state1;
        last_state2 = state2;

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, struct timespec *x) {
    if (x->tv_nsec < result->tv_nsec) {
        int nsec = (result->tv_nsec - x->tv_nsec) / 1000000;
        result->tv_nsec -= (nsec * 1000000);
        result->tv_sec -= (x->tv_sec + 1);
        return result->tv_sec - x->tv_sec;
    } else {
        int nsec = (x->tv_nsec - result->tv_nsec) / 1000000;
        result->tv_nsec = x->tv_nsec - result->tv_nsec + (nsec * 1000000);
        result->tv_sec = x->tv_sec - result->tv_sec;
        return result->tv_sec - x->tv_sec;
    }
}

