#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define PEAK_DURATION_MS 100

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Sample the microphone pin
        int level = gpioRead(MIC_PIN);
        if (level == PI_HIGH) {
            // Detected a sound peak
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                continue;
            }
            printf("Peak detected at %ld.%03ld ms\n", ts.tv_sec * 1000 + ts.tv_nsec / 1000000, ts.tv_nsec % 1000000 / 1000);

            // Turn on the LED for 100 ms
            gpioWrite(LED_PIN, PI_HIGH);
            gpioDelay(PEAK_DURATION_MS * 1000);
            gpioWrite(LED_PIN, PI_LOW);
        }

        // Wait for the next sample period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

