            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                continue;
            }
            printf("Peak detected at %ld.%03ld ms\n", ts.tv_sec * 1000 + ts.tv_nsec / 1000000, ts.tv_nsec % 1000000 / 1000);

            // Turn on the LED for 100 ms
            gpioWrite(LED_PIN, PI_HIGH);
            gpioDelay(PEAK_DURATION_MS * 1000);
            gpioWrite(LED_PIN, PI_LOW);
        }

        // Wait for the next sample period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}
