        ret = EXIT_FAILURE;
        goto release_right_line;
    }

    ret = gpiod_line_request_input(center_line, "ir_sensor_center");
    if (ret < 0) {
        perror("Failed to request center sensor line as input");
        ret = EXIT_FAILURE;
        goto release_left_line;
    }

    ret = gpiod_line_request_input(right_line, "ir_sensor_right");
    if (ret < 0) {
        perror("Failed to request right sensor line as input");
        ret = EXIT_FAILURE;
        goto release_center_line;
    }

    // Set lines to active-low
    ret = gpiod_line_set_active_low(left_line, 1);
    if (ret < 0) {
        perror("Failed to set left sensor line to active-low");
        ret = EXIT_FAILURE;
        goto release_right_line;
    }

    ret = gpiod_line_set_active_low(center_line, 1);
    if (ret < 0) {
        perror("Failed to set center sensor line to active-low");
        ret = EXIT_FAILURE;
        goto release_right_line;
    }

    ret = gpiod_line_set_active_low(right_line, 1);
    if (ret < 0) {
        perror("Failed to set right sensor line to active-low");
        ret = EXIT_FAILURE;
        goto release_right_line;
    }

    // Main loop
    while (running) {
        int left_state = gpiod_line_get_value(left_line);
        int center_state = gpiod_line_get_value(center_line);
        int right_state = gpiod_line_get_value(right_line);

        if (left_state < 0 || center_state < 0 || right_state < 0) {
