            ret = EXIT_FAILURE;
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        usleep(POLL_INTERVAL_US);
    }

    // Clean up
release_right_line:
    gpiod_line_release(right_line);
release_center_line:
    gpiod_line_release(center_line);
release_left_line:
    gpiod_line_release(left_line);
close_chip:
    gpiod_chip_close(chip);

