#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS_PATH "/dev/i2c-1"
#define SI1175_I2C_ADDRESS 0x5A
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint8_t als_vis_data0, als_vis_data1;
    uint16_t als_vis_value;

    // Set up signal handler for Ctrl+C
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    i2c_fd = open(I2C_BUS_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read the LSB of the ALS data
        if (read(i2c_fd, &als_vis_data0, 1) != 1) {
            perror("Failed to read ALS_VIS_DATA0");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Read the MSB of the ALS data
        if (read(i2c_fd, &als_vis_data1, 1) != 1) {
            perror("Failed to read ALS_VIS_DATA1");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Combine LSB and MSB into a single 16-bit value
        als_vis_value = (als_vis_data1 << 8) | als_vis_data0;

        // Log the raw sensor reading
        printf("ALS Raw Value: %u\n", als_vis_value);

        // Wait for 100 ms
        usleep(100000);
    }

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

