#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define POLL_INTERVAL_US 200000
#define NUM_CHANNELS 8

struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_CHANNELS];
volatile sig_atomic_t running = 1;

void cleanup() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int offsets[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};
    int values[NUM_CHANNELS] = {0};

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_input(lines[i], "touch_poll") < 0) {
            perror("gpiod_line_request_input");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            perror("clock_gettime");
            cleanup();
            exit(EXIT_FAILURE);
        }

        // Read line values
        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                perror("gpiod_line_get_value");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }

        // Print the result
        printf("[%ld.%03lds] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               ts.tv_sec, ts.tv_nsec / 1000000,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    return 0;
}

