        int g = (green * i) / INTERPOLATION_STEPS;
        int b = (blue * i) / INTERPOLATION_STEPS;
        set_pwm(red_line, r);
        set_pwm(green_line, g);
        set_pwm(blue_line, b);
        usleep((TRANSITION_INTERVAL * 1000000) / INTERPOLATION_STEPS);
    }
}

