        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        close(fd);
        cleanup();
        return EXIT_FAILURE;
    }
    close(fd);

    srand(seed);

    while (running) {
        int red = rand() % (PWM_RANGE + 1);
        int green = rand() % (PWM_RANGE + 1);
        int blue = rand() % (PWM_RANGE + 1);

        fade_to_color(red, green, blue);
    }

    cleanup();
    return EXIT_SUCCESS;
