#include <linux/i2c-dev.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_PERS 0x0C
#define TCS34725_CONFIG 0x0D
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define LED_GPIO 17
#define RED_THRESHOLD 200

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    int ret;

    // Open I2C bus
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request GPIO line for LED
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure LED line as output
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Power on the sensor and enable RGBC
    uint8_t enable = TCS34725_COMMAND_BIT | TCS34725_ENABLE | 0x03;
    if (write(i2c_fd, &enable, 1) != 1) {
        perror("Failed to write to I2C");
        goto cleanup;
    }

    // Set integration time to approximately 154 ms
    uint8_t atime = TCS34725_COMMAND_BIT | TCS34725_ATIME | 0xF6;
    if (write(i2c_fd, &atime, 1) != 1) {
        perror("Failed to write to I2C");
        goto cleanup;
    }

    // Set persistence register
    uint8_t pers = TCS34725_COMMAND_BIT | TCS34725_PERS | 0x00;
    if (write(i2c_fd, &pers, 1) != 1) {
        perror("Failed to write to I2C");
        goto cleanup;
    }

    // Set configuration register
    uint8_t config = TCS34725_COMMAND_BIT | TCS34725_CONFIG | 0x00;
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write to I2C");
        goto cleanup;
    }

    // Set control register
    uint8_t control = TCS34725_COMMAND_BIT | TCS34725_CONTROL | 0x02;
    if (write(i2c_fd, &control, 1) != 1) {
        perror("Failed to write to I2C");
        goto cleanup;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t data[8];
        uint16_t clear, red, green, blue;

        // Read sensor data
        uint8_t command = TCS34725_COMMAND_BIT | TCS34725_CDATAL;
        if (write(i2c_fd, &command, 1) != 1) {
            perror("Failed to write to I2C");
            goto cleanup;
        }

        if (read(i2c_fd, data, 8) != 8) {
            perror("Failed to read from I2C");
            goto cleanup;
        }

        clear = (data[1] << 8) | data[0];
        red = (data[3] << 8) | data[2];
        green = (data[5] << 8) | data[4];
        blue = (data[7] << 8) | data[6];

        printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

        // Control LED based on red value
        if (red > RED_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 200 ms
        usleep(200000);
    }

cleanup:
    // Power down the sensor
    enable = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    if (write(i2c_fd, &enable, 1) != 1) {
        perror("Failed to write to I2C");
    }

    // Release resources
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

