#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <math.h>

#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define LED_COUNT 10
#define GPIO_PIN 18
#define PWM_BASE 0x20C00000
#define PWM_LEN 0x24
#define PWM_PAGE_SIZE 4096
#define PWM_CLK_DIV 0x1000000
#define PWM_RANGE 1024

volatile unsigned int *pwm_reg;
int i2c_fd, pwm_fd;
int running = 1;

void cleanup() {
    if (i2c_fd >= 0) close(i2c_fd);
    if (pwm_fd >= 0) {
        pwm_reg[PWM_CTL] = 0;
        munmap((void *)pwm_reg, PWM_LEN);
        close(pwm_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

void setup_i2c() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(EXIT_FAILURE);
    }
}

void setup_pwm() {
    if ((pwm_fd = open("/dev/mem", O_RDWR | O_SYNC)) < 0) {
        perror("Failed to open /dev/mem");
        exit(EXIT_FAILURE);
    }
    pwm_reg = (volatile unsigned int *)mmap(NULL, PWM_LEN, PROT_READ | PROT_WRITE, MAP_SHARED, pwm_fd, PWM_BASE);
    if (pwm_reg == MAP_FAILED) {
        perror("Failed to map PWM registers");
        exit(EXIT_FAILURE);
    }
    pwm_reg[PWM_CLK_DIV] = PWM_CLK_DIV;
    pwm_reg[PWM_RNG1] = PWM_RANGE;
    pwm_reg[PWM_CTL] = (1 << 18) | (1 << 12); // Enable PWM1 and PWM0
}

unsigned short read_bh1750() {
    unsigned char cmd[] = {BH1750_CONTINUOUS_HIGH_RES_MODE};
    if (write(i2c_fd, cmd, 1) != 1) {
        perror("Failed to send command to BH1750");
        return 0;
    }
    usleep(180000); // Wait for measurement
    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return 0;
    }
    return (data[0] << 8) | data[1];
}

unsigned int map_lux_to_brightness(unsigned short lux) {
    return (unsigned int)(log10(lux + 1) * 255);
}

void set_led_brightness(unsigned int brightness) {
    for (int i = 0; i < LED_COUNT; i++) {
        pwm_reg[PWM_DAT1] = brightness;
    }
}

int main() {
    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_i2c();
    setup_pwm();

    while (running) {
        unsigned short lux = read_bh1750();
        if (lux == 0) continue; // Retry on error
        unsigned int brightness = map_lux_to_brightness(lux);
        set_led_brightness(brightness);
        usleep(100000); // 100 ms delay
    }

    return 0;
}

