#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR1 0x23
#define BH1750_ADDR2 0x5C
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define SPI_DEVICE "/dev/spidev0.0"
#define APA102_DATA_PIN 10
#define APA102_CLK_PIN 11
#define NUM_SENSORS 3
#define READ_DELAY_US 180000
#define FADE_DURATION_US 500000
#define LOOP_DELAY_US 100000

static int i2c_fd[NUM_SENSORS] = {-1, -1, -1};
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clk_line = NULL;

void cleanup() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fd[i] != -1) {
            close(i2c_fd[i]);
            i2c_fd[i] = -1;
        }
    }
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (data_line) {
        gpiod_line_release(data_line);
        data_line = NULL;
    }
    if (clk_line) {
        gpiod_line_release(clk_line);
        clk_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

int init_i2c(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }
    return fd;
}

int init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }
    uint32_t speed = 8000000;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed");
        close(fd);
        return -1;
    }
    return fd;
}

int init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    data_line = gpiod_chip_get_line(gpio_chip, APA102_DATA_PIN);
    if (!data_line) {
        perror("Failed to get data line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    clk_line = gpiod_chip_get_line(gpio_chip, APA102_CLK_PIN);
    if (!clk_line) {
        perror("Failed to get clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_output(data_line, "apa102_data", 0) < 0) {
        perror("Failed to request data line");
        gpiod_line_release(data_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_output(clk_line, "apa102_clk", 0) < 0) {
        perror("Failed to request clock line");
        gpiod_line_release(data_line);
        gpiod_line_release(clk_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    return 0;
}

void send_spi(uint8_t *data, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = 8000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to send SPI data");
    }
}

void set_brightness(uint8_t brightness) {
    uint8_t header[] = {0x00, 0x00, 0x00, 0x00};
    uint8_t footer[] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t data[4 * 32];
    for (int i = 0; i < 32; i++) {
        data[i * 4] = 0xE0 | brightness;
        data[i * 4 + 1] = 0x00;
        data[i * 4 + 2] = 0x00;
        data[i * 4 + 3] = 0x00;
    }
    send_spi(header, sizeof(header));
    send_spi(data, sizeof(data));
    send_spi(footer, sizeof(footer));
}

uint16_t read_bh1750(int fd) {
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to send command to BH1750");
        return 0;
    }
    usleep(READ_DELAY_US);
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from BH1750");
        return 0;
    }
    return (buffer[0] << 8) | buffer[1];
}

int main() {
    signal(SIGINT, sigint_handler);

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    i2c_fd[0] = init_i2c(BH1750_ADDR1);
    i2c_fd[1] = init_i2c(BH1750_ADDR2);
    spi_fd = init_spi();
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    uint8_t current_brightness = 0;
    while (1) {
        uint16_t total_light = 0;
        int valid_sensors = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fd[i] != -1) {
                uint16_t light = read_bh1750(i2c_fd[i]);
                if (light > 0) {
                    total_light += light;
                    valid_sensors++;
                }
            }
        }
        if (valid_sensors > 0) {
            uint16_t average_light = total_light / valid_sensors;
            uint8_t target_brightness = average_light / 100; // Example scaling
            for (int step = 0; step <= FADE_DURATION_US; step += 1000) {
                uint8_t new_brightness = current_brightness + (target_brightness - current_brightness) * step / FADE_DURATION_US;
                set_brightness(new_brightness);
                usleep(1000);
            }
            current_brightness = target_brightness;
        }
        usleep(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

