#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <sys/poll.h>
#include <sys/time.h>
#include <gpiod.h>

#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BUFFER_SIZE 60
#define GPIO_LED 17
#define MIN_FREQ 0.5
#define MAX_FREQ 5.0

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int read_lux(int i2c_fd) {
    uint8_t data[2];
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to send command to BH1750");
        return -1;
    }
    usleep(180000); // Wait for measurement to complete
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

void blink_led(float frequency) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = (1.0 / (2 * frequency)) * 1e9;

    while (running) {
        gpiod_line_set_value(led_line, 1);
        nanosleep(&ts, NULL);
        gpiod_line_set_value(led_line, 0);
        nanosleep(&ts, NULL);
    }
}

int main() {
    int lux_buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    int total_lux = 0;
    float average_lux = 0.0;
    float frequency = MIN_FREQ;

    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request GPIO line
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Start blinking LED in a separate thread
    pthread_t blink_thread;
    if (pthread_create(&blink_thread, NULL, (void *(*)(void *))blink_led, &frequency) != 0) {
        perror("Failed to create blink thread");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        int lux = read_lux(i2c_fd);
        if (lux >= 0) {
            // Update buffer
            total_lux -= lux_buffer[buffer_index];
            lux_buffer[buffer_index] = lux;
            total_lux += lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average lux
            average_lux = (float)total_lux / BUFFER_SIZE;

            // Update LED frequency
            frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (average_lux / 1000.0);
            if (frequency > MAX_FREQ) {
                frequency = MAX_FREQ;
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pthread_join(blink_thread, NULL);
    cleanup();

    return 0;
}

