#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define DIGIT_5 0b01101101

struct gpiod_chip *chip;
struct gpiod_line *data_line;
struct gpiod_line *clock_line;
struct gpiod_line *latch_line;

void cleanup() {
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

void shift_out(uint8_t data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        gpiod_line_set_value(data_line, bit);
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
    }
    gpiod_line_set_value(latch_line, 1);
    usleep(1);
    gpiod_line_set_value(latch_line, 0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "shift_register", 0) < 0 ||
        gpiod_line_request_output(clock_line, "shift_register", 0) < 0 ||
        gpiod_line_request_output(latch_line, "shift_register", 0) < 0) {
        perror("Failed to request GPIO lines as outputs");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        shift_out(DIGIT_5);
        usleep(500000); // 500 ms on
        shift_out(0);    // Turn off
        usleep(500000); // 500 ms off
    }

    cleanup();
    return EXIT_SUCCESS;
}

