#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_GPIO 17
#define BUTTON_GPIO 18
#define TIMEOUT 1000000000 // 1 second in nanoseconds

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handler for graceful termination
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request LED line as output, initially low
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line as input with pull-up and event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(button_line, "blink_button");
    if (ret < 0) {
        perror("Failed to request button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_debounce(button_line, 1000000); // 1 ms debounce
    if (ret < 0) {
        perror("Failed to set debounce on button line");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_event(button_line, "blink_button");
    if (ret < 0) {
        perror("Failed to request event on button line");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Blink LED with 1 second on, 1 second off
    while (running) {
        // Turn LED on
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Failed to set LED value");
            break;
        }
        sleep(1);

        // Check for button event
        ret = gpiod_line_event_wait(button_line, TIMEOUT);
        if (ret < 0) {
            perror("Failed to wait for button event");
            break;
        } else if (ret > 0) {
            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                perror("Failed to read button event");
                break;
            }
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed, stopping blinking.\n");
                break;
            }
        }

        // Turn LED off
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Failed to set LED value");
            break;
        }
        sleep(1);
    }

    // Turn LED off before exiting
    gpiod_line_set_value(led_line, 0);

    // Release resources
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

