#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <time.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000  // 10 ms
#define PWM_STEP_NS 1000000     // 1 ms
#define COLOR_CHANGE_INTERVAL_US 100000  // 100 ms

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    running = 0;
}

void pwm(struct gpiod_line *line, int duty_cycle) {
    struct timespec ts = {0, PWM_STEP_NS};
    int on_time = (duty_cycle * PWM_PERIOD_NS) / 100;
    int off_time = PWM_PERIOD_NS - on_time;

    for (int i = 0; i < on_time / PWM_STEP_NS; i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Failed to set line value");
            cleanup();
            exit(EXIT_FAILURE);
        }
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }

    for (int i = 0; i < off_time / PWM_STEP_NS; i++) {
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Failed to set line value");
            cleanup();
            exit(EXIT_FAILURE);
        }
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }
}

int main() {
    srand(time(NULL));

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    if (!red_line) {
        perror("Failed to get red line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("Failed to request red line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line) {
        perror("Failed to get green line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("Failed to request green line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line) {
        perror("Failed to get blue line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("Failed to request blue line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        int red_duty = rand() % 101;
        int green_duty = rand() % 101;
        int blue_duty = rand() % 101;

        for (int i = 0; i < 10; i++) {
            pwm(red_line, red_duty);
            pwm(green_line, green_duty);
            pwm(blue_line, blue_duty);
        }

        usleep(COLOR_CHANGE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

