#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303DLHC_ADDR 0x19
#define ACCEL_REG_OUT_X_L_A 0x28
#define ACCEL_REG_OUT_Y_L_A 0x2A
#define ACCEL_REG_OUT_Z_L_A 0x2C
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define PULSE_DURATION 50000 // 50 ms in microseconds

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int i2c_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    float threshold = DEFAULT_THRESHOLD;
    char *log_filename = "impact_log.txt";
    FILE *log_file = NULL;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        }
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(gpio_line, "impact_trigger", 0) < 0) {
        perror("Failed to request GPIO line as output");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(log_filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t buffer[6];
        int16_t x, y, z;
        float g_force;

        // Read accelerometer data
        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read accelerometer data");
            continue;
        }

        x = (buffer[1] << 8) | buffer[0];
        y = (buffer[3] << 8) | buffer[2];
        z = (buffer[5] << 8) | buffer[4];

        // Compute total G-force magnitude
        g_force = sqrt((x * x + y * y + z * z) / 1024.0);

        // Log data
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%s: X=%d, Y=%d, Z=%d, G-force=%.2f\n",
                asctime(tm_info), x, y, z, g_force);
        fflush(log_file);

        // Check if G-force exceeds threshold
        if (g_force > threshold) {
            // Trigger impact interrupt
            gpiod_line_set_value(gpio_line, 1);
            usleep(PULSE_DURATION);
            gpiod_line_set_value(gpio_line, 0);
        }

        // Sleep for 100 ms (10 Hz)
        usleep(100000);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

