#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define FXOS8700CQ_ADDR 0x1E
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define XYZ_DATA_CFG_REG 0x0E
#define STATUS_REG 0x00
#define OUT_X_MSB_REG 0x01
#define OUT_Y_MSB_REG 0x03
#define OUT_Z_MSB_REG 0x05

#define IMPACT_THRESHOLD 1.5

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, FXOS8700CQ_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG) != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I value does not match expected value\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1 = 0x00;
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, ctrl_reg1) < 0) {
        perror("Failed to write to CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t xyz_data_cfg = 0x00; // ±2g range
    if (i2c_smbus_write_byte_data(i2c_fd, XYZ_DATA_CFG_REG, xyz_data_cfg) < 0) {
        perror("Failed to write to XYZ_DATA_CFG_REG");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 = 0x01; // Active mode, 200Hz ODR
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, ctrl_reg1) < 0) {
        perror("Failed to write to CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t status;
        if (i2c_smbus_read_byte_data(i2c_fd, STATUS_REG) < 0) {
            perror("Failed to read STATUS_REG");
            continue;
        }

        if (status & 0x08) { // Data ready
            int16_t x = i2c_smbus_read_word_data(i2c_fd, OUT_X_MSB_REG);
            int16_t y = i2c_smbus_read_word_data(i2c_fd, OUT_Y_MSB_REG);
            int16_t z = i2c_smbus_read_word_data(i2c_fd, OUT_Z_MSB_REG);

            if (x < 0) x = ~x + 1;
            if (y < 0) y = ~y + 1;
            if (z < 0) z = ~z + 1;

            double magnitude = sqrt(x * x + y * y + z * z) / 4096.0;

            if (magnitude > IMPACT_THRESHOLD) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
                fflush(log_file);
            }
        }

        usleep(50000); // 50 ms interval
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

