code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x68
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0xD4
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define THRESHOLD 50
#define PERIOD_US 50000

static int i2c_fd = -1;
static FILE *log_file = NULL;
static int running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_byte(int reg, char data) {
    char buf[2] = {reg, data};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, char *buf, int len) {
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("read");
        return -1;
    }
    return 0;
}

int read_who_am_i() {
    char buf;
    if (i2c_read_bytes(WHO_AM_I_REG, &buf, 1) < 0) {
        return -1;
    }
    return buf;
}

int init_gyro() {
    if (i2c_write_byte(CTRL_REG1, 0x0F) < 0) { // Normal power mode, all axes enabled, 100 Hz
        return -1;
    }
    if (i2c_write_byte(CTRL_REG4, 0x00) < 0) { // 245 dps full scale
        return -1;
    }
    return 0;
}

int read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2c_read_bytes(OUT_X_L | 0x80, buf, 6) < 0) {
        return -1;
    }
    *x = (buf[1] << 8) | buf[0];
    *y = (buf[3] << 8) | buf[2];
    *z = (buf[5] << 8) | buf[4];
    return 0;
}

void log_data(int16_t x, int16_t y, int16_t z) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
    fprintf(log_file, "%s.%03ld, %d, %d, %d\n", timestamp, tv.tv_usec / 1000, x, y, z);
    fflush(log_file);
}

int main() {
    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (read_who_am_i() != WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor not found\n");
        return EXIT_FAILURE;
    }

    if (init_gyro() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    int16_t offsets[3] = {0};
    for (int i = 0; i < SAMPLES; i++) {
        int16_t x, y, z;
        if (read_gyro(&x, &y, &z) < 0) {
            return EXIT_FAILURE;
        }
        offsets[0] += x;
        offsets[1] += y;
        offsets[2] += z;
        usleep(PERIOD_US);
    }
    offsets[0] /= SAMPLES;
    offsets[1] /= SAMPLES;
    offsets[2] /= SAMPLES;

    while (running) {
        int16_t x, y, z;
        if (read_gyro(&x, &y, &z) < 0) {
            return EXIT_FAILURE;
        }
        x -= offsets[0];
        y -= offsets[1];
        z -= offsets[2];
        log_data(x, y, z);

        if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
            fprintf(log_file, "Alert: Axis exceeded threshold\n");
            fflush(log_file);
            fprintf(stderr, "Warning: Axis exceeded threshold\n");
        }

        usleep(PERIOD_US);
    }

    return EXIT_SUCCESS;
}

