#include <errno.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_DEVID_REG 0x00
#define ADXL345_DEVID_VAL 0xE5
#define ADXL345_BW_RATE_REG 0x2C
#define ADXL345_BW_RATE_100HZ 0x0A
#define ADXL345_DATA_FORMAT_REG 0x31
#define ADXL345_DATA_FORMAT_FULL_RES 0x08
#define ADXL345_DATA_FORMAT_RANGE_2G 0x00
#define ADXL345_DATAX0_REG 0x32

#define LED_GPIO 17

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    FILE *log_file;
    struct timespec ts;
    uint8_t devid;
    int16_t x, y, z;
    float gx, gy, gz;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read device ID
    if (i2c_smbus_read_byte_data(i2c_fd, ADXL345_DEVID_REG) != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Incorrect device ID\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_BW_RATE_REG, ADXL345_BW_RATE_100HZ) < 0) {
        perror("Failed to set bandwidth rate");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_DATA_FORMAT_REG, ADXL345_DATA_FORMAT_FULL_RES | ADXL345_DATA_FORMAT_RANGE_2G) < 0) {
        perror("Failed to set data format");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request line for output
    if (gpiod_line_request_output(led_line, "adxl345_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Read acceleration data
        if (i2c_smbus_read_i2c_block_data(i2c_fd, ADXL345_DATAX0_REG, 6, (uint8_t *)&x) != 6) {
            perror("Failed to read acceleration data");
            continue;
        }

        // Convert to g units
        gx = x / 256.0;
        gy = y / 256.0;
        gz = z / 256.0;

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }

        // Log data
        fprintf(log_file, "%ld.%09ld,%0.3f,%0.3f,%0.3f\n", ts.tv_sec, ts.tv_nsec, gx, gy, gz);
        fflush(log_file);

        // Check for high acceleration
        if (fabs(gx) > 2.0 || fabs(gy) > 2.0 || fabs(gz) > 2.0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

