#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303DLHC_ACCEL_ADDR 0x19
#define LSM303DLHC_MAG_ADDR 0x1E

#define ACCEL_REG_CTRL_REG1_A 0x20
#define ACCEL_REG_OUT_X_L_A 0x28
#define MAG_REG_CRA_REG_M 0x00
#define MAG_REG_MR_REG_M 0x02
#define MAG_REG_OUT_X_H_M 0x03

#define SAMPLE_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_accel_fd, i2c_mag_fd;
    FILE *log_file;
    struct sigaction sa;
    struct tm *tm_info;
    char timestamp[20];
    int16_t accel_data[3], mag_data[3];
    float heading, accel_g[3], mag_g[3];
    float declination = -0.01; // Example declination value, adjust as needed

    // Install signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    if ((i2c_accel_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus for accelerometer");
        return EXIT_FAILURE;
    }
    if ((i2c_mag_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus for magnetometer");
        close(i2c_accel_fd);
        return EXIT_FAILURE;
    }

    // Set I2C addresses
    if (ioctl(i2c_accel_fd, I2C_SLAVE, LSM303DLHC_ACCEL_ADDR) < 0) {
        perror("Failed to set I2C address for accelerometer");
        close(i2c_accel_fd);
        close(i2c_mag_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_mag_fd, I2C_SLAVE, LSM303DLHC_MAG_ADDR) < 0) {
        perror("Failed to set I2C address for magnetometer");
        close(i2c_accel_fd);
        close(i2c_mag_fd);
        return EXIT_FAILURE;
    }

    // Initialize accelerometer
    uint8_t accel_ctrl_reg1_a = 0x27; // Normal power mode, 100 Hz output data rate
    if (write(i2c_accel_fd, &accel_ctrl_reg1_a, 1) != 1) {
        perror("Failed to write to accelerometer control register");
        close(i2c_accel_fd);
        close(i2c_mag_fd);
        return EXIT_FAILURE;
    }

    // Initialize magnetometer
    uint8_t mag_cra_reg_m = 0x10; // Continuous conversion mode, 15 Hz data rate
    uint8_t mag_mr_reg_m = 0x00; // Default settings
    if (write(i2c_mag_fd, &mag_cra_reg_m, 1) != 1 || write(i2c_mag_fd, &mag_mr_reg_m, 1) != 1) {
        perror("Failed to write to magnetometer control registers");
        close(i2c_accel_fd);
        close(i2c_mag_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_accel_fd);
        close(i2c_mag_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Heading,Ax,Ay,Az,Mx,My,Mz\n");
    }

    while (running) {
        // Read accelerometer data
        uint8_t accel_regs[6] = {ACCEL_REG_OUT_X_L_A | 0x80, 0, 0, 0, 0, 0};
        if (write(i2c_accel_fd, accel_regs, 1) != 1 || read(i2c_accel_fd, accel_regs + 1, 5) != 5) {
            perror("Failed to read from accelerometer");
            break;
        }
        accel_data[0] = (accel_regs[1] | (accel_regs[2] << 8));
        accel_data[1] = (accel_regs[3] | (accel_regs[4] << 8));
        accel_data[2] = (accel_regs[5] | (accel_regs[6] << 8));

        // Read magnetometer data
        uint8_t mag_regs[6] = {MAG_REG_OUT_X_H_M, 0, 0, 0, 0, 0};
        if (write(i2c_mag_fd, mag_regs, 1) != 1 || read(i2c_mag_fd, mag_regs + 1, 5) != 5) {
            perror("Failed to read from magnetometer");
            break;
        }
        mag_data[0] = (mag_regs[1] << 8) | mag_regs[2];
        mag_data[1] = (mag_regs[3] << 8) | mag_regs[4];
        mag_data[2] = (mag_regs[5] << 8) | mag_regs[6];

        // Convert to g and gauss
        accel_g[0] = accel_data[0] / 256.0;
        accel_g[1] = accel_data[1] / 256.0;
        accel_g[2] = accel_data[2] / 256.0;
        mag_g[0] = mag_data[0] / 1100.0;
        mag_g[1] = mag_data[1] / 1100.0;
        mag_g[2] = mag_data[2] / 1100.0;

        // Compute tilt-compensated heading
        float pitch = asin(-accel_g[1]);
        float roll = atan2(accel_g[0], accel_g[2]);
        float heading_x = mag_g[0] * cos(roll) + mag_g[1] * sin(roll) * sin(pitch) + mag_g[2] * sin(roll) * cos(pitch);
        float heading_y = mag_g[1] * cos(pitch) - mag_g[2] * sin(pitch);
        heading = atan2(heading_y, heading_x) * 180.0 / M_PI + declination;
        if (heading < 0) heading += 360.0;
        if (heading > 360) heading -= 360.0;

        // Get timestamp
        time_t now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log data
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, accel_g[0], accel_g[1], accel_g[2], mag_g[0], mag_g[1], mag_g[2]);
        fflush(log_file);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    // Close resources
    fclose(log_file);
    close(i2c_accel_fd);
    close(i2c_mag_fd);

    return EXIT_SUCCESS;
}

