        perror("Failed to open log file");
        close(i2c_accel_fd);
        close(i2c_mag_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Heading,Ax,Ay,Az,Mx,My,Mz\n");
    }

    while (running) {
        // Read accelerometer data
        uint8_t accel_regs[6] = {ACCEL_REG_OUT_X_L_A | 0x80, 0, 0, 0, 0, 0};
        if (write(i2c_accel_fd, accel_regs, 1) != 1 || read(i2c_accel_fd, accel_regs + 1, 5) != 5) {
            perror("Failed to read from accelerometer");
            break;
        }
        accel_data[0] = (accel_regs[1] | (accel_regs[2] << 8));
        accel_data[1] = (accel_regs[3] | (accel_regs[4] << 8));
        accel_data[2] = (accel_regs[5] | (accel_regs[6] << 8));

        // Read magnetometer data
        uint8_t mag_regs[6] = {MAG_REG_OUT_X_H_M, 0, 0, 0, 0, 0};
        if (write(i2c_mag_fd, mag_regs, 1) != 1 || read(i2c_mag_fd, mag_regs + 1, 5) != 5) {
            perror("Failed to read from magnetometer");
            break;
        }
        mag_data[0] = (mag_regs[1] << 8) | mag_regs[2];
        mag_data[1] = (mag_regs[3] << 8) | mag_regs[4];
        mag_data[2] = (mag_regs[5] << 8) | mag_regs[6];

        // Convert to g and gauss
        accel_g[0] = accel_data[0] / 256.0;
        accel_g[1] = accel_data[1] / 256.0;
        accel_g[2] = accel_data[2] / 256.0;
        mag_g[0] = mag_data[0] / 1100.0;
        mag_g[1] = mag_data[1] / 1100.0;
        mag_g[2] = mag_data[2] / 1100.0;

        // Compute tilt-compensated heading
        float pitch = asin(-accel_g[1]);
        float roll = atan2(accel_g[0], accel_g[2]);
        float heading_x = mag_g[0] * cos(roll) + mag_g[1] * sin(roll) * sin(pitch) + mag_g[2] * sin(roll) * cos(pitch);
        float heading_y = mag_g[1] * cos(pitch) - mag_g[2] * sin(pitch);
        heading = atan2(heading_y, heading_x) * 180.0 / M_PI + declination;
        if (heading < 0) heading += 360.0;
        if (heading > 360) heading -= 360.0;

        // Get timestamp
        time_t now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log data
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, accel_g[0], accel_g[1], accel_g[2], mag_g[0], mag_g[1], mag_g[2]);
        fflush(log_file);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_US);
    }

    // Close resources
    fclose(log_file);
    close(i2c_accel_fd);
    close(i2c_mag_fd);

    return EXIT_SUCCESS;
}
