    if (i2c_smbus_write_byte(i2c_fd, VL6180X_REG_SYSRANGE_START) < 0) {
        perror("Failed to start range measurement");
        return -1;
    }
    usleep(10000); // Wait for measurement to complete

    int distance = i2c_smbus_read_byte_data(i2c_fd, VL6180X_REG_RESULT_RANGE_VAL);
    if (distance < 0) {
        perror("Failed to read range value");
        return -1;
    }
    return distance;
}

