            fprintf(stderr, "Sensor initialization failed, retrying...\n");
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        while (running) {
            int distance = read_distance(i2c_fd);
            if (distance < 0) {
                fprintf(stderr, "Failed to read distance, retrying...\n");
                break;
            }

            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            fprintf(log_file, "%s: Distance = %d mm\n", timestamp, distance);
