            if (distance < 100) {
                fprintf(log_file, "%s: DOOR_OPEN\n", timestamp);
            } else {
                fprintf(log_file, "%s: DOOR_CLOSED\n", timestamp);
            }
            fflush(log_file);

            usleep(SAMPLE_INTERVAL_US);
        }
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

