#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x1A
#define SENSOR2_ADDR 0x1B
#define SAMPLE_INTERVAL_US 10000
#define SAMPLE_SIZE 2

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct timespec ts;
    int16_t sensor1_sample, sensor2_sample;
    int tdoa;
    FILE *log_file = fopen("audio_log.dat", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 1");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 2");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (running) {
        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
            perror("Failed to set I2C address for sensor 1");
            continue;
        }

        if (read(i2c_fd, &sensor1_sample, SAMPLE_SIZE) != SAMPLE_SIZE) {
            perror("Failed to read from sensor 1");
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
            perror("Failed to set I2C address for sensor 2");
            continue;
        }

        if (read(i2c_fd, &sensor2_sample, SAMPLE_SIZE) != SAMPLE_SIZE) {
            perror("Failed to read from sensor 2");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            continue;
        }

        tdoa = sensor1_sample - sensor2_sample;

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_sample, sensor2_sample, tdoa);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_US);
    }

    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

