    double gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timespec ts;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen("imu_data.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Write header to CSV file
    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Initialize SPI transfer structures
    xfer[0].tx_buf = (unsigned long)&command;
    xfer[0].rx_buf = 0;
    xfer[0].len = sizeof(command);
    xfer[0].speed_hz = SPI_SPEED;
    xfer[0].bits_per_word = SPI_BITS_PER_WORD;
    xfer[0].delay_usecs = STALL_TIME_US;

    xfer[1].tx_buf = 0;
    xfer[1].rx_buf = (unsigned long)&data;
    xfer[1].len = sizeof(data);
    xfer[1].speed_hz = SPI_SPEED;
    xfer[1].bits_per_word = SPI_BITS_PER_WORD;
    xfer[1].delay_usecs = 0;

    while (running) {
        // Read gyro and accelerometer data
        command = (REG_GYRO_X << 8);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("Failed to read gyro_x");
            continue;
        }
        gyro_x = (int16_t)data * GYRO_SENSITIVITY;

        command = (REG_GYRO_Y << 8);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("Failed to read gyro_y");
            continue;
        }
        gyro_y = (int16_t)data * GYRO_SENSITIVITY;

        command = (REG_GYRO_Z << 8);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("Failed to read gyro_z");
            continue;
        }
        gyro_z = (int16_t)data * GYRO_SENSITIVITY;

        command = (REG_ACCEL_X << 8);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("Failed to read accel_x");
            continue;
        }
        accel_x = (int16_t)data * ACCEL_SENSITIVITY;

        command = (REG_ACCEL_Y << 8);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("Failed to read accel_y");
            continue;
        }
        accel_y = (int16_t)data * ACCEL_SENSITIVITY;

        command = (REG_ACCEL_Z << 8);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("Failed to read accel_z");
            continue;
        }
        accel_z = (int16_t)data * ACCEL_SENSITIVITY;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

        // Write data to CSV file
        fprintf(csv_file, "%.6f,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Sleep for the remaining time to achieve the desired sample interval
        struct timespec sleep_time = {0, (SAMPLE_INTERVAL_MS - STALL_TIME_US) * 1000};
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    fclose(csv_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}
