#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

#define RETRY_COUNT 3

int i2c_fd = -1;

void close_i2c_fd() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    close_i2c_fd();
    exit(EXIT_SUCCESS);
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_msg msgs[2];
    uint8_t reg_addr = reg;

    msgs[0].addr = MPU6886_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg_addr;

    msgs[1].addr = MPU6886_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = len;
    msgs[1].buf = buf;

    struct i2c_rdwr_ioctl_data pkg;
    pkg.nmsgs = 2;
    pkg.msgs = msgs;

