        retries--;
        if (retries > 0) {
            perror("I2C read failed, retrying...");
            usleep(10000); // 10 ms delay before retry
        }
    }
    perror("I2C read failed after retries");
    return -1;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

