    if (gpiod_line_request_output(led_line, "adxl345_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        led_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static int init_log() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

static int init_sensor() {
    uint8_t devid;
    if (i2c_read_bytes(ADXL345_DEVID, &devid, 1) < 0) {
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }
    if (i2c_write_byte(ADXL345_POWER_CTL, ADXL345_MEASURE) < 0) {
        return -1;
    }
    if (i2c_write_byte(ADXL345_BW_RATE, 0x0A) < 0) { // 100 Hz
        return -1;
    }
    if (i2c_write_byte(ADXL345_DATA_FORMAT, 0x08) < 0) { // Full resolution, ±2g
        return -1;
    }
    return 0;
}

static void log_event(double magnitude, int16_t x, int16_t y, int16_t z) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld: Magnitude = %.2f g, X = %d, Y = %d, Z = %d\n",
            (long)tv.tv_sec, (long)tv.tv_usec, magnitude, x, y, z);
    fflush(log_file);
}

static void handle_impact(double magnitude, int16_t x, int16_t y, int16_t z) {
    gpiod_line_set_value(led_line, 1);
    usleep(500000);
    gpiod_line_set_value(led_line, 0);
    log_event(magnitude, x, y, z);
}

int main() {
    if (atexit(cleanup) != 0) {
        perror("Failed to set cleanup function");
        return EXIT_FAILURE;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0 || init_gpio() < 0 || init_log() < 0 || init_sensor() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data[6];
        if (i2c_read_bytes(ADXL345_DATAX0, data, 6) < 0) {
            continue;
        }
        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];
        double magnitude = sqrt(x * x + y * y + z * z) / SCALE_FACTOR;
        if (magnitude > THRESHOLD) {
            handle_impact(magnitude, x, y, z);
        }
        usleep(POLL_INTERVAL_US);
    }

    return EXIT_SUCCESS;
}
