                (buffer[6] << 8) | buffer[7], (buffer[8] << 8) | buffer[9], (buffer[10] << 8) | buffer[11]);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(SAMPLE_RATE);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
