#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0x3A
#define OUT_X_MSB_REG 0x01
#define LED_GPIO 17
#define THRESHOLD 2048 // 2.0 g in ±2 g range
#define LOG_FILE "impact_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, log_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    struct timespec ts;
    uint8_t who_am_i, data[6];
    int16_t x, y, z;
    float magnitude;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    if (!(chip = gpiod_chip_open_by_number(0))) {
        perror("Failed to open GPIO chip");
        close(log_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get GPIO line for LED
    if (!(led_line = gpiod_chip_get_line(chip, LED_GPIO))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(log_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request line for output
    if (gpiod_line_request_output(led_line, "accel_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(log_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor identity
    if (read(i2c_fd, &who_am_i, 1) != 1 || who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor identity verification failed\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(log_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Read acceleration data
        if (write(i2c_fd, &OUT_X_MSB_REG, 1) != 1 || read(i2c_fd, data, 6) != 6) {
            perror("Failed to read acceleration data");
            continue;
        }

        x = (data[0] << 8) | data[1];
        y = (data[2] << 8) | data[3];
        z = (data[4] << 8) | data[5];

        // Calculate magnitude
        magnitude = sqrt(x * x + y * y + z * z);

        // Check if magnitude exceeds threshold
        if (magnitude > THRESHOLD) {
            // Turn on LED
            gpiod_line_set_value(led_line, 1);

            // Get current time
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("Failed to get current time");
            } else {
                // Log the reading with timestamp
                dprintf(log_fd, "%ld.%09ld: X=%d, Y=%d, Z=%d, Magnitude=%.2f\n",
                        ts.tv_sec, ts.tv_nsec, x, y, z, magnitude);
            }

            // Turn off LED after 500 ms
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_US);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(log_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

