    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    if (!(chip = gpiod_chip_open_by_label("gpiochip0"))) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request GPIO line
    if (!(line = gpiod_chip_get_line(chip, ADXL345_INT1_PIN))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure GPIO line as input
    if (gpiod_line_request_input(line, "adxl345_int1") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

