    if (!(log_file = fopen("freefall_log.csv", "w"))) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    // Verify device ID
    if (i2c_smbus_read_byte_data(i2c_fd, ADXL345_DEVID) != ADXL345_DEVID) {
        fprintf(stderr, "Device ID verification failed\n");
        fclose(log_file);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Place sensor in standby mode
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_POWER_CTL, 0x00) < 0) {
        perror("Failed to set power control register");
        fclose(log_file);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set data format
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        perror("Failed to set data format register");
        fclose(log_file);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

