    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_INT_ENABLE, 0x08) < 0) {
        perror("Failed to set interrupt enable register");
        fclose(log_file);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set bandwidth rate
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_BW_RATE, 0x0A) < 0) {
        perror("Failed to set bandwidth rate register");
        fclose(log_file);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Wake up sensor
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        perror("Failed to wake up sensor");
        fclose(log_file);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Poll for interrupt
    while (running) {
        if (gpiod_line_get_value(line) == 1) {
