    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_INT_ENABLE, 0x00) < 0) {
        perror("Failed to disable interrupts");
    }

    // Close resources
    fclose(log_file);
    gpiod_chip_close(chip);
    close(i2c_fd);

