#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <math.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define CTRL1_XL_REG 0x10
#define CTRL2_G_REG 0x11
#define OUTX_L_XL_REG 0x28
#define OUTX_L_G_REG 0x22

#define ACCEL_SCALE 0.061 // ±2g range
#define GYRO_SCALE 8.75   // ±250dps range

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define DETECTION_WINDOW 1.0

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} State;

State state = IDLE;
time_t fall_start_time = 0;

void cleanup(int sig) {
    printf("Exiting...\n");
    exit(0);
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("I2C write byte failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) * ACCEL_SCALE;
}

void log_data(FILE *fp, time_t timestamp, int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz) {
    fprintf(fp, "%ld,%d,%d,%d,%d,%d,%d,%d\n", timestamp, ax, ay, az, gx, gy, gz);
}

int main() {
    int i2c_fd;
    FILE *log_file;
    uint8_t who_am_i;
    uint8_t buf[6];

    setup_signals();

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    if (i2c_read(i2c_fd, WHO_AM_I_REG, &who_am_i, 1) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (who_am_i != 0x6A) {
        fprintf(stderr, "Sensor not found\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, CTRL1_XL_REG, 0x60) < 0 || // 104 Hz, ±2g
        i2c_write(i2c_fd, CTRL2_G_REG, 0x60)) {    // 104 Hz, ±250dps
        close(i2c_fd);
        return 1;
    }

    if ((log_file = fopen("motion_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        if (i2c_read(i2c_fd, OUTX_L_XL_REG, buf, 6) < 0) {
            break;
        }

        int16_t ax = (buf[1] << 8) | buf[0];
        int16_t ay = (buf[3] << 8) | buf[2];
        int16_t az = (buf[5] << 8) | buf[4];
        int16_t gx = (buf[7] << 8) | buf[6];
        int16_t gy = (buf[9] << 8) | buf[8];
        int16_t gz = (buf[11] << 8) | buf[10];

        float magnitude = calculate_magnitude(ax, ay, az);

        log_data(log_file, now, ax, ay, az, gx, gy, gz);

        switch (state) {
            case IDLE:
                if (magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    fall_start_time = now;
                }
                break;
            case FREEFALL:
                if (magnitude > IMPACT_THRESHOLD) {
                    state = IMPACT;
                    printf("Impact detected!\n");
                } else if (difftime(now, fall_start_time) > DETECTION_WINDOW) {
                    state = IDLE;
                }
                break;
            case IMPACT:
                state = IDLE;
                break;
        }

        usleep(10000); // 10 ms delay
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

