#include <libgpiod.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE0_PIN 8
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x40
#define GYRO_XOUT_H_REG 0x04
#define GYRO_XOUT_L_REG 0x05
#define GYRO_YOUT_H_REG 0x06
#define GYRO_YOUT_L_REG 0x07
#define GYRO_ZOUT_H_REG 0x08
#define GYRO_ZOUT_L_REG 0x09
#define SAMPLE_INTERVAL_US 10000
#define SCALE_FACTOR 0.0305

static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ce0_line = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (ce0_line) {
