#define WHO_AM_I_VAL 0xD4
#define CTRL_REG1 0x20
#define CTRL_REG1_VAL 0x0F
#define OUT_X_L 0x28
#define OUT_Y_L 0x2A
#define OUT_Z_L 0x2C
#define SAMPLE_RATE_US 10000

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;

static void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

static int i2c_write_reg(int reg, int val) {
    unsigned char buf[2] = {reg, val};
    int retries = 3;
    while (retries--) {
        if (write(i2c_fd, buf, 2) == 2) {
            return 0;
        }
        perror("i2c_write_reg");
        usleep(100000); // 100ms delay before retry
    }
    return -1;
}

static int i2c_read_reg(int reg, unsigned char *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("i2c_read_reg write");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("i2c_read_reg read");
        return -1;
    }
    return 0;
}

static int init_gyro() {
    unsigned char who_am_i;
    if (i2c_read_reg(WHO_AM_I_REG, &who_am_i, 1) != 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    if (i2c_write_reg(CTRL_REG1, CTRL_REG1_VAL) != 0) {
        return -1;
    }
    return 0;
}

static void read_and_log_gyro() {
    unsigned char buf[6];
    if (i2c_read_reg(OUT_X_L, buf, 6) != 0) {
        return;
    }
    int16_t x = (buf[1] << 8) | buf[0];
    int16_t y = (buf[3] << 8) | buf[2];
    int16_t z = (buf[5] << 8) | buf[4];
    double x_dps = x / 114.285;
    double y_dps = y / 114.285;
    double z_dps = z / 114.285;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gyro() != 0) {
        fprintf(stderr, "Failed to initialize gyroscope\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    while (1) {
        read_and_log_gyro();
        usleep(SAMPLE_RATE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

