#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s – %s\n", timestamp, message);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!exit_flag) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_event("Error reading GPIO pin");
            continue;
        }

        const char *flame_status = (level == PI_LOW) ? "YES" : "NO";
        const char *console_message = (level == PI_LOW) ? "FLAME DETECTED!" : NULL;

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Flame detected: %s", flame_status);
        log_event(log_message);

        if (console_message) {
            printf("%s\n", console_message);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

