#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define CONVEYOR_LOG "conveyor_log.txt"
#define GPIO_CHIP "gpiochip0"
#define HALL_SENSOR_1 17
#define HALL_SENSOR_2 27
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *hall_sensor_1 = NULL;
    struct gpiod_line *hall_sensor_2 = NULL;
    FILE *log_file = NULL;
    struct timespec ts;
    int ret;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request lines with internal pull-ups
    hall_sensor_1 = gpiod_chip_get_line(chip, HALL_SENSOR_1);
    hall_sensor_2 = gpiod_chip_get_line(chip, HALL_SENSOR_2);
    if (!hall_sensor_1 || !hall_sensor_2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    ret = gpiod_line_request_input(hall_sensor_1, "hall_sensor_1");
    if (ret < 0) {
        perror("gpiod_line_request_input hall_sensor_1");
        goto cleanup;
    }

    ret = gpiod_line_request_input(hall_sensor_2, "hall_sensor_2");
    if (ret < 0) {
        perror("gpiod_line_request_input hall_sensor_2");
        goto cleanup;
    }

    ret = gpiod_line_set_bias(hall_sensor_1, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_set_bias hall_sensor_1");
        goto cleanup;
    }

    ret = gpiod_line_set_bias(hall_sensor_2, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_set_bias hall_sensor_2");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(CONVEYOR_LOG, "a");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    // Main loop
    while (running) {
        int sensor_1_state = gpiod_line_get_value(hall_sensor_1);
        int sensor_2_state = gpiod_line_get_value(hall_sensor_2);
        if (sensor_1_state < 0 || sensor_2_state < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%03ld: Sensor 1: %d, Sensor 2: %d\n",
                ts.tv_sec, ts.tv_nsec / 1000000, sensor_1_state, sensor_2_state);
        fflush(log_file);

        if (sensor_1_state == 1 && sensor_2_state == 1) {
            printf("Halt conveyor\n");
        }

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (hall_sensor_1) {
        gpiod_line_release(hall_sensor_1);
    }
    if (hall_sensor_2) {
        gpiod_line_release(hall_sensor_2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

