#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01

#define MMA8452Q_WHO_AM_I 0x2A
#define MMA8452Q_DATA_RATE_100HZ 0x0A

#define TILT_THRESHOLD 45.0

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_block");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("i2c_read_block");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("ioctl");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read_block(i2c_fd, WHO_AM_I_REG, &who_am_i, 1) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (who_am_i != MMA8452Q_WHO_AM_I) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X\n", who_am_i);
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1;
    if (i2c_read_block(i2c_fd, CTRL_REG1, &ctrl_reg1, 1) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, CTRL_REG1, ctrl_reg1 & ~0x01) < 0) { // Standby mode
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, CTRL_REG1, (ctrl_reg1 & ~0x1E) | MMA8452Q_DATA_RATE_100HZ) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, CTRL_REG1, ctrl_reg1 | 0x01) < 0) { // Active mode
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data[6];
        if (i2c_read_block(i2c_fd, OUT_X_MSB, data, 6) < 0) {
            continue;
        }

        int16_t x = ((data[0] << 8) | data[1]) >> 4;
        int16_t y = ((data[2] << 8) | data[3]) >> 4;
        int16_t z = ((data[4] << 8) | data[5]) >> 4;

        double tilt = atan2(sqrt(x * x + y * y), z) * 180.0 / M_PI;
        if (fabs(tilt) > TILT_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
            fflush(log_file);
        }

        usleep(10000); // 10 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

