#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define RESET_REGISTER 0x1F
#define RESET_VALUE 0x52
#define POWER_CONTROL_REGISTER 0x2D
#define STATUS_REGISTER 0x2C
#define PARTID_REGISTER 0x00
#define PARTID_VALUE 0xE5
#define DATA_REGISTER 0x08
#define DATA_LENGTH 6
#define LOG_FILE "vibration_log.txt"
#define RETRY_COUNT 3

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        return -1;
    }

    return 0;
}

void spi_close(int fd) {
    close(fd);
}

uint8_t read_register(int fd, uint8_t reg) {
    uint8_t tx[2] = {reg | 0x80, 0x00};
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return 0xFF; // Error value
    }
    return rx[1];
}

void write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg, value};
    if (spi_transfer(fd, tx, NULL, 2) < 0) {
        // Handle error
    }
}

int reset_sensor(int fd) {
    write_register(fd, RESET_REGISTER, RESET_VALUE);
    usleep(1000);
    write_register(fd, POWER_CONTROL_REGISTER, 0x00);
    while (!(read_register(fd, STATUS_REGISTER) & 0x02)) {
        usleep(100);
    }
    write_register(fd, POWER_CONTROL_REGISTER, 0x08);
    return 0;
}

int verify_sensor(int fd) {
    uint8_t partid = read_register(fd, PARTID_REGISTER);
    return partid == PARTID_VALUE;
}

int read_acceleration(int fd, int16_t *data) {
    uint8_t tx[DATA_LENGTH] = {DATA_REGISTER | 0xC0, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[DATA_LENGTH] = {0};
    if (spi_transfer(fd, tx, rx, DATA_LENGTH) < 0) {
        return -1;
    }
    data[0] = (rx[1] << 8) | rx[2];
    data[1] = (rx[3] << 8) | rx[4];
    data[2] = (rx[5] << 8) | rx[6];
    return 0;
}

