            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            data[0], data[1], data[2]);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        spi_close(spi_fd);
        return EXIT_FAILURE;
    }

    if (reset_sensor(spi_fd) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        fclose(log_file);
        spi_close(spi_fd);
        return EXIT_FAILURE;
    }

    if (!verify_sensor(spi_fd)) {
        fprintf(stderr, "Sensor verification failed\n");
        fclose(log_file);
        spi_close(spi_fd);
        return EXIT_FAILURE;
    }

    int16_t data[3];
    while (running) {
        if (read_acceleration(spi_fd, data) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }
        log_data(log_file, data);
        fflush(log_file);
        usleep(100000);
    }

    fclose(log_file);
    spi_close(spi_fd);
    return EXIT_SUCCESS;
}

