#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USEC 0

#define ADIS16362_GYRO_SCALE 0.05
#define ADIS16362_ACCEL_SCALE 0.0025

#define GYRO_X_REG 0x04
#define GYRO_Y_REG 0x06
#define GYRO_Z_REG 0x08
#define ACCEL_X_REG 0x0A
#define ACCEL_Y_REG 0x0C
#define ACCEL_Z_REG 0x0E

#define REG_READ_MASK 0x80
#define DUMMY_BYTE 0x00

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    FILE *log_file;
    struct sigaction sa;
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    struct spi_ioc_transfer xfer[2];
    uint8_t tx[2] = {0, DUMMY_BYTE};
    uint8_t rx[2] = {0};
    int ret;

    // Setup signal handler for graceful shutdown
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip and line for CS
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(cs_line, "spi_cs", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    while (running) {
        struct timespec ts;
