    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure the line as input
    ret = gpiod_line_request_input(line, "ir_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

