        // Check if the sensor reports an obstacle
        if (value == 0) {
            log_message("Self-parking sequence started");
            // Simulate the self-parking routine
            sleep(5); // Simulated routine duration
            log_message("Self-parking sequence completed");
        }

        // Wait for the next poll interval
        sleep(POLL_INTERVAL);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

