    if (!sensor1) {
        perror("gpiod_chip_get_line (sensor1)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    sensor2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2) {
        perror("gpiod_chip_get_line (sensor2)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure lines as input
    ret = gpiod_line_request_input(sensor1, "ir_sensor1");
    if (ret < 0) {
        perror("gpiod_line_request_input (sensor1)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(sensor2, "ir_sensor2");
    if (ret < 0) {
        perror("gpiod_line_request_input (sensor2)");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        int sensor1_value, sensor2_value;
        struct timespec ts;

        // Read sensor values
        sensor1_value = gpiod_line_get_value(sensor1);
        if (sensor1_value < 0) {
            perror("gpiod_line_get_value (sensor1)");
            break;
        }

        sensor2_value = gpiod_line_get_value(sensor2);
        if (sensor2_value < 0) {
            perror("gpiod_line_get_value (sensor2)");
            break;
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Log detection status
        printf("[%ld.%09ld] Sensor 1: %s, Sensor 2: %s\n",
               ts.tv_sec, ts.tv_nsec,
               sensor1_value ? "Path clear" : "Obstacle detected",
               sensor2_value ? "Path clear" : "Obstacle detected");

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_US);
    }

    // Release resources
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_chip_close(chip);

    return 0;
}
