#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USEC 0

#define GYRO_SCALE_FACTOR 0.02

#define GYRO_XOUT_H 0x28
#define GYRO_XOUT_L 0x29
#define GYRO_YOUT_H 0x2A
#define GYRO_YOUT_L 0x2B
#define GYRO_ZOUT_H 0x2C
#define GYRO_ZOUT_L 0x2D

#define READ_REG(addr) ((addr) | 0x80)

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = SPI_DELAY_USEC,
    };
    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_gyro_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = {READ_REG(reg), 0};
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    *value = (rx[0] << 8) | rx[1];
    return 0;
}

int main() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t xout, yout, zout;
        if (read_gyro_register(spi_fd, GYRO_XOUT_H, &xout) < 0 ||
            read_gyro_register(spi_fd, GYRO_YOUT_H, &yout) < 0 ||
            read_gyro_register(spi_fd, GYRO_ZOUT_H, &zout) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            break;
        }

        double x_rate = (int16_t)xout * GYRO_SCALE_FACTOR;
        double y_rate = (int16_t)yout * GYRO_SCALE_FACTOR;
        double z_rate = (int16_t)zout * GYRO_SCALE_FACTOR;

        printf("X Rate: %.2f deg/sec, Y Rate: %.2f deg/sec, Z Rate: %.2f deg/sec\n", x_rate, y_rate, z_rate);

        usleep(100000);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

