#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_PATH "/dev/i2c-1"
#define LSM6DSR_I2C_ADDRESS 0x6A
#define LSM6DSR_WHO_AM_I_REG 0x0F
#define LSM6DSR_WHO_AM_I_VALUE 0x6A
#define LSM6DSR_CTRL1_XL_REG 0x10
#define LSM6DSR_CTRL2_G_REG 0x11
#define LSM6DSR_OUTX_L_XL_REG 0x28
#define LSM6DSR_OUTX_L_G_REG 0x22

#define LSM6DSR_CTRL1_XL_VALUE 0x82 // 104 Hz, ±2g
#define LSM6DSR_CTRL2_G_VALUE 0x82  // 104 Hz, ±245 dps

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint8_t who_am_i;
    uint8_t buffer[12];

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM6DSR_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Check WHO_AM_I register
    if (i2c_smbus_read_byte_data(i2c_fd, LSM6DSR_WHO_AM_I_REG) != LSM6DSR_WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure accelerometer and gyroscope
    if (i2c_smbus_write_byte_data(i2c_fd, LSM6DSR_CTRL1_XL_REG, LSM6DSR_CTRL1_XL_VALUE) < 0) {
        perror("Failed to write CTRL1_XL register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte_data(i2c_fd, LSM6DSR_CTRL2_G_REG, LSM6DSR_CTRL2_G_VALUE) < 0) {
        perror("Failed to write CTRL2_G register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read accelerometer and gyroscope data
        if (i2c_smbus_read_i2c_block_data(i2c_fd, LSM6DSR_OUTX_L_XL_REG, 12, buffer) != 12) {
            perror("Failed to read I2C data");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Convert raw data to signed 16-bit values
        int16_t ax = (buffer[1] << 8) | buffer[0];
        int16_t ay = (buffer[3] << 8) | buffer[2];
        int16_t az = (buffer[5] << 8) | buffer[4];
        int16_t gx = (buffer[7] << 8) | buffer[6];
        int16_t gy = (buffer[9] << 8) | buffer[8];
        int16_t gz = (buffer[11] << 8) | buffer[10];

        // Print the values
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n", ax, ay, az, gx, gy, gz);

        // Sleep for 100 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;
        nanosleep(&ts, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

