code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define FXOS8700_ADDR 0x1E
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_OUT_X_MSB 0x01
#define FXOS8700_OUT_Y_MSB 0x03
#define FXOS8700_OUT_Z_MSB 0x05
#define FXOS8700_M_OUT_X_MSB 0x33
#define FXOS8700_M_OUT_Y_MSB 0x35
#define FXOS8700_M_OUT_Z_MSB 0x37

#define I2C_RETRIES 3

int i2c_fd = -1;
volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int retries = I2C_RETRIES;
    while (retries--) {
        if (write(fd, buf, 2) == 2) {
            return 0;
        }
        perror("i2c_write_byte");
        if (errno != EIO) {
            return -1;
        }
        usleep(1000);
    }
    return -1;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        return -1;
    }
    int retries = I2C_RETRIES;
    while (retries--) {
        if (read(fd, buf, len) == len) {
            return 0;
        }
        perror("i2c_read_block");
        if (errno != EIO) {
            return -1;
        }
        usleep(1000);
    }
    return -1;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, FXOS8700_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read_block(i2c_fd, FXOS8700_WHO_AM_I, &who_am_i, 1) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "FXOS8700 not found, expected 0x%02X, got 0x%02X\n", FXOS8700_WHO_AM_I_VAL, who_am_i);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, FXOS8700_CTRL_REG1, 0x01) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data[12];
        if (i2c_read_block(i2c_fd, FXOS8700_OUT_X_MSB, data, 12) < 0) {
            continue;
        }

        int16_t accel_x = ((int16_t)data[0] << 6) | ((int16_t)data[1] >> 2);
        int16_t accel_y = ((int16_t)data[2] << 6) | ((int16_t)data[3] >> 2);
        int16_t accel_z = ((int16_t)data[4] << 6) | ((int16_t)data[5] >> 2);

        int16_t mag_x = ((int16_t)data[6] << 8) | data[7];
        int16_t mag_y = ((int16_t)data[8] << 8) | data[9];
        int16_t mag_z = ((int16_t)data[10] << 8) | data[11];

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Mag: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

        usleep(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

