    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        return -1;
    }
    int retries = I2C_RETRIES;
    while (retries--) {
        if (read(fd, buf, len) == len) {
            return 0;
        }
        perror("i2c_read_block");
        if (errno != EIO) {
            return -1;
        }
        usleep(1000);
    }
    return -1;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, FXOS8700_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read_block(i2c_fd, FXOS8700_WHO_AM_I, &who_am_i, 1) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "FXOS8700 not found, expected 0x%02X, got 0x%02X\n", FXOS8700_WHO_AM_I_VAL, who_am_i);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, FXOS8700_CTRL_REG1, 0x01) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data[12];
        if (i2c_read_block(i2c_fd, FXOS8700_OUT_X_MSB, data, 12) < 0) {
            continue;
        }

        int16_t accel_x = ((int16_t)data[0] << 6) | ((int16_t)data[1] >> 2);
        int16_t accel_y = ((int16_t)data[2] << 6) | ((int16_t)data[3] >> 2);
        int16_t accel_z = ((int16_t)data[4] << 6) | ((int16_t)data[5] >> 2);

        int16_t mag_x = ((int16_t)data[6] << 8) | data[7];
        int16_t mag_y = ((int16_t)data[8] << 8) | data[9];
        int16_t mag_z = ((int16_t)data[10] << 8) | data[11];

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Mag: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

        usleep(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}
```

