#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_DEVID 0xE5
#define ADXL345_BW_RATE_100HZ 0x0A
#define ADXL345_POWER_CTL_MEASURE 0x08
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double roll = atan2(y, z) * 180.0 / M_PI;
    double pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;
    return fmax(fabs(roll), fabs(pitch));
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    FILE *log_file;
    struct tm *tm_info;
    char timestamp[80];
    int16_t x, y, z;
    uint8_t buffer[6];
    double tilt;

    // Set up signal handler for Ctrl+C
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check device ID
    uint8_t devid;
    if (i2c_smbus_read_byte_data(i2c_fd, ADXL345_REG_DEVID) != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 device ID mismatch\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_BW_RATE, ADXL345_BW_RATE_100HZ) < 0) {
        perror("Failed to set ADXL345 bandwidth rate");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_MEASURE) < 0) {
        perror("Failed to enable ADXL345 measurement mode");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read acceleration data
        if (i2c_smbus_read_i2c_block_data(i2c_fd, ADXL345_REG_DATAX0, 6, buffer) != 6) {
            perror("Failed to read ADXL345 data");
            break;
        }

        x = (int16_t)((buffer[1] << 8) | buffer[0]);
        y = (int16_t)((buffer[3] << 8) | buffer[2]);
        z = (int16_t)((buffer[5] << 8) | buffer[4]);

        // Calculate tilt angle
        tilt = calculate_tilt(x, y, z);

        // Check if tilt exceeds threshold
        if (tilt > TILT_THRESHOLD) {
            // Get current timestamp
            time_t now = time(NULL);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            // Log tilt event
            fprintf(log_file, "%s - Tilt: %.2f degrees\n", timestamp, tilt);
            fflush(log_file);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

