#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define WINDOW_DURATION 5000 // 5 seconds in ms
#define SAMPLE_INTERVAL 1 // 1 ms in ms

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    long threshold = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Request line for input
    ret = gpiod_line_request_input(line, "sound_sensor");
    if (ret < 0) {
        perror("Error requesting GPIO line as input");
        goto cleanup;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up SIGINT handler");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up SIGTERM handler");
        goto cleanup;
    }

    while (running) {
        struct timespec start, end;
        long high_count = 0;

        if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
            perror("Error getting start time");
            goto cleanup;
        }

        while (running) {
            if (gpiod_line_get_value(line) == 1) {
                high_count++;
            }

            if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
                perror("Error getting current time");
                goto cleanup;
            }

            long elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
            if (elapsed >= WINDOW_DURATION) {
                break;
            }

            usleep(SAMPLE_INTERVAL * 1000);
        }

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline

        if (high_count > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s %ld high readings\n", timestamp, high_count);
        }

        sleep(1);
    }

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

