    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", line, strerror(errno));
        gpiod_line_release(gpio_line);
        exit(EXIT_FAILURE);
    }

    gpiod_line_release(gpio_line);
}

void unlock_door(struct gpiod_chip *chip, unsigned int line) {
    struct gpiod_line *gpio_line = gpiod_chip_get_line(chip, line);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line %u: %s\n", line, strerror(errno));
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(gpio_line, "door_access", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", line, strerror(errno));
        gpiod_line_release(gpio_line);
        exit(EXIT_FAILURE);
    }

    sleep(5);

    ret = gpiod_line_set_value(gpio_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line %u to LOW: %s\n", line, strerror(errno));
    }

    gpiod_line_release(gpio_line);
}

int generate_code(char *code) {
    for (int i = 0; i < CODE_LENGTH; i++) {
        code[i] = '0' + rand() % 10;
    }
    code[CODE_LENGTH] = '\0';
    return 0;
}

int read_code(char *code) {
    char input[CODE_LENGTH + 1];
    printf("Enter the security code: ");
    if (fgets(input, sizeof(input), stdin) == NULL) {
        fprintf(stderr, "Failed to read input: %s\n", strerror(errno));
        return -1;
    }

    if (strlen(input) != CODE_LENGTH + 1 || input[CODE_LENGTH] != '\n') {
        printf("Invalid input. Please enter a six-digit code.\n");
        return -1;
    }

    for (int i = 0; i < CODE_LENGTH; i++) {
        if (!isdigit(input[i])) {
            printf("Invalid input. Please enter a six-digit code.\n");
            return -1;
        }
        code[i] = input[i];
    }
    code[CODE_LENGTH] = '\0';
    return 0;
}

void log_access(const char *code) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%s\n", timestamp, code);
    fclose(log_file);
}

int main() {
    srand(time(NULL));

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    set_gpio_low(chip, GPIO_LINE_A);
    set_gpio_low(chip, GPIO_LINE_B);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!exit_flag) {
        char generated_code[CODE_LENGTH + 1];
        generate_code(generated_code);
        printf("Generated security code: %s\n", generated_code);

        char entered_code[CODE_LENGTH + 1];
        while (read_code(entered_code) != 0);

        if (strcmp(generated_code, entered_code) == 0) {
            printf("Access granted.\n");
            unlock_door(chip, GPIO_LINE_A);
            unlock_door(chip, GPIO_LINE_B);
            log_access(generated_code);
        } else {
            printf("Access denied.\n");
        }
    }

    set_gpio_low(chip, GPIO_LINE_A);
    set_gpio_low(chip, GPIO_LINE_B);

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}
