    while (running) {
        // Wait for conversion time
        usleep(CONVERSION_TIME_US);

        // Read lux value
        uint8_t buffer[I2C_BUFFER_SIZE];
        if (read(i2c_fd, buffer, I2C_BUFFER_SIZE) != I2C_BUFFER_SIZE) {
            log_error("Failed to read lux value from BH1750 sensor");
            continue;
        }

        lux_value = (buffer[0] << 8) | buffer[1];
        lux_value /= 1.2; // Convert to lux

