        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Timestamp: %s, Lux: %u", timestamp, lux_value);
        log_message(log_entry);
    }

    // Clean up
    close(i2c_fd);
    log_message("Program terminated");

    return EXIT_SUCCESS;
}

