#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL 20000 // 20 ms
#define PLAYBACK_DURATION 5000 // 5 seconds
#define TCP_PORT 12345
#define BUFFER_SIZE 1024
#define SECRET_KEY "MySecretKey"
#define LOG_FILE "frequency_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int init_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(*fd);
        return -1;
    }

    return 0;
}

int init_mpr121(int fd) {
    uint8_t reset = 0x63;
    if (write(fd, &reset, 1) != 1) {
        perror("Failed to write reset command to MPR121");
        return -1;
    }

    usleep(10000); // Wait for reset to complete

    uint8_t config[] = {0x5E, 0x00, 0x00, 0x01, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (write(fd, config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write configuration to MPR121");
        return -1;
    }

    return 0;
}

int read_touch_values(int fd, uint16_t *values) {
    uint8_t command = 0x00;
    if (write(fd, &command, 1) != 1) {
        perror("Failed to write command to MPR121");
        return -1;
    }

    uint8_t buffer[24];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from MPR121");
        return -1;
    }

    for (int i = 0; i < 12; i++) {
        values[i] = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
    }

    return 0;
}

int init_tcp_server(int *sockfd) {
    *sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (*sockfd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in server_addr = {
        .sin_family = AF_INET,
        .sin_addr.s_addr = INADDR_ANY,
        .sin_port = htons(TCP_PORT)
    };

    if (bind(*sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(*sockfd);
        return -1;
    }

    if (listen(*sockfd, 1) < 0) {
        perror("Failed to listen on socket");
        close(*sockfd);
        return -1;
    }

    return 0;
}

int authenticate_client(int client_sock) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_sock, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Failed to receive data from client");
        return -1;
    }

    buffer[bytes_received] = '\0';
    if (strncmp(buffer, "MOTION_DETECTED:", 14) != 0 || strstr(buffer, SECRET_KEY) == NULL) {
        fprintf(stderr, "Authentication failed\n");
        return -1;
    }

    return 0;
}

void play_theremin(int fd, int client_sock) {
    uint16_t touch_values[12];
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        if (read_touch_values(fd, touch_values) < 0) {
            break;
        }

        uint16_t max_value = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_values[i] > max_value) {
                max_value = touch_values[i];
            }
        }

        int frequency = 100 + (max_value / 100); // Simple mapping for demonstration
        gpioHardwarePWM(PWM_PIN, PWM_FREQ, frequency * 1000);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (timespec_diff_us(&current_time, &start_time) >= PLAYBACK_DURATION) {
            break;
        }

        fprintf(log_file, "Frequency: %d Hz\n", frequency);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

    gpioHardwarePWM(PWM_PIN, 0, 0);
    fclose(log_file);
}

long timespec_diff_us(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd, tcp_sockfd, client_sock;
    if (init_i2c(&i2c_fd) < 0 || init_mpr121(i2c_fd) < 0 || init_tcp_server(&tcp_sockfd) < 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(i2c_fd);
        close(tcp_sockfd);
        return EXIT_FAILURE;
    }

    while (running) {
        client_sock = accept(tcp_sockfd, NULL, NULL);
        if (client_sock < 0) {
            perror("Failed to accept connection");
            continue;
        }

        if (authenticate_client(client_sock) == 0) {
            play_theremin(i2c_fd, client_sock);
        }

        close(client_sock);
    }

    gpioTerminate();
    close(i2c_fd);
    close(tcp_sockfd);

    return EXIT_SUCCESS;
}

