#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LSM303DLHC_ADDR 0x1E
#define MAG_DATA_REG 0x03
#define LED_GPIO 17
#define PWM_PERIOD 1000000 // 1 second
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000000 // 1 second

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static int pwm_fd = -1;

void cleanup() {
    if (pwm_fd != -1) {
        close(pwm_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

