#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define HMC5883L_ADDR 0x1E
#define HMC5883L_REG_CONFIG_A 0x00
#define HMC5883L_REG_CONFIG_B 0x01
#define HMC5883L_REG_MODE 0x02
#define HMC5883L_REG_DATA_X_MSB 0x03
#define HMC5883L_REG_DATA_Z_MSB 0x05
#define HMC5883L_REG_DATA_Y_MSB 0x07
#define SAMPLE_COUNT 100

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    int16_t raw_data[3];
    int16_t sum[3] = {0};
    int16_t avg[3] = {0};
    int16_t offset[3] = {0};
    int sample_index = 0;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure HMC5883L
    uint8_t config_a = 0x70; // 8 samples averaged, 15 Hz data rate
    uint8_t config_b = 0x20; // Gain 5 (default)
    uint8_t mode = 0x00;     // Continuous measurement mode

    if (write(i2c_fd, &HMC5883L_REG_CONFIG_A, 1) != 1 ||
        write(i2c_fd, &config_a, 1) != 1) {
        perror("Failed to write CONFIG_A register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &HMC5883L_REG_CONFIG_B, 1) != 1 ||
        write(i2c_fd, &config_b, 1) != 1) {
        perror("Failed to write CONFIG_B register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &HMC5883L_REG_MODE, 1) != 1 ||
        write(i2c_fd, &mode, 1) != 1) {
        perror("Failed to write MODE register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read raw data
        uint8_t buffer[6];
        if (write(i2c_fd, &HMC5883L_REG_DATA_X_MSB, 1) != 1 ||
            read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read data from HMC5883L");
            continue;
        }

        raw_data[0] = (buffer[0] << 8) | buffer[1];
        raw_data[1] = (buffer[4] << 8) | buffer[5];
        raw_data[2] = (buffer[2] << 8) | buffer[3];

        // Update running average
        sum[0] -= raw_data[0];
        sum[1] -= raw_data[1];
        sum[2] -= raw_data[2];
        sum[0] += raw_data[0];
        sum[1] += raw_data[1];
        sum[2] += raw_data[2];
        sample_index = (sample_index + 1) % SAMPLE_COUNT;
        if (sample_index == 0) {
            avg[0] = sum[0] / SAMPLE_COUNT;
            avg[1] = sum[1] / SAMPLE_COUNT;
            avg[2] = sum[2] / SAMPLE_COUNT;
        }

        // Apply offsets
        offset[0] = avg[0];
        offset[1] = avg[1];
        offset[2] = avg[2];

        int16_t corrected_data[3];
        corrected_data[0] = raw_data[0] - offset[0];
        corrected_data[1] = raw_data[1] - offset[1];
        corrected_data[2] = raw_data[2] - offset[2];

        // Print corrected data
        printf("X: %d, Y: %d, Z: %d\n", corrected_data[0], corrected_data[1], corrected_data[2]);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

