    if (i2c_fd != -1) {
        uint8_t ctrl_reg1 = 0x00; // Power down mode
        if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
            perror("Failed to write to CTRL_REG1");
        }
        close(i2c_fd);
    }
    if (int1_line) {
        gpiod_line_release(int1_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return -1;
    }
    uint8_t ctrl_reg1 = 0x57; // Normal mode, 100 Hz, XYZ enabled
    uint8_t ctrl_reg2 = 0x00; // High resolution, no filtering
    uint8_t ctrl_reg3 = 0x08; // INT1 enabled
    uint8_t int1_cfg = 0x01; // Interrupt on X low event
    if (write(i2c_fd, &ctrl_reg1, 1) != 1 ||
        write(i2c_fd, &ctrl_reg2, 1) != 1 ||
        write(i2c_fd, &ctrl_reg3, 1) != 1 ||
        write(i2c_fd, &int1_cfg, 1) != 1) {
        perror("Failed to write to control registers");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    int1_line = gpiod_chip_get_line(chip, 23);
    if (!int1_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_input(int1_line, "lsm303d_mon") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return -1;
    }
    return 0;
}

void read_acceleration(Sample *sample) {
    uint8_t reg = OUT_X_L_A | 0x80; // Read multiple bytes, auto-increment
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        return;
    }
    uint8_t data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read acceleration data");
        return;
    }
    sample->x = (int16_t)((data[1] << 8) | data[0]) * SENSITIVITY;
    sample->y = (int16_t)((data[3] << 8) | data[2]) * SENSITIVITY;
    sample->z = (int16_t)((data[5] << 8) | data[4]) * SENSITIVITY;
    clock_gettime(CLOCK_REALTIME, &sample->ts);
}

void dump_buffer() {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    printf("Timestamp: %ld.%09ld\n", now.tv_sec, now.tv_nsec);
    for (int i = 0; i < 10; i++) {
        int idx = (buffer_index - 10 + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Sample %d: X=%.2f, Y=%.2f, Z=%.2f\n", idx, buffer[idx].x, buffer[idx].y, buffer[idx].z);
    }
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (init_i2c() < 0 || init_gpio() < 0) {
        return EXIT_FAILURE;
    }
    int buffer_index = 0;
    while (running) {
        Sample sample;
        read_acceleration(&sample);
        buffer[buffer_index] = sample;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (gpiod_line_get_value(int1_line) > 0) {
            dump_buffer();
            // Clear the interrupt source
            uint8_t int1_src;
            if (read(i2c_fd, &int1_src, 1) != 1) {
                perror("Failed to read INT1_SRC register");
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }
    disable_accelerometer();
    return EXIT_SUCCESS;
}
