#define CONSUMER "solenoid_control"
#define SOL1_PIN 17
#define SOL2_PIN 27

static struct gpiod_chip *chip;
static struct gpiod_line *sol1_line;
static struct gpiod_line *sol2_line;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (sol1_line) {
        gpiod_line_release(sol1_line);
    }
    if (sol2_line) {
        gpiod_line_release(sol2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct timespec ts = {0, 500000000}; // 500 ms delay

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    sol1_line = gpiod_chip_get_line(chip, SOL1_PIN);
    sol2_line = gpiod_chip_get_line(chip, SOL2_PIN);
    if (!sol1_line || !sol2_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines as output
    if (gpiod_line_request_output(sol1_line, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(sol2_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        if (gpiod_line_set_value(sol1_line, 1) < 0) {
            fprintf(stderr, "Failed to set solenoid 1: %s\n", strerror(errno));
        }
        if (gpiod_line_set_value(sol2_line, 0) < 0) {
            fprintf(stderr, "Failed to set solenoid 2: %s\n", strerror(errno));
        }
        nanosleep(&ts, NULL);

        if (gpiod_line_set_value(sol1_line, 0) < 0) {
            fprintf(stderr, "Failed to set solenoid 1: %s\n", strerror(errno));
        }
        if (gpiod_line_set_value(sol2_line, 1) < 0) {
            fprintf(stderr, "Failed to set solenoid 2: %s\n", strerror(errno));
        }
        nanosleep(&ts, NULL);
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

