#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <termios.h>
#include <libgpiod.h>
#include <sys/select.h>

#define UART0 "/dev/serial0"
#define UART1 "/dev/serial1"
#define BAUDRATE B9600
#define TIMEOUT 5
#define RELAY1 17
#define RELAY2 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static int uart0_fd, uart1_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (uart0_fd >= 0) {
        close(uart0_fd);
    }
    if (uart1_fd >= 0) {
        close(uart1_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        return -1;
    }

    cfsetospeed(&tty, BAUDRATE);
    cfsetispeed(&tty, BAUDRATE);

    tty.c_cflag &= ~PARENB; // No parity bit
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8; // 8 data bits
    tty.c_cflag &= ~CRTSCTS; // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Turn on READ & ignore ctrl lines (CLOCAL = 1)

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off s/w flow ctrl
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL); // Disable any special handling of received bytes

    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; // Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VTIME] = TIMEOUT;    // Wait for up to TIMEOUT tenths-of-seconds (5 seconds)
    tty.c_cc[VMIN] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip\n");
        return -1;
    }

    line1 = gpiod_chip_get_line(chip, RELAY1);
    if (!line1) {
        fprintf(stderr, "Error: Unable to get GPIO line %d\n", RELAY1);
        return -1;
    }

    line2 = gpiod_chip_get_line(chip, RELAY2);
    if (!line2) {
        fprintf(stderr, "Error: Unable to get GPIO line %d\n", RELAY2);
        return -1;
    }

    if (gpiod_line_request_output(line1, "door_lock", 0) < 0) {
        fprintf(stderr, "Error: Unable to request GPIO line %d as output\n", RELAY1);
        return -1;
    }

    if (gpiod_line_request_output(line2, "door_lock", 0) < 0) {
        fprintf(stderr, "Error: Unable to request GPIO line %d as output\n", RELAY2);
        return -1;
    }

    return 0;
}

int read_code(int fd, char *buffer, size_t length) {
    fd_set read_fds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&read_fds);
    FD_SET(fd, &read_fds);
    timeout.tv_sec = TIMEOUT;
    timeout.tv_usec = 0;

    ret = select(fd + 1, &read_fds, NULL, NULL, &timeout);
    if (ret == -1) {
        fprintf(stderr, "Error: select() failed\n");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Error: Read timeout\n");
        return -1;
    }

    size_t i = 0;
    while (i < length) {
        char c;
        if (read(fd, &c, 1) != 1) {
            fprintf(stderr, "Error: read() failed\n");
            return -1;
        }
        if (c < '0' || c > '9') {
            i = 0; // Reset buffer on non-digit character
        } else {
            buffer[i++] = c;
        }
    }
    buffer[i] = '\0';
    return 0;
}

int constant_time_compare(const char *a, const char *b) {
    size_t length = strlen(a);
    int result = 0;
    for (size_t i = 0; i < length; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    uart0_fd = open(UART0, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart0_fd < 0) {
        fprintf(stderr, "Error: Unable to open %s\n", UART0);
        cleanup();
        return EXIT_FAILURE;
    }

    uart1_fd = open(UART1, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart1_fd < 0) {
        fprintf(stderr, "Error: Unable to open %s\n", UART1);
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_uart(uart0_fd) < 0 || setup_uart(uart1_fd) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    char code0[CODE_LENGTH + 1] = {0};
    char code1[CODE_LENGTH + 1] = {0};

    while (running) {
        if (read_code(uart0_fd, code0, CODE_LENGTH) == 0) {
            if (read_code(uart1_fd, code1, CODE_LENGTH) == 0) {
                if (constant_time_compare(code0, EXPECTED_CODE) && constant_time_compare(code1, EXPECTED_CODE)) {
                    gpiod_line_set_value(line1, 1);
                    gpiod_line_set_value(line2, 1);
                    sleep(2);
                    gpiod_line_set_value(line1, 0);
                    gpiod_line_set_value(line2, 0);
                }
                memset(code0, 0, sizeof(code0));
                memset(code1, 0, sizeof(code1));
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

