#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <libgpiod.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define POLL_INTERVAL_US 50000
#define RELAY_ON_TIME_US 1000000
#define FAILSAFE_TIMEOUT_US 10000000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    openlog("pir_monitor", LOG_PID, LOG_DAEMON);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(pir_line, "pir_monitor") < 0) {
        syslog(LOG_ERR, "Failed to request PIR GPIO line as input");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay_line, "pir_monitor", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        if (gpiod_line_get_value(pir_line) > 0) {
            syslog(LOG_INFO, "Motion detected");

            clock_gettime(CLOCK_MONOTONIC, &start_time);
            gpiod_line_set_value(relay_line, 1);
            syslog(LOG_INFO, "Relay activated");

            while (running) {
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                if (timespec_subtract(&current_time, &start_time) >= RELAY_ON_TIME_US) {
                    break;
                }

                if (gpiod_line_get_value(pir_line) == 0) {
                    break;
                }

                usleep(POLL_INTERVAL_US);
            }

            gpiod_line_set_value(relay_line, 0);
            syslog(LOG_INFO, "Relay deactivated");

            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (timespec_subtract(&current_time, &start_time) >= FAILSAFE_TIMEOUT_US) {
                syslog(LOG_WARNING, "Potential malfunction detected");
                syslog(LOG_INFO, "System shutdown initiated");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

int timespec_subtract(struct timespec *result, struct timespec *x, struct timespec *y) {
    if (x->tv_nsec < y->tv_nsec) {
        int nsec = (y->tv_nsec - x->tv_nsec) / 1000000000 + 1;
        y->tv_nsec -= 1000000000 * nsec;
        y->tv_sec += nsec;
    }
    if (x->tv_nsec - y->tv_nsec > 1000000000) {
        int nsec = (x->tv_nsec - y->tv_nsec) / 1000000000;
        y->tv_nsec += 1000000000 * nsec;
        y->tv_sec -= nsec;
    }

    result->tv_sec = x->tv_sec - y->tv_sec;
    result->tv_nsec = x->tv_nsec - y->tv_nsec;

    return x->tv_sec < y->tv_sec;
}

