#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <libgpiod.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22
#define RELAY_COUNT 4
#define RELAY_GPIO_CHIP "gpiochip0"
#define RELAY_GPIO_LINE_OFFSET 4
#define RELAY_ON 0
#define RELAY_OFF 1
#define CYCLE_TIME 60
#define RELAY_ON_TIME 300
#define PAUSE_TIME 60

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void set_relay(struct gpiod_chip *chip, unsigned int line_offset, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_offset);
    if (!line) {
        log_message("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(line, "irrigation_system", value);
    if (ret < 0) {
        log_message("Failed to request GPIO line as output");
        gpiod_line_release(line);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        log_message("Failed to set GPIO line value");
        gpiod_line_release(line);
        exit(EXIT_FAILURE);
    }

    gpiod_line_release(line);
}

void deactivate_all_relays(struct gpiod_chip *chip) {
    for (unsigned int i = 0; i < RELAY_COUNT; i++) {
        set_relay(chip, RELAY_GPIO_LINE_OFFSET + i, RELAY_OFF);
    }
}

void timer_handler(union sigval sv) {
    static unsigned int current_relay = 0;
    struct gpiod_chip *chip = (struct gpiod_chip *)sv.sival_ptr;

    set_relay(chip, RELAY_GPIO_LINE_OFFSET + current_relay, RELAY_ON);
    log_message("Relay ON: %d", current_relay + 1);

    sleep(RELAY_ON_TIME);

    set_relay(chip, RELAY_GPIO_LINE_OFFSET + current_relay, RELAY_OFF);
    log_message("Relay OFF: %d", current_relay + 1);

    sleep(PAUSE_TIME);

    current_relay = (current_relay + 1) % RELAY_COUNT;
}

int main() {
    openlog("irrigation_system", LOG_PID, LOG_USER);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(RELAY_GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip");
        closelog();
        exit(EXIT_FAILURE);
    }

    for (unsigned int i = 0; i < RELAY_COUNT; i++) {
        set_relay(chip, RELAY_GPIO_LINE_OFFSET + i, RELAY_OFF);
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    timer_t timerid;
    struct sigevent sev;
    struct itimerspec its;

    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_value.sival_ptr = chip;
    sev.sigev_notify_function = timer_handler;
    sev.sigev_notify_attributes = NULL;

    if (timer_create(CLOCK_REALTIME, &sev, &timerid) == -1) {
        log_message("Failed to create timer");
        deactivate_all_relays(chip);
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    its.it_value.tv_sec = CYCLE_TIME;
    its.it_value.tv_nsec = 0;
    its.it_interval.tv_sec = CYCLE_TIME;
    its.it_interval.tv_nsec = 0;

    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        log_message("Failed to set timer");
        timer_delete(timerid);
        deactivate_all_relays(chip);
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    while (running) {
        sleep(1);
    }

    timer_delete(timerid);
    deactivate_all_relays(chip);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

