#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_XOUT_L 0x3C
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_YOUT_L 0x3E
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_ZOUT_L 0x40
#define BUFFER_SIZE 100

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

accel_data_t buffer[BUFFER_SIZE];
volatile int buffer_index = 0;
volatile int buffer_full = 0;

int i2c_fd = -1;
int timer_fd = -1;
int driver_fd = -1;

void cleanup() {
    if (i2c_fd != -1) close(i2c_fd);
    if (timer_fd != -1) close(timer_fd);
    if (driver_fd != -1) close(driver_fd);
    unlink("/sys/kernel/mpu6050_accel/latest");
    printf("Cleanup complete\n");
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

void timer_handler() {
    uint8_t data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("I2C read failed");
        return;
    }

    accel_data_t sample = {
        .x = (data[0] << 8) | data[1],
        .y = (data[2] << 8) | data[3],
        .z = (data[4] << 8) | data[5]
    };

    buffer[buffer_index] = sample;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) buffer_full = 1;

    if (driver_fd != -1) {
        lseek(driver_fd, 0, SEEK_SET);
        if (write(driver_fd, &sample, sizeof(sample)) != sizeof(sample)) {
            perror("Driver write failed");
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t power_mgmt_1 = 0x00;
    if (write(i2c_fd, &power_mgmt_1, 1) != 1) {
        perror("Failed to write to power management register");
        cleanup();
        return EXIT_FAILURE;
    }

    timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        cleanup();
        return EXIT_FAILURE;
    }

    struct itimerspec timer_spec = {
        .it_interval = { .tv_sec = 0, .tv_nsec = 10000000 },
        .it_value = { .tv_sec = 0, .tv_nsec = 10000000 }
    };

    if (timerfd_settime(timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("Failed to set timer");
        cleanup();
        return EXIT_FAILURE;
    }

    driver_fd = open("/sys/kernel/mpu6050_accel/latest", O_RDWR | O_CREAT, 0666);
    if (driver_fd < 0) {
        perror("Failed to open driver file");
        cleanup();
        return EXIT_FAILURE;
    }

    uint64_t exp;
    while (read(timer_fd, &exp, sizeof(uint64_t)) > 0) {
        timer_handler();
    }

    cleanup();
    return EXIT_SUCCESS;
}

