#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL_US 100000
#define RELAY_ACTIVE_TIME_US 3000000
#define DEBOUNCE_TIME_US 200000

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_activation(const char *filename) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(file, "Activation at %s", ctime(&now));
    fclose(file);
}

void control_relay(int activate) {
    int ret = gpiod_line_set_value(relay_line, activate);
    if (ret < 0) {
        perror("Failed to set relay value");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(relay_line, "relay_control", 0);
    if (ret < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = 0;
    struct timespec last_activation = {0};
    while (running) {
        int current_state = gpiod_line_get_value(sensor_line);
        if (current_state < 0) {
            perror("Failed to read sensor line value");
            break;
        }

        if (current_state && !last_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (timespec_subtract(&now, &last_activation) > RELAY_ACTIVE_TIME_US) {
                control_relay(1);
                log_activation("alarm_log.txt");
                clock_gettime(CLOCK_MONOTONIC, &last_activation);
                usleep(RELAY_ACTIVE_TIME_US);
                control_relay(0);
            }
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

    control_relay(0);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, struct timespec *x) {
    if (x->tv_nsec < result->tv_nsec) {
        int nsec = (result->tv_nsec - x->tv_nsec) / 1000000;
        result->tv_sec = x->tv_sec - result->tv_sec - 1;
        result->tv_nsec = 1000000000 - x->tv_nsec + result->tv_nsec;
        return nsec;
    } else {
        int nsec = (x->tv_nsec - result->tv_nsec) / 1000000;
        result->tv_sec = x->tv_sec - result->tv_sec;
        result->tv_nsec = x->tv_nsec - result->tv_nsec;
        return nsec;
    }
}

