#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define BUFFER_SIZE 100

typedef struct {
    float x;
    float y;
    float z;
} Vector3;

Vector3 buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_sigint(int sig) {
    printf("Received SIGINT, exiting...\n");
    exit(0);
}

void callback(const Vector3 *data) {
    printf("Angular velocity exceeded threshold: %.2f, %.2f, %.2f\n", data->x, data->y, data->z);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("I2C write byte failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

float calculate_magnitude(const Vector3 *data) {
    return sqrt(data->x * data->x + data->y * data->y + data->z * data->z);
}

int main() {
    int fd;
    uint8_t buf[6];
    Vector3 data;
    float threshold = 50.0;

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(fd, 0x6B, 0x00) < 0) { // Power management register 1, wake up
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (i2c_read(fd, 0x43, buf, 6) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }

        data.x = ((int16_t)(buf[0] << 8 | buf[1])) / 131.0;
        data.y = ((int16_t)(buf[2] << 8 | buf[3])) / 131.0;
        data.z = ((int16_t)(buf[4] << 8 | buf[5])) / 131.0;

        buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (calculate_magnitude(&data) > threshold) {
            callback(&data);
        }

        usleep(10000); // 10ms delay
    }

    close(fd);
    return EXIT_SUCCESS;
}

