void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return -1;
    }

    struct termios options;
    tcgetattr(fd, &options);
    cfsetispeed(&options, baud_rate);
    cfsetospeed(&options, baud_rate);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    tcsetattr(fd, TCSANOW, &options);
    return fd;
}

int send_command(int fd, const uint8_t *command, size_t length) {
    if (write(fd, command, length) != length) {
        perror("Failed to send command");
        return -1;
    }
    return 0;
}

int read_response(int fd, uint8_t *response, size_t length) {
    struct timeval start, now;
    gettimeofday(&start, NULL);

    size_t bytes_read = 0;
    while (bytes_read < length) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        struct timeval timeout;
        timeout.tv_sec = TIMEOUT;
        timeout.tv_usec = 0;

        int ret = select(fd + 1, &read_fds, NULL, NULL, &timeout);
        if (ret == -1) {
            perror("Select failed");
            return -1;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout reading from UART\n");
            return -1;
        }

        ssize_t n = read(fd, response + bytes_read, length - bytes_read);
        if (n == -1) {
            perror("Failed to read from UART");
            return -1;
        }
        bytes_read += n;
    }
    return 0;
}

int calculate_checksum(const uint8_t *data, size_t length) {
    uint8_t checksum = 0;
    for (size_t i = 1; i < length - 1; i++) {
        checksum += data[i];
    }
    return checksum;
}

void log_error(const char *message) {
    FILE *error_log = fopen(ERROR_LOG_FILE, "a");
    if (error_log == NULL) {
        perror("Failed to open error log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(error_log, "%.9f: %s\n", ts.tv_sec + ts.tv_nsec / 1e9, message);
    fclose(error_log);
}

void log_reading(const char *timestamp, int ppm, int error_flag) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %d}\n", timestamp, ppm, error_flag);
    fflush(log_file);
    fclose(log_file);

    printf("{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %d}\n", timestamp, ppm, error_flag);
}

int main() {
    setup_signal_handler();

    int uart_fd = open_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    uint8_t command[RESPONSE_LENGTH] = COMMAND_SEQUENCE;
    uint8_t response[RESPONSE_LENGTH];

    while (running) {
        if (send_command(uart_fd, command, RESPONSE_LENGTH) == -1) {
            log_error("Failed to send command");
            break;
        }

        if (read_response(uart_fd, response, RESPONSE_LENGTH) == -1) {
            log_error("Failed to read response");
            break;
        }

        int checksum = calculate_checksum(response, RESPONSE_LENGTH);
        if (checksum != response[8]) {
            log_error("Checksum mismatch");
            continue;
        }

        int ppm = (response[2] << 8) | response[3];

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        log_reading(timestamp, ppm, 0);

        sleep(SAMPLE_INTERVAL);
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

