#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define HMC5883L_ADDR 0x1E
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define GPIO_PIN 17

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    float headings[BUFFER_SIZE];
    int head = 0;
    float last_heading = 0.0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "hmc5883l_heading", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        uint8_t data[6];
        int16_t x, y, z;
        float heading;

        // Read data from HMC5883L
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read from I2C device");
            continue;
        }

        x = (data[0] << 8) | data[1];
        y = (data[4] << 8) | data[5];
        z = (data[2] << 8) | data[3];

        // Apply hard-iron compensation
        x -= 100;
        y += 50;

        // Calculate heading
        heading = atan2(y, x) * 180.0 / M_PI;
        if (heading < 0) {
            heading += 360.0;
        }

        // Store in circular buffer
        headings[head] = heading;
        head = (head + 1) % BUFFER_SIZE;

        // Check deviation from target heading
        if (fabs(heading - TARGET_HEADING) > HEADING_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL_US);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

