    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    return 0;
}

int init_log() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

int read_lux() {
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }

    usleep(120000); // Wait at least 120 ms

    uint16_t lux;
    if (read(i2c_fd, &lux, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }

    lux = (lux >> 8) | (lux << 8); // Swap bytes
    lux /= 1.2; // Convert to lux

    return lux;
}

void control_lamps(int lux) {
    if (lux < 50) {
        gpiod_line_set_value(red_line, 1);
        gpiod_line_set_value(green_line, 0);
        gpiod_line_set_value(blue_line, 0);
    } else if (lux < 150) {
        gpiod_line_set_value(red_line, 0);
        gpiod_line_set_value(green_line, 1);
        gpiod_line_set_value(blue_line, 0);
    } else if (lux < 300) {
        gpiod_line_set_value(red_line, 0);
        gpiod_line_set_value(green_line, 0);
        gpiod_line_set_value(blue_line, 1);
    } else {
        gpiod_line_set_value(red_line, 1);
        gpiod_line_set_value(green_line, 1);
        gpiod_line_set_value(blue_line, 1);
    }
}

void log_data(int lux) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = localtime(&tv.tv_sec);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03ld, Lux: %d, Red: %d, Green: %d, Blue: %d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, tv.tv_usec / 1000,
            lux, gpiod_line_get_value(red_line), gpiod_line_get_value(green_line), gpiod_line_get_value(blue_line));
    fflush(log_file);
}

int main() {
    if (atexit(cleanup) != 0) {
        perror("Failed to set cleanup function");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NSIG; i++) {
        signal(i, signal_handler);
    }

    if (init_gpio() < 0 || init_i2c() < 0 || init_log() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux, retrying...\n");
            continue;
        }

        control_lamps(lux);
        log_data(lux);

        sleep(1);
    }

    return EXIT_SUCCESS;
}
