#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define MOTOR_COILS {17, 18, 27, 22}
#define MOTOR_STEPS 512
#define STEP_DELAY_US 2000

static struct gpiod_chip *chip;
static struct gpiod_line *lock_button_line;
static struct gpiod_line *unlock_button_line;
static struct gpiod_line *motor_coils[4];
static volatile sig_atomic_t running = 1;

void deenergize_motor(void) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(motor_coils[i], 0);
    }
}

void handle_signal(int sig) {
    running = 0;
    deenergize_motor();
    printf("Program terminated by signal %d\n", sig);
}

void setup_gpio(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    lock_button_line = gpiod_chip_get_line(chip, LOCK_BUTTON);
    unlock_button_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON);
    if (!lock_button_line || !unlock_button_line) {
        perror("Failed to get GPIO lines for buttons");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 4; i++) {
        motor_coils[i] = gpiod_chip_get_line(chip, MOTOR_COILS[i]);
        if (!motor_coils[i]) {
            perror("Failed to get GPIO lines for motor coils");
            deenergize_motor();
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    if (gpiod_line_request_input(lock_button_line, "lock_button") < 0 ||
        gpiod_line_request_input(unlock_button_line, "unlock_button") < 0) {
        perror("Failed to request input for buttons");
        deenergize_motor();
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(motor_coils[i], "motor_coil") < 0) {
            perror("Failed to request output for motor coils");
            deenergize_motor();
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    if (gpiod_line_set_config(lock_button_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP) < 0 ||
        gpiod_line_set_config(unlock_button_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP) < 0) {
        perror("Failed to set pull-up resistors for buttons");
        deenergize_motor();
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void rotate_motor(int steps, int direction) {
    int sequence[] = {0b0001, 0b0011, 0b0010, 0b0110, 0b0100, 0b1100, 0b1000, 0b1001};
    int seq_len = sizeof(sequence) / sizeof(sequence[0]);

    for (int i = 0; i < steps; i++) {
        int step = sequence[(i * direction) % seq_len];
        for (int j = 0; j < 4; j++) {
            gpiod_line_set_value(motor_coils[j], (step >> j) & 1);
        }
        usleep(STEP_DELAY_US);
    }
}

int main(void) {
    setup_gpio();

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int lock_state = gpiod_line_get_value(lock_button_line);
        int unlock_state = gpiod_line_get_value(unlock_button_line);

        if (lock_state == 0) {
            printf("Locking door...\n");
            rotate_motor(MOTOR_STEPS, 1);
            printf("Door locked.\n");
            while (gpiod_line_get_value(lock_button_line) == 0) {
                usleep(10000);
            }
        }

        if (unlock_state == 0) {
            printf("Unlocking door...\n");
            rotate_motor(MOTOR_STEPS, -1);
            printf("Door unlocked.\n");
            while (gpiod_line_get_value(unlock_button_line) == 0) {
                usleep(10000);
            }
        }

        usleep(10000);
    }

    deenergize_motor();
    gpiod_chip_close(chip);
    printf("Program exited normally.\n");
    return 0;
}

