#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/poll.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <gpiod.h>

#define MPU6050_ADDR 0x68
#define I2C_DEV "/dev/i2c-1"
#define PWM_CHIP "pwmchip2"
#define PWM_CHANNEL 0
#define PWM_PERIOD 20000000 // 20ms period for 50Hz PWM
#define PWM_DUTY_MIN 1000000  // 1ms pulse for 0 degrees
#define PWM_DUTY_MAX 2000000  // 2ms pulse for 180 degrees
#define LOG_FILE "solar_tracker.log"

#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_XOUT_L 0x3C
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_YOUT_L 0x3E
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_ZOUT_L 0x40

#define G 9.81
#define RAD_TO_DEG 57.2958

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read data from I2C");
        return -1;
    }

    return 0;
}

int i2c_write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data to I2C");
        return -1;
    }

    return 0;
}

int init_i2c(const char *dev) {
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int init_pwm(const char *chip, unsigned int channel) {
    struct gpiod_chip *chip_handle;
    struct gpiod_line *line;
    int ret;

    chip_handle = gpiod_chip_open_by_name(chip);
    if (!chip_handle) {
        perror("Failed to open PWM chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip_handle, channel);
    if (!line) {
        perror("Failed to get PWM line");
        gpiod_chip_close(chip_handle);
        return -1;
    }

    ret = gpiod_line_request_output(line, "solar_tracker", 0);
    if (ret < 0) {
        perror("Failed to request PWM line");
        gpiod_chip_close(chip_handle);
        return -1;
    }

    return gpiod_line_release(line);
}

void set_pwm_duty(unsigned int duty) {
    struct gpiod_chip *chip_handle;
    struct gpiod_line *line;
    int ret;

    chip_handle = gpiod_chip_open_by_name(PWM_CHIP);
    if (!chip_handle) {
