#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define NUM_RELAYS 4
#define RELAY_PINS {4, 17, 27, 22}
#define SCHEDULE_FILE "lighting_schedule.txt"
#define FADE_DURATION 1800
#define PWM_FREQ 100
#define PWM_PERIOD (1000000 / PWM_FREQ)
#define DUTY_CYCLE_STEPS 100

static struct gpiod_chip *chip;
static struct gpiod_line *relays[NUM_RELAYS];
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void release_resources() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relays[i]) {
            gpiod_line_release(relays[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    int pins[NUM_RELAYS] = RELAY_PINS;
    for (int i = 0; i < NUM_RELAYS; i++) {
        relays[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!relays[i]) {
            perror("Failed to get GPIO line");
            release_resources();
            return -1;
        }

        int ret = gpiod_line_request_output(relays[i], "lighting_system", 0);
        if (ret < 0) {
            perror("Failed to request GPIO line as output");
            release_resources();
            return -1;
        }
    }

    return 0;
}

int parse_time(const char *time_str, struct tm *tm) {
    if (sscanf(time_str, "%d:%d:%d", &tm->tm_hour, &tm->tm_min, &tm->tm_sec) != 3) {
        return -1;
    }
    return 0;
}

int parse_schedule_entry(const char *entry, struct tm *tm, int *relay, int *state) {
    char time_str[9];
    if (sscanf(entry, "%8[^,],%d,%d", time_str, relay, state) != 3) {
        return -1;
    }
    if (parse_time(time_str, tm) < 0) {
        return -1;
    }
    if (*relay < 0 || *relay >= NUM_RELAYS || (*state != 0 && *state != 1)) {
        return -1;
    }
    return 0;
}

void fade_relay(int relay, int target_state) {
    int current_state = gpiod_line_get_value(relays[relay]);
    int step = target_state > current_state ? 1 : -1;
    for (int i = current_state; i != target_state; i += step) {
        gpiod_line_set_value(relays[relay], i);
        usleep(PWM_PERIOD / DUTY_CYCLE_STEPS);
    }
}

int main() {
    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        release_resources();
        return EXIT_FAILURE;
    }

    FILE *schedule_file = fopen(SCHEDULE_FILE, "r");
    if (!schedule_file) {
        perror("Failed to open schedule file");
        release_resources();
        return EXIT_FAILURE;
    }

    char line[256];
    struct tm current_time, schedule_time;
    time_t now, schedule_time_t;
    int relay, state;

    while (running) {
        time(&now);
        localtime_r(&now, &current_time);

        rewind(schedule_file);
        while (fgets(line, sizeof(line), schedule_file)) {
            if (parse_schedule_entry(line, &schedule_time, &relay, &state) < 0) {
                fprintf(stderr, "Invalid schedule entry: %s", line);
                continue;
            }

            schedule_time_t = mktime(&schedule_time);
            if (schedule_time_t < now) {
                continue;
            }

            if (difftime(schedule_time_t, now) <= FADE_DURATION) {
                fade_relay(relay, state);
            }
        }

        sleep(1);
    }

    fclose(schedule_file);
    release_resources();
    return EXIT_SUCCESS;
}

