#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_DISTANCE 10.0  // cm
#define MAX_DISTANCE 400.0 // cm
#define MIN_FREQUENCY 200  // Hz
#define MAX_FREQUENCY 2000 // Hz
#define MEASUREMENT_INTERVAL_US 20000 // 20 ms
#define MIN_MEASUREMENT_GAP_US 60000  // 60 ms

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int ret;
    struct gpiod_line_event event;
    struct timespec start, end;
    double distance, frequency;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trigger_line, "theremin", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "theremin");
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer_line, "theremin", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        // Trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo start
        ret = gpiod_line_event_wait(echo_line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for echo start: %s\n", strerror(errno));
            continue;
        }

        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo start event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            fprintf(stderr, "Unexpected echo start event type\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for echo end
        ret = gpiod_line_event_wait(echo_line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for echo end: %s\n", strerror(errno));
            continue;
        }

        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo end event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            fprintf(stderr, "Unexpected echo end event type\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate distance
        long echo_duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        distance = echo_duration * 0.034 / 2.0; // cm

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            continue;
        }

        // Map distance to frequency
        frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);

        // Clamp frequency
        if (frequency < MIN_FREQUENCY) {
            frequency = MIN_FREQUENCY;
        } else if (frequency > MAX_FREQUENCY) {
            frequency = MAX_FREQUENCY;
        }

        // Set buzzer frequency
        // Note: libgpiod does not directly support PWM, so we simulate it with a square wave
        int period_us = 1000000 / frequency;
        int duty_cycle_us = period_us / 2;

        while (running && (clock_gettime(CLOCK_MONOTONIC, &start) == 0)) {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(duty_cycle_us);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(period_us - duty_cycle_us);

            clock_gettime(CLOCK_MONOTONIC, &end);
