    ret = gpiod_line_request_output(red_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Failed to request red line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(green_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Failed to request green line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(blue_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Failed to request blue line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // PWM setup
    struct gpiod_line_settings settings;
    gpiod_line_settings_init(&settings);
    gpiod_line_settings_set_output_value(&settings, 0);
    gpiod_line_settings_set_output_flags(&settings, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    gpiod_line_settings_set_output_duty_cycle(&settings, 0, PWM_FREQ);
    gpiod_line_settings_set_output_period(&settings, PWM_FREQ);

    ret = gpiod_line_set_settings(red_line, &settings);
    if (ret < 0) {
        perror("Failed to set red line settings");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_settings(green_line, &settings);
    if (ret < 0) {
        perror("Failed to set green line settings");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_settings(blue_line, &settings);
    if (ret < 0) {
        perror("Failed to set blue line settings");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    double t = 0.0;
    while (running) {
        double proximity = 0.5 * (1 + sin(t));
        int red_duty = (int)(proximity * 1000);
        int green_duty = (int)((1 - proximity) * 1000);
        int blue_duty = 0;

        gpiod_line_set_output_duty_cycle(red_line, red_duty, PWM_FREQ);
        gpiod_line_set_output_duty_cycle(green_line, green_duty, PWM_FREQ);
        gpiod_line_set_output_duty_cycle(blue_line, blue_duty, PWM_FREQ);

        t += 0.01;
        if (t >= 2 * M_PI) {
            t -= 2 * M_PI;
        }

        usleep(10000); // 10 ms
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

