#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_GYRO_XOUT_H 0x43

#define I2C_DEVICE "/dev/i2c-1"
#define SAMPLE_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    struct sigaction sa;
    struct timespec ts;
    int16_t gyro_data[3];
    char timestamp[20];

    // Set up signal handler for graceful termination
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Wake up the MPU6050
    uint8_t power_mgmt_1 = 0;
    if (write(i2c_fd, &power_mgmt_1, 1) != 1) {
        perror("Failed to write to power management register");
        goto cleanup;
    }

    // Set gyro full scale range to ±250 degrees/s
    uint8_t gyro_config = 0x00;
    if (write(i2c_fd, &gyro_config, 1) != 1) {
        perror("Failed to write to gyro config register");
        goto cleanup;
    }

    // Open log file
    log_fd = open("gyro_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (running) {
        // Read gyro data
        uint8_t reg = MPU6050_REG_GYRO_XOUT_H;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to gyro data register");
            break;
        }

        if (read(i2c_fd, gyro_data, sizeof(gyro_data)) != sizeof(gyro_data)) {
            perror("Failed to read gyro data");
            break;
        }

        // Convert raw data to degrees per second
        float gyro_x = gyro_data[0] / 131.0;
        float gyro_y = gyro_data[1] / 131.0;
        float gyro_z = gyro_data[2] / 131.0;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            break;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write data to log file
        dprintf(log_fd, "%s %.2f %.2f %.2f\n", timestamp, gyro_x, gyro_y, gyro_z);

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL_US);
    }

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fd >= 0) close(log_fd);
    return 0;
}

