#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <libgpiod.h>

#define BUTTON_GPIO 17
#define BUZZER_GPIO 18
#define DEBOUNCE_INTERVAL_US 50000

volatile sig_atomic_t running = 1;
volatile sig_atomic_t button_pressed = 0;

struct gpiod_chip *chip;
struct gpiod_line *button_line;
struct gpiod_line *buzzer_line;

const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523}; // C4, D4, E4, F4, G4, A4, B4, C5
const int durations[] = {500000, 500000, 500000, 500000, 500000, 500000, 500000, 500000}; // 0.5 seconds each

void signal_handler(int signum) {
    running = 0;
}

void play_melody() {
    for (int i = 0; i < sizeof(melody) / sizeof(melody[0]); i++) {
        if (!running) break;
        if (button_pressed) {
            button_pressed = 0;
            break;
        }
        gpiod_line_set_value(buzzer_line, 1);
        usleep(durations[i] / 2);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(durations[i] / 2);
    }
}

void button_isr(struct gpiod_line *line, unsigned int event_type, unsigned int offset, void *data) {
    static struct timespec last_press = {0};
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (timespec_subtract(&now, &last_press) > DEBOUNCE_INTERVAL_US) {
            button_pressed = 1;
        }
        last_press = now;
    }
}

int timespec_subtract(struct timespec *result, struct timespec *x) {
    if (x->tv_nsec < result->tv_nsec) {
        int nsec = (result->tv_nsec - x->tv_nsec) / 1000;
        result->tv_sec = x->tv_sec - result->tv_sec - 1;
        result->tv_nsec = 1000000000 - nsec;
    } else {
        int nsec = (x->tv_nsec - result->tv_nsec) / 1000;
        result->tv_sec = x->tv_sec - result->tv_sec;
        result->tv_nsec = nsec;
    }
