#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void log_event(FILE *log_file, int value) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return;
    }

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
    fprintf(log_file, "%s.%09ld %d\n", timestamp, ts.tv_nsec, value);
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;
    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        goto cleanup;
    }

    // Request line for input with edge detection
    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        goto cleanup;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        goto cleanup;
    }

    int event_count = 0;
    int event_window[WINDOW_SIZE] = {0};
    int current_index = 0;

    while (!exit_flag) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, timeout * 1000);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            continue;
        } else if (ret == 0) {
            continue; // Timeout occurred
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        int value = event.id == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0;
        log_event(log_file, value);

        // Update sliding window
        event_window[current_index] = value;
        current_index = (current_index + 1) % WINDOW_SIZE;

        // Count number of HIGH events in the window
        event_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (event_window[i] == 1) {
                event_count++;
            }
        }

        // Check for earthquake alert
        if (event_count >= 3) {
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
                continue;
            }

            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
            printf("EARTHQUAKE ALERT at %s.%09ld\n", timestamp, ts.tv_nsec);
        }
    }

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

