#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LSM303DLHC_ADDRESS 0x1E
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = 0x03; // Register for X MSB
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    return 0;
}

double calculate_heading(int16_t x, int16_t y) {
    double heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

const char* get_compass_direction(double heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading >= 22.5 && heading < 67.5) return "NE";
    if (heading >= 67.5 && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    if (heading >= 292.5 && heading < 337.5) return "NW";
    return "Unknown";
}

int main() {
    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read magnetometer data, skipping sample\n");
            continue;
        }

        int16_t calibrated_x = x + X_OFFSET;
        int16_t calibrated_y = y + Y_OFFSET;
        int16_t calibrated_z = z + Z_OFFSET;

        double heading = calculate_heading(calibrated_x, calibrated_y);
        const char* direction = get_compass_direction(heading);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %d, %d, %d, %.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
        fflush(log_file);

        printf("Direction: %s, Heading: %.2f\n", direction, heading);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

