void log_state_change(const char *state) {
    struct timespec current_time;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, &current_time);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&current_time));

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state);
    fflush(log_file);
}

void handle_sigint(int sig) {
    running = 0;
}

void toggle_relay(void) {
    int current_state = gpiod_line_get_value(relay_line);
    if (current_state < 0) {
        perror("Failed to get relay state");
        exit(EXIT_FAILURE);
    }

    int new_state = !current_state;
    int ret = gpiod_line_set_value(relay_line, new_state);
    if (ret < 0) {
        perror("Failed to set relay state");
        exit(EXIT_FAILURE);
    }

    log_state_change(new_state ? "ON" : "OFF");
}

void handle_touch_event(void) {
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    if (timespec_subtract(&current_time, &last_touch_time) >= DEBOUNCE_DELAY_US) {
        toggle_relay();
        last_touch_time = current_time;
    }
}

int timespec_subtract(struct timespec *result, struct timespec *x) {
    if (x->tv_nsec < last_touch_time.tv_nsec) {
        int nsec = (x->tv_nsec + 1000000000) - last_touch_time.tv_nsec;
        int sec = x->tv_sec - 1 - last_touch_time.tv_sec;
    } else {
        int nsec = x->tv_nsec - last_touch_time.tv_nsec;
        int sec = x->tv_sec - last_touch_time.tv_sec;
    }

    result->tv_sec = sec;
    result->tv_nsec = nsec;

    return (sec < 0) || (sec == 0 && nsec < 0);
}

int main(void) {
    int ret;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    touch_sensor_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_GPIO);
    if (!touch_sensor_line) {
        perror("Failed to get touch sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(touch_sensor_line, "touch_sensor");
    if (ret < 0) {
        perror("Failed to request input for touch sensor");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        perror("Failed to request output for relay");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("relay_log.json", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        int value = gpiod_line_get_value(touch_sensor_line);
        if (value < 0) {
            perror("Failed to get touch sensor value");
            break;
        }

        if (value == 0) {
            handle_touch_event();
        }

        usleep(10000); // Sleep for 10 ms
    }

    // Force relay OFF on exit
    ret = gpiod_line_set_value(relay_line, 0);
    if (ret < 0) {
        perror("Failed to set relay state to OFF");
    }

    log_state_change("OFF");

    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

