#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/time.h>

#define NUM_RELAYS 4
#define RELAY_PINS {17, 23, 24, 25}
#define MOISTURE_THRESHOLD 30
#define RELAY_DELAY 5
#define GAP_DELAY 1
#define LOG_FILE "irrigation_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *relays[NUM_RELAYS];
static FILE *log_file;

void log_event(const char *relay, int moisture) {
    struct timespec ts;
    char timestamp[30];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
    fprintf(log_file, "%s, Relay %s, Moisture %d\n", timestamp, relay, moisture);
    fflush(log_file);
}

void deactivate_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relays[i]) {
            gpiod_line_set_value(relays[i], 1);
        }
    }
}

void cleanup(void) {
    deactivate_relays();
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relays[i]) {
            gpiod_line_release(relays[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    int moisture;
    const int pin_numbers[NUM_RELAYS] = RELAY_PINS;

    srand(time(NULL));
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relays[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!relays[i]) {
            perror("gpiod_chip_get_line");
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(relays[i], "irrigation", 1) < 0) {
            perror("gpiod_line_request_output");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        moisture = rand() % 101;
        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(relays[i], 0);
                log_event(gpiod_line_get_name(relays[i]), moisture);
                sleep(RELAY_DELAY);
                gpiod_line_set_value(relays[i], 1);
                if (i < NUM_RELAYS - 1) {
                    sleep(GAP_DELAY);
                }
            }
        }
        sleep(10);
    }

    cleanup();
    return EXIT_SUCCESS;
}

