#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18
#define MOISTURE_VALUES {20, 40, 60, 80, 100}
#define MOISTURE_THRESHOLD 50
#define VALVE_OPEN_US 1500
#define VALVE_CLOSE_US 500
#define NOZZLE_ANGLES {500, 1000, 1500, 2000, 2500}
#define ANGLE_DELAY 2
#define SPRAY_DELAY 5
#define BACKOFF_MS 100
#define MAX_RETRIES 3

volatile sig_atomic_t sigint_received = 0;
volatile sig_atomic_t sigterm_received = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        sigint_received = 1;
    } else if (signum == SIGTERM) {
        sigterm_received = 1;
    }
}

int set_servo_angle(struct gpiod_chip *chip, unsigned int offset, unsigned int us) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, offset);
    if (!line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "watering", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        return -1;
    }

    usleep(us);

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int moisture_values[] = MOISTURE_VALUES;
    int nozzle_angles[] = NOZZLE_ANGLES;
    int num_moisture_values = sizeof(moisture_values) / sizeof(moisture_values[0]);
    int num_nozzle_angles = sizeof(nozzle_angles) / sizeof(nozzle_angles[0]);
    int current_moisture = 0;
    int i, j, ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    while (!sigint_received && !sigterm_received) {
        current_moisture = moisture_values[(time(NULL) / 1) % num_moisture_values];
        printf("Current moisture: %d\n", current_moisture);

        if (current_moisture < MOISTURE_THRESHOLD) {
            for (i = 0; i < MAX_RETRIES; i++) {
                ret = set_servo_angle(chip, VALVE_GPIO, VALVE_OPEN_US);
                if (ret == 0) {
                    break;
                }
                usleep(BACKOFF_MS * 1000);
            }
            if (ret != 0) {
                fprintf(stderr, "Failed to open valve after %d retries\n", MAX_RETRIES);
                break;
            }

            for (j = 0; j < num_nozzle_angles; j++) {
                for (i = 0; i < MAX_RETRIES; i++) {
                    ret = set_servo_angle(chip, NOZZLE_GPIO, nozzle_angles[j]);
                    if (ret == 0) {
                        break;
                    }
                    usleep(BACKOFF_MS * 1000);
                }
                if (ret != 0) {
                    fprintf(stderr, "Failed to set nozzle angle %d after %d retries\n", nozzle_angles[j], MAX_RETRIES);
                    continue;
                }
                sleep(ANGLE_DELAY);
            }

            sleep(SPRAY_DELAY);

            for (i = 0; i < MAX_RETRIES; i++) {
                ret = set_servo_angle(chip, VALVE_GPIO, VALVE_CLOSE_US);
                if (ret == 0) {
                    break;
                }
                usleep(BACKOFF_MS * 1000);
            }
            if (ret != 0) {
                fprintf(stderr, "Failed to close valve after %d retries\n", MAX_RETRIES);
            }
        }

        sleep(5);
    }

    for (i = 0; i < MAX_RETRIES; i++) {
        ret = set_servo_angle(chip, VALVE_GPIO, 0);
        if (ret == 0) {
            break;
        }
        usleep(BACKOFF_MS * 1000);
    }
    if (ret != 0) {
        fprintf(stderr, "Failed to stop valve after %d retries\n", MAX_RETRIES);
    }

    for (i = 0; i < MAX_RETRIES; i++) {
        ret = set_servo_angle(chip, NOZZLE_GPIO, 0);
        if (ret == 0) {
            break;
        }
        usleep(BACKOFF_MS * 1000);
    }
    if (ret != 0) {
        fprintf(stderr, "Failed to stop nozzle after %d retries\n", MAX_RETRIES);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

