                ret = set_servo_angle(chip, VALVE_GPIO, VALVE_OPEN_US);
                if (ret == 0) {
                    break;
                }
                usleep(BACKOFF_MS * 1000);
            }
            if (ret != 0) {
                fprintf(stderr, "Failed to open valve after %d retries\n", MAX_RETRIES);
                break;
            }

            for (j = 0; j < num_nozzle_angles; j++) {
                for (i = 0; i < MAX_RETRIES; i++) {
                    ret = set_servo_angle(chip, NOZZLE_GPIO, nozzle_angles[j]);
                    if (ret == 0) {
                        break;
                    }
                    usleep(BACKOFF_MS * 1000);
                }
                if (ret != 0) {
                    fprintf(stderr, "Failed to set nozzle angle %d after %d retries\n", nozzle_angles[j], MAX_RETRIES);
                    continue;
                }
                sleep(ANGLE_DELAY);
            }

            sleep(SPRAY_DELAY);

            for (i = 0; i < MAX_RETRIES; i++) {
                ret = set_servo_angle(chip, VALVE_GPIO, VALVE_CLOSE_US);
                if (ret == 0) {
                    break;
                }
                usleep(BACKOFF_MS * 1000);
            }
            if (ret != 0) {
                fprintf(stderr, "Failed to close valve after %d retries\n", MAX_RETRIES);
            }
        }

        sleep(5);
    }

    for (i = 0; i < MAX_RETRIES; i++) {
        ret = set_servo_angle(chip, VALVE_GPIO, 0);
        if (ret == 0) {
            break;
        }
        usleep(BACKOFF_MS * 1000);
    }
    if (ret != 0) {
        fprintf(stderr, "Failed to stop valve after %d retries\n", MAX_RETRIES);
    }

    for (i = 0; i < MAX_RETRIES; i++) {
        ret = set_servo_angle(chip, NOZZLE_GPIO, 0);
        if (ret == 0) {
            break;
        }
        usleep(BACKOFF_MS * 1000);
    }
    if (ret != 0) {
        fprintf(stderr, "Failed to stop nozzle after %d retries\n", MAX_RETRIES);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}
