#define MPU6050_ADDR 0x68
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG 0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_RATE 10

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, char data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int reg, char *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register to I2C");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read from I2C");
        return -1;
    }
    return 0;
}

int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2c_read_bytes(MPU6050_GYRO_XOUT_H, buf, 6) != 0) {
        return -1;
    }
    *x = (buf[0] << 8) | buf[1];
    *y = (buf[2] << 8) | buf[3];
    *z = (buf[4] << 8) | buf[5];
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(MPU6050_SMPLRT_DIV, 0x07) != 0 || // 10 Hz sample rate
        i2c_write_byte(MPU6050_CONFIG, 0x00) != 0 ||    // 250 Hz gyro
        i2c_write_byte(MPU6050_GYRO_CONFIG, 0x00) != 0 || // Full scale ± 250 °/s
        i2c_write_byte(MPU6050_ACCEL_CONFIG, 0x00) != 0) { // Full scale ± 2g
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(log_file);

        sleep(1 / SAMPLE_RATE);
    }

    cleanup();
    return EXIT_SUCCESS;
}

