#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define STEP_DELAY_US 3000

struct gpiod_chip *chip;
struct gpiod_line *lock_button_line;
struct gpiod_line *unlock_button_line;
struct gpiod_line *in1_line;
struct gpiod_line *in2_line;
struct gpiod_line *in3_line;
struct gpiod_line *in4_line;

void deenergize_coils() {
    gpiod_line_set_value(in1_line, 0);
    gpiod_line_set_value(in2_line, 0);
    gpiod_line_set_value(in3_line, 0);
    gpiod_line_set_value(in4_line, 0);
}

void rotate_motor(int steps, int direction) {
    for (int i = 0; i < steps; i++) {
        switch ((i / 1) % 4) {
            case 0:
                gpiod_line_set_value(in1_line, direction);
                gpiod_line_set_value(in2_line, 0);
                gpiod_line_set_value(in3_line, 0);
                gpiod_line_set_value(in4_line, 0);
                break;
            case 1:
                gpiod_line_set_value(in1_line, 0);
                gpiod_line_set_value(in2_line, direction);
                gpiod_line_set_value(in3_line, 0);
                gpiod_line_set_value(in4_line, 0);
                break;
            case 2:
                gpiod_line_set_value(in1_line, 0);
                gpiod_line_set_value(in2_line, 0);
                gpiod_line_set_value(in3_line, direction);
                gpiod_line_set_value(in4_line, 0);
                break;
            case 3:
                gpiod_line_set_value(in1_line, 0);
                gpiod_line_set_value(in2_line, 0);
                gpiod_line_set_value(in3_line, 0);
                gpiod_line_set_value(in4_line, direction);
                break;
        }
        usleep(STEP_DELAY_US);
    }
    deenergize_coils();
}

void handle_sigint(int sig) {
    deenergize_coils();
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    lock_button_line = gpiod_chip_get_line(chip, LOCK_BUTTON);
    unlock_button_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON);
    in1_line = gpiod_chip_get_line(chip, IN1);
    in2_line = gpiod_chip_get_line(chip, IN2);
    in3_line = gpiod_chip_get_line(chip, IN3);
    in4_line = gpiod_chip_get_line(chip, IN4);

    if (!lock_button_line || !unlock_button_line || !in1_line || !in2_line || !in3_line || !in4_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(lock_button_line, "lock_button");
    if (ret < 0) {
        perror("Failed to request input for lock button");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(unlock_button_line, "unlock_button");
    if (ret < 0) {
        perror("Failed to request input for unlock button");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(in1_line, "in1", 0);
    if (ret < 0) {
        perror("Failed to request output for IN1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(in2_line, "in2", 0);
    if (ret < 0) {
        perror("Failed to request output for IN2");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(in3_line, "in3", 0);
    if (ret < 0) {
        perror("Failed to request output for IN3");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(in4_line, "in4", 0);
    if (ret < 0) {
        perror("Failed to request output for IN4");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int lock_button_state = gpiod_line_get_value(lock_button_line);
        int unlock_button_state = gpiod_line_get_value(unlock_button_line);

        if (lock_button_state == 0) {
            printf("Locking door...\n");
            rotate_motor(512, 1);
            printf("Door locked.\n");
            while (gpiod_line_get_value(lock_button_line) == 0) {
                usleep(10000);
            }
        }

        if (unlock_button_state == 0) {
            printf("Unlocking door...\n");
            rotate_motor(512, -1);
            printf("Door unlocked.\n");
            while (gpiod_line_get_value(unlock_button_line) == 0) {
                usleep(10000);
            }
        }

        usleep(10000);
    }

    deenergize_coils();
    gpiod_chip_close(chip);
    return 0;
}

