#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define MIN_DELAY_US 60000
#define SAMPLE_INTERVAL_US 1000000

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

static void cleanup() {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static void signal_handler(int signum) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        cleanup();
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "ultrasonic_echo") < 0) {
        perror("Failed to request echo line as input");
        cleanup();
        return -1;
    }

    return 0;
}

static int measure_distance() {
    struct timespec start, end;
    int ret;

    // Generate 10us trigger pulse
    gpiod_line_set_value(trigger_line, 1);
    usleep(TRIGGER_PULSE_US);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for rising edge of echo
    ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
    if (ret < 0) {
        perror("Failed to wait for rising edge");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }

    if (gpiod_line_get_value(echo_line) != 1) {
        fprintf(stderr, "Echo line not high after rising edge\n");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("Failed to get start time");
        return -1;
    }

    // Wait for falling edge of echo
    ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
    if (ret < 0) {
        perror("Failed to wait for falling edge");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
