    while (running) {
        uint8_t buffer[2];
        uint16_t distance;

        // Read distance from VL53L1X
        buffer[0] = 0x00; // Register address for distance
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C");
            goto cleanup;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C");
            goto cleanup;
        }

        distance = (buffer[0] << 8) | buffer[1];

        // Print distance
        printf("Distance: %d mm\n", distance);

        // Set relay based on distance
        if (distance <= 500) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_US);
    }

cleanup:
    // Clean up resources
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

