    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    sda_line = gpiod_chip_get_line(chip, 2);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    scl_line = gpiod_chip_get_line(chip, 3);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        sda_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    return 0;
}

int init_mpu6050() {
    uint8_t data = 0;

    // Wake up the MPU6050
    data = 0;
    if (write(i2c_fd, &MPU6050_PWR_MGMT_1, 1) != 1 || write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }

    // Set gyro full scale range to ±250°/s
    data = 0x00;
    if (write(i2c_fd, &MPU6050_GYRO_CONFIG, 1) != 1 || write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to GYRO_CONFIG");
        return -1;
