        perror("Failed to write to GYRO_XOUT_H");
        return -1;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read from I2C");
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    return 0;
}

int main() {
    int16_t gyro_x, gyro_y, gyro_z;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (setup_i2c() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpiod() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Gyro X: %d, Y: %d, Z: %d\n", gyro_x, gyro_y, gyro_z);
        usleep(100000); // 100 ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

