#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {17, 18, 27, 22}
#define NUM_LINES 4
#define CYCLE_INTERVAL 86400
#define RELAY_ON_TIME 5
#define LOG_FILE "watering_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_LINES];
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_cycle_start() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

void release_resources() {
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            release_resources();
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_output(lines[i], "watering_system", 1);
        if (ret < 0) {
            perror("Failed to request GPIO line as output");
            release_resources();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        log_cycle_start();

        for (int i = 0; i < NUM_LINES; i++) {
            int ret = gpiod_line_set_value(lines[i], 0); // Activate relay (active-low)
            if (ret < 0) {
                perror("Failed to set GPIO line value");
