#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_US 50000
#define THRESHOLD 250

typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    printf("Received signal %d, cleaning up...\n", sig);
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t power_mgmt_1 = 0;
    if (write(i2c_fd, &power_mgmt_1, 1) != 1) {
        perror("Failed to write to MPU6050 power management register");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_gyro(GyroReading *reading) {
    uint8_t reg = MPU6050_GYRO_XOUT_H;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to MPU6050 register");
        return -1;
    }

    uint8_t data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read from MPU6050");
        return -1;
    }

    reading->x = (data[0] << 8) | data[1];
    reading->y = (data[2] << 8) | data[3];
    reading->z = (data[4] << 8) | data[5];

    clock_gettime(CLOCK_REALTIME, &reading->timestamp);

    return 0;
}

void update_led(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "gyro_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    int init_attempts = 0;
    while (init_i2c() < 0) {
        if (init_attempts >= 3) {
            fprintf(stderr, "Failed to initialize I2C after 3 attempts\n");
            cleanup();
            return EXIT_FAILURE;
        }
        init_attempts++;
        sleep(1);
    }

    while (1) {
        GyroReading reading;
        if (read_gyro(&reading) < 0) {
            fprintf(stderr, "Failed to read from MPU6050, attempting re-initialization\n");
            close(i2c_fd);
            i2c_fd = -1;
            init_attempts = 0;
            while (init_i2c() < 0) {
                if (init_attempts >= 3) {
                    fprintf(stderr, "Failed to initialize I2C after 3 attempts\n");
                    cleanup();
                    return EXIT_FAILURE;
                }
                init_attempts++;
                sleep(1);
            }
            continue;
        }

        buffer[buffer_index] = reading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        update_led(reading.x, reading.y, reading.z);

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

