#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define LED_GPIO 21
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    FILE *log_file;
    struct timespec ts;
    int16_t accel_x, accel_y, accel_z;
    double roll, pitch;
    char timestamp[20];

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize MPU6050
    uint8_t power_mgmt_1 = 0x00;
    if (write(i2c_fd, &power_mgmt_1, 1) != 1) {
        perror("Failed to initialize MPU6050");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request line for output
    if (gpiod_line_request_output(led_line, "tilt_indicator", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    while (running) {
        // Read accelerometer data
        uint8_t buffer[6];
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read accelerometer data");
            continue;
        }

        accel_x = (buffer[0] << 8) | buffer[1];
        accel_y = (buffer[2] << 8) | buffer[3];
        accel_z = (buffer[4] << 8) | buffer[5];

        // Calculate roll and pitch
        roll = atan2(accel_y, accel_z) * 180.0 / M_PI;
        pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180.0 / M_PI;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));

        // Print to console
        printf("Timestamp: %s, Roll: %.2f, Pitch: %.2f\n", timestamp, roll, pitch);

        // Log to file
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
        fflush(log_file);

        // Control LED
        if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

