        pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180.0 / M_PI;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts));

        // Print to console
        printf("Timestamp: %s, Roll: %.2f, Pitch: %.2f\n", timestamp, roll, pitch);

        // Log to file
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
        fflush(log_file);

        // Control LED
        if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
```

This code fulfills the user's request by reading tilt data from an MPU-6050 accelerometer/gyroscope on the I2C bus, computing roll and pitch, printing the values to the console, logging them to a file, controlling an LED based on the tilt values, and handling cleanup on a SIGINT signal.

