#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USEC 10000

#define ADXRS290_XOUT_L 0x00
#define ADXRS290_XOUT_H 0x01
#define ADXRS290_YOUT_L 0x02
#define ADXRS290_YOUT_H 0x03

#define READ_BIT 0x80

#define MAX_RETRIES 3

static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, 8);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "adxrs290_cs", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(cs_line);
        cs_line = NULL;
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    return 0;
}

int read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {reg | READ_BIT, 0};
    uint8_t rx[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .delay_usecs = SPI_DELAY_USEC,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to set CS line low");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to set CS line high");
        return -1;
    }

    *value = rx[1];
    return 0;
}

int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_l, x_h, y_l, y_h;

    if (read_register(ADXRS290_XOUT_L, &x_l) < 0 || read_register(ADXRS290_XOUT_H, &x_h) < 0 ||
        read_register(ADXRS290_YOUT_L, &y_l) < 0 || read_register(ADXRS290_YOUT_H, &y_h) < 0) {
        return -1;
    }

    *x_rate = (x_h << 8) | x_l;
    *y_rate = (y_h << 8) | y_l;
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_data.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,x_rate,y_rate\n");

    while (1) {
        int16_t x_rate, y_rate;
        struct timespec ts;

        if (read_gyro_data(&x_rate, &y_rate) < 0) {
            int retries = 0;
            while (retries < MAX_RETRIES) {
                fprintf(stderr, "Failed to read gyro data, retrying...\n");
                cleanup();
                if (init_spi() < 0 || init_gpio() < 0) {
                    fprintf(stderr, "Failed to reinitialize SPI or GPIO\n");
                    cleanup();
                    return EXIT_FAILURE;
                }
                if (read_gyro_data(&x_rate, &y_rate) == 0) {
                    break;
                }
                retries++;
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Failed to read gyro data after %d retries\n", MAX_RETRIES);
                cleanup();
                return EXIT_FAILURE;
            }
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            cleanup();
            return EXIT_FAILURE;
        }

        fprintf(log_file, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000, x_rate, y_rate);
        fflush(log_file);

        usleep(100000); // 100 Hz sampling rate
    }

    cleanup();
    return EXIT_SUCCESS;
}

