This code sets up a Raspberry Pi to monitor two tilt sensors using the libgpiod library. It logs seismic events to a file and triggers an alert on a specific GPIO pin. The program handles signals to perform a graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define BUFFER_SIZE 100
#define THRESHOLD 20.0
#define LED_GPIO 17
#define CE_GPIO 8

typedef struct {
    struct timespec timestamp;
    int16_t rate;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
volatile int buffer_head = 0;
volatile int buffer_tail = 0;
volatile int buffer_count = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void *monitor_thread(void *arg) {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    int ret;

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return NULL;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_output(led_line, "gyro_monitor", 0);
    if (ret < 0) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip);
        return NULL;
    }

    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        if (buffer_count > 0) {
            GyroReading reading = buffer[buffer_tail];
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
            buffer_count--;
            pthread_mutex_unlock(&buffer_mutex);

            if (abs(reading.rate) > THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            pthread_mutex_unlock(&buffer_mutex);
            usleep(10000); // Sleep for 10ms
        }
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    return NULL;
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *ce_line;
    uint8_t tx[2] = {0x80 | 0x02, 0x00}; // Read from X-axis rate register
    uint8_t rx[2];
    GyroReading reading;
    pthread_t monitor_tid;
    struct sigaction sa;
    int ret;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Get CE line
    ce_line = gpiod_chip_get_line(chip, CE_GPIO);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request CE line as output
    ret = gpiod_line_request_output(ce_line, "gyro_ce", 1);
    if (ret < 0) {
        perror("Failed to request CE line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Start monitor thread
    ret = pthread_create(&monitor_tid, NULL, monitor_thread, NULL);
    if (ret != 0) {
        perror("Failed to create monitor thread");
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Select CE line
        gpiod_line_set_value(ce_line, 0);

        // Perform SPI transfer
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 2,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
            .cs_change = 0,
        };

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }

        // Deselect CE line
        gpiod_line_set_value(ce_line, 1);

        // Convert received data to rate
        int16_t rate = (rx[0] << 8) | rx[1];
        rate = (rate >> 4) * 0.061; // Convert to deg/s

        // Timestamp the reading
        clock_gettime(CLOCK_MONOTONIC, &reading.timestamp);
        reading.rate = rate;

        // Store in buffer
        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_head] = reading;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }
        pthread_mutex_unlock(&buffer_mutex);

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up
    pthread_join(monitor_tid, NULL);
    gpiod_line_release(ce_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

