#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17
#define DEBOUNCE_MS 100
#define POLL_INTERVAL_MS 10

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;

void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "[%ld.%06ld] ERROR: %s\n", tv.tv_sec, tv.tv_usec, message);
    fflush(log_file);
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    log_error("Received signal to exit");
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        log_error("I2C write reg failed");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        log_error("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "touch_relay", 0) < 0) {
        log_error("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t last_status = 0;
    struct timeval last_change_time;
    gettimeofday(&last_change_time, NULL);

    while (1) {
        uint8_t status;
        if (i2c_read_byte(0x00, &status) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if ((status & 0x01) && !(last_status & 0x01)) {
            struct timeval current_time;
            gettimeofday(&current_time, NULL);
            if (current_time.tv_sec - last_change_time.tv_sec > 0 ||
                current_time.tv_usec - last_change_time.tv_usec > DEBOUNCE_MS * 1000) {
                int current_value = gpiod_line_get_value(relay_line);
                if (current_value < 0) {
                    log_error("Failed to get GPIO line value");
                    cleanup();
                    return EXIT_FAILURE;
                }
                if (gpiod_line_set_value(relay_line, !current_value) < 0) {
                    log_error("Failed to set GPIO line value");
                    cleanup();
                    return EXIT_FAILURE;
                }
                gettimeofday(&last_change_time, NULL);
            }
        }

        last_status = status;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

