#define READ_INTERVAL_US 50000
#define CONSECUTIVE_LOW_READS 3

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *led_line;
static FILE *log_file;

static void cleanup(void) {
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    int ret;
    int low_count = 0;
    struct timespec ts;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request flame sensor line
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        perror("Failed to request input for flame sensor");
        cleanup();
        return EXIT_FAILURE;
    }

