    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        perror("Failed to request output for buzzer");
        cleanup();
        return EXIT_FAILURE;
    }

