    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request output for LED");
        cleanup();
        return EXIT_FAILURE;
