#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define SOL1_PIN 17
#define SOL2_PIN 27
#define DISPENSE_INTERVAL 1000
#define HALF_INTERVAL (DISPENSE_INTERVAL / 2)

static struct gpiod_chip *chip;
static struct gpiod_line *sol1_line;
static struct gpiod_line *sol2_line;
static FILE *log_file;

void sigint_handler(int sig) {
    fprintf(stderr, "Caught SIGINT, deactivating solenoids and exiting.\n");
    gpiod_line_set_value(sol1_line, 0);
    gpiod_line_set_value(sol2_line, 0);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int init_gpio(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    sol1_line = gpiod_chip_get_line(chip, SOL1_PIN);
    sol2_line = gpiod_chip_get_line(chip, SOL2_PIN);

    if (!sol1_line || !sol2_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(sol1_line, "solenoid1", 0) < 0 ||
        gpiod_line_request_output(sol2_line, "solenoid2", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int log_dispense_event(void) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s: Solenoid1: %d ms, Solenoid2: %d ms\n", timestamp, HALF_INTERVAL, HALF_INTERVAL) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    return 0;
}

int dispense(void) {
    if (gpiod_line_set_value(sol1_line, 1) < 0) {
        perror("Failed to set solenoid1 value");
        return -1;
    }
    usleep(HALF_INTERVAL * 1000);

    if (gpiod_line_set_value(sol1_line, 0) < 0 || gpiod_line_set_value(sol2_line, 1) < 0) {
        perror("Failed to set solenoid values");
        return -1;
    }
    usleep(HALF_INTERVAL * 1000);

    if (gpiod_line_set_value(sol2_line, 0) < 0) {
        perror("Failed to set solenoid2 value");
        return -1;
    }

    return 0;
}

int main(void) {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("dispense_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (dispense() != 0) {
            fprintf(stderr, "Failed to dispense\n");
            break;
        }

        if (log_dispense_event() != 0) {
            fprintf(stderr, "Failed to log dispense event\n");
            break;
        }

        sleep(5);
    }

    gpiod_chip_close(chip);
    fclose(log_file);
    return EXIT_SUCCESS;
}

