#define ENA 24
#define ENB 25
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define LOG_FILE "balance_log.txt"
#define PID_INTERVAL_US 50000
#define MAX_SPEED 255
#define MIN_SPEED -255
#define OBSTACLE_THRESHOLD 20.0

static struct gpiod_chip *chip;
static struct gpiod_line *ena_line, *enb_line;
static struct gpiod_line *motor_a_forward, *motor_a_backward;
static struct gpiod_line *motor_b_forward, *motor_b_backward;
static FILE *log_file;

static void cleanup() {
    if (ena_line) gpiod_line_release(ena_line);
    if (enb_line) gpiod_line_release(enb_line);
    if (motor_a_forward) gpiod_line_release(motor_a_forward);
    if (motor_a_backward) gpiod_line_release(motor_a_backward);
    if (motor_b_forward) gpiod_line_release(motor_b_forward);
    if (motor_b_backward) gpiod_line_release(motor_b_backward);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

static void set_motor_speed(struct gpiod_line *forward, struct gpiod_line *backward, int speed) {
    if (speed > 0) {
        gpiod_line_set_value(forward, 1);
        gpiod_line_set_value(backward, 0);
        gpiod_line_set_value(ena_line, 1);
        gpiod_line_set_value(enb_line, 1);
    } else if (speed < 0) {
        gpiod_line_set_value(forward, 0);
        gpiod_line_set_value(backward, 1);
        gpiod_line_set_value(ena_line, 1);
        gpiod_line_set_value(enb_line, 1);
    } else {
        gpiod_line_set_value(forward, 0);
        gpiod_line_set_value(backward, 0);
        gpiod_line_set_value(ena_line, 0);
        gpiod_line_set_value(enb_line, 0);
    }
}

static float random_float(float min, float max) {
    return min + (float)rand() / RAND_MAX * (max - min);
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm_info = localtime(&tv.tv_sec);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s %.2f %.2f %d %d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    ena_line = gpiod_chip_get_line(chip, ENA);
    enb_line = gpiod_chip_get_line(chip, ENB);
    motor_a_forward = gpiod_chip_get_line(chip, MOTOR_A_FORWARD);
    motor_a_backward = gpiod_chip_get_line(chip, MOTOR_A_BACKWARD);
    motor_b_forward = gpiod_chip_get_line(chip, MOTOR_B_FORWARD);
    motor_b_backward = gpiod_chip_get_line(chip, MOTOR_B_BACKWARD);

    if (!ena_line || !enb_line || !motor_a_forward || !motor_a_backward || !motor_b_forward || !motor_b_backward) {
        perror("Failed to get GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(ena_line, "ena") < 0 ||
        gpiod_line_request_output(enb_line, "enb") < 0 ||
        gpiod_line_request_output(motor_a_forward, "motor_a_forward") < 0 ||
        gpiod_line_request_output(motor_a_backward, "motor_a_backward") < 0 ||
        gpiod_line_request_output(motor_b_forward, "motor_b_forward") < 0 ||
        gpiod_line_request_output(motor_b_backward, "motor_b_backward") < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    srand(time(NULL));

    while (1) {
        float tilt_error = random_float(-10.0, 10.0);
        float distance = random_float(2.0, 400.0);

        int motor_a_speed = (int)(tilt_error * 10); // Simple PID-like control
        int motor_b_speed = (int)(tilt_error * 10);

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -128; // Reverse at 50% speed
            motor_b_speed = -128;
        }

        motor_a_speed = fmin(fmax(motor_a_speed, MIN_SPEED), MAX_SPEED);
        motor_b_speed = fmin(fmax(motor_b_speed, MIN_SPEED), MAX_SPEED);

        set_motor_speed(motor_a_forward, motor_a_backward, motor_a_speed);
        set_motor_speed(motor_b_forward, motor_b_backward, motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        usleep(PID_INTERVAL_US);
    }

    cleanup();
    return 0;
}

