    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure sensor line as input with pull-down
    ret = gpiod_line_request_input(sensor_line, "touch_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure relay line as output
    ret = gpiod_line_request_output(relay_line, "relay_control", 0);
    if (ret < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            break;
        }

        if (sensor_value == 1) {
            // Toggle relay
            int current_relay_state = gpiod_line_get_value(relay_line);
            if (current_relay_state < 0) {
                perror("Failed to read relay state");
                break;
            }

            ret = gpiod_line_set_value(relay_line, !current_relay_state);
            if (ret < 0) {
                perror("Failed to set relay value");
                break;
            }

            // Debounce delay
            usleep(DEBOUNCE_DELAY_US);
        }

        // Sleep briefly to reduce CPU usage
        usleep(10000);
    }

    // Cleanup
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

