#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define ALSA_AVAILABLE 1
#define BUFFER_SIZE 1024
#define SAMPLE_RATE 8000
#define CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE
#define DEFAULT_SENSITIVITY 1.0
#define PWM_PERIOD 1000000 // 1 ms
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000000 // 1 ms

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void release_resources(snd_pcm_t *handle, struct gpiod_chip *chip, struct gpiod_line *red, struct gpiod_line *green, struct gpiod_line *blue) {
    if (handle) {
        snd_pcm_close(handle);
    }
    if (red) {
        gpiod_line_release(red);
    }
    if (green) {
        gpiod_line_release(green);
    }
    if (blue) {
        gpiod_line_release(blue);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

double compute_rms(short *buffer, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i] * buffer[i];
    }
    return sqrt(sum / size);
}

void map_amplitude_to_color(double rms, double sensitivity, struct gpiod_line *red, struct gpiod_line *green, struct gpiod_line *blue) {
    rms *= sensitivity;
    if (rms > 1.0) {
        rms = 1.0;
    }
    int duty_cycle = (int)(rms * PWM_DUTY_MAX);

    gpiod_line_set_value(red, duty_cycle > PWM_DUTY_MAX / 2);
    gpiod_line_set_value(green, duty_cycle > PWM_DUTY_MAX / 2);
    gpiod_line_set_value(blue, duty_cycle > PWM_DUTY_MAX / 2);
}

int main(int argc, char *argv[]) {
    double sensitivity = DEFAULT_SENSITIVITY;
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value. Must be positive.\n");
            return EXIT_FAILURE;
        }
    }

    setup_signal_handlers();

    snd_pcm_t *handle = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red = NULL, *green = NULL, *blue = NULL;

    if (ALSA_AVAILABLE) {
        int err = snd_pcm_open(&handle, "default", SND_PCM_STREAM_CAPTURE, 0);
        if (err < 0) {
            fprintf(stderr, "Cannot open audio device (%s)\n", snd_strerror(err));
            return EXIT_FAILURE;
        }

        snd_pcm_hw_params_t *params;
        snd_pcm_hw_params_alloca(&params);
        snd_pcm_hw_params_any(handle, params);
        snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
        snd_pcm_hw_params_set_format(handle, params, FORMAT);
        snd_pcm_hw_params_set_rate(handle, params, SAMPLE_RATE, 0);
        snd_pcm_hw_params_set_channels(handle, params, CHANNELS);
        snd_pcm_hw_params_set_buffer_size(handle, params, BUFFER_SIZE);
        snd_pcm_hw_params_set_period_size(handle, params, BUFFER_SIZE, 0);

        err = snd_pcm_hw_params(handle, params);
        if (err < 0) {
            fprintf(stderr, "Cannot set hardware parameters (%s)\n", snd_strerror(err));
            release_resources(handle, chip, red, green, blue);
            return EXIT_FAILURE;
        }

        err = snd_pcm_prepare(handle);
        if (err < 0) {
            fprintf(stderr, "Cannot prepare audio interface for use (%s)\n", snd_strerror(err));
            release_resources(handle, chip, red, green, blue);
            return EXIT_FAILURE;
        }
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open GPIO chip\n");
        release_resources(handle, chip, red, green, blue);
        return EXIT_FAILURE;
    }

    red = gpiod_chip_get_line(chip, 17);
    green = gpiod_chip_get_line(chip, 18);
    blue = gpiod_chip_get_line(chip, 27);

    if (!red || !green || !blue) {
        fprintf(stderr, "Cannot get GPIO lines\n");
        release_resources(handle, chip, red, green, blue);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(red, "mood_light_red", 0) < 0 ||
        gpiod_line_request_output(green, "mood_light_green", 0) < 0 ||
        gpiod_line_request_output(blue, "mood_light_blue", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO lines as output\n");
        release_resources(handle, chip, red, green, blue);
        return EXIT_FAILURE;
    }

    short buffer[BUFFER_SIZE];
    while (running) {
        if (ALSA_AVAILABLE) {
            int err = snd_pcm_readi(handle, buffer, BUFFER_SIZE);
            if (err == -EPIPE) {
                fprintf(stderr, "Buffer overrun, preparing audio interface\n");
                snd_pcm_prepare(handle);
                continue;
            } else if (err == -ESTRPIPE) {
                fprintf(stderr, "Audio interface suspended, resuming\n");
                snd_pcm_resume(handle);
                continue;
            } else if (err < 0) {
                fprintf(stderr, "Read from audio interface failed (%s)\n", snd_strerror(err));
                break;
            } else if (err != BUFFER_SIZE) {
                fprintf(stderr, "Short read, expected %d frames, got %d\n", BUFFER_SIZE, err);
                continue;
            }
        } else {
            // Simulate audio input with a sine wave
            static double phase = 0.0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                buffer[i] = (short)(32767 * sin(2 * M_PI * 440 * phase / SAMPLE_RATE));
                phase += 1.0;
            }
        }

        double rms = compute_rms(buffer, BUFFER_SIZE);
        map_amplitude_to_color(rms, sensitivity, red, green, blue);

        usleep(10000); // 10 ms
    }

    release_resources(handle, chip, red, green, blue);
    return EXIT_SUCCESS;
}

