#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define INTEGRATION_TIME 154 // 154 ms

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    struct sigaction sa;
    struct timespec ts;
    uint8_t buffer[8];
    uint16_t c, r, g, b;

    // Register signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Enable sensor and set integration time
    buffer[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buffer[1] = 0x03; // Power on and enable ADC
    if (write(i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "Failed to enable sensor: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    buffer[0] = TCS34725_COMMAND_BIT | TCS34725_ATIME;
    buffer[1] = 256 - INTEGRATION_TIME / 2.4; // 154 ms integration time
    if (write(i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "Failed to set integration time: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen("color_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header to CSV
    fprintf(csv_file, "Timestamp,C,R,G,B\n");

    while (running) {
        // Read sensor data
        buffer[0] = TCS34725_COMMAND_BIT | TCS34725_CDATAL;
        if (write(i2c_fd, buffer, 1) != 1) {
            fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
            c = r = g = b = 0;
        } else {
            if (read(i2c_fd, buffer, 8) != 8) {
                fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
                c = r = g = b = 0;
            } else {
                c = (buffer[1] << 8) | buffer[0];
                r = (buffer[3] << 8) | buffer[2];
                g = (buffer[5] << 8) | buffer[4];
                b = (buffer[7] << 8) | buffer[6];
            }
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            c = r = g = b = 0;
        }

        // Write data to CSV
        fprintf(csv_file, "%ld,%u,%u,%u,%u\n", ts.tv_sec, c, r, g, b);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close CSV file
    fclose(csv_file);

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

