#define SUNRISE_DURATION (1 * 60 * 60)
#define SUNSET_DURATION (1 * 60 * 60)
#define DAYTIME_DURATION (6 * 60 * 60)
#define NIGHTTIME_DURATION (14 * 60 * 60)

static struct gpiod_chip *chip;
static struct gpiod_line *relay1, *relay2, *relay3, *relay4;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (relay1) gpiod_line_release(relay1);
    if (relay2) gpiod_line_release(relay2);
    if (relay3) gpiod_line_release(relay3);
    if (relay4) gpiod_line_release(relay4);
    if (chip) gpiod_chip_close(chip);
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    relay1 = gpiod_chip_get_line(chip, RELAY1);
    relay2 = gpiod_chip_get_line(chip, RELAY2);
    relay3 = gpiod_chip_get_line(chip, RELAY3);
    relay4 = gpiod_chip_get_line(chip, RELAY4);

    if (!relay1 || !relay2 || !relay3 || !relay4) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines as output
    ret = gpiod_line_request_output(relay1, "relay1", 1);
    if (ret < 0) {
        perror("Failed to request output for relay1");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(relay2, "relay2", 1);
    if (ret < 0) {
        perror("Failed to request output for relay2");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(relay3, "relay3", 1);
    if (ret < 0) {
        perror("Failed to request output for relay3");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(relay4, "relay4", 1);
    if (ret < 0) {
        perror("Failed to request output for relay4");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        time_t start_time = time(NULL);
        time_t current_time = start_time;
        double phase_duration = SUNRISE_DURATION;
        double duty_cycle = 0.0;

        while (running && current_time - start_time < CYCLE_DURATION) {
            if (current_time - start_time >= SUNRISE_DURATION + DAYTIME_DURATION) {
                phase_duration = SUNSET_DURATION;
                duty_cycle = 1.0;
            } else if (current_time - start_time >= SUNRISE_DURATION) {
                phase_duration = DAYTIME_DURATION;
                duty_cycle = 1.0;
            } else {
                phase_duration = SUNRISE_DURATION;
                duty_cycle = (current_time - start_time) / SUNRISE_DURATION;
            }

            if (current_time - start_time >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION) {
                duty_cycle = 1.0 - ((current_time - start_time - (SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION)) / NIGHTTIME_DURATION);
            }

            if (duty_cycle < 0.0) duty_cycle = 0.0;
            if (duty_cycle > 1.0) duty_cycle = 1.0;

            ret = gpiod_line_set_value(relay1, duty_cycle < 0.5);
            if (ret < 0) {
                perror("Failed to set value for relay1");
                cleanup();
                return EXIT_FAILURE;
            }

            ret = gpiod_line_set_value(relay2, duty_cycle < 0.5);
            if (ret < 0) {
                perror("Failed to set value for relay2");
                cleanup();
                return EXIT_FAILURE;
            }

            ret = gpiod_line_set_value(relay3, duty_cycle < 0.5);
            if (ret < 0) {
                perror("Failed to set value for relay3");
                cleanup();
                return EXIT_FAILURE;
            }

            ret = gpiod_line_set_value(relay4, duty_cycle < 0.5);
            if (ret < 0) {
                perror("Failed to set value for relay4");
                cleanup();
                return EXIT_FAILURE;
            }

            usleep(1000000); // 1 second
            current_time = time(NULL);
        }
    }

    // Turn off all relays
    ret = gpiod_line_set_value(relay1, 1);
    if (ret < 0) {
        perror("Failed to turn off relay1");
    }

    ret = gpiod_line_set_value(relay2, 1);
    if (ret < 0) {
        perror("Failed to turn off relay2");
    }

    ret = gpiod_line_set_value(relay3, 1);
    if (ret < 0) {
        perror("Failed to turn off relay3");
    }

    ret = gpiod_line_set_value(relay4, 1);
    if (ret < 0) {
        perror("Failed to turn off relay4");
    }

    cleanup();
    return EXIT_SUCCESS;
}

