#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/wait.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_INTERVAL 200000 // 200 ms in microseconds
#define VIDEO_DURATION 5 // 5 seconds
#define VIDEO_PATH "/home/pi/videos/"
#define LOG_PATH "/home/pi/logs/motion_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction sa;
    struct timespec last_trigger = {0, 0};
    struct timespec current_time;
    char video_filename[100];
    char command[200];

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request line for input
    if (gpiod_line_request_input(line, "ir_sensor") < 0) {
        perror("gpiod_line_request_input");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_PATH, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read current time
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("clock_gettime");
            cleanup();
            exit(EXIT_FAILURE);
        }

        // Check if the sensor is triggered
        if (gpiod_line_get_value(line) == 0) {
            // Check debounce interval
            if (timespec_subtract(&current_time, &last_trigger) >= DEBOUNCE_INTERVAL) {
                // Update last trigger time
                last_trigger = current_time;

                // Generate timestamp for filename
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(video_filename, sizeof(video_filename), "%Y%m%d_%H%M%S.h264", tm_info);

                // Generate command for raspivid
                snprintf(command, sizeof(command), "raspivid -o %s%s -t %d", VIDEO_PATH, video_filename, VIDEO_DURATION * 1000);

                // Execute raspivid command
                if (system(command) != 0) {
                    perror("system");
                }

                // Log motion event
                char log_entry[100];
                strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%S", tm_info);
                fprintf(log_file, "%s\n", log_entry);
                fflush(log_file);
            }
        }

        // Sleep for a short period to reduce CPU usage
        usleep(10000); // 10 ms
    }

    cleanup();
    return 0;
}

int timespec_subtract(struct timespec *result, struct timespec *x, struct timespec *y) {
    if (x->tv_nsec < y->tv_nsec) {
        int nsec = (y->tv_nsec - x->tv_nsec) / 1000000000 + 1;
        y->tv_nsec -= 1000000000 * nsec;
        y->tv_sec += nsec;
    }
    if (x->tv_nsec - y->tv_nsec > 1000000000) {
        int nsec = (x->tv_nsec - y->tv_nsec) / 1000000000;
        y->tv_nsec += 1000000000 * nsec;
        y->tv_sec -= nsec;
    }

    result->tv_sec = x->tv_sec - y->tv_sec;
    result->tv_nsec = x->tv_nsec - y->tv_nsec;

    return x->tv_sec < y->tv_sec;
}

