#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

#define SAMPLE_INTERVAL_US 10000
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int init_mpu6050(int fd) {
    uint8_t data = 0;
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    // Wake up the MPU-6050
    data = 0;
    if (write(fd, &PWR_MGMT_1, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }

    // Set full scale range to ±250 °/s
    data = 0x00;
    if (write(fd, &GYRO_CONFIG, 1) != 1) {
        perror("Failed to write to GYRO_CONFIG");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to GYRO_CONFIG");
        return -1;
    }

    return 0;
}

int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (write(fd, &GYRO_XOUT_H, 1) != 1) {
        perror("Failed to write to GYRO_XOUT_H");
        return -1;
    }
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read from I2C");
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    return 0;
}

