#include <libgpiod.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22
#define LOG_FILE "irrigation_log.txt"
#define LOOP_INTERVAL 5

static struct gpiod_chip *chip;
static struct gpiod_line *relays[4];
static FILE *log_file;

void signal_handler(int signum) {
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(relays[i], 1) < 0) {
            perror("Failed to deactivate relay");
        }
    }
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_FAILURE);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        relays[i] = gpiod_chip_get_line(chip, (i == 0) ? RELAY1 : (i == 1) ? RELAY2 : (i == 2) ? RELAY3 : RELAY4);
        if (!relays[i]) {
            perror("Failed to get GPIO line");
            signal_handler(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(relays[i], "irrigation_system", 1) < 0) {
            perror("Failed to request GPIO line as output");
            signal_handler(EXIT_FAILURE);
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        signal_handler(EXIT_FAILURE);
    }

    while (1) {
        int moisture = rand() % 101;
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        for (int i = 0; i < 4; i++) {
            int relay_state = (moisture < 30) ? 0 : 1;
            if (gpiod_line_set_value(relays[i], relay_state) < 0) {
                perror("Failed to set GPIO line value");
                signal_handler(EXIT_FAILURE);
            }
            fprintf(log_file, "Moisture: %d, Relay %d: %s, Timestamp: %s\n", moisture, i + 1, relay_state ? "OFF" : "ON", timestamp);
        }

        fflush(log_file);
        sleep(LOOP_INTERVAL);
    }

    return EXIT_SUCCESS;
}

