#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27

#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION_US 500000
#define ALARM_DURATION_US 5000000

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_freefall(float x, float y, float z) {
    FILE *log_file = fopen("freefall.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(log_file);
}

int read_i2c_register(int reg) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

float convert_to_g(int16_t raw) {
    return raw * 0.00390625;
}

int main() {
    signal(SIGINT, sigint_handler);

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize ADXL345
    uint8_t data_format = 0x0B; // ±16g, 13-bit resolution
    if (write(i2c_fd, (uint8_t[]){ADXL345_REG_DATA_FORMAT, data_format}, 2) != 2) {
        perror("Failed to write data format");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t bw_rate = 0x0A; // 100 Hz
    if (write(i2c_fd, (uint8_t[]){ADXL345_REG_BW_RATE, bw_rate}, 2) != 2) {
        perror("Failed to write bandwidth rate");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t power_ctl = 0x08; // Measure mode
    if (write(i2c_fd, (uint8_t[]){ADXL345_REG_POWER_CTL, power_ctl}, 2) != 2) {
        perror("Failed to write power control");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "freefall_alarm", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct timespec start_time, end_time, delay_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    delay_time.tv_sec = 0;
    delay_time.tv_nsec = 500000000; // 500 ms

    while (running) {
        int16_t x_raw = read_i2c_register(ADXL345_REG_DATAX0);
        int16_t y_raw = read_i2c_register(ADXL345_REG_DATAX0 + 2);
        int16_t z_raw = read_i2c_register(ADXL345_REG_DATAX0 + 4);

        float x = convert_to_g(x_raw);
        float y = convert_to_g(y_raw);
        float z = convert_to_g(z_raw);

        if (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD) {
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            if (timespec_subtract(&end_time, &start_time) >= FREEFALL_DURATION_US) {
                // Confirm freefall after 0.5 seconds
                int16_t x_raw2 = read_i2c_register(ADXL345_REG_DATAX0);
                int16_t y_raw2 = read_i2c_register(ADXL345_REG_DATAX0 + 2);
                int16_t z_raw2 = read_i2c_register(ADXL345_REG_DATAX0 + 4);

                float x2 = convert_to_g(x_raw2);
                float y2 = convert_to_g(y_raw2);
                float z2 = convert_to_g(z_raw2);

                if (fabs(x2) < FREEFALL_THRESHOLD && fabs(y2) < FREEFALL_THRESHOLD && fabs(z2) < FREEFALL_THRESHOLD) {
                    // Trigger alarm
                    gpiod_line_set_value(line, 1);
                    log_freefall(x, y, z);
                    nanosleep(&delay_time, NULL);
                    gpiod_line_set_value(line, 0);
                }

                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
        } else {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        nanosleep(&delay_time, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

int timespec_subtract(struct timespec *result, const struct timespec *x, const struct timespec *y) {
    if (x->tv_nsec < y->tv_nsec) {
        int nsec = (y->tv_nsec - x->tv_nsec) / 1000;
        result->tv_sec = x->tv_sec - y->tv_sec - 1;
        result->tv_nsec = 1000000000 - nsec;
    } else {
        int nsec = (x->tv_nsec - y->tv_nsec) / 1000;
        result->tv_sec = x->tv_sec - y->tv_sec;
        result->tv_nsec = nsec;
    }

    return result->tv_sec < 0;
}

