    if (!echo_line) {
        perror("Failed to get ECHO line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "ultrasonic_trig", 0) < 0) {
        perror("Failed to request TRIG line as output");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "ultrasonic_echo") < 0) {
        perror("Failed to request ECHO line as input");
        cleanup();
        return -1;
    }

    return 0;
}

static void echo_rising_edge_callback(void *data) {
    pthread_mutex_lock(&mutex);
    start_tick = gpiod_line_event_get_timestamp_ns(data);
    echo_received = 1;
    pthread_mutex_unlock(&mutex);
}

static void echo_falling_edge_callback(void *data) {
    pthread_mutex_lock(&mutex);
    end_tick = gpiod_line_event_get_timestamp_ns(data);
    echo_received = 0;
    pthread_mutex_unlock(&mutex);
}

static int setup_interrupts(void) {
    struct gpiod_line_event_callback rising_callback = {
        .cb = echo_rising_edge_callback,
    };
    struct gpiod_line_event_callback falling_callback = {
        .cb = echo_falling_edge_callback,
    };

    if (gpiod_line_event_request_rising_edge(echo_line, &rising_callback) < 0) {
        perror("Failed to request rising edge event");
        cleanup();
        return -1;
