    echo_received = 0;
    pthread_mutex_unlock(&mutex);

    trigger_sensor();

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    start_tick = ts.tv_sec * 1000000000 + ts.tv_nsec;

    while (1) {
        pthread_mutex_lock(&mutex);
        current_tick = gpiod_line_event_get_timestamp_ns(echo_line);
        if (echo_received) {
            end_tick = current_tick;
            break;
        }
        pthread_mutex_unlock(&mutex);

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        uint32_t elapsed_ns = (now.tv_sec - ts.tv_sec) * 1000000000 + (now.tv_nsec - ts.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            pthread_mutex_unlock(&mutex);
            return -1; // Timeout
        }

        usleep(1000); // Sleep for 1 ms
    }

    pthread_mutex_unlock(&mutex);

    pulse_width_ns = end_tick - start_tick;
    if (pulse_width_ns > MAX_PULSE_WIDTH_US * 1000) {
        return -1; // Invalid pulse width
    }

    *distance_cm = pulse_width_ns / 58; // Convert ns to cm
    return 0;
}

