        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_interrupts() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
