            uint64_t timestamp_ns = ts.tv_sec * 1000000000 + ts.tv_nsec;
            fprintf(log_file, "%" PRIu64 ",%u\n", timestamp_ns, distance_cm);
            fflush(log_file);
        }

        usleep(TRIGGER_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
