#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <math.h>

#define LIS3DH_I2C_ADDR 0x18
#define LIS3DH_REG_CTRL_REG1 0x20
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_I2C_BUS "/dev/i2c-1"
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define RETRY_COUNT 3

static struct gpiod_chip *chip;
static struct gpiod_line *buzzer_line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void sigint_handler(int sig) {
    running = 0;
}

int i2c_write_reg(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int retries = RETRY_COUNT;
    while (retries--) {
        if (write(i2c_fd, buf, 2) == 2) {
            return 0;
        }
        perror("I2C write failed");
        if (retries > 0) {
            usleep(10000); // 10ms delay before retry
        }
    }
    return -1;
}

int i2c_read_reg(int reg, uint8_t *value) {
    uint8_t buf[1] = {reg};
    int retries = RETRY_COUNT;
    while (retries--) {
        if (write(i2c_fd, buf, 1) == 1 && read(i2c_fd, value, 1) == 1) {
            return 0;
        }
        perror("I2C read failed");
        if (retries > 0) {
            usleep(10000); // 10ms delay before retry
        }
    }
    return -1;
}

float read_acceleration(int reg) {
    uint8_t data[2];
    if (i2c_read_reg(reg, &data[0]) == 0 && i2c_read_reg(reg + 1, &data[1]) == 0) {
        int16_t value = (data[1] << 8) | data[0];
        return value * 0.004; // Convert to g
    }
    return 0.0;
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    signal(SIGINT, sigint_handler);

    // Initialize I2C
    i2c_fd = open(LIS3DH_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3DH_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize LIS3DH
    if (i2c_write_reg(LIS3DH_REG_CTRL_REG1, 0x77) < 0) { // Normal mode, 100 Hz, all axes enabled
        fprintf(stderr, "Failed to initialize LIS3DH\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    float prev_acceleration = 0.0;
    int freefall_detected = 0;

    while (running) {
        float x = read_acceleration(LIS3DH_REG_OUT_X_L);
        float y = read_acceleration(LIS3DH_REG_OUT_Y_L);
        float z = read_acceleration(LIS3DH_REG_OUT_Z_L);
        float magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude < freefall_threshold) {
            freefall_detected = 1;
        } else if (magnitude > impact_threshold && freefall_detected) {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(1000000); // 1 second
            gpiod_line_set_value(buzzer_line, 0);
            freefall_detected = 0;
        }

        usleep(10000); // 10ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

