#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define LIS3DH_I2C_ADDR_DEFAULT 0x18
#define LIS3DH_I2C_ADDR_MIN 0x18
#define LIS3DH_I2C_ADDR_MAX 0x19
#define LIS3DH_REG_CTRL_REG1 0x20
#define LIS3DH_REG_CTRL_REG4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D
#define LIS3DH_ODR_100HZ 0x60
#define LIS3DH_FS_2G 0x00
#define LIS3DH_HR_MODE 0x08
#define LIS3DH_I2C_BUS "/dev/i2c-1"
#define LOG_FILE "/var/log/high_acceleration.log"

int i2c_fd = -1;
int lis3dh_addr = LIS3DH_I2C_ADDR_DEFAULT;
float threshold = 2.0f;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    // Additional cleanup if needed
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

void log_high_acceleration(float x, float y, float z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: X=%.2f, Y=%.2f, Z=%.2f\n", asctime(tm_info), x, y, z);
    fclose(log_file);
}

float read_register(int reg) {
    uint8_t value;
    if (i2c_smbus_read_byte_data(i2c_fd, reg) < 0) {
        perror("Failed to read register");
        return 0.0f;
    }
    return (float)i2c_smbus_read_byte_data(i2c_fd, reg);
}

void read_acceleration(float *x, float *y, float *z) {
    *x = read_register(LIS3DH_REG_OUT_X_L) / 16.0f;
    *y = read_register(LIS3DH_REG_OUT_Y_L) / 16.0f;
    *z = read_register(LIS3DH_REG_OUT_Z_L) / 16.0f;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                lis3dh_addr = strtoul(optarg, NULL, 16);
                if (lis3dh_addr < LIS3DH_I2C_ADDR_MIN || lis3dh_addr > LIS3DH_I2C_ADDR_MAX) {
                    fprintf(stderr, "Invalid I2C address\n");
                    exit(EXIT_FAILURE);
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    exit(EXIT_FAILURE);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <address>] [-t <threshold>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, sigint_handler);

    i2c_fd = open(LIS3DH_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, lis3dh_addr) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(i2c_fd, LIS3DH_REG_CTRL_REG4, LIS3DH_FS_2G | LIS3DH_HR_MODE) < 0) {
        perror("Failed to write to CTRL_REG4");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(i2c_fd, LIS3DH_REG_CTRL_REG1, LIS3DH_ODR_100HZ) < 0) {
        perror("Failed to write to CTRL_REG1");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        float x, y, z;
        read_acceleration(&x, &y, &z);
        if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
            log_high_acceleration(x, y, z);
            system("sudo shutdown -h now");
            break;
        }
        usleep(100000);
    }

    cleanup();
    return 0;
}

