#define ALERT_PIN 22
#define BUFFER_SIZE 5
#define POLL_INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void init_gpio(struct gpiod_chip *chip, int pin, int direction, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request(*line, "line_following_robot", direction);
    if (ret < 0) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }
}

void motor_forward() {
    printf("Move forward\n");
}

void motor_left() {
    printf("Turn left\n");
}

void motor_right() {
    printf("Turn right\n");
}

void motor_stop() {
    printf("Stop\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *left_line, *center_line, *right_line, *alert_line;
    int left_sensor, center_sensor, right_sensor;
    int buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    int consecutive_no_line = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    init_gpio(chip, LEFT_SENSOR, GPIOD_LINE_REQUEST_DIR_IN, &left_line);
    init_gpio(chip, CENTER_SENSOR, GPIOD_LINE_REQUEST_DIR_IN, &center_line);
    init_gpio(chip, RIGHT_SENSOR, GPIOD_LINE_REQUEST_DIR_IN, &right_line);
    init_gpio(chip, ALERT_PIN, GPIOD_LINE_REQUEST_DIR_OUT, &alert_line);

    while (running) {
        left_sensor = gpiod_line_get_value(left_line);
        center_sensor = gpiod_line_get_value(center_line);
        right_sensor = gpiod_line_get_value(right_line);

        if (left_sensor < 0 || center_sensor < 0 || right_sensor < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        buffer[buffer_index] = center_sensor;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        int all_no_line = 1;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (buffer[i] == 0) {
                all_no_line = 0;
                break;
            }
        }

        if (all_no_line) {
            consecutive_no_line++;
        } else {
            consecutive_no_line = 0;
        }

        if (consecutive_no_line >= 5) {
            gpiod_line_set_value(alert_line, 1);
            usleep(2000000);
            gpiod_line_set_value(alert_line, 0);
            consecutive_no_line = 0;
        } else if (center_sensor == 0) {
            motor_forward();
        } else if (left_sensor == 0) {
            motor_left();
        } else if (right_sensor == 0) {
            motor_right();
        } else {
            motor_stop();
        }

        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(left_line);
    gpiod_line_release(center_line);
    gpiod_line_release(right_line);
    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);

    return 0;
}
