#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7210_ADDRESS 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MILLIT 5.0
#define POLL_ATTEMPTS 50
#define SAMPLE_INTERVAL_US 100000

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int i2c_fd;

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen("magnetic_events.txt", "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

void cleanup() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    log_event("Program terminated.");
}

void sigint_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_register(uint8_t reg, uint8_t *value) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        log_error("Failed to write to I2C register.");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        log_error("Failed to read from I2C register.");
        return -1;
    }
    return 0;
}

int write_register(uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        log_error("Failed to write to I2C register.");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus.");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI7210_ADDRESS) < 0) {
        log_error("Failed to set I2C slave address.");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        log_error("Failed to open GPIO chip.");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        log_error("Failed to get GPIO line.");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        log_error("Failed to request GPIO line as output.");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint8_t status;
        int attempts = 0;
        while (attempts < POLL_ATTEMPTS) {
            if (read_register(0x00, &status) == 0) {
                break;
            }
            attempts++;
            usleep(1000);
        }
        if (attempts == POLL_ATTEMPTS) {
            log_error("Timeout waiting for status register to clear.");
            continue;
        }

        uint8_t field_msb, field_lsb;
        if (read_register(0x01, &field_msb) < 0 || read_register(0x02, &field_lsb) < 0) {
            log_error("Failed to read magnetic field data.");
            gpiod_line_set_value(relay_line, 0);
            continue;
        }

        int16_t field_value = (field_msb << 8) | field_lsb;
        double field_millit = field_value * 0.1; // Convert to mT

        char event_message[100];
        snprintf(event_message, sizeof(event_message), "Magnetic field: %.1f mT", field_millit);
        log_event(event_message);

        if (field_millit > THRESHOLD_MILLIT) {
            gpiod_line_set_value(relay_line, 1);
            log_event("Relay activated.");
        } else {
            gpiod_line_set_value(relay_line, 0);
            log_event("Relay deactivated.");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

