#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_LINE 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static int server_fd, new_socket;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    log_event("Received signal to terminate");
    cleanup();
    exit(signum);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    int valread;

    // Initialize GPIO
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Bind socket
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Listen
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Server started and listening on port 5000");

    while (1) {
        // Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            continue;
        }

        valread = read(new_socket, buffer, BUFFER_SIZE);
        if (valread <= 0) {
            perror("Read failed");
            close(new_socket);
            continue;
        }

        // Remove trailing whitespace
        buffer[strcspn(buffer, "\r\n")] = 0;

        if (strcasecmp(buffer, "ON") == 0) {
            gpiod_line_set_value(line, 1);
            log_event("Relay turned ON");
        } else if (strcasecmp(buffer, "OFF") == 0) {
            gpiod_line_set_value(line, 0);
            log_event("Relay turned OFF");
        } else {
            log_event("Invalid command received");
        }

        close(new_socket);
    }

    cleanup();
    return EXIT_SUCCESS;
}

