#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x48
#define SENSOR2_ADDR 0x49
#define RELAY_GPIO 18
#define START_MEASUREMENT_CMD {0x36, 0x15}
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define MIN_FLOW_RATE 5.0

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int i2c_fd, uint8_t addr, uint8_t *data) {
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    uint8_t cmd[2] = START_MEASUREMENT_CMD;
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to send start measurement command");
        return -1;
    }

    usleep(100000); // Wait for measurement to complete

    if (read(i2c_fd, data, 3) != 3) {
        perror("Failed to read sensor data");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd1 = open(I2C_BUS, O_RDWR);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C bus 1");
        return EXIT_FAILURE;
    }

    int i2c_fd2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C bus 1");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get GPIO line");
