    uint8_t cmd[2] = START_MEASUREMENT_CMD;
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to send start measurement command");
        return -1;
    }

    usleep(100000); // Wait for measurement to complete

    if (read(i2c_fd, data, 3) != 3) {
        perror("Failed to read sensor data");
        return -1;
    }

    return 0;
}

