#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24
#define POLL_INTERVAL_US 200000
#define MOTOR_HOLD_TIME_US 5000000
#define DRY_CONSECUTIVE_POLLS 3

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *ena_line;
static struct gpiod_line *in1_line;
static struct gpiod_line *in2_line;
static volatile sig_atomic_t running = 1;

void log_event(int priority, const char *message) {
    syslog(priority, "rain_window: %s", message);
}

void stop_motor() {
    if (gpiod_line_set_value(ena_line, 0) < 0) {
        log_event(LOG_ERR, "Failed to set ENA low");
    }
    if (gpiod_line_set_value(in1_line, 0) < 0) {
        log_event(LOG_ERR, "Failed to set IN1 low");
    }
    if (gpiod_line_set_value(in2_line, 0) < 0) {
        log_event(LOG_ERR, "Failed to set IN2 low");
    }
}

void handle_signal(int sig) {
    running = 0;
    log_event(LOG_INFO, "Received signal, shutting down");
    stop_motor();
}

int main() {
    openlog("rain_window", LOG_PID, LOG_USER);
    log_event(LOG_INFO, "Starting rain window control program");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    ena_line = gpiod_chip_get_line(chip, ENA_PIN);
    in1_line = gpiod_chip_get_line(chip, IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, IN2_PIN);

    if (!sensor_line || !ena_line || !in1_line || !in2_line) {
        log_event(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "rain_sensor") < 0) {
        log_event(LOG_ERR, "Failed to request input on sensor line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0) {
        log_event(LOG_ERR, "Failed to request output on ENA line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        log_event(LOG_ERR, "Failed to request output on IN1 line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        log_event(LOG_ERR, "Failed to request output on IN2 line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    int consecutive_dry_polls = 0;
    int last_sensor_state = 1; // Assume initially dry

    while (running) {
        int sensor_state = gpiod_line_get_value(sensor_line);
        if (sensor_state < 0) {
            log_event(LOG_ERR, "Failed to read sensor state");
            break;
        }

        if (sensor_state == 0) {
            consecutive_dry_polls = 0;
        } else {
            consecutive_dry_polls++;
        }

        if (sensor_state == 1 && last_sensor_state == 0 && consecutive_dry_polls >= DRY_CONSECUTIVE_POLLS) {
            log_event(LOG_INFO, "Rain detected, starting close-window sequence");
            if (gpiod_line_set_value(ena_line, 1) < 0) {
                log_event(LOG_ERR, "Failed to set ENA high");
                break;
            }
            if (gpiod_line_set_value(in1_line, 1) < 0) {
                log_event(LOG_ERR, "Failed to set IN1 high");
                break;
            }
            if (gpiod_line_set_value(in2_line, 0) < 0) {
                log_event(LOG_ERR, "Failed to set IN2 low");
                break;
            }
            usleep(MOTOR_HOLD_TIME_US);
            stop_motor();
            log_event(LOG_INFO, "Motor stopped");
        }

        last_sensor_state = sensor_state;
        usleep(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down");
    stop_motor();
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

