#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define PULSE_LOCK 2000
#define PULSE_UNLOCK 1000
#define PULSE_STOP 0
#define DEBOUNCE_DELAY 200000 // 200 ms

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *servo_line, *lock_button_line, *unlock_button_line;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request servo line
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        perror("Failed to get servo line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request lock button line
    lock_button_line = gpiod_chip_get_line(chip, LOCK_BUTTON_PIN);
    if (!lock_button_line) {
        perror("Failed to get lock button line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request unlock button line
    unlock_button_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON_PIN);
    if (!unlock_button_line) {
        perror("Failed to get unlock button line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure servo line as output
    ret = gpiod_line_request_output(servo_line, "servo", 0);
    if (ret < 0) {
        perror("Failed to request servo line as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure button lines as input with pull-up
    ret = gpiod_line_request_input(lock_button_line, "lock_button");
    if (ret < 0) {
        perror("Failed to request lock button line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(unlock_button_line, "unlock_button");
    if (ret < 0) {
        perror("Failed to request unlock button line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set internal pull-up resistors
    ret = gpiod_line_set_config(lock_button_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set pull-up resistor for lock button");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_config(unlock_button_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set pull-up resistor for unlock button");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Check lock button
        if (gpiod_line_get_value(lock_button_line) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpiod_line_get_value(lock_button_line) == 0) {
                ret = gpiod_line_set_value(servo_line, 1);
                if (ret < 0) {
                    perror("Failed to set servo line for lock");
                    gpiod_chip_close(chip);
                    exit(EXIT_FAILURE);
                }
                usleep(PULSE_LOCK);
                ret = gpiod_line_set_value(servo_line, 0);
                if (ret < 0) {
                    perror("Failed to stop servo line for lock");
                    gpiod_chip_close(chip);
                    exit(EXIT_FAILURE);
                }
                printf("Lock\n");
            }
        }

        // Check unlock button
        if (gpiod_line_get_value(unlock_button_line) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpiod_line_get_value(unlock_button_line) == 0) {
                ret = gpiod_line_set_value(servo_line, 1);
                if (ret < 0) {
                    perror("Failed to set servo line for unlock");
                    gpiod_chip_close(chip);
                    exit(EXIT_FAILURE);
                }
                usleep(PULSE_UNLOCK);
                ret = gpiod_line_set_value(servo_line, 0);
                if (ret < 0) {
                    perror("Failed to stop servo line for unlock");
                    gpiod_chip_close(chip);
                    exit(EXIT_FAILURE);
                }
                printf("Unlock\n");
            }
        }

        usleep(10000); // Sleep for 10 ms to keep CPU usage low
    }

    // Stop the servo
    ret = gpiod_line_set_value(servo_line, 1);
    if (ret < 0) {
        perror("Failed to set servo line for stop");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    usleep(PULSE_STOP);
    ret = gpiod_line_set_value(servo_line, 0);
    if (ret < 0) {
        perror("Failed to stop servo line for stop");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    printf("Shutdown\n");

    // Release resources
    gpiod_line_release(servo_line);
    gpiod_line_release(lock_button_line);
    gpiod_line_release(unlock_button_line);
    gpiod_chip_close(chip);

    return 0;
}

