#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_GPIO 4
#define FLOODLIGHT_GPIO 17
#define POLL_INTERVAL_US 100000
#define LOG_FILE "security_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *floodlight_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void log_event(const char *event, double duration) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "%s %s", timestamp, event) < 0) {
        perror("fprintf");
        running = 0;
    }
    if (duration >= 0 && fprintf(log_file, " %.2f\n", duration) < 0) {
        perror("fprintf");
        running = 0;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        running = 0;
    }
}

void signal_handler(int signum) {
    running = 0;
}

void cleanup() {
    if (floodlight_line) {
        gpiod_line_release(floodlight_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int ret;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        return EXIT_FAILURE;
    }

    // Request PIR GPIO line
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(pir_line, "pir_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request floodlight GPIO line
    floodlight_line = gpiod_chip_get_line(chip, FLOODLIGHT_GPIO);
    if (!floodlight_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(floodlight_line, "floodlight", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    int last_state = 0;
    time_t start_time = 0;

    while (running) {
        int current_state = gpiod_line_get_value(pir_line);
        if (current_state < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (current_state && !last_state) {
            // Rising edge detected
            start_time = time(NULL);
            log_event("Motion detected, floodlight ON", -1);
            gpiod_line_set_value(floodlight_line, 1);
        } else if (!current_state && last_state) {
            // Falling edge detected
            double duration = difftime(time(NULL), start_time);
            log_event("Floodlight OFF", duration);
            gpiod_line_set_value(floodlight_line, 0);
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

    // Ensure floodlight is off on exit
    gpiod_line_set_value(floodlight_line, 0);

    cleanup();
    return EXIT_SUCCESS;
}

