#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17

#define MPR121_SOFT_RESET 0x80
#define MPR121_ECR 0x5E
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_DEBOUNCE 0x2B
#define MPR121_FFI 0x2C
#define MPR121_SFI 0x2D
#define MPR121_CDT 0x2E
#define MPR121_AFE0 0x5C
#define MPR121_AFE1 0x5D
#define MPR121_E0_TCH 0x00

#define MHD 0x01
#define NHD 0x01
#define NCL 0x0E
#define FDL 0x00
#define DEBOUNCE 0x01
#define FFI 0x20
#define SFI 0x20
#define CDT 0x05

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int mpr121_init() {
    if (i2c_write_byte(i2c_fd, MPR121_SOFT_RESET, 0x63) < 0) {
        return -1;
    }
    usleep(10000);

    if (i2c_write_byte(i2c_fd, MPR121_MHD_R, MHD) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_NHD_R, NHD) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_NCL_R, NCL) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_FDL_R, FDL) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_DEBOUNCE, DEBOUNCE) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_FFI, FFI) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_SFI, SFI) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_CDT, CDT) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_AFE0, 0x10) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_AFE1, 0x10) < 0) {
        return -1;
    }
    if (i2c_write_byte(i2c_fd, MPR121_ECR, 0x01) < 0) {
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t last_touched = 0;
    while (running) {
        uint8_t touched;
        if (i2c_read_byte(i2c_fd, MPR121_E0_TCH, &touched) < 0) {
            fprintf(stderr, "Failed to read MPR121 touch status\n");
            break;
        }

        if (touched & 0x01 && !(last_touched & 0x01)) {
            gpiod_line_set_value(relay_line, !gpiod_line_get_value(relay_line));
            usleep(200000);
        }

        last_touched = touched;
        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

