#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_PIN 23
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 2
#define MIN_LUX 150
#define DELAY_AFTER_TRIGGER 120000 // 120 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *relay_line;
    FILE *log_file;
    int lux;
    struct timespec ts;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    if (!(chip = gpiod_chip_open_by_label("gpiochip0"))) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get relay line
    if (!(relay_line = gpiod_chip_get_line(chip, RELAY_PIN))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request line for output
    if (gpiod_line_request_output(relay_line, "grow-light", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if (!(log_file = fopen(LOG_FILE, "a"))) {
        perror("Failed to open log file");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Trigger measurement
        if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Failed to trigger measurement");
            goto retry;
        }

        // Wait for measurement to complete
        usleep(DELAY_AFTER_TRIGGER);

        // Read lux value
        uint8_t buffer[2];
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read lux value");
            goto retry;
        }

        lux = (buffer[0] << 8) | buffer[1];
        lux /= 1.2; // Convert to lux

        // Log timestamp and lux value
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            fprintf(log_file, "%ld.%09ld, %d lux\n", ts.tv_sec, ts.tv_nsec, lux);
            fflush(log_file);
        } else {
            perror("Failed to get timestamp");
        }

        // Control relay
        if (lux < MIN_LUX) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

retry:
        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

