#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <time.h>

#define DOUT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 25
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define READ_TIMEOUT 1000000 // 1 second in microseconds
#define MAX_RETRIES 3
#define AVG_READINGS 5
#define TARE_READINGS 10

static struct gpiod_chip *chip;
static struct gpiod_line *dout_line;
static struct gpiod_line *sck_line;
static struct gpiod_line *lock_line;
static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

void cleanup() {
    if (lock_line) {
        gpiod_line_release(lock_line);
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int read_hx711(double *value) {
    int retries = 0;
    struct timespec start, now;
    long elapsed;

    while (retries < MAX_RETRIES) {
        if (gpiod_line_get_value(dout_line) == 0) {
            break;
        }
        retries++;
        usleep(100000); // 100 ms delay before retry
    }

    if (retries == MAX_RETRIES) {
        syslog(LOG_ERR, "Failed to read HX711 after %d retries", MAX_RETRIES);
        return -1;
    }

    int data = 0;
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1);
        data = (data << 1) | gpiod_line_get_value(dout_line);
        gpiod_line_set_value(sck_line, 0);
        usleep(1);
    }

    gpiod_line_set_value(sck_line, 1); // Settling pulse
    usleep(1);
    gpiod_line_set_value(sck_line, 0);

    *value = (double)data;
    return 0;
}

double tare_hx711() {
    double sum = 0.0;
    for (int i = 0; i < TARE_READINGS; i++) {
        double value;
        if (read_hx711(&value) == 0) {
            sum += value;
        }
    }
    return sum / TARE_READINGS;
}

double read_weight(double scale) {
    double sum = 0.0;
    for (int i = 0; i < AVG_READINGS; i++) {
        double value;
        if (read_hx711(&value) == 0) {
            sum += value;
        }
    }
    return (sum / AVG_READINGS) * scale;
}

int main(int argc, char *argv[]) {
    openlog("hx711_monitor", LOG_PID | LOG_CONS, LOG_USER);

    int threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = atof(argv[++i]);
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            duration = atoi(argv[++i]);
        } else {
            fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
            exit(EXIT_FAILURE);
        }
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);

    if (!dout_line || !sck_line || !lock_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(dout_line, "hx711_dout") < 0 ||
        gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0 ||
        gpiod_line_request_output(lock_line, "solenoid_lock", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        cleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    double tare_offset = tare_hx711();
    syslog(LOG_INFO, "Tare offset: %f", tare_offset);

    while (running) {
        double weight = read_weight(scale) - tare_offset;
        syslog(LOG_INFO, "Weight: %f grams", weight);

        if (weight > threshold) {
            gpiod_line_set_value(lock_line, 1);
            usleep(duration * 1000);
            gpiod_line_set_value(lock_line, 0);
        }

        usleep(500000); // 500 ms delay
    }

    cleanup();
    closelog();
    return 0;
}
