#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define KEEP_ALIVE 60
#define RECONNECT_DELAY 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void log_info(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void gpio_init(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(*line, "relay_controller", 0);
    if (ret < 0) {
        log_error("Failed to request GPIO line as output");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }
}

void gpio_cleanup(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        log_info("Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        log_error("Failed to connect to MQTT broker: %d", rc);
    }
}

void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (strcmp(msg->topic, MQTT_TOPIC) == 0) {
        if (msg->payloadlen == 2 && strcmp((char *)msg->payload, "ON") == 0) {
            log_info("Relay set to ON");
            gpiod_line_set_value((struct gpiod_line *)userdata, 1);
        } else if (msg->payloadlen == 3 && strcmp((char *)msg->payload, "OFF") == 0) {
            log_info("Relay set to OFF");
            gpiod_line_set_value((struct gpiod_line *)userdata, 0);
        } else {
            log_error("Invalid payload: %.*s", msg->payloadlen, (char *)msg->payload);
        }
    }
}

void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("Unexpected disconnection from MQTT broker: %d", rc);
    } else {
        log_info("Disconnected from MQTT broker");
    }
}

void mqtt_error_callback(struct mosquitto *mosq, void *userdata, const char *err) {
    log_error("MQTT error: %s", err);
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    gpio_init(&chip, &line);

    struct mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID, true, line);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        gpio_cleanup(chip, line);
        closelog();
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_error_callback_set(mosq, mqtt_error_callback);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEP_ALIVE);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to connect to MQTT broker: %d", rc);
            sleep(RECONNECT_DELAY);
            continue;
        }

        while (running) {
            rc = mosquitto_loop(mosq, -1, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("MQTT loop error: %d", rc);
                break;
            }
        }

        mosquitto_disconnect(mosq);
        sleep(RECONNECT_DELAY);
    }

    mosquitto_destroy(mosq);
    gpio_cleanup(chip, line);
    closelog();

    return 0;
}

