#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_1_GPIO 7
#define SERVO_2_GPIO 8
#define SERVO_3_GPIO 9
#define SERVO_4_GPIO 10
#define SERVO_5_GPIO 11

#define PULSE_MIN 500
#define PULSE_MAX 2500
#define PULSE_TARGETS {1000, 1500, 2000, 500, 2500}
#define PWM_FREQUENCY 50

int main() {
    int gpio_pins[] = {SERVO_1_GPIO, SERVO_2_GPIO, SERVO_3_GPIO, SERVO_4_GPIO, SERVO_5_GPIO};
    int pulse_targets[] = PULSE_TARGETS;
    int num_servos = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(gpio_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pins[i]);
            goto cleanup;
        }
        if (gpioSetPWMfrequency(gpio_pins[i], PWM_FREQUENCY) != PWM_FREQUENCY) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio_pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        int pulse_width = pulse_targets[i];
        if (pulse_width < PULSE_MIN || pulse_width > PULSE_MAX) {
            fprintf(stderr, "Pulse width %d out of range for GPIO %d\n", pulse_width, gpio_pins[i]);
            continue;
        }
        gpioPWM(gpio_pins[i], (pulse_width * PWM_FREQUENCY) / 1000);
        printf("Setting GPIO %d to %d us pulse width\n", gpio_pins[i], pulse_width);
        sleep(3);
    }

cleanup:
    for (int i = 0; i < num_servos; i++) {
        gpioPWM(gpio_pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

