#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>
#include <libgpiod.h>

#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12

#define PWM_FREQ 10000
#define CONTROL_INTERVAL 100000 // 100 ms in microseconds
#define TARGET_RPM 50
#define Ticks_PER_REV 64
#define RPM_TO_TICKS_PER_SEC (Ticks_PER_REV * TARGET_RPM / 60)
#define MAX_DUTY_CYCLE 255

static struct gpiod_chip *chip;
static struct gpiod_line *motor_a_pwm, *motor_a_dir, *motor_b_pwm, *motor_b_dir;
static struct gpiod_line *encoder_a_a, *encoder_a_b, *encoder_b_a, *encoder_b_b;

static atomic_int encoder_a_ticks = 0;
static atomic_int encoder_b_ticks = 0;
static atomic_bool encoder_stall_a = false;
static atomic_bool encoder_stall_b = false;

static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void *control_loop(void *arg) {
    struct timespec last_time, current_time;
    double dt;
    int last_a_ticks = 0, last_b_ticks = 0;
    double integral_a = 0, integral_b = 0;
    double error_a, error_b;
    int duty_cycle_a, duty_cycle_b;

    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        dt = (current_time.tv_sec - last_time.tv_sec) + (current_time.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = current_time;

        int current_a_ticks = atomic_load(&encoder_a_ticks);
        int current_b_ticks = atomic_load(&encoder_b_ticks);

        error_a = RPM_TO_TICKS_PER_SEC * dt - (current_a_ticks - last_a_ticks);
        error_b = RPM_TO_TICKS_PER_SEC * dt - (current_b_ticks - last_b_ticks);

        integral_a += error_a * dt;
        integral_b += error_b * dt;

        // Anti-windup
        if (integral_a > MAX_DUTY_CYCLE) integral_a = MAX_DUTY_CYCLE;
        if (integral_a < -MAX_DUTY_CYCLE) integral_a = -MAX_DUTY_CYCLE;
        if (integral_b > MAX_DUTY_CYCLE) integral_b = MAX_DUTY_CYCLE;
        if (integral_b < -MAX_DUTY_CYCLE) integral_b = -MAX_DUTY_CYCLE;

        duty_cycle_a = (int)(error_a * 10 + integral_a);
        duty_cycle_b = (int)(error_b * 10 + integral_b);

        if (duty_cycle_a > MAX_DUTY_CYCLE) duty_cycle_a = MAX_DUTY_CYCLE;
        if (duty_cycle_a < 0) duty_cycle_a = 0;
        if (duty_cycle_b > MAX_DUTY_CYCLE) duty_cycle_b = MAX_DUTY_CYCLE;
        if (duty_cycle_b < 0) duty_cycle_b = 0;

        gpiod_line_set_value(motor_a_dir, 1);
        gpiod_line_set_value(motor_b_dir, 1);
        gpiod_line_set_value(motor_a_pwm, duty_cycle_a);
        gpiod_line_set_value(motor_b_pwm, duty_cycle_b);

        printf("Motor A RPM: %.2f, PWM: %d\n", (current_a_ticks - last_a_ticks) / dt * 60 / Ticks_PER_REV, duty_cycle_a);
        printf("Motor B RPM: %.2f, PWM: %d\n", (current_b_ticks - last_b_ticks) / dt * 60 / Ticks_PER_REV, duty_cycle_b);

        last_a_ticks = current_a_ticks;
        last_b_ticks = current_b_ticks;

        nanosleep((const struct timespec[]){{0, CONTROL_INTERVAL * 1000}}, NULL);
    }

    return NULL;
}

void encoder_a_callback(const struct gpiod_line_event *event) {
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        atomic_fetch_add(&encoder_a_ticks, 1);
        atomic_store(&encoder_stall_a, false);
    }
}

void encoder_b_callback(const struct gpiod_line_event *event) {
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        atomic_fetch_add(&encoder_b_ticks, 1);
        atomic_store(&encoder_stall_b, false);
    }
}

void *stall_detection(void *arg) {
