#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define LOG_FILE "chicken_coop_log.txt"
#define POLL_INTERVAL 5
#define LUX_THRESHOLD_DARK 50
#define LUX_THRESHOLD_LIGHT 200
#define HYSTERESIS 20

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_lux(int i2c_fd) {
    uint8_t data[2];
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }
    usleep(180000); // Wait for measurement to complete

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    uint16_t lux = (data[0] << 8) | data[1];
    lux /= 1.2; // Convert to lux
    return lux;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, message);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "chicken_coop_relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int lux = 0;
    int relay_state = 0;

    while (running) {
        lux = read_lux(i2c_fd);
        if (lux < 0) {
            log_event("Sensor non-response");
            gpiod_line_set_value(relay_line, 0);
            relay_state = 0;
        } else {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Lux = %d", lux);
            log_event(log_message);

            if (lux < LUX_THRESHOLD_DARK && !relay_state) {
                gpiod_line_set_value(relay_line, 1);
                relay_state = 1;
                log_event("Relay = ON");
            } else if (lux > LUX_THRESHOLD_LIGHT + HYSTERESIS && relay_state) {
                gpiod_line_set_value(relay_line, 0);
                relay_state = 0;
                log_event("Relay = OFF");
            }
        }

        sleep(POLL_INTERVAL);
    }

    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

