#include <time.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define DEBOUNCE_TIMEOUT_US 1000000
#define PULSE_TO_LPM 60.0 / 2.0  // 2 pulses per liter
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5

volatile sig_atomic_t running = 1;
pthread_mutex_t pulse_mutex;
unsigned int pulse_count = 0;
struct gpiod_chip *chip;
struct gpiod_line *flow_sensor_line;
struct gpiod_line *solenoid_line;
FILE *log_file;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: %s\n", asctime(tm_info), message);
    fflush(log_file);
}

void *flow_sensor_isr(void *arg) {
    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = DEBOUNCE_TIMEOUT_US * 1000;

    while (running) {
        int value = gpiod_line_get_value(flow_sensor_line);
        if (value == 1) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
            nanosleep(&timeout, NULL);
        }
    }
    return NULL;
}

void handle_signal(int sig) {
    running = 0;
    log_event("Signal received, shutting down.");
    gpiod_line_set_value(solenoid_line, 1);  // Open solenoid
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpiod_line_release(solenoid_line);
    gpiod_line_release(flow_sensor_line);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    log_event("Program started.");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    flow_sensor_line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!flow_sensor_line) {
        perror("Failed to get flow sensor line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        perror("Failed to get solenoid line");
        gpiod_line_release(flow_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flow_sensor_line, "flow_sensor") < 0) {
        perror("Failed to request input on flow sensor line");
        gpiod_line_release(solenoid_line);
        gpiod_line_release(flow_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 1) < 0) {  // Open solenoid
        perror("Failed to request output on solenoid line");
        gpiod_line_release(flow_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    pthread_t isr_thread;
    if (pthread_create(&isr_thread, NULL, flow_sensor_isr, NULL) != 0) {
        perror("Failed to create ISR thread");
        gpiod_line_release(solenoid_line);
        gpiod_line_release(flow_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        sleep(1);
        pthread_mutex_lock(&pulse_mutex);
        unsigned int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = current_pulse_count * PULSE_TO_LPM;
        char buffer[100];
        snprintf(buffer, sizeof(buffer), "Flow rate: %.2f LPM", flow_rate);
        log_event(buffer);

        if (flow_rate > FLOW_THRESHOLD_HIGH) {
            gpiod_line_set_value(solenoid_line, 0);  // Close solenoid
            log_event("Solenoid closed.");
        } else if (flow_rate < FLOW_THRESHOLD_LOW) {
            gpiod_line_set_value(solenoid_line, 1);  // Open solenoid
            log_event("Solenoid opened.");
        }
    }

    pthread_join(isr_thread, NULL);
    handle_signal(0);  // Clean up resources
    return EXIT_SUCCESS;
}

