#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <ini.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define TIMEOUT_ATTEMPTS 1000
#define PULSE_MIN 1000
#define PULSE_MAX 2000
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define LOG_FILE "dispensing_log.json"
#define CONFIG_FILE "config.ini"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_hx711() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *sck_line;
    int value = 0;
    int attempts = 0;

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    if (!data_line || !sck_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(data_line, "hx711_data") < 0 ||
        gpiod_line_request_output(sck_line, "hx711_sck") < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    while (gpiod_line_get_value(data_line) == 1) {
        if (++attempts > TIMEOUT_ATTEMPTS) {
            fprintf(stderr, "Timeout waiting for HX711 data\n");
            gpiod_chip_close(chip);
            return -1;
        }
        usleep(1);
    }

    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1);
        value = (value << 1) | gpiod_line_get_value(data_line);
        gpiod_line_set_value(sck_line, 0);
        usleep(1);
    }

    gpiod_line_set_value(sck_line, 1);
    usleep(1);
    gpiod_line_set_value(sck_line, 0);
    gpiod_chip_close(chip);

    return value;
}

double read_calibration_factor() {
    double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    char buffer[1024];

    if (ini_load(CONFIG_FILE, buffer, sizeof(buffer)) > 0) {
        calibration_factor = atof(ini_get("calibration", "factor", buffer));
    }

    return calibration_factor;
}

void log_event(double target_weight, double actual_weight, const char *error) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "{\n");
    fprintf(log_file, "  \"timestamp\": \"%s\",\n", timestamp);
    fprintf(log_file, "  \"target_weight\": %.2f,\n", target_weight);
    fprintf(log_file, "  \"actual_weight\": %.2f,\n", actual_weight);
    if (error) {
        fprintf(log_file, "  \"error\": \"%s\"\n", error);
    } else {
        fprintf(log_file, "  \"error\": null\n");
    }
    fprintf(log_file, "},\n");

    fclose(log_file);
}

void handle_client(int client_socket) {
    char buffer[1024];
    double target_weight, actual_weight;
    double calibration_factor = read_calibration_factor();
    int pulse_width;

    if (recv(client_socket, buffer, sizeof(buffer) - 1, 0) <= 0) {
        perror("Failed to receive data from client");
        close(client_socket);
        return;
    }
    buffer[sizeof(buffer) - 1] = '\0';
    target_weight = atof(buffer);

    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        close(client_socket);
        return;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, 0);

    if (gpioHardwarePWM(SERVO_PIN, 50, PULSE_MIN) < 0) {
        perror("Failed to set hardware PWM");
        gpioTerminate();
        close(client_socket);
        return;
    }

    usleep(1000000);

    int hx711_value = read_hx711();
    if (hx711_value < 0) {
        gpioTerminate();
        close(client_socket);
        return;
    }

    actual_weight = hx711_value * calibration_factor;

    pulse_width = PULSE_MIN + (PULSE_MAX - PULSE_MIN) * (target_weight - actual_weight) / (PULSE_MAX - PULSE_MIN);
    if (pulse_width < PULSE_MIN) pulse_width = PULSE_MIN;
    if (pulse_width > PULSE_MAX) pulse_width = PULSE_MAX;

    if (gpioHardwarePWM(SERVO_PIN, 50, pulse_width) < 0) {
        perror("Failed to set hardware PWM");
        gpioTerminate();
        close(client_socket);
        return;
    }

    usleep(1000000);

    gpioTerminate();

    sprintf(buffer, "%.2f", actual_weight);
    if (send(client_socket, buffer, strlen(buffer), 0) <= 0) {
        perror("Failed to send data to client");
    }

    log_event(target_weight, actual_weight, NULL);

    close(client_socket);
}

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Failed to create socket");
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(server_socket);
        return 1;
    }

    if (listen(server_socket, 5) < 0) {
        perror("Failed to listen on socket");
        close(server_socket);
        return 1;
    }

    printf("Server listening on %s:%d\n", SERVER_IP, SERVER_PORT);

    while (running) {
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            perror("Failed to accept connection");
            continue;
        }

        handle_client(client_socket);
    }

    close(server_socket);
    return 0;
}

