#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *touch_sensor_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

void release_resources() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (touch_sensor_line) {
        gpiod_line_release(touch_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    if (argc == 3 && strcmp(argv[1], "-d") == 0) {
        debounce_ms = atoi(argv[2]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Invalid debounce time: %s\n", argv[2]);
            return EXIT_FAILURE;
        }
    } else if (argc != 1) {
        fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    touch_sensor_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_sensor_line) {
        perror("Failed to get touch sensor line");
        release_resources();
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        release_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_sensor_line, "touch_sensor") < 0) {
        perror("Failed to request input for touch sensor");
        release_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request output for relay");
        release_resources();
        return EXIT_FAILURE;
    }

    int last_state = gpiod_line_get_value(touch_sensor_line);
    while (running) {
        int current_state = gpiod_line_get_value(touch_sensor_line);
        if (current_state != last_state && current_state == 1) {
            log_relay_state(!gpiod_line_get_value(relay_line));
            gpiod_line_set_value(relay_line, !gpiod_line_get_value(relay_line));
            last_state = current_state;
            usleep(debounce_ms * 1000);
        }
        usleep(1000); // Poll every 1 ms
    }

    release_resources();
    return EXIT_SUCCESS;
}

