#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <termios.h>
#include <fcntl.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define PWM_FREQ 50
#define PWM_PERIOD (1000000 / PWM_FREQ)
#define MIN_PULSE 500
#define MAX_PULSE 2500
#define NEUTRAL_PULSE 1500
#define ANGLE_STEP 10
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct termios original_termios;
static volatile sig_atomic_t running = 1;

void restore_terminal() {
    tcsetattr(STDIN_FILENO, TCSANOW, &original_termios);
}

void handle_signal(int sig) {
    running = 0;
}

int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Angle out of range: %d\n", angle);
        return -1;
    }

    int pulse_width = NEUTRAL_PULSE + ((angle - 90) * (MAX_PULSE - MIN_PULSE) / 180);
    pulse_width = pulse_width < MIN_PULSE ? MIN_PULSE : (pulse_width > MAX_PULSE ? MAX_PULSE : pulse_width);

    int ret = gpiod_line_set_value(line, pulse_width);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return ret;
    }

    printf("Current angle: %d°\n", angle);
    return 0;
}

int main() {
    struct sigaction sa;
    struct termios raw_termios;

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Save original terminal settings
    if (tcgetattr(STDIN_FILENO, &original_termios) < 0) {
        perror("tcgetattr");
        return EXIT_FAILURE;
    }

    // Set terminal to raw mode
    raw_termios = original_termios;
    cfmakeraw(&raw_termios);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw_termios) < 0) {
        perror("tcsetattr");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_label");
        restore_terminal();
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        restore_terminal();
        return EXIT_FAILURE;
    }

    // Request line for output
    int ret = gpiod_line_request_output(line, "servo_control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        restore_terminal();
        return EXIT_FAILURE;
    }

    // Set initial angle
    if (set_servo_angle(90) < 0) {
        gpiod_chip_close(chip);
        restore_terminal();
        return EXIT_FAILURE;
    }

    // Main loop
    int angle = 90;
    while (running) {
        char c = getchar();
        if (c == '+') {
            angle += ANGLE_STEP;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            if (set_servo_angle(angle) < 0) break;
        } else if (c == '-') {
            angle -= ANGLE_STEP;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            if (set_servo_angle(angle) < 0) break;
        } else if (c == 'q') {
            running = 0;
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    restore_terminal();

    return EXIT_SUCCESS;
}

