    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts));
    fprintf(log_file, "%s,%0.2f\n", timestamp, rpm);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "rpm_monitor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_debounce(line, DEBOUNCE_US);
    if (ret < 0) {
        fprintf(stderr, "Failed to set debounce: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct timespec last_pulse_time = {0};
    unsigned long pulse_count = 0;
    struct timespec start_time = {0};
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event: %s\n", strerror(errno));
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pulse_count++;
            last_pulse_time = event.ts;
        }

        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (timespec_diff_us(&current_time, &start_time) >= RPM_INTERVAL_US) {
            double elapsed_time = timespec_diff_us(&current_time, &start_time) / 1000000.0;
            double rpm = (pulse_count / elapsed_time) * 60.0;
            log_rpm(log_file, rpm);
            printf("Current RPM: %0.2f\n", rpm);
            pulse_count = 0;
            start_time = current_time;
        }
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

long timespec_diff_us(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}
