    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioWrite(RELAY_GPIO, PI_LOW);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", TOUCH_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    gpioWrite(RELAY_GPIO, PI_LOW);

    setup_signal_handlers();

    int last_state = PI_LOW;
    struct timespec start_time, current_time;
    int long_press = 0;

    while (!exit_flag) {
        int current_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (current_state == PI_HIGH && last_state == PI_LOW) {
            gpioWrite(RELAY_GPIO, !gpioRead(RELAY_GPIO));
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            long_press = 0;
        } else if (current_state == PI_HIGH) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (timespec_diff_us(&current_time, &start_time) > LONG_PRESS_TIMEOUT_US) {
                gpioWrite(RELAY_GPIO, PI_LOW);
                long_press = 1;
            }
        } else if (current_state == PI_LOW && long_press) {
            long_press = 0;
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

long timespec_diff_us(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
