#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>
#include <pigpio.h>

#define PWM_PIN 18
#define ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 100
#define Kp 1.0
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static unsigned int flow_rate = 0;
static unsigned int target_flow_rate = 0;

void signal_handler(int sig) {
    running = 0;
}

void log_flow(unsigned int timestamp_ms, unsigned int flow_rate, unsigned int valve_position) {
    fprintf(log_file, "%u,%u,%u\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file);
}

void flow_sensor_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) return;
    flow_rate++;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (sscanf(argv[1], "%u", &target_flow_rate) != 1 || target_flow_rate == 0) {
        fprintf(stderr, "Invalid target flow rate\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISR(FLOW_SENSOR_PIN, RISING_EDGE, flow_sensor_callback) < 0) {
        fprintf(stderr, "Failed to register ISR\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(ENABLE_PIN, PI_HIGH);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    unsigned int last_sample_time = 0;
    unsigned int valve_position = 0;

    while (running) {
        unsigned int current_time = gpioTick();
        if (current_time - last_sample_time >= SAMPLE_INTERVAL_MS) {
            last_sample_time = current_time;

            valve_position = (unsigned int)(Kp * (target_flow_rate - flow_rate));
            if (valve_position > PWM_RANGE) valve_position = PWM_RANGE;
            gpioPWM(PWM_PIN, valve_position);

            log_flow(current_time, flow_rate, valve_position);
            flow_rate = 0;
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioWrite(ENABLE_PIN, PI_LOW);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

