    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);

    if (!lock1_line || !lock2_line || !button_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(lock1_line, "door_lock", 1) < 0 ||
        gpiod_line_request_output(lock2_line, "door_lock", 1) < 0 ||
        gpiod_line_request_input(button_line, "door_lock") < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode or speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_rfid(char *buffer, size_t length) {
    uint8_t tx[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[length];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = length,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from SPI");
        return -1;
    }

    memcpy(buffer, rx, length);
    return 0;
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR ||
        signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0 || setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        handle_signal(0);
        return EXIT_FAILURE;
    }

    char tag[11];
    int button_pressed = 0;
    struct timeval last_button_press = {0};

    while (1) {
        if (read_rfid(tag, sizeof(tag) - 1) < 0) {
            log_event("RFID read failure");
            continue;
        }
        tag[sizeof(tag) - 1] = '\0';

        if (strcmp(tag, VALID_TAG) == 0) {
            log_event("Valid tag detected");

            struct timeval current_time;
            gettimeofday(&current_time, NULL);
            if (button_pressed && (current_time.tv_sec - last_button_press.tv_sec) * 1000000 + (current_time.tv_usec - last_button_press.tv_usec) > DEBOUNCE_TIME) {
                log_event("Button pressed after valid tag");

                gpiod_line_set_value(lock1_line, 0);
                gpiod_line_set_value(lock2_line, 0);
                sleep(5);
                gpiod_line_set_value(lock1_line, 1);
                gpiod_line_set_value(lock2_line, 1);

                log_event("Locks disengaged and reengaged");
                button_pressed = 0;
            }
        } else if (strcmp(tag, "0000000000") != 0) {
            log_event("Invalid tag detected");
        }

        int button_value = gpiod_line_get_value(button_line);
        if (button_value == 0) {
            gettimeofday(&current_time, NULL);
            if (!button_pressed || (current_time.tv_sec - last_button_press.tv_sec) * 1000000 + (current_time.tv_usec - last_button_press.tv_usec) > DEBOUNCE_TIME) {
                log_event("Button pressed");
                button_pressed = 1;
                last_button_press = current_time;
            }
        } else {
            button_pressed = 0;
        }

        usleep(100000); // 100 ms delay
    }

    return EXIT_SUCCESS;
}
