#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17

#define MPR121_ECR 0x5E
#define MPR121_SOFT_RESET 0x80
#define MPR121_CONFIG2 0x5D
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01

#define NUM_ELECTRODES 12

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_relay_state(int state) {
    FILE *log_file = fopen("relay_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s: Relay state %d\n", timestamp, state);
    fclose(log_file);
}

int main() {
    signal(SIGINT, sigint_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Soft reset
    uint8_t reset_cmd = MPR121_SOFT_RESET;
    if (write(i2c_fd, &reset_cmd, 1) != 1) {
        perror("Failed to send soft reset command");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait for reset to complete

    // Configure filtering parameters
    uint8_t config2 = 0x20; // 16x filter
    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG2, config2) < 0) {
        perror("Failed to write CONFIG2");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set touch and release thresholds
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2c_smbus_write_byte_data(i2c_fd, MPR121_MHDR + i, 0x01) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_NHDR + i, 0x01) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_NCLR + i, 0x0E) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_FDLR + i, 0x00) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_MHDF + i, 0x01) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_NHDF + i, 0x01) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_NCLF + i, 0x0E) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_FDLF + i, 0x00) < 0 ||
            i2c_smbus_write_byte_data(i2c_fd, MPR121_NHDT + i, 0x01) < 0 ||
