#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17

#define MPR121_ECR 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_DEBOUNCE 0x3E
#define MPR121_CONFIG2 0x3F

#define TOUCH_THRESHOLD 128
#define RELEASE_THRESHOLD 64

volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *relay_line;
    uint8_t touch_status;

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize MPR121 in stop mode
    if (i2c_write(i2c_fd, MPR121_ECR, 0x00) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2c_write(i2c_fd, MPR121_MHDR + i, TOUCH_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_NHDR + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_NCLR + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_FDLR + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_MHDF + i, TOUCH_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_NHDF + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_NCLF + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_FDLF + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_NHDT + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_NCLT + i, RELEASE_THRESHOLD) < 0 ||
            i2c_write(i2c_fd, MPR121_FDLT + i, RELEASE_THRESHOLD) < 0) {
            close(i2c_fd);
            return EXIT_FAILURE;
        }
    }

    // Set filter and charge time, electrode current
    if (i2c_write(i2c_fd, MPR121_DEBOUNCE, 0x10) < 0 ||
        i2c_write(i2c_fd, MPR121_CONFIG2, 0x2A) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Switch to run mode
    if (i2c_write(i2c_fd, MPR121_ECR, 0x8F) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for stabilization
    usleep(100000);

    // Initialize GPIO for relay
    if (!(chip = gpiod_chip_open_by_label("gpiochip0"))) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (!(relay_line = gpiod_chip_get_line(chip, RELAY_GPIO))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        if (i2c_read(i2c_fd, 0x00, &touch_status) < 0) {
            break;
        }

        if (touch_status > 0) {
            int current_state = gpiod_line_get_value(relay_line);
            gpiod_line_set_value(relay_line, !current_state);
            printf("Relay toggled to %d\n", !current_state);
        }

        usleep(100000);
    }

    // Cleanup
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

