#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define POLL_INTERVAL_US 50000
#define RELAY_ACTIVE_US 500000
#define RATE_LIMIT_US 2000000

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static FILE *log_file;

static void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(0);
}

static void log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%.6f - %s\n", ts.tv_sec + ts.tv_nsec / 1e9, event);
    fflush(log_file);
}

int main() {
    atexit(cleanup);
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        perror("Failed to get PIR GPIO line");
        cleanup();
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get RELAY GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        perror("Failed to request PIR GPIO line as input");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "door_relay", 0) < 0) {
        perror("Failed to request RELAY GPIO line as output");
        cleanup();
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    int last_state = 0;
    struct timespec last_event_time = {0};
    while (1) {
        int current_state = gpiod_line_get_value(pir_line);
        if (current_state < 0) {
            perror("Failed to read PIR GPIO line");
            cleanup();
            return 1;
        }

        if (current_state && !last_state) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec - last_event_time.tv_sec > 2 ||
                (now.tv_sec == last_event_time.tv_sec && now.tv_nsec - last_event_time.tv_nsec > RATE_LIMIT_US * 1000)) {
                log_event("Motion detected");
                gpiod_line_set_value(relay_line, 1);
                log_event("Door unlocked");
                usleep(RELAY_ACTIVE_US);
                gpiod_line_set_value(relay_line, 0);
                last_event_time = now;
            } else {
                log_event("Rate limited");
            }
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

    return 0;
}

