#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <errno.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION 50
#define MAX_DURATION 200
#define MIN_DUTY 0
#define MAX_DUTY 255

volatile sig_atomic_t shutdown = 0;

void handle_sigint(int sig) {
    shutdown = 1;
}

struct gpiod_chip *chip;
struct gpiod_line *motor1_line;
struct gpiod_line *motor2_line;

void cleanup() {
    if (motor1_line) {
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("Failed to get GPIO line for Motor 1");
        cleanup();
        return -1;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("Failed to get GPIO line for Motor 2");
        cleanup();
        return -1;
    }

    int ret = gpiod_line_request_output(motor1_line, "motor1", 0);
    if (ret < 0) {
        perror("Failed to request output for Motor 1");
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(motor2_line, "motor2", 0);
    if (ret < 0) {
        perror("Failed to request output for Motor 2");
        cleanup();
        return -1;
    }

    return 0;
}

void generate_pattern(int *duties, int *durations, int *num_steps) {
    *num_steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
    for (int i = 0; i < *num_steps; i++) {
        duties[i] = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        durations[i] = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
    }
}

void play_pattern(int *duties, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpiod_line_set_value(motor1_line, duties[i]);
        gpiod_line_set_value(motor2_line, duties[i]);
        usleep(durations[i] * 1000);
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_set_value(motor2_line, 0);
        if (shutdown) {
            break;
        }
    }
}

int main() {
    srand(time(NULL));

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int duties[MAX_STEPS];
    int durations[MAX_STEPS];
    int num_steps;

    while (!shutdown) {
        generate_pattern(duties, durations, &num_steps);
        play_pattern(duties, durations, num_steps);
    }

    cleanup();
    return EXIT_SUCCESS;
}

