code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define READ_TIMEOUT_US 500000
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define STARTUP_READINGS 100
#define WEIGHT_THRESHOLD 10.0

static struct gpiod_chip *chip;
static struct gpiod_line *data_line;
static struct gpiod_line *clock_line;
static struct gpiod_line *lock_line;
static double scale = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;
static FILE *log_file;

static void cleanup() {
    if (lock_line) {
        gpiod_line_release(lock_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

static void read_calibration() {
    FILE *cal_file = fopen(CALIBRATION_FILE, "r");
    if (cal_file) {
        if (fscanf(cal_file, "%lf %lf", &scale, &offset) != 2) {
            scale = DEFAULT_SCALE;
            offset = DEFAULT_OFFSET;
        }
        fclose(cal_file);
    } else {
        scale = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
    }
}

static void write_calibration() {
    FILE *cal_file = fopen(CALIBRATION_FILE, "w");
    if (cal_file) {
        fprintf(cal_file, "%lf %lf\n", scale, offset);
        fclose(cal_file);
    }
}

static void startup_calibration() {
    long long sum = 0;
    for (int i = 0; i < STARTUP_READINGS; i++) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(data_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if (timespec_diff_us(&end, &start) > READ_TIMEOUT_US) {
                return;
            }
        }
        gpiod_line_set_value(clock_line, 1);
        gpiod_line_set_value(clock_line, 0);
        sum += gpiod_line_get_value(data_line);
    }
    offset = (double)sum / STARTUP_READINGS;
}

static long long read_hx711() {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(data_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timespec_diff_us(&end, &start) > READ_TIMEOUT_US) {
            return 0;
        }
    }
    long long value = 0;
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(clock_line, 1);
        gpiod_line_set_value(clock_line, 0);
        value = (value << 1) | gpiod_line_get_value(data_line);
    }
    gpiod_line_set_value(clock_line, 1);
    gpiod_line_set_value(clock_line, 0);
    if (value & 0x800000) {
        value |= ~0xffffff;
    }
    return value;
}

static long long timespec_diff_us(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

int main() {
    atexit(cleanup);
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);

    if (!data_line || !clock_line || !lock_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(data_line, "hx711_data") < 0 ||
        gpiod_line_request_output(clock_line, "hx711_clock", 0) < 0 ||
        gpiod_line_request_output(lock_line, "solenoid_lock", 0) < 0) {
        perror("Failed to request GPIO lines");
        cleanup();
        return 1;
    }

    read_calibration();
    startup_calibration();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    while (1) {
        long long raw_value = read_hx711();
        if (raw_value == 0) {
            continue;
        }
        double weight = (raw_value - offset) * scale;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%06ld: Weight = %.2f kg\n", ts.tv_sec, ts.tv_nsec / 1000, weight);
        fflush(log_file);

        if (weight > WEIGHT_THRESHOLD) {
            gpiod_line_set_value(lock_line, 1);
        } else {
            gpiod_line_set_value(lock_line, 0);
        }

        usleep(500000);
    }

    cleanup();
    return 0;
}

