void sig_handler(int sig) {
    running = 0;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(LOG_INFO, "[%s] %s", timestamp, event);
}

void setup_gpio(struct gpiod_chip **chip, struct gpiod_line **sensor_line, struct gpiod_line **motor_in1, struct gpiod_line **motor_in2, struct gpiod_line **motor_pwm) {
    *chip = gpiod_chip_open_by_name(SENSOR_CHIP);
    if (!*chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    *sensor_line = gpiod_chip_get_line(*chip, SENSOR_LINE);
    if (!*sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(*sensor_line, "rain_sensor") < 0) {
        perror("Failed to request input for sensor line");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    *motor_in1 = gpiod_chip_get_line(*chip, MOTOR_IN1_LINE);
    *motor_in2 = gpiod_chip_get_line(*chip, MOTOR_IN2_LINE);
    *motor_pwm = gpiod_chip_get_line(*chip, MOTOR_PWM_LINE);

    if (!*motor_in1 || !*motor_in2 || !*motor_pwm) {
        perror("Failed to get motor control lines");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(*motor_in1, "motor_in1", 0) < 0 ||
        gpiod_line_request_output(*motor_in2, "motor_in2", 0) < 0 ||
        gpiod_line_request_output(*motor_pwm, "motor_pwm", 0) < 0) {
        perror("Failed to request output for motor control lines");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *motor_in1, struct gpiod_line *motor_in2, struct gpiod_line *motor_pwm) {
    if (motor_in1) gpiod_line_release(motor_in1);
    if (motor_in2) gpiod_line_release(motor_in2);
    if (motor_pwm) gpiod_line_release(motor_pwm);
    if (chip) gpiod_chip_close(chip);
}

