    gpiod_line_set_value(motor_in1, 1);
    gpiod_line_set_value(motor_in2, 0);
    gpiod_line_set_value(motor_pwm, 1);

    struct timespec ts = {0, PWM_PERIOD * PWM_DUTY / 255};
    struct timespec rem;
    for (int i = 0; i < PWM_PERIOD / ts.tv_nsec; i++) {
        if (!running) break;
        nanosleep(&ts, &rem);
    }

    gpiod_line_set_value(motor_in1, 0);
    gpiod_line_set_value(motor_in2, 0);
    gpiod_line_set_value(motor_pwm, 0);
}

int read_sensor(struct gpiod_line *sensor_line) {
    int count = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        if (gpiod_line_get_value(sensor_line) == 0) {
            count++;
        }
        usleep(DEBOUNCE_DELAY);
    }
    return count >= 3;
}

int main() {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *motor_in1 = NULL;
    struct gpiod_line *motor_in2 = NULL;
    struct gpiod_line *motor_pwm = NULL;

    setup_gpio(&chip, &sensor_line, &motor_in1, &motor_in2, &motor_pwm);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        if (read_sensor(sensor_line)) {
            log_event("Rain detected, closing window.");
            control_motor(motor_in1, motor_in2, motor_pwm);
            log_event("Window closed.");
            sleep(60); // Wait 60 seconds after closing
        }
        sleep(60); // Check sensor every 60 seconds
    }

    cleanup_gpio(chip, motor_in1, motor_in2, motor_pwm);

    closelog();
    return 0;
}

