#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define WEIGHT_THRESHOLD 100
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT 1000000 // 1 second

static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
}

int hx711_read(int dt_fd, int sck_fd) {
    struct timespec start, now;
    int data = 0;
    int bit = 1;

    // Wait for the data line to go low
    if (gpiod_line_get_value(dt_fd) != 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(dt_fd) != 0) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (now.tv_sec - start.tv_sec > HX711_TIMEOUT / 1000000 ||
                now.tv_nsec - start.tv_nsec > HX711_TIMEOUT % 1000000) {
                return -1; // Timeout
            }
        }
    }

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_fd, 1);
        usleep(1);
        data |= gpiod_line_get_value(dt_fd) ? bit : 0;
        gpiod_line_set_value(sck_fd, 0);
        usleep(1);
        bit <<= 1;
    }

    // Read 1 more bit (gain factor)
    gpiod_line_set_value(sck_fd, 1);
    usleep(1);
    data |= gpiod_line_get_value(dt_fd) ? bit : 0;
    gpiod_line_set_value(sck_fd, 0);
    usleep(1);

    // Set channel and gain factor for next reading
    gpiod_line_set_value(sck_fd, 1);
    usleep(1);
    gpiod_line_set_value(sck_fd, 0);
    usleep(1);
    gpiod_line_set_value(sck_fd, 1);
    usleep(1);
    gpiod_line_set_value(sck_fd, 0);
    usleep(1);

    return data;
}

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log, "[%s] %s\n", timestamp, message);
    fclose(log);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *dt_line = gpiod_chip_get_line(chip, DT_PIN);
    struct gpiod_line *sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    struct gpiod_line *lock_line = gpiod_chip_get_line(chip, LOCK_PIN);

    if (!dt_line || !sck_line || !lock_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dt_line, "hx711_dt") < 0 ||
        gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0 ||
        gpiod_line_request_output(lock_line, "lock", 0) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int weight = hx711_read(dt_line, sck_line);
        if (weight < 0) {
            log_event("HX711 read timeout or data line stuck high");
            continue;
        }

        if (weight < WEIGHT_THRESHOLD) {
            gpiod_line_set_value(lock_line, 1);
            log_event("Weight below threshold, activating lock");
            sleep(LOCK_DURATION);
            gpiod_line_set_value(lock_line, 0);
            log_event("Lock deactivated");
        }

        sleep(1);
    }

    gpiod_line_release(lock_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(dt_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

