    if (fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiochip_info_c info;
    if (ioctl(fd, GPIO_GET_CHIPINFO_IOCTL, &info) < 0) {
        perror("Failed to get GPIO chip info");
        close(fd);
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = pin;
    req.flags = (direction == GPIOHANDLE_REQUEST_OUTPUT) ? GPIOHANDLE_REQUEST_OUTPUT : GPIOHANDLE_REQUEST_INPUT;
    req.lines = 1;
    strncpy(req.consumer_label, "hx711", sizeof(req.consumer_label) - 1);

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("Failed to get GPIO line handle");
        close(fd);
        return -1;
    }

    close(fd);
    return req.fd;
}

void cleanup_gpio(int fd) {
    if (fd >= 0) {
