    struct gpiohandle_data data;
    int value = 0;
    int bit_count = 0;

    // Start a new conversion
    data.values[0] = 1;
    if (ioctl(clock_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set clock high");
        return -1;
    }
    usleep(1);
    data.values[0] = 0;
    if (ioctl(clock_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set clock low");
        return -1;
    }

    // Wait for the data line to go low
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (ioctl(data_fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data) < 0) {
            perror("Failed to read data line");
            return -1;
        }
        if (data.values[0] == 0) {
