        }
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - start.tv_sec > 0 || now.tv_nsec - start.tv_nsec > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for data line to go low\n");
            return -1;
        }
    }

