            return -1;
        }
        value = (value << 1) | data.values[0];
        data.values[0] = 0;
        if (ioctl(clock_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
            perror("Failed to set clock low");
            return -1;
