    data.values[0] = 1;
    if (ioctl(clock_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set clock high");
        return -1;
    }
    usleep(1);
    data.values[0] = 0;
    if (ioctl(clock_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
