            lock_data.values[0] = 1;
            if (ioctl(lock_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &lock_data) < 0) {
                perror("Failed to set lock high");
            } else {
                sleep(5);
                lock_data.values[0] = 0;
                if (ioctl(lock_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &lock_data) < 0) {
                    perror("Failed to set lock low");
                }

                if (log_file) {
                    time_t now = time(NULL);
                    struct tm *tm_info = localtime(&now);
                    char timestamp[80];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                    fprintf(log_file, "%s: Weight %.2f kg\n", timestamp, weight_kg);
                    fflush(log_file);
                }
            }
        }
    }

    if (log_file) {
        fclose(log_file);
    }

    cleanup_gpio(data_fd);
    cleanup_gpio(clock_fd);
    cleanup_gpio(lock_fd);

    return EXIT_SUCCESS;
}

