#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *relay_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *state) {
    time_t now = time(NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(log_file, "%s - Relay state: %s\n", timestamp, state);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        cleanup();
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay line");
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(sensor_line, "ir_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        perror("Failed to request relay line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    int current_relay_state = 0;
    while (running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            continue;
        }

        if (sensor_value == 0) { // Obstacle detected
            current_relay_state = !current_relay_state;
            ret = gpiod_line_set_value(relay_line, current_relay_state);
            if (ret < 0) {
                perror("Failed to set relay value");
                continue;
            }
            log_event(current_relay_state ? "ON" : "OFF");
        }

        usleep(100000); // 100ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

