    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

void log_motion() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        perror("Error writing to log file");
        cleanup();
        exit(EXIT_FAILURE);
    }
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        perror("Error getting PIR GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Error getting buzzer GPIO line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        perror("Error requesting PIR GPIO line as input");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Error requesting buzzer GPIO line as output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            perror("Error reading PIR GPIO line");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (pir_value) {
            log_motion();
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("Error setting buzzer GPIO line high");
                cleanup();
                exit(EXIT_FAILURE);
            }
            usleep(2000000); // 2 seconds
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("Error setting buzzer GPIO line low");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }

        usleep(100000); // 100 ms delay
    }

    cleanup();
    return 0;
}
