#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define MIN_DURATION 1
#define MAX_DURATION 3600

volatile sig_atomic_t sigint_received = 0;

void signal_handler(int signum) {
    sigint_received = 1;
}

int parse_duration(const char *line, int *duration) {
    if (sscanf(line, "duration=%d", duration) != 1) {
        return -1;
    }
    if (*duration < MIN_DURATION || *duration > MAX_DURATION) {
        return -1;
    }
    return 0;
}

void release_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    FILE *config_file = NULL;
    char line_buffer[256];
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open configuration file
    config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    // Read and parse duration from configuration file
    if (!fgets(line_buffer, sizeof(line_buffer), config_file)) {
        fprintf(stderr, "Error: Empty configuration file\n");
        fclose(config_file);
        return EXIT_FAILURE;
    }
    fclose(config_file);

    if (parse_duration(line_buffer, &duration) == -1) {
        fprintf(stderr, "Error: Malformed or out-of-range duration in configuration file\n");
        return EXIT_FAILURE;
    }

    printf("Configured duration: %d seconds\n", duration);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        release_gpio(chip, NULL);
        return EXIT_FAILURE;
    }

    // Request GPIO line as output
    if (gpiod_line_request_output(line, "watering_system", 0) < 0) {
        perror("gpiod_line_request_output");
        release_gpio(chip, line);
        return EXIT_FAILURE;
    }

    // Activate valve
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        release_gpio(chip, line);
        return EXIT_FAILURE;
    }
    printf("Valve activated\n");

    // Wait for the configured duration
    while (duration > 0 && !sigint_received) {
        sleep(1);
        duration--;
    }

    // Deactivate valve
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value");
        release_gpio(chip, line);
        return EXIT_FAILURE;
    }
    printf("Valve deactivated\n");

    // Release GPIO resources
    release_gpio(chip, line);

    if (sigint_received) {
        printf("Received SIGINT/SIGTERM, exiting\n");
    }

    return EXIT_SUCCESS;
}

