#define LEFT_MOTOR_BACKWARD 23
#define RIGHT_MOTOR_FORWARD 24
#define RIGHT_MOTOR_BACKWARD 25

#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_US 10000

static struct gpiod_chip *chip;
static struct gpiod_line *left_sensor_line, *middle_sensor_line, *right_sensor_line;
static struct gpiod_line *left_motor_forward_line, *left_motor_backward_line;
static struct gpiod_line *right_motor_forward_line, *right_motor_backward_line;
static FILE *log_file;

void cleanup() {
    if (left_motor_forward_line) gpiod_line_release(left_motor_forward_line);
    if (left_motor_backward_line) gpiod_line_release(left_motor_backward_line);
    if (right_motor_forward_line) gpiod_line_release(right_motor_forward_line);
    if (right_motor_backward_line) gpiod_line_release(right_motor_backward_line);
    if (left_sensor_line) gpiod_line_release(left_sensor_line);
    if (middle_sensor_line) gpiod_line_release(middle_sensor_line);
    if (right_sensor_line) gpiod_line_release(right_sensor_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

void set_motor_speed(int forward_line, int backward_line, int speed) {
    if (speed > 0) {
        gpiod_line_set_value(forward_line, 1);
        gpiod_line_set_value(backward_line, 0);
        gpiod_line_set_value(forward_line, speed);
    } else if (speed < 0) {
        gpiod_line_set_value(forward_line, 0);
        gpiod_line_set_value(backward_line, 1);
        gpiod_line_set_value(backward_line, -speed);
    } else {
        gpiod_line_set_value(forward_line, 0);
        gpiod_line_set_value(backward_line, 0);
    }
}

