        !left_motor_forward_line || !left_motor_backward_line ||
        !right_motor_forward_line || !right_motor_backward_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(left_sensor_line, "line_follower") < 0 ||
        gpiod_line_request_input(middle_sensor_line, "line_follower") < 0 ||
        gpiod_line_request_input(right_sensor_line, "line_follower") < 0 ||
        gpiod_line_request_output(left_motor_forward_line, "line_follower") < 0 ||
        gpiod_line_request_output(left_motor_backward_line, "line_follower") < 0 ||
        gpiod_line_request_output(right_motor_forward_line, "line_follower") < 0 ||
        gpiod_line_request_output(right_motor_backward_line, "line_follower") < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("trace_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int left_sensor = !gpiod_line_get_value(left_sensor_line);
        int middle_sensor = !gpiod_line_get_value(middle_sensor_line);
        int right_sensor = !gpiod_line_get_value(right_sensor_line);

        int left_speed = 0, right_speed = 0;

        if (middle_sensor) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        }

        set_motor_speed(left_motor_forward_line, left_motor_backward_line, left_speed);
        set_motor_speed(right_motor_forward_line, right_motor_backward_line, right_speed);

        log_state(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

