static struct gpiod_chip *chip;
static struct gpiod_line *servo_line;
static struct gpiod_line *lock_button_line;
static struct gpiod_line *unlock_button_line;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (lock_button_line) {
        gpiod_line_release(lock_button_line);
    }
    if (unlock_button_line) {
        gpiod_line_release(unlock_button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the servo line
    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        perror("Failed to get servo line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(servo_line, "servo", 0);
    if (ret < 0) {
        perror("Failed to request servo line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the lock button line
    lock_button_line = gpiod_chip_get_line(chip, LOCK_BUTTON_GPIO);
    if (!lock_button_line) {
        perror("Failed to get lock button line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(lock_button_line, "lock_button");
    if (ret < 0) {
        perror("Failed to request lock button line as input");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_set_config(lock_button_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set pull-up resistor on lock button line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the unlock button line
    unlock_button_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON_GPIO);
    if (!unlock_button_line) {
        perror("Failed to get unlock button line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(unlock_button_line, "unlock_button");
    if (ret < 0) {
        perror("Failed to request unlock button line as input");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_set_config(unlock_button_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to set pull-up resistor on unlock button line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_button_state = gpiod_line_get_value(lock_button_line);
        int unlock_button_state = gpiod_line_get_value(unlock_button_line);

        if (lock_button_state == 0) {
            // Lock button pressed
            printf("Lock button pressed. Locking door...\n");
            gpiod_line_set_value(servo_line, 1);
            usleep(1000000); // 1 second pulse
            gpiod_line_set_value(servo_line, 0);
            usleep(DEBOUNCE_DELAY_US);
        }

        if (unlock_button_state == 0) {
            // Unlock button pressed
            printf("Unlock button pressed. Unlocking door...\n");
            gpiod_line_set_value(servo_line, 1);
            usleep(1000000); // 1 second pulse
            gpiod_line_set_value(servo_line, 0);
            usleep(DEBOUNCE_DELAY_US);
        }

        usleep(10000); // 10 ms delay
    }

    cleanup();
    printf("Door lock control program exited.\n");
    return EXIT_SUCCESS;
}

