#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <czmq.h>

#define GPIO_CHIP "gpiochip0"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_TOPIC "SOUND_ALERTS"
#define ZMQ_BIND_ADDRESS "tcp://*:5555"
#define ZMQ_CONNECT_ADDRESS "tcp://localhost:5555"
#define POLL_INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void cleanup_zmq(zmq_ctx_t *ctx, zmq_socket_t *socket) {
    if (socket) {
        zmq_close(socket);
    }
    if (ctx) {
        zmq_ctx_destroy(ctx);
    }
}

void sound_sensor_mode() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    zmq_ctx_t *ctx = NULL;
    zmq_socket_t *socket = NULL;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return;
    }

    line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup_gpio(chip, NULL);
        return;
    }

    if (gpiod_line_request_input(line, "sound_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        cleanup_gpio(chip, line);
        return;
    }

    ctx = zmq_ctx_new();
    if (!ctx) {
        perror("Failed to create ZeroMQ context");
        cleanup_gpio(chip, line);
        return;
    }

    socket = zmq_socket(ctx, ZMQ_PUB);
    if (!socket) {
        perror("Failed to create ZeroMQ socket");
        cleanup_gpio(chip, line);
        cleanup_zmq(ctx, NULL);
        return;
    }

    if (zmq_bind(socket, ZMQ_BIND_ADDRESS) < 0) {
        perror("Failed to bind ZeroMQ socket");
        cleanup_gpio(chip, line);
        cleanup_zmq(ctx, socket);
        return;
    }

    while (running) {
        if (gpiod_line_get_value(line) == 0) {
            if (zmq_send(socket, ZMQ_TOPIC, strlen(ZMQ_TOPIC), 0) < 0) {
                perror("Failed to send ZeroMQ message");
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    cleanup_gpio(chip, line);
