#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define PULSE_BUFFER_SIZE 1000

typedef struct {
    uint32_t address;
    uint32_t command;
} nec_frame_t;

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct mosquitto *mosq = NULL;
static uint64_t pulse_buffer[PULSE_BUFFER_SIZE];
static size_t pulse_count = 0;

void signal_handler(int signum) {
    running = 0;
}

void init_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_input(line, "ir_receiver");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    int ret = mosquitto_connect(mosq, "localhost", 1883, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    closelog();
}

void alert_callback(struct gpiod_line *line, unsigned int event_type, unsigned int offset, void *data) {
    if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        return;
    }

    if (pulse_count >= PULSE_BUFFER_SIZE) {
        syslog(LOG_WARNING, "Pulse buffer overflow");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    pulse_buffer[pulse_count++] = ts.tv_nsec;
}

bool decode_nec_frame(nec_frame_t *frame) {
    if (pulse_count < 32) {
        return false;
    }

    uint32_t address = 0;
    uint32_t command = 0;
    uint32_t inverted_address = 0;
    uint32_t inverted_command = 0;

    for (size_t i = 0; i < 32; i++) {
        uint64_t mark = pulse_buffer[i * 2];
        uint64_t space = pulse_buffer[i * 2 + 1];

        if (mark < 560000 || mark > 660000) {
            return false;
        }

        bool bit = (space > 1690000);

        if (i < 8) {
            address = (address << 1) | bit;
        } else if (i < 16) {
            inverted_address = (inverted_address << 1) | bit;
        } else if (i < 24) {
            command = (command << 1) | bit;
        } else {
            inverted_command = (inverted_command << 1) | bit;
        }
    }

    if (address != ~inverted_address) {
        return false;
    }

    if (command != ~inverted_command) {
        return false;
    }

    frame->address = address;
    frame->command = command;
    return true;
}

void publish_nec_frame(const nec_frame_t *frame) {
    char json[100];
    snprintf(json, sizeof(json), "{\"address\": %u, \"command\": %u}", frame->address, frame->command);

    mosquitto_publish(mosq, NULL, "ir/decoded", strlen(json), json, 0, false);
}

int main() {
    openlog("ir_receiver", LOG_PID | LOG_CONS, LOG_USER);
    init_signal_handler();
    init_gpio();
    init_mqtt();

    int ret = gpiod_line_event_request(line, alert_callback, NULL);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line event");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        mosquitto_loop(mosq, 100, 1);

        if (pulse_count >= 32) {
            nec_frame_t frame;
            if (decode_nec_frame(&frame)) {
                syslog(LOG_INFO, "Decoded NEC frame: address=%u, command=%u", frame.address, frame.command);
                publish_nec_frame(&frame);
            }
            pulse_count = 0;
        }
    }

    cleanup();
    closelog();
    return 0;
}

