        return -1;
    }
    return fd;
}

int set_i2c_address(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    return 0;
}

int write_i2c_command(int fd, uint8_t command) {
    if (write(fd, &command, 1) != 1) {
        perror("Failed to write I2C command");
        return -1;
    }
    return 0;
}

int read_i2c_data(int fd, uint16_t *data) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read I2C data");
        return -1;
    }
    *data = (buffer[0] << 8) | buffer[1];
    return 0;
}

float calculate_lux(uint16_t raw) {
    return raw / 1.2;
}

int send_udp_packet(const char *message) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    inet_pton(AF_INET, MULTICAST_GROUP, &addr.sin_addr);

    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send UDP packet");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fd[i] = open_i2c_device(I2C_DEVICE);
        if (i2c_fd[i] < 0) {
            for (int j = 0; j < i; j++) {
                close(i2c_fd[j]);
            }
            return EXIT_FAILURE;
        }
    }

    while (!terminate) {
        char buffer[BUFFER_SIZE];
        buffer[0] = '\0';

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (set_i2c_address(i2c_fd[i], BH1750_ADDR) < 0) {
                snprintf(buffer + strlen(buffer), BUFFER_SIZE - strlen(buffer), "%d,NaN;", i + 1);
                continue;
            }

            if (write_i2c_command(i2c_fd[i], BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
                snprintf(buffer + strlen(buffer), BUFFER_SIZE - strlen(buffer), "%d,NaN;", i + 1);
                continue;
            }

            usleep(180000);

            uint16_t raw;
            if (read_i2c_data(i2c_fd[i], &raw) < 0) {
                snprintf(buffer + strlen(buffer), BUFFER_SIZE - strlen(buffer), "%d,NaN;", i + 1);
                continue;
            }

            float lux = calculate_lux(raw);
            snprintf(buffer + strlen(buffer), BUFFER_SIZE - strlen(buffer), "%d,%.1f;", i + 1, lux);
        }

        if (buffer[0] != '\0') {
            buffer[strlen(buffer) - 1] = '\0'; // Remove trailing semicolon
            if (send_udp_packet(buffer) < 0) {
                fprintf(stderr, "Failed to send UDP packet\n");
            }
        }

        sleep(1);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        close(i2c_fd[i]);
    }

    return EXIT_SUCCESS;
}
