#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define AS7341_I2C_ADDRESS 0x39
#define AS7341_ID 0x44
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0x86
#define AS7341_SP_EN 0x01
#define AS7341_PON 0x01
#define AS7341_F1DATA_L 0x94
#define AS7341_F1DATA_H 0x95
#define AS7341_F8DATA_L 0xB4
#define AS7341_F8DATA_H 0xB5
#define AS7341_CLEAR_L 0x96
#define AS7341_CLEAR_H 0x97
#define AS7341_NIR_L 0xB6
#define AS7341_NIR_H 0xB7

#define SPECTRAL_LOG "spectral_log.csv"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_write_byte(int reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_word(int reg) {
    uint8_t buffer[1] = {reg};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (data[1] << 8) | data[0];
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    int id = i2c_read_word(0x00);
    if (id != AS7341_ID) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%02X, got 0x%02X\n", AS7341_ID, id);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(AS7341_ENABLE, AS7341_PON) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(AS7341_CFG6, 0x00) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(AS7341_ENABLE, AS7341_PON | AS7341_SP_EN) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(SPECTRAL_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int f1 = i2c_read_word(AS7341_F1DATA_L);
        int f2 = i2c_read_word(AS7341_F2DATA_L);
        int f3 = i2c_read_word(AS7341_F3DATA_L);
        int f4 = i2c_read_word(AS7341_F4DATA_L);
        int f5 = i2c_read_word(AS7341_F5DATA_L);
        int f6 = i2c_read_word(AS7341_F6DATA_L);
        int f7 = i2c_read_word(AS7341_F7DATA_L);
        int f8 = i2c_read_word(AS7341_F8DATA_L);
        int clear = i2c_read_word(AS7341_CLEAR_L);
        int nir = i2c_read_word(AS7341_NIR_L);

        if (f1 < 0 || f2 < 0 || f3 < 0 || f4 < 0 || f5 < 0 || f6 < 0 || f7 < 0 || f8 < 0 || clear < 0 || nir < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        double lux = (clear + nir) / 2.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%.2f\n",
                timestamp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);
        fflush(log_file);

        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

