#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define DEFAULT_ERROR_LOG "seismic_error.log"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(error_file, "%s: %s\n", asctime(tm_info), message);
    fflush(error_file);
}

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (data_file != NULL) {
        fclose(data_file);
        data_file = NULL;
    }
    if (error_file != NULL) {
        fclose(error_file);
        error_file = NULL;
    }
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(fd, buffer, 2) == 2) {
            return 0;
        }
        retries++;
        usleep(BACKOFF_MS * 1000);
    }
    return -1;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buffer, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(fd, buffer, length) == length) {
            return 0;
        }
        retries++;
        usleep(BACKOFF_MS * 1000);
    }
