#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define UDP_MULTICAST_GROUP "239.255.255.250"
#define UDP_PORT 5000
#define UDP_TTL 1

int i2c_fd = -1;
int udp_sock = -1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (udp_sock != -1) {
        close(udp_sock);
        udp_sock = -1;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int init_udp() {
    udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sock < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    int ttl = UDP_TTL;
    if (setsockopt(udp_sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set UDP TTL");
        close(udp_sock);
        udp_sock = -1;
        return -1;
    }

    return 0;
}

int read_light_level() {
    uint8_t command = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    sleep(1); // Wait for measurement to complete

    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    float lux = raw_value / 1.2;

    return lux;
}

void send_udp(float lux) {
    char message[20];
    snprintf(message, sizeof(message), "%.2f", lux);

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_MULTICAST_GROUP, &addr.sin_addr);

    if (sendto(udp_sock, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send UDP message");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0 || init_udp() < 0) {
        cleanup();
        return 1;
    }

    while (1) {
        float lux = read_light_level();
        if (lux >= 0) {
            send_udp(lux);
        } else {
            printf("Error reading light level, retrying in 1 second...\n");
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

