#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <libgpiod.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define BUFFER_SIZE 4096
#define MAGIC_WORD 0x24494D42
#define CSV_FILE "radar_data.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int setup_uart(const char *device, int baud_rate) {
    int uart_fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART device");
        return -1;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, baud_rate);
    cfsetospeed(&options, baud_rate);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &options);

    return uart_fd;
}

void close_uart(int uart_fd) {
    close(uart_fd);
}

void write_csv_header(FILE *csv_file) {
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
}

void write_csv_row(FILE *csv_file, double timestamp, int object_index, float range_m, float velocity_mps) {
    fprintf(csv_file, "%.6f,%d,%.3f,%.3f\n", timestamp, object_index, range_m, velocity_mps);
}

int main() {
    setup_signal_handlers();

    int uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close_uart(uart_fd);
        return EXIT_FAILURE;
    }

    if (ftell(csv_file) == 0) {
        write_csv_header(csv_file);
    }

    unsigned char buffer[BUFFER_SIZE];
    size_t buffer_pos = 0;
    size_t buffer_len = 0;

    while (running) {
        ssize_t bytes_read = read(uart_fd, buffer + buffer_pos, BUFFER_SIZE - buffer_pos);
        if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("Failed to read from UART");
            break;
        }
        buffer_len += bytes_read;

        while (buffer_len >= 8) {
            uint32_t magic_word = *(uint32_t *)(buffer + buffer_pos);
            if (magic_word == MAGIC_WORD) {
                // Synchronize on magic word
                buffer_pos += 4;
                buffer_len -= 4;

                // Process TLV payloads
                while (buffer_len >= 4) {
                    uint16_t tlv_type = *(uint16_t *)(buffer + buffer_pos);
                    uint16_t tlv_length = *(uint16_t *)(buffer + buffer_pos + 2);
                    if (buffer_len < tlv_length + 4) {
                        break;
                    }

                    if (tlv_type == 0x02) { // Range and velocity TLV
                        for (int i = 0; i < (tlv_length / 8); i++) {
                            float range_m = *(float *)(buffer + buffer_pos + 4 + i * 8);
                            float velocity_mps = *(float *)(buffer + buffer_pos + 4 + i * 8 + 4);
                            struct timeval tv;
                            gettimeofday(&tv, NULL);
                            double timestamp = tv.tv_sec + tv.tv_usec / 1e6;
                            write_csv_row(csv_file, timestamp, i, range_m, velocity_mps);
                        }
                    }

                    buffer_pos += tlv_length + 4;
                    buffer_len -= tlv_length + 4;
                }
            } else {
                // Skip malformed frame
                buffer_pos++;
                buffer_len--;
            }
        }

        if (buffer_pos == BUFFER_SIZE) {
            // Handle buffer overflow
            memmove(buffer, buffer + buffer_pos, buffer_len);
            buffer_pos = 0;
        }
    }

    fclose(csv_file);
    close_uart(uart_fd);

    return EXIT_SUCCESS;
}

