                            gettimeofday(&tv, NULL);
                            double timestamp = tv.tv_sec + tv.tv_usec / 1e6;
                            write_csv_row(csv_file, timestamp, i, range_m, velocity_mps);
                        }
                    }

                    buffer_pos += tlv_length + 4;
                    buffer_len -= tlv_length + 4;
                }
            } else {
                // Skip malformed frame
                buffer_pos++;
                buffer_len--;
            }
        }

        if (buffer_pos == BUFFER_SIZE) {
            // Handle buffer overflow
            memmove(buffer, buffer + buffer_pos, buffer_len);
            buffer_pos = 0;
        }
    }

    fclose(csv_file);
    close_uart(uart_fd);

    return EXIT_SUCCESS;
}
