#define TIMEOUT_SECONDS 2
#define TIMEOUT_USEC 0

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void print_error(const char *msg) {
    perror(msg);
}

void close_uart(int uart_fd) {
    if (uart_fd >= 0) {
        close(uart_fd);
    }
}

int main() {
    int uart_fd = -1;
    struct termios tty;
    fd_set read_fds;
    struct timeval timeout;
    char buffer[BUFFER_SIZE];
    char *line = NULL;
    size_t line_len = 0;
    ssize_t bytes_read;
    char *timestamp_str, *range_str;
    time_t timestamp;
    struct tm *tm_info;

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        print_error("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        print_error("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    // Open UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        print_error("open");
        return EXIT_FAILURE;
    }

    // Configure UART
    if (tcgetattr(uart_fd, &tty) != 0) {
        print_error("tcgetattr");
        close_uart(uart_fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8; // 8 bits per byte
    tty.c_cflag &= ~CRTSCTS; // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~ICANON; // Non-canonical mode
    tty.c_lflag &= ~ECHO; // Disable echo
    tty.c_lflag &= ~ECHOE; // Disable erasure
    tty.c_lflag &= ~ECHONL; // Disable new-line echo
    tty.c_lflag &= ~ISIG; // Disable interpretation of INTR, QUIT and SUSP
    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off s/w flow ctrl
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL); // Disable special handling of received bytes
    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; // Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VTIME] = 50; // 0.5 seconds inter-byte timeout
    tty.c_cc[VMIN] = 0;

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        print_error("tcsetattr");
        close_uart(uart_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = TIMEOUT_SECONDS;
        timeout.tv_usec = TIMEOUT_USEC;

        if (select(uart_fd + 1, &read_fds, NULL, NULL, &timeout) == -1) {
            if (errno == EINTR) {
                continue; // Interrupted by signal, try again
            }
            print_error("select");
            close_uart(uart_fd);
            return EXIT_FAILURE;
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
            if (bytes_read == -1) {
                print_error("read");
                close_uart(uart_fd);
                return EXIT_FAILURE;
            } else if (bytes_read == 0) {
                printf("Sensor absent or bus error\n");
                continue;
            }

            buffer[bytes_read] = '\0';
            line = strtok(buffer, "\n");
            while (line != NULL) {
                timestamp_str = strtok(line, ",");
                range_str = strtok(NULL, ",");
                if (timestamp_str != NULL && range_str != NULL) {
                    timestamp = atol(timestamp_str);
                    tm_info = localtime(&timestamp);
                    printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Range: %.2f meters\n",
                           tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                           atof(range_str));
                }
                line = strtok(NULL, "\n");
            }
        }
    }

    close_uart(uart_fd);
    return EXIT_SUCCESS;
}

