#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

static struct gpiod_chip *chip;
static struct gpiod_line *left_line, *middle_line, *right_line;
static int uart_fd;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (uart_fd >= 0) {
        close(uart_fd);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

void setup_uart() {
    struct termios options;
    uart_fd = open(UART_DEVICE, O_WRONLY | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART device");
        exit(1);
    }

    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    tcsetattr(uart_fd, TCSANOW, &options);
}

void send_emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(uart_fd, message, strlen(message));
    if (bytes_written == -1) {
        perror("Failed to write to UART");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR);

    if (!left_line || !middle_line || !right_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        exit(1);
    }

    if (gpiod_line_request_input(left_line, "ky033_left") < 0 ||
        gpiod_line_request_input(middle_line, "ky033_middle") < 0 ||
        gpiod_line_request_input(right_line, "ky033_right") < 0) {
        perror("Failed to request GPIO lines as inputs");
        cleanup();
        exit(1);
    }

    gpiod_line_set_config(left_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    gpiod_line_set_config(middle_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    gpiod_line_set_config(right_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP);

    setup_uart();

    while (1) {
        int left_state = gpiod_line_get_value(left_line);
        int middle_state = gpiod_line_get_value(middle_line);
        int right_state = gpiod_line_get_value(right_line);

        time_t now = time(NULL);
        printf("%sLeft: %d, Middle: %d, Right: %d\n", ctime(&now), left_state, middle_state, right_state);

        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            send_emergency_stop();
        }

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

